local ADDON_NAME = ...

local pack = {
	version = 1,
	addon = ADDON_NAME,
	quality = "high",
	bitrate = 128,
	language = "esES",
	pages = {
		[15] = { file = "15", len = 25.678, text = "Hola, Morgan, Los negocios en Villadorada van muy bien, tan bien que no he tenido tiempo de hacerte ningún envío. He encargado al portador de esta nota que entregue un paquete de velas de cera grandes (sabes a cuáles me refiero, ¿no?, las que los kobolds suelen llevar en sus cabezas). Te ruego que se lo agradezcas a esta persona de nuestra parte y le pagues lo que sea justo." },
		[16] = { file = "16", len = 32.731, text = "Al Honorable Director Crillian, Mi antiguo Maestro, te escribo para que sepas lo que tu aprendiz ha estado haciendo últimamente. Haciendo caso a tus consejos, he intentado aumentar mis conocimientos y sabiduría viajando fuera de las puertas de nuestro querido Stormwind. Mis viajes me llevaron a muchos lugares, pero he decidido fijar mi residencia aquí, en la encantadora ciudad de Moonbrook. Los campos circundantes de Westfall son muy hermosos a medida que se acerca la cosecha." },
		[17] = { file = "17", len = 23.38, text = "A los pocos días de mi visita me encontré dando clases a los niños de las granjas cercanas. Las clases fueron tan bien que el alcalde de la ciudad me encargó la dirección de una escuela, ¡y ya ha comenzado la construcción de una nueva escuela! De Silverpine a Stormwind y ahora a Moonbrook, ¡quién me iba a decir que vería tanto Azeroth! Saludos cordiales, Stalvan Mistmantle" },
		[18] = { file = "18", len = 31.321, text = "Estimado Noble Señor, Me han llegado noticias de que necesita un tutor para sus hijos aquí en Goldshire, donde resido temporalmente en la Posada del Orgullo del León. Debido al desafortunado estado de los acontecimientos en la región, me vi obligado a abandonar mi puesto como Director de la Escuela Moonbrook. Por favor, acepte mi solicitud para servir como tutor de su descendencia. El Director Crillian de la Academia puede hablarle de mis habilidades si es necesario." },
		[19] = { file = "19", len = 10.919, text = "Viajaré para conocerle en persona cuando amainen las lluvias invernales y las carreteras vuelvan a ser aptas para viajar. Hasta entonces, Stalvan Mistmantle de Silverpine" },
		[20] = { file = "20", len = 38.583, text = "... Giles, el chico, parece un poco arrogante y su educación será todo un desafío. No obstante, Tilloa, la hija mayor, parece extraordinariamente inteligente. Por otra parte, no he podido obviar su cautivadora belleza. Está en la flor de la edad. Al parecer, el señor ha fijado su boda para el próximo año. Pero cambio de tema. Esta semana acompañaré a la familia a su casita de verano junto al aserradero de la Vega del Este en Elwynn, cerca de las montañas Crestagrana. Espero escribir con mayor asiduidad cuando esté allí." },
		[21] = { file = "21", len = 25.783, text = ". ...la sensación más extraña e incontrolable. Nunca me había sentido como hoy. Mientras ayudaba a Giles con su lección de historia, Tilloa estaba fuera cuidando el jardín de flores. Al cabo de unos minutos entró y me puso una begonia escarlata en la palma de la mano y me sonrió de tal manera que sentí que el corazón me temblaba en el pecho. . . . ." },
		[22] = { file = "22", len = 20.14, text = ". ...muy segura de que ahora comparte los mismos sentimientos por mí. Esta mañana incluso me ha puesto la mano encima. Cuando sonríe, sus ojos brillan como diamantes. Entre nosotros se cruzan palabras mudas. Puedo sentirla en mi corazón palpitante y en mis venas calientes." },
		[23] = { file = "23", len = 32.366, text = ". ...ira y furia como nunca supe que existieran. ¡Cómo se atreve! Mientras instruía a Giles en el significado de los números, Tilloa aparece ante mí con un pretendiente, ¡tomados de la mano a pesar de todo en público! Qué joven más grosero. En lugar de presentarme como es debido, Tilloa se limitó a decir: \"Oh, ése es mi tutor, el tío Stalvan. Es un viejo simpático\". ¡Viejo! Al oír esa palabra mis mejillas se sonrojaron. No soy más que unos pocos años mayor y, sin embargo, ella traiciona. . ." },
		[24] = { file = "24", len = 25.443, text = ". ...espiral descendente de desesperación. Primero se burla de mí y ahora está comprometida. La charlatana sin gracia fingía amar cuando en realidad siempre deseó hacerme daño. Un vacío negro me acecha ahora y crece con cada momento de vigilia. La sangre que derramaré palidece en comparación con las lágrimas que he derramado. . ." },
		[25] = { file = "25", len = 35.109, text = "Tommy Joe, Cada hora que pasa, mi corazón se marchita sin tu presencia. Oh, si nuestra gente pudiera comprender el trasfondo de los crímenes que han cometido con sus semejantes, sabría que el único verdadero crimen es el odio. El odio consume, y me temo que, en estos tiempos oscuros, se apoderará no solo de nuestras familias. Si simplemente se dieran cuenta de ello, al menos podríamos estar juntos al fin. Sueño con que llegue ese día, vivo para ese día. Con todo mi amor, Maybell" },
		[26] = { file = "26", len = 28.134, text = "Hola, William, Han pasado años desde que hablamos la última vez, pero espero que tú y tu hermano estéis bien y que prosperes como boticario. William, tengo que pedirte un favor. Para ser breve, mi hijo Tommy Joe se ha enamorado locamente de la joven Maybell Maclure. Y a pesar del gran amor que siente el uno por el otro, nuestras familias... verás, nuestras familias llevan años enemistadas." },
		[28] = { file = "28", len = 28.421, text = "Argus: Como ya sabéis, estoy harto de recibir solicitudes de reparación por parte del ejército. No puedo quejarme por tanto trabajo, pero lo cierto es que están agotando mis reservas de hierro. No tengo suficiente hierro para herraduras. Sé que siempre dispones de abundantes reservas, por eso quería pedirte prestados 50 pares de herraduras hasta que consiga mi próximo cargamento de hierro. Te lo agradezco de antemano, Verner" },
		[29] = { file = "29", len = 30.067, text = "El cajón lleva una nota adjunta. La nota dice: \"Verner, lamento saber que Crestagrana tiene tantos problemas. Aquí están las herraduras que necesitas. Por favor, no olvides pagarme 100 monedas de plata en cuanto te sea posible.\" \"O bien, si lo prefieres, puedes pagarme con escamas de vientre de cría (he oído que las crías de dragón son comunes en las montañas Crestagrana). Porque somos amigos... 4 escamas serán suficiente. Gracias, Argus\"" },
		[30] = { file = "30", len = 22.674, text = "Señor, La guerra está sobre nosotros. La fatalidad nos acecha. Como Magistrado del municipio de Lakeshire es mi deber informar de la reciente actividad militar que ha tenido lugar en la colonia más oriental de Su Majestad. En estas páginas encontrarán un informe del estado de Lakeshire, enclavado en las montañas Redridge." },
		[31] = { file = "31", len = 25.025, text = "La pérdida de la Fortaleza de Stonewatch fue muy grave. En informes anteriores os detallé la alianza entre el Clan de Orcos Roca Negra y el Brujo conocido como Morganth. Los Orcos de Blackrock lucharon con horroroso salvajismo, sin duda alimentados por la magia maligna de Morganth. Muchos de los soldados más valientes de Su Majestad perecieron intentando defender la Fortaleza, pero al final no se pudo hacer nada." },
		[32] = { file = "32", len = 31.06, text = "Curiosamente, Morganth se volvió contra sus cohortes orcos poco después de su desdichada victoria. El Brujo construyó una torre arcana en el Noreste, y ha utilizado sus poderes para crear un pequeño ejército de Gnolls de la Piel Sombría al servicio de sus maliciosas órdenes. Tanto Orcos como Hombres han caído víctimas de los viscosos brutos que sirven al Brujo. En cuanto a la traición que tuvo lugar entre Morganth y Gath'Ilzogg, el Señor de la Guerra de Roca Negra, sólo se puede especular en este momento." },
		[33] = { file = "33", len = 28.865, text = "Para nuestro peligro, los asquerosos Orcos parecen más preocupados por la desaparición de los buenos ciudadanos de Su Majestad. En la última quincena el Clan Blackrock organizó una despiadada ofensiva en Lakeshire. Muchos hombres valientes perdieron la vida ese sombrío día. Las fuerzas orcas avanzaron con tal velocidad y furia que el puente que cruza Everstill quedó en ruinas. Nuestros suministros de guerra han disminuido mucho. Nos faltan vendas para curar las heridas de los caídos." },
		[34] = { file = "34", len = 28.369, text = "Ahora pido a Su Majestad que apoye a la buena gente de Lakeshire en estos tiempos de necesidad. Necesitamos nuevos soldados para defender el territorio, así como nuevos instrumentos de guerra para reemplazar a los perdidos en el campo de batalla. La comida y los suministros de construcción también escasean. Por favor, mi Señor, ayúdanos a mantener próspero el bastión final entre el Hombre y el miserable Orco. El Enemigo debe ser mantenido fuera del Reino de Stormwind." },
		[35] = { file = "35", len = 21.29, text = "Temo que un mal mayor y más oscuro se esté gestando en el caldero de corrupción en que se han convertido las Tierras del Norte. Es imperativo que el Reino de Stormwind actúe para que no nos convirtamos en recuerdos que se desvanecen para los vivos o en esclavos del Enemigo. Firmado, Magistrado Solomon Municipio de Lakeshire Reino de Stormwind" },
		[36] = { file = "36", len = 25.731, text = "Honorable Magistrado Solomon: Lloro con usted por los muertos. Me ocuparé personalmente de que el Rey sea informado de la situación y tengo la esperanza de poder traer refuerzos a Lakeshire. Su Majestad ha estado escaso últimamente y actúa de manera extraña. Comparto esto con usted en confianza. Hasta entonces, General Marcus Jonathan Reino de Stormwind" },
		[38] = { file = "38", len = 38.113, text = "Mantorrecio:n Hay que tener osadía para enviar a un total desconocido a tratar el asunto de la banda Defias. Salvaste mi vida una vez y ahora la pones gravemente en peligro. No obstante, estoy en deuda contigo. La Hermandad Defias es más grande de lo que crees. Todas las minas de los Páramos de Poniente al bosque de Elwynn están bajo su control. Kobolds y gnolls han sido reclutados para hacer el trabajo sucio. Tienen a los goblins fabricando monstruos metálicos para colocarlos en los campos de los Páramos de Poniente y así alimentar las supersticiones de los habitantes de la zona." },
		[39] = { file = "39", len = 34.9, text = "Han mandado construir una extensa red subterránea. Más grande de lo que te puedes imaginar, Mantorrecio. De la Bahía del Botín hasta el Castillo de Ventormenta. Podrás ser un valiente paladín, pero no estás en tu sano juicio si crees que puedes detenerlos. Están trabajando en la construcción de armas de destrucción masiva. Después de todo, si hay algo que la hermandad de los Albañiles sabe es cómo erigir grandes construcciones. No habrás creído que se trataba de granjas de hortalizas o de viñedos, ¿verdad? Te he devuelto el favor. ¡Ahora déjame en paz! W" },
		[41] = { file = "41", len = 28.63, text = "Lord Stoutmantle... Liderado por Edwin VanCleef, el Gremio de Canteros estaba compuesto por los constructores más hábiles entre los hombres. Los Canteros ayudaron a reconstruir la destrozada ciudad de Stormwind que fue arrasada por los orcos durante la Primera Guerra. VanCleef y sus gremios eran constructores sin parangón y su trabajo y arte quedaron patentes en los edificios de la Catedral de la Luz y la propia Fortaleza de Stormwind." },
		[42] = { file = "42", len = 25.286, text = "Sin embargo, los nobles de Stormwind acumularon una enorme deuda al expandir la presencia militar del reino a través de Elwynn y hacia Stranglethorn. La enorme deuda paralizó la economía del reino y despojó a VanCleef y sus Canteros de las recompensas prometidas. Tras pasar años esforzándose por reconstruir la gloriosa ciudad, los Canteros se quedaron en la ruina, olvidados por los corruptos funcionarios de la ciudad." },
		[43] = { file = "43", len = 29.44, text = "Después de haber conocido personalmente a Edwin VanCleef toda mi vida, puedo decirte que enfrentarse a él como enemigo es una tarea bastante desalentadora. Verás, él era mi amigo de la infancia, y yo personalmente lo entrené en los caminos de las sombras pensando que algún día podría considerar una carrera junto a mí. Si VanCleef dirige la Hermandad Defias, que la Luz se apiade de nuestras almas. Maestro Mathias Shaw Gremio de Asesinos de Stormwind" },
		[45] = { file = "45", len = 17.842, text = "¡Buen trabajo, amigo! Ahora tenéis que dirigiros hacia el este. Al este de los acantilados, al este de la carretera. Busca las ruinas de la vieja chimenea cerca del camino. Allí encontrarás un viejo barril con tu siguiente pista." },
		[46] = { file = "46", len = 18.965, text = "Desde este barril, mira hacia el norte. Recto como el cuervo vuela, sigue caminando hasta que veas la jarra vacía junto al molino de viento solitario en los acantilados del mar. Si hurgas alrededor de esa jarra, puede que encuentres lo que buscas." },
		[47] = { file = "47", len = 20.114, text = "¡Ahora que has encontrado la vieja tinaja de whisky, estás a punto de dar con el tesoro! Mira hacia el oeste desde ahí y camina hasta llegar a la costa. Cuando hayas llegado al agua, ¡no te detengas! ¡Nada hacia el oeste hasta que encuentres la isla con mi cofre del tesoro!" },
		[48] = { file = "48", len = 26.305, text = "Blacknails-- El Mar nos espera. Necesitamos sus provisiones del Norte. Despojadlo todo: cada pica de ferrocarril, cada cubo de agua. Necesitamos metal. Un cargamento se debe de BB pero hace mucho tiempo. Hazlo por mí, Blacknails. Envía tus suministros directamente al \"granero\" esta vez. No hay tiempo que perder. --VanCleef" },
		[49] = { file = "49", len = 32.287, text = "Lord Stoutmantle -- El Municipio de Lakeshire solicita humildemente la ayuda de su Milicia. Mientras escribo esto, nos encontramos bajo asedio tanto de los Orcos de Blackrock como de los Gnolls Shadowhide de Morganth. No enviaría pujas si nuestra situación no fuera grave. Esperamos la ayuda de Stormwind, pero hasta que llegue, os ruego que prestéis vuestro apoyo. Una vez que el Reino sea violado, toda la Humanidad estará en peligro. Magistrado Solomon" },
		[50] = { file = "50", len = 33.855, text = "Señoría... Todo Westfall lamenta su pérdida, pero estamos plagados de nuestra propia guerra en Westfall. Los granjeros han sido perseguidos por ladrones y golems mecánicos. Stormwind retiró sus tropas, dejando al pueblo indefenso. He reunido a la Milicia Popular tras el abandono de Stormwind para salvar lo que queda de esta tierra. Llevar a la Milicia a Redridge significaría la perdición segura de Westfall. Lo siento, Gryan Stoutmantle." },
		[51] = { file = "51", len = 31.007, text = "Lord Ebonlocke... El municipio de Lakeshire solicita humildemente la ayuda de la Guardia de la Noche. Estamos bajo asedio tanto de los orcos de Blackrock como de los gnolls de Shadowhide de Morganth. No enviaría pujas si nuestra situación no fuera grave. Esperamos la ayuda de Stormwind, pero hasta que llegue, les ruego que nos presten su apoyo. Una vez que el reino se rompe, toda la humanidad está en peligro. Magistrado Solomon" },
		[52] = { file = "52", len = 30.145, text = "Señoría... Lamento informarle que la Guardia de la Noche no puede abandonar su puesto en Darkshire en este momento. Tal vez ignorabais que Stormwind ya no proporciona apoyo militar en esta región. La Guardia de la Noche ha sido formada y entrenada enteramente por la gente del bosque para defender Darkshire en ausencia de Stormwind. Sin la Guardia, la ciudad caería. Te deseo suerte en tu difícil situación. --Lord Ello Ebonlocke" },
		[53] = { file = "53", len = 9.613, text = "Las letras de este billete parecen parpadear y bailar sobre su superficie. Es imposible deducir su significado..." },
		[54] = { file = "54", len = 31.948, text = "Saludos Ello Ebonlocke, Alcalde de Darkshire. Me temo que tengo noticias para su ciudad. Graves noticias. Verás, soy un creador. Engañé al portador de esta nota para que me ayudara en mi última y más terrible creación: ¡un demonio de carne, hueso y metal retorcido! Mientras lees esto, es probable que esté fuera de mi humilde morada, rechinando los dientes y esperando mi palabra para salir a masacrar. Pero pronto lo sabrás. -El embalsamador" },
		[55] = { file = "55", len = 23.197, text = "Esta es la escritura de una extensión de tierra dentro de la región de Westfall. Otorga a las personas que figuran a continuación derechos de propiedad sobre la zona designada, así como sobre todos los artículos producidos y las estructuras construidas dentro de sus límites. El documento está firmado por: Theodore Furlbrow Verna Furlbrow" },
		[56] = { file = "56", len = 14.237, text = "[Las palabras a continuación fueron garabateadas rápidamente en el reverso de la escritura] Nos apoyamos en Furlbrow y conseguimos su escritura. Pensé que podría ser útil si querías forjar una de estas para tu propia casa. Los Furlbrows no nos darán problemas. La última vez que los vi estaban saliendo de Westfall, con una carreta rota." },
		[58] = { file = "58", len = 21.133, text = "Brilla la luna sobre el valle arrojando su resplandor sobre la jungla Donde orgullosos guerreros acuden a la llamada Para defender nuestra Nación y nuestras tierras sagradas. Una Luna sobre el Valle brilla Muy por encima de los gritos de batalla Donde se derrama sangre de enemigos y camaradas." },
		[59] = { file = "59", len = 19.775, text = "Y cuando nuestros hermanos pasen A reinos más allá de lo conocido El espíritu del alma se endurece En las profundidades del valle. Y cuando nuestros hermanos pasan Al templo de la montaña Protegeremos su espíritu eterno encerrado en el sagrado cristal azul. Y cuando nuestros hermanos pasen Una Luna sobre el Valle brilla." },
		[62] = { file = "62", len = 16.353, text = "Por luna y fuego, Por carne y hueso, Escrito en sangre, Esculpido en piedra. Abandona este lugar O encuentra tu perdición La muerte monta guardia Sobre la Tumba del Emperador." },
		[63] = { file = "63", len = 29.649, text = "Maestro Carevin, El portador de esta nota ha demostrado ser honrado en la Luz, capaz de luchar contra los muertos vivientes y demonios que plagan las fronteras de Duskwood, y dispuesto a unirse a la familia Carevin en su causa de la Luz. Por lo tanto, te sugiero que le des a este guerrero de la Luz más deberes - tal vez investigar a algunos de los habitantes de la ciudad que están bajo sospecha de ayudar a los enemigos de la Luz. Atentamente, Calor" },
		[64] = { file = "64", len = 32.627, text = "Morgan Masdama fue un noble caballero que luchó en defensa de los inocentes, los pobres y los afligidos. Durante años, trabajó diligentemente en la periferia de Azeroth, aliviando a las víctimas y castigando a los malhechores. En el verano, al cumplir dieciocho años, contrajo matrimonio con una joven llamada Lys. Estaban muy enamorados y tuvieron tres hijos, un varón y dos chicas. Morgan tenía treinta y dos años cuando estalló la guerra en" },
		[65] = { file = "65", len = 29.962, text = "Lordaeron. Morgan fue llamado al lado del legendario paladín Uther el Portador de Luz para luchar contra los orcos y los no muertos. Dejando a su mujer e hijos en la seguridad de su hogar, Morgan partió a la guerra. Pasaron los años y la guerra se prolongó, y Morgan sería testigo de muchos sucesos horribles, como la disolución de los Paladines de la Mano de Plata, la muerte de Uther y la propagación de la plaga. Lo único que lo mantenía al borde de la locura era saber que iba a" },
		[66] = { file = "66", len = 30.171, text = "se reuniría con su mujer y sus hijos. Morgan regresó finalmente a su hogar, pero lo que encontró nada tenía que ver con lo que recordaba. El bosque que antes era verde ahora estaba contaminado, infestado de no-muertos y otras fuerzas oscuras. Por doquier había casas y granjas destruidas y el Cementerio del Cerro del Cuervo cubría gran parte del territorio. Morgan, indignado y perplejo, llegó hasta su casa, encontrándola en ruinas. Ignorando lo que le había ocurrido a su tierra," },
		[67] = { file = "67", len = 33.541, text = "se dirigió al pueblo en busca de respuestas y, esperaba, de su mujer y sus hijos. Morgan preguntó por su familia, pero no pudo encontrar ninguna respuesta. Un sacerdote de Darkshire, como se llamaba ahora, le dijo que podría buscar una lápida en el cementerio de Raven Hill. Morgan se negó a creer que su familia estuviera muerta y siguió buscando en todas las granjas y casas de Duskwood, pero fue en vano. Morgan cabalgó desde Darkshire hasta la cercana Lakeshire, pensando que tal vez su familia había huido. En su camino" },
		[68] = { file = "68", len = 32.653, text = "allí, decidió, en contra de su buen juicio, pasar por el cementerio de Raven Hill. Morgan pasó horas paseando entre las lápidas. Reconoció muchos nombres de personas que conocía y se sintió cada vez más angustiado. Entonces los vio: una pequeña parcela desatendida con tres pequeñas lápidas. Una sensación de temor le invadió mientras se acercaba. Morgan quitó el polvo de la lápida más prominente para descubrir el nombre que había en ella. Simplemente tallado sobre la tumba, las letras deletreaban" },
		[69] = { file = "69", len = 33.907, text = "su peor temor: Lys Ladimore Amada esposa y madre La aprensión de Morgan se convirtió en consternación y luego en dolor, y cayó de rodillas llorando. Durante horas se quedó mirando aquella tumba, suplicando perdón a la fría piedra y pidiendo disculpas entre sollozos. Entonces, horas más tarde, algo en él se quebró y empezó a atacar. Sacó su espada de la vaina y empezó a golpear las lápidas, gritando de rabia. Cegado por la furia, arremetió contra ellas y las golpeó salvajemente." },
		[70] = { file = "70", len = 30.302, text = "de un trío de asistentes del cementerio. Cuando intentaron detenerlo, se centró en ellos, los acusó de ser culpables y los mató a todos. Más tarde, cuando se le pasó la rabia, Morgan se dio cuenta de lo que estaba pasando y vio su espada ensangrentada clavada en el pecho de uno de los asistentes. Llevado al límite por sus emociones, sacó el cuchillo de su cinturón y se lo clavó en el corazón. El cadáver de Morgan Ladimore y los tres cuerpos de sus víctimas fueron encontrados" },
		[71] = { file = "71", len = 33.646, text = "al día siguiente. Fue enterrado rápidamente, sin ceremonia alguna, en una tumba cavada a toda prisa en las afueras del cementerio. Debido a que Morgan cometió un asesinato contra inocentes, algo que iba completamente en contra de sus creencias y de su naturaleza, y debido a la pena que sentía por no haber podido salvar a su familia, Morgan no pudo tener una muerte pacífica, y siguió viviendo como uno de los muertos inquietos. Sólo unos días más tarde, su tumba fue removida, y su cuerpo no pudo ser encontrado. El ser que era Morgan ahora" },
		[72] = { file = "72", len = 17.763, text = "vaga por Duskwood, consumido por su dolor por la pérdida de su esposa e hijos y por su propio odio hacia sí mismo. Mor'Ladim, como ahora se llama a sí mismo, vaga por Duskwood con odio y venganza sin sentido, y es conocido por cometer asesinatos indiscriminados." },
		[73] = { file = "73", len = 16.98, text = "El terror de estas últimas semanas ha supuesto más de lo que puedo soportar, sin embargo, siento que escribir lo que he vivido me reconforta en cierta medida. Por eso lo hago y es el único consuelo que tengo en estos días aciagos." },
		[74] = { file = "74", len = 30.198, text = "PRIMER DÍA Mi aprendiz y yo hemos llegado hoy al Valle de Crestanevada. El recorrido por la caverna prácticamente no tuvo incidencias. Acampamos bastante lejos de la cueva en la que, según nos dijeron, se habían reunido los trols. SEGUNDO DÍA El aullido de un maldito lobo me mantuvo despierto toda la noche. En un par de días tendré un nuevo traje de piel de lobo. El chico se enfrascó en una pelea con un trogg hoy y" },
		[78] = { file = "78", len = 12.774, text = "Este marcador de armaduras es útil para marcar una armadura de cuero o tela, canjeable en el la casa de los Timberlain, en el Aserradero de la Vega del Este." },
		[79] = { file = "79", len = 35.709, text = "A continuación se describe el proceso y el programa de excavación y transporte del oro de Defias de las minas de Elwynn a nuestro puesto de mando en los Páramos de Poniente. Programa de excavación: Domingo: 12.30 p. m. Miércoles: 12.30 p. m. Durante todos los días señalados, el oro extraído de las minas de Elwynn se recogerá en la plantación de calabazas de Brackwell. El agente encargado de estos cargamentos o \"Recolector\" se reconocerá por su anillo grabado. Un anillo que yo le entregué." },
		[80] = { file = "80", len = 23.798, text = "Grelin: Me queda poco tiempo y muchos asuntos me preocupan, así que espero que tu investigación sobre los trols no sea una preocupación más. Por esta razón, permitiré que utilices mi autoridad como mejor te parezca para tratar con los trols, sobre todo si te permite encontrar una solución oportuna. Magni Barbabronce" },
		[81] = { file = "81", len = 28.63, text = "logró extraer lo mejor de la bestia espantosa, pero ahora se está curando de una herida inmunda en el brazo. Todo indica que tendré que ocuparme de las tareas domésticas durante un tiempo. \\TERCER DÍA Hace frío. Ha nevado un poco cerca del mediodía. CUARTO DÍA El chico volvió hoy y de buen humor, así que echamos un primer vistazo a los trols. Pertenecían al clan Peloescarcha, a juzgar por las marcas en la piel y los diversos abalorios que llevaban en el cuerpo." },
		[82] = { file = "82", len = 28.63, text = "QUINTO DÍA Encargué al chico que vigilara el campamento mientras yo husmeaba en la cueva y echaba un vistazo por los alrededores. Son muchos trols y esto genera ciertos problemas. Tal vez haya que convocar a los montaraces por si resulta necesario limpiar la cueva de la plaga de trols. \\Soy consciente de no haber mencionado a los troggs últimamente. Aparecen por la zona en grandes grupos, pero son tan primitivos que no suponen una amenaza. El tiempo dirá si esto es verdad o no." },
		[83] = { file = "83", len = 24.294, text = "Ni gota de cerveza durante casi una semana. SEXTO DÍA Vuelve a hacer frío. Nieva. Trols y nada de cerveza. SÉPTIMO DÍA La nieve es blanca, el cielo es añil, los lobos aúllan de noche, y yo sin cerveza de barril. OCTAVO DÍA Quizás los trols no representen un problema tan grande como el que inicialmente supusimos. Son bastantes," },
		[84] = { file = "84", len = 7.863, text = "pero no están bien armados ni organizados. Una pequeña demostración de fuerza deberá ser más que suficiente para neutralizarlos." },
		[85] = { file = "85", len = 34.011, text = "Mi diario El terror de estas últimas semanas es casi más de lo que puedo soportar; ¿por qué al escribir palabras en este libro puedo mantener a raya de algún modo la locura? Tal vez sea como si estuviera confesando mis pecados a un compañero silencioso, o liberando mi mente de estos pensamientos torturados y confinándolos al papel. Comencé un diario antes de éste, pero permanece en un lugar al que no puedo volver. Así que empezaré de nuevo. Pero esta vez empezaré por el verdadero principio." },
		[86] = { file = "86", len = 33.254, text = "Informe sobre el estado de los trols Peloescarcha en el área general del Valle de Crestanevada Elaborado por Grelin Barbablanca, enviado especial del senado Desde el momento en que empecé a observar el movimiento de los trols Peloescarcha en el área del Valle de Crestanevada, he determinado que no representan una especial amenaza para los asentamientos enanos de la zona. De hecho, constituyen esa clase de amenazas que pueden eliminarse con un pequeño apoyo adicional por parte del ejército. Con la ayuda de los montaraces instalados en" },
		[87] = { file = "87", len = 14.785, text = "el Valle de Crestanevada y unos cuantos mercenarios (pagados con fondos apartados por el senado antes de mi envío), confío en que el problema se resolverá muy pronto. Esta acción ha sido autorizada mediante la sanción que me otorgó el rey Barbabronce." },
		[88] = { file = "88", len = 41.822, text = "Informe sobre el estado de los trols Peloescarcha en el área general de Dun Morogh Elaborado por Senir Barbablanca, enviado especial del senado Los trols situados en Dun Morogh están fundamentalmente ubicados en el Poblado Peloescarcha, una cueva de montaña en la frontera oeste. Son lo suficientemente numerosos como para causar cierta preocupación. No obstante, parecen estar más que contentos dentro de su cueva. Sin duda, esto se debe a que no desean volver a desatar la ira de los enanos y arriesgarse al exterminio total de su raza. Sus acciones pueden considerarse de carácter territorial, por así decirlo, y creo" },
		[89] = { file = "89", len = 26.227, text = "que no suponen una verdadera amenaza para nosotros, siempre que no invadamos su territorio. Esta situación puede resultar poco agradable para el pueblo de los enanos, pero dada la dispersión de los recursos militares, puede ser prudente relegar el exterminio de los trols a un segundo plano, para poder centrarnos en la amenaza de los troggs y los Hierro Negro. Adjunto copia del informe de mi hermano Grelin sobre Yunquemar." },
		[90] = { file = "90", len = 31.869, text = "Informe sobre el estado de los trols Peloescarcha en el área general del Valle de Crestanevada Elaborado por Grelin Barbablanca, enviado especial del senado Desde el momento en que empecé a observar el movimiento de los trols Peloescarcha en el área del Valle de Crestanevada, he determinado que no representan una especial amenaza para los asentamientos enanos de la zona. De hecho, constituyen esa clase de amenaza que puede eliminarse con un pequeño apoyo adicional por parte del ejército. Con la ayuda de los montaraces instalados en" },
		[91] = { file = "91", len = 14.916, text = "el Valle de Crestanevada y unos cuantos mercenarios (pagados con fondos apartados por el senado antes de mi envío), confío en que el problema se resolverá muy pronto. Esta acción ha sido autorizada por la sanción otorgada por el rey Barbabronce." },
		[92] = { file = "92", len = 22.7, text = "Mi queridísimo Tarrel - Disculpa la prisa con la que se ha escrito esta correspondencia, pero el tiempo no es un lujo del que dispongamos. El equipo de excavación estaba haciendo progresos significativos desenterrando importantes artefactos de Titán. Pero empezamos a descubrir otros objetos antiguos, concretamente huesos grandes." },
		[93] = { file = "93", len = 24.346, text = "Poco después de desenterrar los huesos fuimos víctimas de un ataque de rapaces. El batallón de hombres del regimiento de Longbraid luchó valientemente. Pero al final, fueron abrumados. Casi todos perecieron. Sólo 3 de nosotros sobrevivimos. Un trabajador llamado Ormer Ironbraid demostró ser el más heroico al garantizar mi seguridad y la del prospector Whelgar." },
		[94] = { file = "94", len = 29.074, text = "Ahora nos refugiamos en una caverna protegida, aparentemente fuera de peligro. Pero estamos atrapados hasta que una fuerza pueda ser enviada para hacer frente a los Raptors. Whelgar está tratando de seguir trabajando, pero sospecho que todavía está bastante asustado. Esa es nuestra situación, Tarrel. Por favor, insta a Longbraid a reunir una fuerza de rescate de inmediato. Mi amor por ti sigue siendo fuerte, incluso en estos tiempos difíciles. --Merrin" },
		[95] = { file = "95", len = 34.351, text = "Las verdes colinas de Stranglethorn Nuestro primer día fue tan bien como se puede esperar de un primer día. Pasamos la mayor parte del tiempo haciendo los preparativos necesarios para establecer un campamento base. Localicé un lugar ideal junto a la desembocadura de un río de agua dulce. A juzgar por los viejos muelles abandonados que había cerca, este lugar estuvo habitado hace algún tiempo. En cuanto a los habitantes originales, sólo el tiempo podrá contarlo." },
		[98] = { file = "98", len = 30.511, text = "En los años siguientes, después de que Stormwind traicionara al Gremio de Canteros, Sir Erlgadin se amargó con el papel de los nobles dentro del Reino. Ya no deseaba mantener la posición que el linaje de su padre le había ganado en la Casa de los Nobles. Pero estoy divagando. El propósito de esta historia no es servir de tratado político ni de biografía. Es el relato de mis experiencias cazando caza mayor en las verdes colinas de Stranglethorn." },
		[100] = { file = "100", len = 29.44, text = "Justo cuando estaba a punto de cuestionar la falta de interés de Ajeck en la estrategia de caza del día, echó mano a su carcaj, sacó una flecha y soltó un disparo directo hacia el pobre Barnil. Pero no era a Barnil a quien disparaba Ajeck. Cuando Barnil se apartó, con la boca abierta, un gran crocilisco de río salió a la superficie con la flecha de Ajeck perfectamente colocada entre sus dos grandes ojos." },
		[102] = { file = "102", len = 32.313, text = "En uno de esos pasos en falso, Erlgadin puso una fuerte mano sobre el hombro de Barnil. Ajeck y yo le echamos una mirada despreocupada, suponiendo que el hombre simplemente estaba regañando a Barnil por su descuido. Sin embargo, Erlgadin señaló lentamente con la cabeza hacia un árbol caído cercano. Nos devolvió la mirada con dos penetrantes ojos negros justo por encima de una boca llena de colmillos afilados como cuchillas." },
		[104] = { file = "104", len = 24.424, text = "La matanza provocó un ambiente festivo entre la expedición. Barnil sirvió hidromiel para el disfrute de todos. Pero nuestra fiesta duró poco. Mientras preparábamos el cadáver para transportarlo al campamento base, nos sorprendió un horrible gruñido. En todos mis años nunca había oído nada tan espeluznante." },
		[105] = { file = "105", len = 27.429, text = "En lo alto de un precipicio rocoso, silueteado por el sol poniente, pude distinguir al mayor felino de presa que jamás había visto. Pude soltar una torpe descarga con mi rifle, pero el felino se mantuvo firme. Volvió a gruñir, esta vez más fuerte que la primera vez, y desapareció. Recogimos nuestras pertenencias y regresamos solemnemente al campamento." },
		[108] = { file = "108", len = 36.127, text = "Este día nos aventuramos hacia el sur, siguiendo unas huellas frescas de pantera. Pronto llegamos a un barranco atravesado por un tremendo puente de cuerda. No pude evitar pensar en los escritos descriptivos de Brann sobre esta región cuando vi aquella maravilla de la ingeniería. A menudo se suponía que los gnomos nativos eran una raza primitiva e inculta, pero al contemplar la maestría artesanal del puente pude reconocer la habilidad con la que los constructores gnomos superaron la hazaña aparentemente imposible." },
		[110] = { file = "110", len = 29.806, text = "Tanto Ajeck como Sir Erlgadin estaban preparados, con las armas apuntando a la maleza erizada en la base de los árboles que se balanceaban. El sol del mediodía nos golpeaba con fuerza. Una lenta gota de sudor se deslizaba por la sien de Erlgadin mientras tiraba del pasador hacia atrás. Al oír el chasquido, la espesa flora se abrió y una gran pantera negra, un hermoso espécimen, se lanzó a la llanura." },
		[112] = { file = "112", len = 37.851, text = "Su arma se agitó violentamente en sus brazos. El cañón se inclinó hacia un lado y apareció bajo el rifle de Ajeck. Ajeck había elegido ese momento exacto para apretar el gatillo. El rifle, que ahora apuntaba torpemente hacia la línea de árboles, se disparó con un claro estampido. Una bandada de pájaros salió gritando de la copa de los árboles y se dispersó en todas direcciones. Una columna de humo se elevó del árbol. Vimos con asombro cómo una tremenda rama caía de lleno sobre la pantera que huía, rompiéndole la espalda." },
		[114] = { file = "114", len = 38.531, text = "Salimos con las primeras luces del día, en dirección sur, más allá de las ruinas de Tkashi. Barnil expresó su preocupación por si nos encontrábamos con miembros de la tribu de los Escalpos Sangrientos. Le recordé a Barnil que los Bloodscalps estaban más preocupados por destruir a su enemigo tribal, los Skullsplitters. Ni que decir tiene que Barnil no se tranquilizó lo más mínimo. Yo, sin embargo, llevaba conmigo un rifle cargado, una mochila llena de pólvora y tres mortíferos cazadores para aliviar cualquier preocupación de una emboscada poco amistosa." },
		[115] = { file = "115", len = 35.997, text = "He estado frente a un imponente Infernal en el campo de batalla, el ejército de la Legión Ardiente avanzando desde todas direcciones. Una revoltosa banda de Trolls parece tan inofensiva como una liebre en las colinas de Dun Morogh. Pasamos las Ruinas de Tkashi sin incidentes, para alivio de Barnil. El grupo procedió a dirigirse hacia el oeste, hacia el Gran Mar, bordeando las Ruinas de Zul'Kunda justo al sur. Mientras ascendíamos por los altos acantilados del mar, avistamos nuestro primer Raptor." },
		[118] = { file = "118", len = 23.223, text = "Nuestros disparos apresurados fueron suficientes para comprar la huida de Barnil. Barnil bajó la colina y se reunió con el grupo. Nos escabullimos en la selva; una manada de feroces Rapaces de Cola de Láser acechaba cada uno de nuestros movimientos. Los cazadores eran ahora los cazados." },
		[119] = { file = "119", len = 25.966, text = "Conduje al grupo hacia el mar, con la esperanza de que la costa nos proporcionara refugio de los rapaces. Con las prisas, nos habíamos desviado demasiado hacia el norte, a una altura precaria. El error estaba cometido. La culpa fue mía. Nos detuvimos justo al lado de un acantilado escarpado, los Raptors a pocos pasos detrás." },
		[120] = { file = "120", len = 27.69, text = "Avancé lentamente, con el arma en alto. Había llevado a estos valientes cazadores a la muerte. Moriría defendiéndolos. Las rapaces de cola blanca son particularmente feroces, conocidas por su implacable sed de sangre. Nos superaban en número. Pero que me condenen si dejo que me maten a mí y a mis compañeros sin derramar algo de su propia sangre primero." },
		[121] = { file = "121", len = 25.365, text = "Ajeck y Sir Erlgadin prepararon sus armas, flanqueándome por ambos lados, de espaldas al mar. Barnil soltó un suspiro derrotado y desenvainó su hacha. Los Lashtail estaban casi sobre nosotros. Su paso firme se había ralentizado. Ahora acechaban a su presa, pues sabían que nos tenían atrapados." },
		[124] = { file = "124", len = 7.21, text = "Las verdes colinas de Stranglethorn Por Hemet Nesingwary" },
		[153] = { file = "153", len = 31.869, text = "Nuestro primer día fue tan bien como se puede esperar de un primer día. Pasamos la mayor parte del tiempo haciendo los preparativos necesarios para establecer un campamento base. Localicé un lugar ideal junto a la desembocadura de un río de agua dulce. A juzgar por los viejos muelles abandonados que había cerca, este lugar estuvo habitado hace algún tiempo. En cuanto a los habitantes originales, sólo el tiempo podrá contarlo." },
		[154] = { file = "154", len = 23.38, text = "Para esta expedición he reunido a Ajeck Rouack y Sir S. J Erlgadin, junto con mi sirviente de confianza, Barnil Stonepot. Luché junto al padre de Ajeck en muchas batallas en defensa de la Alianza. Verla crecer es muy especial. Su padre la educó bien en el manejo de las armas. Su habilidad con el arco me hace preguntarme si corre sangre élfica por sus venas." },
		[155] = { file = "155", len = 17.345, text = "Sir S. J. Erlgadin procede de la aristocracia humana. Su padre, el Conde Erlgadin, era famoso por su generosidad. Fue el Conde quien presionó para mejorar las condiciones de trabajo del Gremio de Canteros durante la restauración de Stormwind tras la Segunda Gran Guerra." },
		[156] = { file = "156", len = 27.115, text = "En los años siguientes, después de que Stormwind traicionara al Gremio de Canteros, Sir Erlgadin se amargó con el papel de los nobles dentro del Reino. Ya no deseaba mantener la posición que el linaje de su padre le había ganado en la Casa de los Nobles. Pero estoy divagando. El propósito de esta historia no es servir de tratado político ni de biografía. Es el relato de mis experiencias cazando caza mayor en las verdes colinas de Stranglethorn." },
		[157] = { file = "157", len = 25.731, text = "Nos levantamos con el sol. Barnil empezó a preparar la comida de la mañana. Noté que la atención de Ajeck estaba algo distraída. La caminata del día sería larga y nuestra caza nos acercaría al peligro. La falta de concentración podría provocar fácilmente un percance. Sin embargo, Ajeck parecía incapaz de desviar la mirada de Barnil, que estaba de pie junto a la orilla del río enjuagando su equipo de cocina." },
		[158] = { file = "158", len = 24.921, text = "Justo cuando estaba a punto de cuestionar la falta de interés de Ajeck en la estrategia de caza del día, echó mano a su carcaj, sacó una flecha y soltó un disparo directo hacia el pobre Barnil. Pero no era a Barnil a quien disparaba Ajeck. Cuando Barnil se apartó, con la boca abierta, un gran crocilisco de río salió a la superficie con la flecha de Ajeck perfectamente colocada entre sus dos grandes ojos." },
		[159] = { file = "159", len = 32.914, text = "Salimos hacia el oeste, a través de la espesa maleza de la enmarañada jungla. Moviéndonos con pasos lentos y deliberados, atravesamos el espeso follaje en busca de una presa. La mañana transcurrió en un silencio frustrante. Nada se movía en el Valle, ni siquiera una brisa. Por la tarde, la expedición se había vuelto inquieta Barnil ya no caminaba con los pasos cautelosos de un depredador que rastrea una presa. Más bien caminaba torpemente por el sendero, a menudo pisando ruidosamente hojas secas o ramas caídas." },
		[160] = { file = "160", len = 26.619, text = "En uno de esos pasos en falso, Erlgadin puso una fuerte mano sobre el hombro de Barnil. Ajeck y yo le echamos una mirada despreocupada, suponiendo que el hombre simplemente estaba regañando a Barnil por su descuido. Sin embargo, Erlgadin señaló lentamente con la cabeza hacia un árbol caído cercano. Nos devolvió la mirada con dos penetrantes ojos negros justo por encima de una boca llena de colmillos afilados como cuchillas." },
		[161] = { file = "161", len = 30.276, text = "La bestia era un tigre de Stranglethorn macho. Antes de que pudiera amartillar mi rifle, Erlgadin levantó su ballesta y disparó contra la bestia. El proyectil no dio en el blanco y alcanzó a la bestia en el flanco izquierdo. El tigre hizo un vano intento de huir, pero su herida era demasiado grave. La bestia se tambaleó durante unos trágicos segundos hasta que Barnil terminó de matarla con un hachazo." },
		[162] = { file = "162", len = 20.062, text = "La matanza provocó un ambiente festivo entre la expedición. Barnil sirvió hidromiel para el disfrute de todos. Pero nuestra fiesta duró poco. Mientras preparábamos el cadáver para transportarlo al campamento base, nos sorprendió un horrible gruñido. En todos mis años nunca había oído nada tan espeluznante." },
		[163] = { file = "163", len = 22.805, text = "En lo alto de un precipicio rocoso, silueteado por el sol poniente, pude distinguir al mayor felino de presa que jamás había visto. Pude soltar una torpe descarga con mi rifle, pero el felino se mantuvo firme. Volvió a gruñir, esta vez más fuerte que la primera vez, y desapareció. Recogimos nuestras pertenencias y nos dirigimos solemnemente de vuelta al campamento." },
		[164] = { file = "164", len = 17.58, text = "Había prometido a la expedición que pasaríamos el día siguiente cazando panteras, ya que sus pieles son muy demandadas en todo Azeroth. Es lógico que exista tal demanda, ya que todos los cazadores, tramperos y comerciantes de pieles están dando su vida valientemente en nombre de la Alianza." },
		[165] = { file = "165", len = 16.091, text = "Ajeck y Sir Erlgadin estaban ansiosos por aprender a cazar eficazmente con un rifle enano. Hice que los dos humanos dejaran sus primitivas armas de alcance en el campamento base. Barnil y yo los equipamos con algunas de las mejores armas de fuego de Ironforge." },
		[166] = { file = "166", len = 31.922, text = "Este día nos aventuramos hacia el sur, siguiendo unas huellas frescas de pantera. Pronto llegamos a un barranco atravesado por un tremendo puente de cuerda. No pude evitar pensar en los escritos descriptivos de Brann sobre esta región cuando vi aquella maravilla de la ingeniería. A menudo se suponía que los gnomos nativos eran una raza primitiva e inculta, pero al contemplar la maestría artesanal del puente pude reconocer la habilidad con la que los constructores gnomos superaron la hazaña aparentemente imposible." },
		[167] = { file = "167", len = 34.586, text = "Al poco tiempo, Ajeck rastreó a la pantera hacia el suroeste. Caminábamos en silencio, con las armas preparadas, a la espera de nuestra presa. Un chasquido de ramas procedente de un bosquecillo cercano llamó nuestra atención de inmediato. Algo había allí. Una mirada severa a Barnil bastó para transmitir mis pensamientos. Barnil bajó lentamente el rifle. Esta presa no era para nosotros, sino para nuestros compañeros humanos. Incontables panteras habían perdido la vida ante nuestros humeantes cañones. Esta matanza sería para los humanos." },
		[168] = { file = "168", len = 25.077, text = "Tanto Ajeck como Sir Erlgadin estaban preparados, con las armas apuntando a la maleza erizada en la base de los árboles que se balanceaban. El sol del mediodía nos golpeaba con fuerza. Una lenta gota de sudor se deslizaba por la sien de Elrgadin mientras tiraba del pasador hacia atrás. Al oír el chasquido, la espesa flora se abrió y una gran pantera negra, un hermoso espécimen, se lanzó a la llanura." },
		[169] = { file = "169", len = 31.164, text = "Los humanos apuntaron a la pantera mientras corría por el borde de la arboleda. Los cañones de sus armas se movían en perfecto tándem paralelo. Barnil me lanzó una mirada apremiante, pero negué con la cabeza. Esta cacería era para los humanos, no para Barnil ni para mí. Erlgadin disparó con fuerza y no alcanzó a la pantera. Al parecer, no estaba preparado para el violento retroceso de la ráfaga del rifle." },
		[170] = { file = "170", len = 33.646, text = "Su arma se agitó violentamente en sus brazos. El cañón se inclinó hacia un lado y apareció bajo el rifle de Ajeck. Ajeck había elegido ese momento exacto para apretar el gatillo. El rifle, que ahora apuntaba torpemente hacia la línea de árboles, se disparó con un claro estampido. Una bandada de pájaros salió gritando de la copa de los árboles y se dispersó en todas direcciones. Una columna de humo se elevó del árbol. Vimos con asombro cómo una tremenda rama caía de lleno sobre la pantera que huía, rompiéndole la espalda." },
		[171] = { file = "171", len = 27.794, text = "Con el paso de las semanas, nuestra reserva de pieles de pantera y tigre se hizo inmensa. Decidí que era hora de que la expedición se centrara en un nuevo reto: Rapaces. Los humanos, aunque apreciaban el entrenamiento que Barnil y yo les ofrecíamos, decidieron abstenerse de cazar con armas de fuego. Ajeck se sentía mucho más cómodo con un arco bien tensado y Sir Erlgadin nunca salía del campamento sin su robusta ballesta." },
		[172] = { file = "172", len = 35.213, text = "Salimos con las primeras luces del día, en dirección sur, más allá de las ruinas de Tkashi. Barnil expresó su preocupación por si nos encontrábamos con miembros de la tribu de los Escalpos Sangrientos. Le recordé a Barnil que los Bloodscalps estaban más preocupados por destruir a su enemigo tribal, los Skullsplitters. Ni que decir tiene que Barnil no se tranquilizó lo más mínimo. Yo, sin embargo, llevaba conmigo un rifle cargado, una mochila llena de pólvora y tres mortíferos cazadores para aliviar cualquier preocupación de una emboscada poco amistosa." },
		[173] = { file = "173", len = 31.843, text = "He estado frente a un imponente Infernal en el campo de batalla, el ejército de la Legión Ardiente avanzando desde todas direcciones. Una revoltosa banda de Trolls parece tan inofensiva como una liebre en las colinas de Dun Morogh. Pasamos las Ruinas de Tkashi sin incidentes, para alivio de Barnil. El grupo procedió a dirigirse hacia el oeste, hacia el Gran Mar, bordeando las Ruinas de Zul'Kunda justo al sur. Mientras ascendíamos por los altos acantilados del mar, avistamos nuestro primer Raptor." },
		[174] = { file = "174", len = 31.269, text = "La bestia ni siquiera detectó nuestra presencia. De hecho, el único saludo que recibió de la expedición fue una bala entre los ojos. Sir Erlgadin soltó un sonoro *hurrah* mientras Ajeck asentía hacia mí con entusiasta aprobación. Rebusqué en mi mochila en busca de mi pipa, con la esperanza de disfrutar de una fumada de celebración. Barnil empezó a correr ladera arriba para recuperar el cadáver del Raptor. Me quedé mirando a la bestia caída con la satisfacción que acompaña a toda gran matanza." },
		[175] = { file = "175", len = 25.339, text = "Pero no pude disfrutar de la gloria de la matanza durante mucho tiempo. Cuando volví los ojos hacia el horizonte, aparecieron varias siluetas coronando la colina, justo por encima del pobre Barnil. *¡Huye, Barnil!* grité. Ajeck, Sir Erlgadin y yo soltamos una andanada de balas, flechas y virotes sobre Barnil y hacia las rapaces perseguidoras. Uno de nosotros mató en medio de la confusión." },
		[176] = { file = "176", len = 12.173, text = "Nuestros disparos apresurados fueron suficientes para comprar la huida de Barnil. Barnil bajó la colina y se reunió con el grupo. Nos escabullimos en la selva Los cazadores eran ahora los cazados." },
		[177] = { file = "177", len = 24.764, text = "Conduje al grupo hacia el mar, con la esperanza de que la costa nos proporcionara refugio de los rapaces. Con las prisas, nos habíamos desviado demasiado hacia el norte, a una altura precaria. El error estaba cometido. La culpa fue mía. Nos detuvimos justo al lado de un acantilado escarpado, los Raptors a pocos pasos detrás." },
		[178] = { file = "178", len = 22.596, text = "Avancé lentamente, con el arma en alto. Había llevado a estos valientes cazadores a la muerte. Moriría defendiéndolos. Las rapaces de cola blanca son particularmente feroces, conocidas por su implacable sed de sangre. Nos superaban en número. Pero que me condenen si dejo que me maten a mí y a mis compañeros sin derramar algo de su propia sangre primero." },
		[179] = { file = "179", len = 19.931, text = "Ajeck y Sir Erlgadin prepararon sus armas, flanqueándome por ambos lados, de espaldas al mar. Barnil soltó un suspiro derrotado y desenvainó su hacha. Los Lashtail estaban casi sobre nosotros. Su paso firme se había ralentizado. Ahora acechaban a su presa, pues sabían que nos tenían atrapados." },
		[180] = { file = "180", len = 25.208, text = "Y entonces ocurrió algo milagroso. A nuestro lado oímos el rugido claro y aterrador del gran tigre blanco. A pesar de su número, las rapaces se dieron la vuelta y se dispersaron en todas direcciones. Sólo vimos un breve destello blanco cuando el tigre pasó a nuestro lado y se abalanzó sobre una de las rapaces. No fue necesario dar ninguna orden. Los cuatro miembros de nuestro grupo sabían que era hora de huir." },
		[181] = { file = "181", len = 30.877, text = "Esprintamos hasta el campamento base sin aflojar el paso. Más tarde, esa noche, nos sentamos tranquilamente alrededor de la hoguera, sabiendo que nuestras vidas se habían salvado por un extraño giro del destino. Tales son los riesgos del cazador de caza mayor. Jugamos con el destino entregándolo. Sin embargo, cada uno de nosotros, en algún momento, se enfrentará a los afilados dientes del destino. Este enano se alegra de que ese momento no haya llegado en las verdes colinas de Stranglethorn." },
		[182] = { file = "182", len = 31.347, text = "Honorables compañeros y sabios buscaverdad La excavación continúa, pero su ritmo ha disminuido debido a los troggs que mencioné en mi último informe. Confío en que los neutralizaremos, aunque algunos son más agresivos de lo habitual. Recientemente se encontraron más artefactos, si bien en todos los casos, salvo en uno (que en breve detallaré), los recientes hallazgos tienen la misma relevancia que los anteriores: son interesantes, pero no esclarecedores." },
		[183] = { file = "183", len = 30.145, text = "Hubo una excepción. Los ídolos tallados recientemente encontrados (una breve descripción de los mismos aparece en mi último informe) parecen afectar de algún modo a los troggs. Se sienten atraídos por la talla en piedra y algunos troggs enloquecen ante su presencia. Es preciso estudiar este fenómeno con mayor profundidad para llegar a una conclusión válida en relación con estos ídolos, si bien espero que el estudio arroje luz sobre un posible vínculo entre los troggs y los titanes." },
		[184] = { file = "184", len = 23.432, text = "Finalmente, debo reiterar mi petición para que se me suministre más pólvora. Mis suministros son muy escasos, lo que dificulta seriamente el éxito de la excavación. Me dijeron que un nuevo suministro de pólvora estaba en camino, sin embargo aún no he recibido nada. ¿Puedo preguntar a qué se debe este retraso? Respetuosamente, Prospector Darteus Vetaferro" },
		[185] = { file = "185", len = 23.171, text = "Todo empezó con el hallazgo de esa maldita guadaña en la Condena de Roland. Antes de que apareciera la guadaña, los terrores de este lugar parecían tan mansos como el valle de Villanorte. Pero desde que encontré el mango de la guadaña sobresaliendo entre la pila de escombros en la mina y lo saqué de ahí, ¡ay de mí!, ¡la Condena de Roland se ha convertido en un lugar de destrucción y muerte!" },
		[186] = { file = "186", len = 31.895, text = "Comenzó con el hallazgo de esa guadaña maldita en la mina que llaman la Perdición de Roland. Sí, ese fue el comienzo. Antes de eso, la Hermandad Defias estaba contenta con nuestro progreso en Duskwood. Antes de la Guadaña, los terrores de este lugar parecían tan mansos como el Valle de Northshire. Pero desde que encontré la empuñadura de la Guadaña sobresaliendo de aquel montón de escombros en la mina y, maldita sea, la liberé, ¡La Perdición de Roland se convirtió en un lugar de vil muerte!" },
		[187] = { file = "187", len = 28.813, text = "Si hubiera sabido lo que iba a pasar, me habría cortado la mano para no agarrar aquella madera tallada con runas. ¡Cuántos remordimientos! Siempre pensé que eso era un privilegio de los viejos. Ahora sé que no son los viejos, sino los desahuciados, quienes llevan el manto del arrepentimiento, incapaces y reacios a encogerse de hombros encorvados por la miseria. Pero basta de hablar como un poeta loco. Debo continuar con la crónica..." },
		[188] = { file = "188", len = 36.859, text = "Una vez liberada la Guadaña, se produjo un cambio en la mina. La luz de nuestras vacilantes antorchas se deformaba y la fuerza de nuestras voces parecía escapar a nuestro control. A veces el susurro de un hombre rugía a través de los túneles obligando a las manos a taparse los oídos, y a veces nuestros gritos apenas recorrían unos pasos antes de reducirse a una insinuación en el viento. Inquietante, sí, pero no tuvimos mucho tiempo para asombrarnos de esta extrañeza. No era más que un presagio de lo que realmente nos sacó de la mina. Los Worgen." },
		[189] = { file = "189", len = 30.041, text = "Nos atacaban por todas partes, arañando desde agujeros ocultos a nuestros pies y cayendo sobre nosotros desde silenciosas perchas. La mitad de nuestros hombres cayeron en esos primeros minutos de pánico. El resto, incluido yo mismo, intentamos huir. Mientras corría, vi a muchos de mis hermanos atrapados por los dientes y las garras, oí muchos gritos que se entrecortaban o gorgoteaban hasta el silencio. Por lo que sé, soy el único ser humano que escapó de aquel lugar." },
		[190] = { file = "190", len = 32.836, text = "Sólo puedo adivinar por qué sobreviví aquella noche. Siempre he sido precavido, siempre me he apresurado a alejarme de los golpes y a saltar de las trampas. Mi apodo, Jitters, proviene de este rasgo. Así que tal vez fue ese don para la cautela lo que me salvó... O tal vez fue la guadaña que saqué de los escombros. No puede ser la guadaña en sí, porque la perdí durante mi frenética huida. Pero si fui yo quien trajo a los Worgen a Duskwood, entonces tal vez los Worgen me dieron una rara cortesía. Malditos sean." },
		[191] = { file = "191", len = 28.055, text = "O tal vez, estoy condenado a presenciar el cambio que he provocado en Duskwood. Tal vez mi destino sea ver cómo los Worgen desgarran esta tierra, tiñéndola cada vez más de oscuro con su inmundicia. Si ese es realmente mi destino, entonces es doble. Porque los Worgen no son el único poder que se aferra a Duskwood - los demonios de Deadwind Pass también han reclamado. Ese es el próximo capítulo de mi historia, y ruego que sea el último..." },
		[192] = { file = "192", len = 32.157, text = "Tras sobrevivir a la huida de la Perdición de Roland, me escondí en un granero propiedad de un hombre llamado Sven. Pasé unos días en el granero, y tal era el horror que me invadía que ni una sola vez me di a conocer a Sven o a su familia. Pero por lo que vi desde mi escondite, supe que estos granjeros eran gente bastante decente. Si hubiera salido de mi escondite, creo que me habrían aceptado, pero me cuesta confiar. Más difícil aún después de ese shock en la mina. Así que permanecí oculto. Y eso me salvó la vida." },
		[193] = { file = "193", len = 31.242, text = "Pocos días después de mi llegada al granero, Sven abandonó su granja rumbo a Darkshire. Besó a su mujer, sonrió a sus hijos y prometió volver pronto con juguetes y caramelos. Pobre hombre. Esa fue la última vez que vio a su familia sin ser mutilado. Al menos se separaron felizmente. Y al menos su esposa fue la primera en morir, y se libró de ver la matanza de sus hijos. Pero estas pequeñas gracias no hacen nada por mí. Vi lo que pasó, y siempre atormentará mis sueños." },
		[194] = { file = "194", len = 34.403, text = "Me tiembla la mano al recordar los detalles de aquella noche, cuando Sven estaba ausente y su familia estaba condenada a enfrentarse sola a los Jinetes Negros. De nuevo me asalta el remordimiento, porque yo estaba allí y podría haberme levantado contra esos demonios del Paso del Viento Muerto. Pero es un falso remordimiento. Es el mismo que atormenta a cualquier superviviente de una tragedia. Sé que, si hubiera abandonado mi escondite, también me habrían matado, mi cuerpo se habría desgarrado y sus pedazos se habrían esparcido tanto que no me habrían reconocido." },
		[195] = { file = "195", len = 32.052, text = "Pero, aunque sé que no podría haber hecho nada para impedir este atroz asesinato, queda un verdadero remordimiento: Yo traje a los Jinetes Negros a la granja de Sven. Mi descubrimiento de la Guadaña no sólo desató a los Worgen en Bosque Nublado, sino que atrajo a los Jinetes del Paso del Viento Muerto. Lo sé porque, justo antes de comenzar su matanza, le hicieron una pregunta a la esposa de Sven mientras abrazaba a sus hijos, dándoles el consuelo que podía aunque estaba segura de que la muerte estaba cerca." },
		[196] = { file = "196", len = 31.556, text = "\"La Guadaña de Elune\", chilló uno de los Jinetes con voz áspera y chillona, como el rechinar de un hacha sobre la piedra. Y la última palabra -Elune- graznó, como si se ahogara con el sonido. El pavor se apoderó de mí al oír aquella voz, tanto por su horrible sonido como porque... conocía la Guadaña de la que hablaba el Jinete. Debía de ser la misma cosa maldita que saqué de las rocas de la Perdición de Roland días atrás. Era lo que buscaban los Jinetes Negros. Y era lo que mataría a la familia de Sven." },
		[197] = { file = "197", len = 32.444, text = "Nunca supe el nombre de la mujer de Sven, ya que su marido y sus hijos sólo la llamaban \"querida\", \"mi amor\" y \"mamá\". Pero me gustaría saberlo. Soy el único recuerdo vivo de su hazaña de aquel día, y aunque no era más que la esposa de un granjero, nunca he visto a un hombre o a una mujer actuar con tanta valentía. Por supuesto que ella no sabía de la Guadaña, pero cuando supo que los Jinetes la buscaban, en un instante un plan se formó en su cabeza. Y fue audaz e inteligente. Ojalá hubiera funcionado." },
		[198] = { file = "198", len = 29.936, text = "\"¿La Guadaña?\", dijo con voz tranquila. \"Por supuesto que sí. ¿Quién de aquí no lo haría?\" Miró a los Jinetes con ojos firmes y habría jurado que decía la verdad si no lo hubiera sabido. Era imposible que supiera lo de la Guadaña. Su táctica dio resultado. El mismo Jinete que había formulado la pregunta inclinó ligeramente la cabeza hacia ella y gritó: \"¿Dónde?\". \"Os llevaré. A todos\", dijo ella, y pude ver un pequeño destello de esperanza tras sus ojos." },
		[199] = { file = "199", len = 32.914, text = "\"Pero el camino es largo, y mis hijos nos retrasarían. Debemos dejarlos\". Su truco era simple, pero los trucos simples tienen la mejor esperanza de éxito. Si funcionaba, llevaría a los Jinetes lejos de la granja. Ella estaría perdida, pero sus hijos estarían a salvo. Y funcionaría, si tan sólo los Jinetes creyeran sus nobles mentiras. Aunque nunca he sido un estudiante de la Luz, recé ferozmente por la esposa de Sven mientras se enfrentaba a esos terribles Jinetes. \"Por favor\", recé. \"Deja que crean\"." },
		[200] = { file = "200", len = 33.254, text = "Se quedaron inmóviles y ella los miró con calma. Entonces, un jinete levantó la vista, como si oyera una llamada lejana. Sacó de su atuendo una pequeña gema y miró en su interior. Luego hizo un gesto con la gema hacia la esposa de Sven. Una luz se deslizó desde el jinete hacia la mujer, formando una mano blanca y sombría. Ella miró fijamente a la luz, sin inmutarse, pero yo pude ver incertidumbre tras su máscara de confianza. Cuando la mano la alcanzó, extendió los dedos sobre su cabeza. Y apretó." },
		[201] = { file = "201", len = 28.865, text = "La mujer de Sven se quedó rígida como una tabla y abrió mucho los ojos. Y aunque sus labios se retrajeron para emitir un grito, no se le escapó ningún sonido. Tras unos instantes de tortura, la mano la soltó y la dejó caer de rodillas. El jinete que sostenía la baratija se sentó entonces erguido en su montura, y de ella brotó una fuerte voz. \"Esta mujer miente\", dijo con una voz que ha marcado mis sueños. \"Ella no ha visto la Guadaña\"." },
		[202] = { file = "202", len = 15.726, text = "Tras esto, los hombros del Jinete se encorvaron ligeramente, como si un espíritu de su interior hubiera huido. Y entonces, con la voz vieja y chillona que usó antes, pronunció estas últimas palabras: \"El Señor ha hablado. Matadlos\"." },
		[203] = { file = "203", len = 33.019, text = "No puedo describir lo que sucedió a continuación. Está claro en mi mente, pero ni siquiera mi desdichada alma puede poner por escrito los acontecimientos de los siguientes y espeluznantes minutos. Sólo puedo escribir que la familia de Sven fue asesinada. Y poco después, Sven regresó a esta escena sombría y mortal. Había tal dolor en él que yo tenía miedo de mostrarme. Y tanto miedo tenía de que me encontrara, que huí de mi escondite en el granero. No sé dónde está Sven ahora, pero rezo para que algún día encuentre la paz." },
		[205] = { file = "205", len = 27.037, text = "Después de liberar la Guadaña, emergieron desde todos los rincones, clavando sus zarpas en nuestros tobillos desde ocultos agujeros, o cayendo sobre nosotros desde lo alto. La mitad de nuestros hombres cayeron en esos primeros minutos de pánico. El resto, entre los que me incluyo, intentaron escapar. A medida que corría, veía a mis hermanos atrapados por la zarpa y el colmillo, oí tantos alaridos truncados o desvaneciéndose en el silencio." },
		[206] = { file = "206", len = 32.47, text = "Solo puedo suponer por qué sobreviví aquella noche. Siempre he sido cuidadoso, rápido a la hora de escapar de las fauces de alguna bestia, o cuando se trataba de saltar algún escollo. Mi sobrenombre tiene que ver con esta característica. Así que tal vez fue el don de la prudencia el que me salvó... O tal vez fue la guadaña que extraje de los escombros. No puede ser la guadaña, puesto que la perdí durante mi frenética huida. Pero si fui yo quien atrajo a los ferocanis al Bosque del Ocaso, quizás me hayan hecho un extraño obsequio. ¡Los maldigo!" },
		[207] = { file = "207", len = 32.522, text = "Tras sobrevivir a la huida de la Condena de Roland, me oculté en el granero de un hombre llamado Sven. Pasé unos cuantos días en el granero y aquel horror caló tan hondo en mí que nunca me presenté ante Sven o su familia. Pero considerando lo que vi desde mi escondite, me di cuenta de que aquellos granjeros eran personas bastante decentes. De haber salido de mi refugio, seguramente me habrían aceptado, pero me cuesta confiar en los demás. Y mucho más después de aquella impresión en la mina. Así que permanecí escondido." },
		[208] = { file = "208", len = 2.116, text = "El resto del libro está en blanco" },
		[209] = { file = "209", len = 27.533, text = "INFORME: Kobolds La actividad de los kobolds ha aumentado en las cercanías del valle de Villanorte. Un alarmante número de ellos acampa al norte de la abadía y dentro de la Mina del Eco. He reunido a paladines y a otros habitantes de la zona para limpiarla de estas alimañas. La labor progresa adecuadamente. Yo, por mi parte, modernizaré el sistema si es necesario." },
		[210] = { file = "210", len = 22.439, text = "INFORME: Ladrones Más peligrosos que los kobolds, una banda de ladrones humanos ha surgido del valle. Llevan pañuelos rojos y se consideran una hermandad. Su nivel de organización puede generar problemas, aquí y en el bosque de Elwynn. Hemos identificado a uno de sus líderes, un tal Garrick Piesuaves, al que esperamos llevar pronto ante el tribunal." },
		[211] = { file = "211", len = 20.793, text = "INFORME: Lobos Según los informes, los ataques de estos animales han aumentado en Villanorte. Eagan cree que los lobos que hay en el valle fueron desterrados desde el Bosque del Ocaso. Aunque los lobos rara vez cazan humanos, su elevado número provocó ciertos incidentes con los granjeros. Y varias piezas de ganado desaparecieron." },
		[212] = { file = "212", len = 21.394, text = "DISTINCIÓN: El portador de estos documentos será condecorado con el rango de Ayudante de Alguacil del ejército de Ventormenta, por haber servido a Villanorte con entusiasmo y especial atención. Confío en que esta persona os resulte útil en el bosque de Elwyyn. Firmado: Alguacil Douglas McBride, Ejército de Ventormenta, Villanorte" },
		[213] = { file = "213", len = 20.167, text = "Estofado de Páramos de Poniente 3 partes de carne fibrosa de buitre 3 morros de dentosangre 3 ojos de múrloc 3 okras Mezclar todos los ingredientes y poner a hervir. Hervir a fuego lento al menos durante dos horas antes de servir." },
		[214] = { file = "214", len = 23.85, text = "Querida Yvette, Encomendaré esta carta a nuestra corredora más veloz. Espero que pueda avanzar sin contratiempos por las zonas en que habitan las fuerzas que nos rodean. También ruego para que puedas leer estas palabras, pues son lo último que sabrás de mí. Mi único consuelo en estos días aciagos es el alivio que me produce saber que no tendrás la misma suerte que yo." },
		[218] = { file = "218", len = 33.437, text = "Temo que la guerra entre los Campopétreo y los Maclure acabe con el incipiente romance entre Tommy Joe y Maybell, así que, en tiempos como estos, en los que los rumores de guerra se ciernen sobre nosotros, es preciso cultivar la juventud y el amor. De ahí el favor que te pido: Te pido que uses tus habilidades y fabriques una poción o elixir para ayudar a estos dos jóvenes en su misión de reunirse. Gracias, William. Y por favor, si puedes apartarte un poco del trabajo, ven a visitarme. Te invito a que nos riamos un poco recordando el pasado. Mildred" },
		[219] = { file = "219", len = 34.116, text = "De la mano de Baros Alexston, Oficina del Arquitecto de la Ciudad de Stormwind Su Majestad, Hay muchas razones por las que sentí que un informe debía ser compilado y presentado sobre los recientes asuntos de la \"Hermandad Defias\" y sus actividades en todo el reino. Para tener una perspectiva, comenzaré con un poco de historia. Como sabrás o no, mi servicio a la ciudad de Stormwind comenzó como miembro del Gremio de Canteros. Tras años de trabajo, completamos la reconstrucción de" },
		[220] = { file = "220", len = 35.5, text = "Stormwind, momento en el que las facturas, honorarios y salarios del Gremio de Stonemasons quedaron impagados y sin pagar. Por aquel entonces, Edwin VanCleef había sido elegido Maestro del Gremio de Canteros y se manifestó exigiendo la restitución de nuestras obras. En respuesta, la Casa de Nobles de Stormwind ordenó la disolución del gremio de Canteros, lo que, comprensiblemente, enfureció a VanCleef. Encabezando un motín, VanCleef expulsó a los Canteros de la ciudad. Antes de continuar, hay otros acontecimientos que tuvieron lugar durante" },
		[221] = { file = "221", len = 30.276, text = "esta vez que debo llamar su atención. En primer lugar, fue entonces cuando me ofrecieron el puesto de arquitecto de la ciudad si no me unía a VanCleef. Debido a ciertas diferencias idealógicas, elegí permanecer en Stormwind. Durante los disturbios, el lugarteniente y ayudante de mayor confianza de VanCleef, Bazil Thredd, fue capturado y encarcelado. A la espera de juicio e interrogatorio, Thredd quedó casi olvidado en la Empalizada. Volviendo a VanCleef, después de que dirigiera a los restos de la" },
		[222] = { file = "222", len = 29.048, text = "Canteros fuera de Stormwind, aprovechó la relativa desprotección de Westfall y utilizó su considerable mano de obra para expulsar a muchos de los granjeros y apoderarse del puñado de minas de oro. Aprovechando los recursos de que disponía, VanCleef urdió un plan de venganza contra el gobierno de Stormwind. Esta información ha salido a la luz recientemente con la ayuda del portador de este documento, que ha sido fundamental para arrojar luz sobre esta vasta conspiración." },
		[223] = { file = "223", len = 35.239, text = "Difundid esta información todo que consideréis necesario. Comando Regional de Tirisfal Capitán Melrose Capitán Vachon Capitán Perrine Órdenes del Gran Señor. Capitán Perrine, es preciso reforzar vuestras posiciones en la torre del sudoeste (tal como se especificó anteriormente). En envíos posteriores mandaremos suministros adicionales. Mientras tanto, deberán obtenerse en las granjas vecinas. Asimismo, es preciso realizar nuevos trabajos de reconocimiento, al tiempo que" },
		[224] = { file = "224", len = 28.108, text = "deberá reunirse información sobre la organización de los no-muertos en Brill. Capitán Vachon, al parecer, los no-muertos han intensificado sus maniobras cerca de la torre del norte. Hay que contener esta rebelión de forma rápida y contundente. Capitán Melrose, nos preocupa el nivel de organización de los no-muertos cerca de las fronteras de las Tierras de la Peste. En las próximas semanas le enviaremos un nuevo contingente de hombres. Gloria a todos en la Luz" },
		[229] = { file = "229", len = 22.361, text = "Día 1 Mi tanque está roto, pero sé que el mineral de Quirón está en alguna parte de estas colinas. Le dije a Hammerfoot que se quedara y vigilara nuestros tanques. Voy a continuar la búsqueda solo. Si no regreso, este diario será mi último testamento. --Buron Hildelve, Piloto Brigada de Vapor de Ironforge" },
		[230] = { file = "230", len = 23.014, text = "Día 2 Mi búsqueda continúa, y no hay mineral. Me pregunto si Stonegear estaba inventando el rumor de ese mineral como una broma. Bueno, si lo hizo, entonces tendrá un cráneo roto cuando regrese al depósito de Steelgrill. Esta noche, mientras preparaba mi campamento, oí un gruñido que resonaba en los cañones. No es un lobo. Puede ser un oso." },
		[231] = { file = "231", len = 13.349, text = "Día 3 Ese gruñido continuó durante toda la noche, y me siguió todo el día de hoy, distrayéndome de mi búsqueda de mineral. ¡Creo que me sigue un oso! Espero que se acerque. ¡Le enterraré mi pico en la cabeza!" },
		[232] = { file = "232", len = 26.54, text = "Día 4 Me estoy quedando sin provisiones. Todavía tengo comida de sobra, pero no había planeado una estancia tan larga en la naturaleza fuera de mi tanque y sólo he traído dos barriles de cerveza. He pasado las dos últimas noches en vela, escuchando ese maldito gruñido, ¡y casi he agotado mis barriles! Mañana tendré que volver a Hammerfoot y a nuestros Tanques de Vapor. No quiero perderme aquí, sin alcohol." },
		[233] = { file = "233", len = 26.227, text = "Día 5 El oso maldito me ha matado. Me atacó a mediodía, rugiendo y atacándome por la espalda. Lo habría olido si me hubiera atacado de frente, ¡su hedor era espantoso! El hedor de su pelaje sarnoso y su aliento putrefacto casi me hacen perder el conocimiento. Luché contra él, pero me destrozó la pierna. Ahora no puedo moverme, mi cerveza ha desaparecido y nunca encontré el mineral. ¡Maldición!" },
		[234] = { file = "234", len = 24.869, text = "Día 6 El oso aún no ha vuelto, ¡le habré dado una buena paliza! Pero aún oigo sus gruñidos. Creo que está esperando a que me muera. A quien encuentre este libro, le tengo una tarea. Mata a ese oso sarnoso. Mátalo, y llévale este libro a mi amigo Hammerfoot. Él querrá saber qué pasó. Y toma mi armadura. ¡La necesitarás contra el viejo Mangeclaw!" },
		[235] = { file = "235", len = 33.411, text = "Saludos Ello Ebonlocke, Alcalde de Darkshire. Me temo que tengo noticias para su ciudad. Graves noticias. Verás, soy un creador. Engañé al portador de esta nota para que me ayudara en mi última y más terrible creación: ¡un demonio de carne, hueso y metal retorcido! Mientras lees esto, es probable que esté fuera de mi humilde morada, rechinando los dientes y esperando mi palabra para salir a masacrar. Pero pronto lo sabrás. -El embalsamador" },
		[236] = { file = "236", len = 22.282, text = "A través del estudio de varias criaturas fosilizadas he deducido que, en la antigüedad, una gran plaga arrasó las aguas del lago Lordamere. ¿Qué causó esto? Puede que nunca lo sepamos. Pero la tasa de contaminación parece ser extremadamente alta según las densas concentraciones de restos distribuidos por el lecho del lago." },
		[237] = { file = "237", len = 28.264, text = "En un intento por desvelar el pasado, he empezado a examinar las criaturas del presente con la esperanza de encontrar la pista que falta para este misterio. Los Skulkers del Lago y los Creepers del Lago son bestias antiguas que habitan en las islas del centro del lago Lordamere. En ellas crece un musgo que se asemeja a los rastros de algunos fósiles. Es necesario investigar más antes de poder especular sobre el significado de esta conexión." },
		[238] = { file = "238", len = 33.933, text = "Mientras intentaba recoger muestras de musgo, me topé con el escenario de una sangrienta batalla. La tribu de Murlocs de Vile Fin había sido asediada por una banda de Gnolls. Había cadáveres de gnolls y de murlocs esparcidos por el campo de batalla. Al pasar junto a un cuerpo destrozado de un murloc, me fijé en un extraño tumor endurecido que sobresalía de la herida. Cuando empecé a estudiar el tumor, me di cuenta de que tenía propiedades similares a las del musgo que estaba recogiendo. Por desgracia, no pude encontrar más tumores aparte de ese." },
		[244] = { file = "244", len = 22.256, text = "Lord Bethor Duroyelo, Siguiendo vuestras instrucciones, os mando al agente que habéis solicitado. Es el portador de esta nota. Esta persona ha demostrado ser de fiar, es capaz de seguir órdenes y puede enfrentarse a las fuerzas de la Plaga, por lo que lo he elegido para vuestra misión. Por la gloria de la Reina, Magistrado Sevren" },
		[245] = { file = "245", len = 30.119, text = "Desaparecido: Cabo Keeshan Visto por última vez durante la sangrienta batalla de la Fortaleza de la Guardia de Piedra, el Cabo Keeshan fue arrastrado por los Orcos de Blackrock. Se cree que el Cabo Keeshan está retenido como prisionero de guerra en el campamento de Blackrock al norte de Lakeshire, justo al oeste del paso que lleva a las Estepas Ardientes. Por mandato del Magistrado Solomon, cualquiera que ayude en la recuperación del Cabo Keeshan será recompensado por el Mariscal Marris." },
		[246] = { file = "246", len = 32.13, text = "Pasé las siguientes semanas moviéndome de un lugar a otro, sin quedarme nunca por miedo a los Jinetes. Ahora estoy en el pueblo abandonado de Colina del Cuervo, como siempre, escondiéndome. No puedo enfrentarme al poder que usaron contra la esposa de Sven, y sé que busca en Duskwood, incluso todavía, la Guadaña. La he perdido, y doy gracias a la Luz por ello, porque si la hubiera conservado sé que me habrían encontrado. Incluso ahora, sé en mi corazón que seré encontrado. Estoy tan cansado." },
		[248] = { file = "248", len = 25.809, text = "Saludos, Maestro, Perdóneme por el método de envío de este mensaje. Mis magos de las sombras en Alterac están concentrados en sus tareas, forzándome a usar un mensajero extranjero -- reclutado entre nuestros nuevos \"aliados\" -- para traerle este informe. Pero he encriptado esta carta con una de nuestras claves más esotéricas. Sus palabras están a salvo de estos paletos." },
		[249] = { file = "249", len = 29.205, text = "Valik, Vigila al esclavo hasta nuestro regreso. No es seguro mantenerlo aquí por más tiempo. Lo moveremos al norte, más lejos de cualquier posibilidad de ser visto. Son animales, pero no dejan de ser animales brutales... si fueran bastantes, tendríamos motivos para preocuparnos. Es mejor ocultar cualquier señal que los provoque. Lo último que queremos darles es una razón para unirse y atacarnos con fuerza." },
		[250] = { file = "250", len = 26.854, text = "Un grupo procedente del puesto de mando de los Defias se pondrá en contacto con el Coleccionista y él trasladará el oro recogido. Asegúrate de que este proceso se lleve a cabo con cuidado y con la mayor discreción. El Coleccionista es responsable del traslado del oro, pero, en última instancia, es responsabilidad de todos los miembros de la Hermandad Defias garantizar que su papel se desempeñe con atención y disciplina." },
		[251] = { file = "251", len = 11.311, text = "Recordad, hermanos míos que un día fuimos orgullosos artesanos. Realizaremos nuestro trabajo con la misma precisión que utilizamos en nuestro oficio anterior. EVC" },
		[252] = { file = "252", len = 23.719, text = "Creo que mi padre cometió un grave error cuando decidió quedarse en casa para defenderla. Las fuerzas de la Peste asolan los Claros de Tirisfal y, aunque estamos fortificados y bien abastecidos, después de la traición de mi hermano Devlin carecemos de fuerza y tropas suficientes para hacer frente a sus continuos asaltos. Yvette, si recibes esta carta, deberás saber que Devlin es un traidor." },
		[253] = { file = "253", len = 27.35, text = "Devlin perdió las esperanzas e intentó escapar a nuestro infortunio, por lo que hizo un pacto con la Peste. No sé cual fue el precio de su traición, pero lo que sí puedo asegurar es que está basado en la mentira. Si ves a mi hermano, huye de él. Es un demonio. Hace un par de noches asesinó a dos de nuestros vigilantes y ayudó a un pequeño grupo de soldados de la Peste a entrar por la brecha, conduciéndolos hacia donde muchos de los nuestros dormían." },
		[254] = { file = "254", len = 31.086, text = "Su emboscada fue brutal. Asesinaron a un tercio de nuestras tropas antes de que pudiéramos responder. Ahora solo contamos con hombres para vigilar nuestras fronteras. Solo es cuestión de tiempo: en cuanto bajemos la guardia, la Peste nos atacará. Y aunque vi el rostro de Devlin en medio de todos esos hombres desesperados y las fuerzas de la Peste aquella noche maldita, se escabulló antes de que pudiera atraparlo. Tal vez esté muerto, o viva aún como agente de la Peste. En cualquier caso, es un monstruo." },
		[255] = { file = "255", len = 23.04, text = "Devlin nos advirtió que si intentábamos enfrentarnos a la Peste, estaríamos condenados. Nos lo dijo cuando entró por primera vez en los Claros de Tirisfal, antes de que rodearan nuestro hogar. Quizás estaba suplicando que nos marcháramos, o quizás se deleitaba. Siempre ha sido difícil comprender las razones de Devlin. Desde que era niño, siempre fue un misterio para nosotros." },
		[256] = { file = "256", len = 20.82, text = "Pero tenía razón. Estábamos perdidos. La familia Agamand está condenada a la desaparición. Aunque yo viva aún, sé que pronto moriré. No tengo miedo, pero no lamento reunirme con los míos. Debes saber que mi último pensamiento te lo dedicaré a ti. Sigue con vida, mi amada Yvette, para poder irme en paz, Thurman" },
		[257] = { file = "257", len = 18.677, text = "Nuestros planes progresan adecuadamente; como ya hemos mencionado, hemos establecido una alianza con un grupo de humanos que se hacen llamar el Sindicato. Sus líderes fueron una vez nobles de Alterac y ansían volver a dominar aquí. Y por eso han hecho un trato con nosotros. Un trato del que se arrepentirán." },
		[258] = { file = "258", len = 31.216, text = "En la actualidad, el Sindicato tiene poco poder en estas tierras, pero conoce bien la zona y ha reunido suficiente mano de obra para las tareas que tiene por delante. Con la guía adecuada, confío en que pronto el Sindicato volverá a gobernar Alterac. Además, hemos instado al Sindicato a apuntar a la ciudad de Stromgarde en las cercanas Tierras Altas de Arathi. La ciudad es un campo de batalla entre nuestras fuerzas, los ogros y los humanos de Stromgarde, pero creemos que con tácticas cuidadosas nos adueñaremos de esta otrora gran ciudad." },
		[259] = { file = "259", len = 17.659, text = "Y cuando esto esté hecho, podrá comenzar la siguiente fase de nuestro plan. Con una nación propia y una base de poder en esta región, podremos preparar el camino para la Tercera Hueste. Pronto, los Señores de la Legión recompensarán nuestro trabajo haciendo llover fuego desde los cielos una vez más." },
		[261] = { file = "261", len = 33.254, text = "Registro municipal de Hillsbrad Nosotros, el pueblo de Hillsbrad, juramos solemnemente nuestra fe y devoción a la Alianza mantenida por los grandes monarcas, el Rey Magni Bronzebeard de Ironforge y el Rey Anduin Wrynn de Stormwind. Aquí se encuentra el registro de la ciudad con el propósito de gobernar esta bella ciudad en las estribaciones de las grandes Montañas de Alterac, así como servir de registro de aquellos que han pagado sus impuestos a sus Reyes y a la gran todopoderosa Alianza." },
		[262] = { file = "262", len = 32.993, text = "Magistrado Rutherford Burnside Todas las deudas saldadas. Herrero Avery Verringtan Todas las deudas saldadas. Oficinista Horrace Whitesteed Todas las deudas saldadas. Concejal Gillis Todas las deudas saldadas. Concejal Hooks Todas las deudas saldadas. Granjero Getz Todas las deudas saldadas. Agricultor Ray Deuda pendiente. Pago en bienes agrícolas prometido en el momento de la cosecha. Agricultor Lyion Deuda pendiente. Desalojado de la tierra." },
		[263] = { file = "263", len = 30.537, text = "Agricultor Kalaba Deudas pendientes. Pago en bienes agrícolas prometido en el momento de la cosecha. Ciudadano Wilkes Todas las deudas pagadas. Ciudadano Bonoan Todas las deudas pagadas. Minero Wellty Deuda pendiente. Pago pendiente en la próxima entrega de mineral de Azurelode. Minero Sidney Deuda pendiente. Pago pendiente en la próxima entrega de mineral de Azurelode. Minero Hackett Deuda pendiente. Pago pendiente en la próxima entrega de mineral de Azurelode." },
		[265] = { file = "265", len = 24.66, text = "Minero Orwell Deuda pendiente. Pago pendiente en la próxima entrega de mineral de Azurelode. Minero Fitzgerald Deuda pendiente. Pago pendiente en la próxima entrega de mineral de Azurelode. Ciudadano Netherand Todas las deudas pagadas. Ciudadano May Todas las deudas pagadas. Capataz Bonos Deuda pendiente. Pago pendiente en la próxima entrega de mineral de Azurelode." },
		[266] = { file = "266", len = 34.638, text = "\"Kegan Darkmar, líder de una pequeña banda de no-muertos que vino a vernos en busca de asilo para escapar de sus \"hermanos\", desafía nuestras actitudes habituales en relación con los de su especie. Puede que su piel se esté pudriendo o que la sangre hace tiempo que no fluye por sus venas, pero actúa con nobleza, mostrando más preocupación por la seguridad de sus compatriotas que por la suya propia. De hecho, percibo en él una humanidad que, siendo franco, a veces echo de menos en algunos humanos que conozco\"." },
		[267] = { file = "267", len = 28.97, text = "Pero, ¿por qué digo todo esto? Lo afirmo para dar credibilidad a lo que voy a escribir, ya que estas fueron palabras de Kegan y es mi deseo que, después de leer este diario, mis compañeros entiendan por qué creo en ellas: \"Vestigios de antiguos dioses yacen en las huecas profundidades del mundo. Ahora, las nuevas fuerzas intentan utilizar aquel antiguo poder, por lo que aquellos que lo consigan, tendrán en sus manos un arma terrible para combatir a sus enemigos.\"" },
		[268] = { file = "268", len = 32.366, text = "Eso fue lo que pronunció Kegan al entregarme su colgante de piedra de sangre, y había miedo, y quizá reverencia, en sus ojos al hacerlo. Y cuando sus manos se encontraron con las mías, se detuvieron, como si se resistieran a entregar el colgante. La repulsión me invadió, pero hasta el día de hoy no sé si me sentí vilipendiado por su carne muerta contra la mía o si el colgante en sí me erizó la piel. Porque sentí un poder dentro de él. Un poder profundo, oculto y hambriento. Y un anhelo de liberación." },
		[269] = { file = "269", len = 18.442, text = "Aunque mis colegas de Dalaran se mostraron cautelosos a la hora de estudiar las piedras de sangre que Kegan y sus seguidores traían consigo, poniendo en cuarentena a los cuatro refugiados y dejando las piedras de sangre sobre sus personas, la sinceridad de Kegan me obligó a estudiar su colgante de piedras de sangre." },
		[270] = { file = "270", len = 20.532, text = "Mis esperanzas eran comprobar para mis colegas que este tipo de piedra poseía propiedades mágicas, y si los magos de Dalaran no deseábamos explotar el poder de las piedras de sangre, al menos debíamos aprender sus propiedades, ya que nuestros enemigos podrían algún día utilizarlas contra nosotros. Y así comenzaron mis estudios." },
		[271] = { file = "271", len = 27.402, text = "Empecé mis pruebas suponiendo que la piedra de sangre era un tipo de roca, como el cuarzo o la obsidiana. Así que empecé una serie de procedimientos para determinar: qué minerales contenía la piedra de sangre, qué fuerzas se aplicaban para producir su color y dureza, y otras propiedades comunes a rocas y minerales. Pero el colgante de piedra de sangre, para mi frustración, no reaccionaba a mis procedimientos como lo haría un mineral normal." },
		[272] = { file = "272", len = 22.152, text = "De hecho, ¡a menudo actuaba precisamente de forma contraria a la esperada! Era casi como si el colgante estropeara deliberadamente mis experimentos. Como si pensara y estuviera vivo. Enfadado pero no desanimado, pasé de suponer que el colgante era un trozo de roca inerte a suponer que era un ser vivo. Pero, de nuevo, fracasé." },
		[273] = { file = "273", len = 32.366, text = "Ninguna de mis nuevas pruebas sacó a la luz ninguna revelación sobre el origen de la piedra de sangre. En aquel momento, el único enigma que resolví fue que la piedra de sangre no estaba ni viva ni muerta. Pero fue entonces, al borde del fracaso, cuando se produjo un gran avance. Mi última prueba consistió en utilizar un vaso de cristal cuyo borde estaba astillado, dejando un pequeño espacio irregular a lo largo de su borde. Una vez terminada la prueba, que tampoco reveló nada, fui a limpiar la mesa de trabajo y me corté con el vaso." },
		[274] = { file = "274", len = 14.916, text = "El corte no era profundo, pero sangraba con fuerza. Antes de que pudiera vendarme el dedo herido, buena parte de la sangre se había derramado sobre la mesa de trabajo. Y mientras limpiaba este nuevo desastre, me di cuenta de algo muy extraño..." },
		[275] = { file = "275", len = 20.402, text = "La sangre que se había derramado cerca del colgante de piedra de sangre avanzaba lentamente hacia la pieza de joyería, como si la gravedad se hubiera inclinado de algún modo hacia la piedra de sangre. La sangre que tocaba el colgante parecía desaparecer, y el color rojo de la piedra se intensificaba a medida que bebía más de mi sangre." },
		[276] = { file = "276", len = 27.925, text = "Después de ver esto se me iluminó la cabeza, quizá por mi reciente herida (aunque no creía haber perdido tanta sangre) o quizá porque por fin, después de tanta frustración, había descubierto una de las propiedades de la piedra de sangre. Busqué mi taburete y me senté a reflexionar. Pensamientos y preguntas se agolpaban en mi cabeza, mareándome y amenazando con derrumbarme. ¿La piedra de sangre bebe sangre? ¿Ansía la sangre? ¿Atrae la sangre?" },
		[277] = { file = "277", len = 21.394, text = "¿O es que la piedra de sangre está hecha de sangre? Y si es así, ¿de quién es la sangre? ¿La mía? ¿La sangre de cualquier humano? ¿De algún animal? O tal vez la piedra de sangre sea la sangre de algo desconocido, la misma cosa que Kegan había temido y venerado a la vez cuando me entregó su colgante. Esa es la pregunta que debe ser respondida. Es la clave." },
		[278] = { file = "278", len = 25.731, text = "Con el fuego reavivado en mi interior, volví a sumergirme en mis experimentos. Esta vez no hice suposiciones, sino que realicé metódicamente todas las pruebas a mi alcance. Esto aumentaba enormemente mis esfuerzos, pero tenía más probabilidades de hacer descubrimientos. Y, aunque mi laboratorio es pequeño y no tengo subordinados que me ayuden, encontré otra cualidad intrigante de la piedra de sangre..." },
		[279] = { file = "279", len = 25.391, text = "Además de la sangre, hay fuerzas elementales fusionadas dentro de la piedra. El fuego, el agua, el trueno y la roca se mezclan con la sangre (pero, una vez más, ¿la sangre de qué?), y aunque esta mezcla es exteriormente inerte, todas estas fuerzas parecen enfurecerse interiormente unas contra otras. Entonces se plantearon muchas más preguntas sobre este material sorprendente y premonitorio." },
		[280] = { file = "280", len = 23.615, text = "Pero para responder a esas preguntas, deben realizarse más estudios y experimentos con el colgante, y me temo que el Campo de Entierros de Lordamere no puede reunir la mano de obra ni el equipo necesarios para la tarea. Así que envié el colgante de piedra de sangre con un mensajero a Dalaran con instrucciones específicas sobre cómo probarlo, para que puedan evitar mis frustraciones anteriores." },
		[281] = { file = "281", len = 22.517, text = "Mientras esperaba los resultados de estas pruebas, pasé el tiempo hablando con Kegan. Aunque le insistí constantemente en lo que sabía sobre las piedras de sangre, nunca me contó más de lo que me dijo el día que me dio su colgante. Y no hablaba a menudo de su tiempo dentro del redil de lo que él llamaba \"los Desamparados\", que es el nombre con el que llama a su clan de no muertos." },
		[282] = { file = "282", len = 19.304, text = "Pero Kegan estaba muy dispuesto a hablar de otros temas, en particular de su época de crecimiento en Lordaeron antes de su caída. Aún siente mucho amor por ese reino perdido, aunque ahora esté arruinado y muerto. Mi creciente afecto por Kegan me dio paciencia mientras esperaba los resultados de mis pruebas." },
		[283] = { file = "283", len = 28.134, text = "Pero tras semanas sin noticias, mi paciencia flaqueó y, tras nuevas indagaciones en Dalaran, me enteré de que la piedra de sangre nunca llegó a mis colegas. Mi mensajero se había perdido por el camino, ¡y el colgante de piedra de sangre se había perdido con él! Son noticias graves, pues aunque Kegan y sus seguidores aún tienen especímenes de piedra de sangre con los que podemos experimentar, temo que el colgante caiga en manos poco recomendables." },
		[284] = { file = "284", len = 12.277, text = "He enviado a otro mensajero a Dalaran y he oído que, hasta el momento, siguen buscando el colgante en las ruinas que están fuera de nuestra esfera de protección. Solo espero que no sea demasiado tarde." },
		[285] = { file = "285", len = 27.246, text = "Historia de Gri'lek el Errante [...El comienzo de la tablilla estaba desgastado y borrado. Pero el final era legible...] Gri'lek atravesó la jungla. Y sus ojos ardían y su pecho retumbaba, pues había una gran ira en él. Con furia rugió al cielo, y levantó su brazo. Levantó su brazo izquierdo, fuerte y seguro de cazar sin su gemelo. El brazo derecho de Gri'lek había desaparecido y no volvería." },
		[286] = { file = "286", len = 30.015, text = "LEYENDAS DE LOS TROLLS, VOLUMEN III Piedra de las Mareas De la mano del Archimago Ansirem Runeweaver Dalaran INTRODUCCIÓN El antiguo Imperio Gurubashi fue fuente de muchas leyendas fascinantes e intrigantes que, sin duda, se remontan a su entorno, ya que los exámenes de sus sistemas de creencias y prácticas sociales han apuntado a una gran reverencia por su entorno natural. Aunque he profundizado en muchas" },
		[287] = { file = "287", len = 31.791, text = "Kurdran Martillo Salvaje Afamado cazador de dragones. Maestro de grifos de Pico Nidal. Comandante de la División de jinetes de grifos adscrita a la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido. “Oiremos la llamada de Cielo-Ree surcar los vientos. Escucharemos el rugir de tu martillo bordeando las cumbres. Cabalga hasta el más allá, hermano. Las salas de nuestros ancestros te aguardan.” - Falstad Martillo Salvaje - Señor de Pico Nidal" },
		[288] = { file = "288", len = 31.06, text = "Capitana especialista Alleria Brisaveloz Afamada Cazatroles de Quel'Thalas. Jefa de rastreadores y agente de inteligencia para la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecida. “Querida hermana, tu corazón atravesó el viento cual hiriente flecha. Fuiste la más brillante de nuestra Orden, la más amada entre nosotros.” - Sylvanas Brisaveloz - General Especialista de Quel'Thalas" },
		[289] = { file = "289", len = 24.163, text = "Archimago Khadgar del Kirin Tor Antiguo aprendiz de Medivh. Comandante en Jefe de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido. “Nadie exploró tan altruistamente las oscuras entrañas de la magia y la guerra. Te deseamos lo mejor, audaz aventurero... estés donde estés.” - Antónidas - Archimago de Dalaran" },
		[290] = { file = "290", len = 29.544, text = "General Turalyon Antiguo teniente de Lord Anduin Lothar. Caballero de la orden de la Mano de Plata. Alto general de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido. “Esarus thar no'Darador' - Servimos por la sangre y el honor. Viejo amigo, fuiste la mano derecha de la justicia y la virtud. Honraremos tu nombre en nuestras salas… por siempre.” - Lord Uther el Iluminado, Caballero de la orden de la Mano de Plata" },
		[291] = { file = "291", len = 29.335, text = "Danath Aterratrols Comandante de Milicia de Stromgarde. Consejero táctico del general Turalyon, Comandante de Fuerza de la Expedición de la Alianza que marchó hacia Draenor, tierra de orcos. Presuntamente fallecido. “Querido sobrino, honramos tu memoria y valoramos tu sacrificio. Desde la fundación de nuestro glorioso imperio, la senda del valor siempre se ha abonado con la sangre de los héroes.” - Thoras Aterratrols, Señor de Stromgarde" },
		[292] = { file = "292", len = 29.989, text = "Aquí yace Uther el Portador de Luz Primer Paladín - Fundador de la Orden de la Mano de Plata Uther vivió y murió para defender el reino de Lordaeron. Aunque fue traicionado por su alumno más querido, creemos que su espíritu sigue vivo. Sigue velando por nosotros, incluso cuando las sombras se ciernen sobre nuestra tierra en ruinas. Su luz es la luz de toda la humanidad, y mientras honremos su ejemplo, nunca se apagará. - Anónimo" },
		[293] = { file = "293", len = 31.53, text = "Aunque en los volúmenes anteriores de este estudio he tratado algunos aspectos de su culto a las serpientes, aquí expongo un examen de la interesante y singular relación de los gnomos con el mar. EL GRAN MAR El Imperio Gurubashi estaba rodeado por tres lados por el mar, por lo que no es de extrañar que el agua ocupara un lugar destacado en su sociedad. Mientras que los gnomos podían recorrer y controlar las grandes extensiones de su imperio selvático, el mar se les escapaba. Era vasto e inconmensurable, no" },
		[294] = { file = "294", len = 28.526, text = "sin duda un vecino desconcertante para los poderosos trolls. Cabe señalar aquí que los descubrimientos recientes parecen sugerir que los trols tenían poco interés en explorar las tierras más allá del Gran Mar. Aunque se han encontrado trols a lo largo y ancho de Azeroth, Khaz Modan y Lordaeron, apenas se han hallado indicios de su civilización en las tierras recién descubiertas de Kalimdor o en las islas de los Mares del Sur. Si esto demuestra una falta de voluntad de" },
		[295] = { file = "295", len = 35.082, text = "que los trolls se aventuren a abandonar sus posesiones terrestres o un fracaso por su parte a la hora de desarrollar las tecnologías necesarias para realizar dicho viaje requerirá una investigación y un análisis más profundos que quedan fuera del alcance de mis escritos aquí. Pero difícilmente se puede ignorar una presencia tan numerosa, y los nuevos hallazgos en las extensas ruinas trol del Valle de Stranglethorn muestran un aspecto de su relación con el mar hasta ahora desconocido e indocumentado. LA PIEDRA DE LAS MAREAS Recientes descubrimientos durante las prospecciones" },
		[296] = { file = "296", len = 30.589, text = "de las ruinas trol del Valle de Stranglethorn han mostrado referencias a un objeto conocido como la \"Piedra de las Mareas\". Varios fragmentos de leyendas trol pueden unirse para pintar una imagen bastante completa de la Piedra y su importancia para el antiguo Imperio Gurubashi. Al parecer, la Piedra de las Mareas permitía a su portador controlar el agua en sus múltiples formas: ríos, lluvia y mareas. Debido a las historias relacionadas con el uso de la Piedra de las Mareas, he conjeturado que es" },
		[297] = { file = "297", len = 28.761, text = "en realidad una manifestación física de los poderes del Señor del Agua, un poderoso elemental de los mares. Cómo y por qué un objeto así abandonaría el control del Señor del Agua y caería en manos de los trolls es otra cuestión que escapa al alcance de mis conocimientos. EL TIDEBEARER Al igual que los movimientos de las mareas epónimas, la Piedra de las Mareas entró en el mundo de los trols y se marchó, sin permanecer nunca en sus manos más de una generación cada vez." },
		[298] = { file = "298", len = 29.518, text = "En las leyendas trol, se dice que la primera vez que la Piedra de las Mareas llegó al Imperio Gurubashi, la encontró un guerrero trol que vagaba por la costa de Stranglethorn. Se topó con una misteriosa piedra azul en cuyo interior flotaban y fluían hebras de color blanco lechoso. Intrigado por la piedra, el guerrero se la llevó consigo y continuó su viaje. Con el paso de las semanas y los meses, el guerrero descubrió que la piedra le otorgaba control sobre el agua. Podía invocar" },
		[299] = { file = "299", len = 33.672, text = "elementales de agua, criaturas formadas completamente de agua, una proeza que sólo pueden realizar los poderosos magos del Kirin Tor. El guerrero viajó a Zul'Gurub, al corazón del imperio, para mostrar sus nuevas habilidades al Emperador. Consiguió fácilmente una audiencia en la corte tras demostrar sus poderes en el centro de la capital imperial. Sus poderes asombraron fácilmente al Emperador Gurubashi, que inmediatamente le otorgó un lugar de honor en la corte, nombrando al guerrero \"Portador de Mareas\", dejando a su" },
		[300] = { file = "300", len = 36.885, text = "antiguo nombre detrás. Durante años, el Portador de Mareas sirvió al Imperio Gurubashi, invocando a sus esclavizados elementales de agua en la batalla y manipulando el flujo de agua en el Valle de Stranglethorn en beneficio del Imperio. Pero con el paso de los años, el Portador de Mareas se volvió más reclusivo, tendiendo a permanecer largos periodos de tiempo lejos de la corte. El Portador de Mareas ocultaba un secreto a las miradas indiscretas de la corte. Las habilidades que le otorgaba la Piedra de las Mareas también venían acompañadas de una maldición. Con el paso de los años" },
		[301] = { file = "301", len = 26.645, text = "el Portador de Mareas se desvanecía. Con cada ir y venir de las mareas, el Portador de Mareas era menos él mismo, perdiendo su forma corpórea, entrando y saliendo de la existencia, hasta que, en sus últimos días, viajó a la playa donde había encontrado la Piedra y se adentró en el mar, desapareciendo por última vez. Generaciones más tarde, la Piedra de las Mareas llegó a las costas de Stranglethorn, y se eligió a otro Portador de Mareas." },
		[302] = { file = "302", len = 21.551, text = "Zul'Gurub. Así continuó el proceso durante generaciones: la Piedra aparecía con la marea y el Portador de Mareas partía con la marea. Los relatos modernos sobre la Piedra de las Mareas han ido apareciendo de un lugar a otro, pero cabe preguntarse por qué un objeto de tal poder aparecería con tanta regularidad, y por designio de quién." },
		[303] = { file = "303", len = 28.526, text = "Órdenes de Bloodsail Presten atención a estas palabras, porque sólo tenemos una oportunidad en la Bahía del Botín. He enviado a Ol' Dunken a explorar hacia el norte y le he dicho que espere la señal. El Damsel's Luck anclará en el cabo sur para aprovisionarse. El capitán Stillwater, el bajito, hará que su tripulación se prepare para recoger todo el botín saqueado. Estoy seguro de que Brutus, ese imbécil, estará al tanto de todo." },
		[306] = { file = "306", len = 26.175, text = "Quiero que el capitán Keelhaul traiga el Riptide a la costa desde el sureste. Enviaremos a su tripulación a pie cuando se dé la señal. Ese grandote, Salthoof, puede llevar a los hombres balanceándose. Quiero la mancha negra sobre Revilgaz y Seahorn. Por mí, envíenlos al fondo del mar. Ustedes son responsables de salvar cualquier cosa que pueda ser útil para nuestro pequeño proyecto con VanCleef en las Minas Muertas." },
		[307] = { file = "307", len = 28.996, text = "Daré la orden para que Ironpatch dispare los cañones. La artillería impedirá que los barcos del Aguasnegras entren o salgan del puerto. Después de que el Crimson Veil haya descargado sus cañones, lo traeré junto al Riptide para apoyarlo y proporcionarle reservas según sea necesario. Una vez que Salthoof y sus chicos hayan atacado la ciudad y todos estén en cubierta, zarparemos y bombardearemos la bahía una vez más desde la Costa Salvaje. --Maestro de Flota Firallon" },
		[308] = { file = "308", len = 31.007, text = "$N, tienes buen brazo para la espada y me he fijado en ello. Tenemos problemas en la Isla de Zephras, es un hecho. Necesitamos a nuestros luchadores shen'dorei en buena forma si queremos sobrevivir a la que se nos viene. Es hora de que dejes de jugar a ser una gran $c y te conviertas en una de verdad. Ven a buscarme en la base de la torre de vigilancia en Thendal. Me encargaré de que recibas el entrenamiento adecuado. -Maestra del acero Ren, instructora de guerreros" },
		[309] = { file = "309", len = 22.883, text = "La bestia que reina sobre esta isla es terriblemente poderosa. Las otras criaturas aquí se acobardan ante él: Skyman y Jaguero por igual. Incluso ahora puedo oír sus rugidos y me hacen estremecer. Estas criaturas seguramente detendrán a cualquiera que venga a la isla. Debo tener fe en mis ancestros." },
		[310] = { file = "310", len = 18.547, text = "Echo de menos mi tribu y mi hogar. Preferiría el viento de las llanuras o la puesta de sol sobre Thunder Bluff al calor de esta jungla. Puedo ver el agua del océano no muy lejos de mí, pero no hace nada para refrescar mi cuerpo o mi temperamento. Sólo me recuerda mi encarcelamiento." },
		[311] = { file = "311", len = 45.662, text = "Día 1:$6am a 11am - campamento superior 11am a 11:30 am- descanso, almuerzo 11:30am a 4:00pm - paso del cañón 4:00pm a 7:30pm - campamento superior Día 2: Smismo horario que el día 1 Día 3: Smismo horario Día 4: Smismo horario, con una excepción. Justo antes de la puesta de sol, Thorsen me hizo cubrirle mientras bajaba sigilosamente por el paso del cañón. Supuse que había ido a reunirse con nuestros agentes. Esto me sorprendió. Esperaba que se reuniera con nuestros agentes y se reuniera con Kurzen. Algo anda mal." },
		[312] = { file = "312", len = 32.888, text = "Día 5: Thorsen estaba muy agitado hoy. Lo que sea que haya visto o a quien sea que haya conocido durante su excursión de ayer debe haberlo asustado. I asumió que nuestros agentes hablaron con él, pero cuando le pregunté a Thorsen adónde había ido mientras yo lo cubría, permaneció callado. Cree que soy su amigo, y cree que me está protegiendo de un secreto peligroso. His lealtades están fuera de lugar, pero son fuertes. Cuando se reúna con nosotros, será una valiosa adición a las fuerzas de Kurzen." },
		[313] = { file = "313", len = 32.235, text = "Día 6: A primera hora de la mañana, Thorsen habló largo y tendido con el sargento Yohwa. Tuve que fingir que aún dormía y por eso no pude moverme al alcance del oído. Pero supongo que hablaron de la excursión anterior de Thorsen. I le observó atentamente durante el almuerzo y se dio cuenta de que Yohwa hacía lo mismo. Más tarde, Doren convocó a Thorsen. Los tres comparten un secreto. Doren y Yohwa deben saber que Thorsen se reúne con sus agentes. Está espiando para los rebeldes." },
		[314] = { file = "314", len = 21.473, text = "No debemos darle más información a Thorsen y debemos matarlo. Ya no es útil para nuestro Coronel. Acabaré con Thorsen si se me da la oportunidad, pero si recibes esta carta sabrás que aún no he tenido la oportunidad. En ese caso, sugiero que el próximo encuentro de Thorsen con nuestros agentes sea fatal. Salve Kurzen, -M" },
		[315] = { file = "315", len = 16.17, text = "El Consejo fue sabio al nombrarte jefe de la Estela de Argus, mariscal de sus estrategias en la tierra de humanos y enanos. Y me siento honrado de servir como la mano de su voluntad en Alterac. En el nombre de Sargeras, Nagaz, Argus Heirophant" },
		[316] = { file = "316", len = 28.656, text = "¡Tontos torpes! Mis planes eran destruir ambos puentes simultáneamente. ¿Y qué hacéis vosotros, matones simplones? Sólo hacen la mitad del trabajo y alertan a toda la Alianza de nuestras intenciones. ¡Tontos digo! Tienen una oportunidad de enmendar sus acciones. Tenemos una reserva de explosivos en las tierras altas de Arathi, no lejos del puente. ¡Terminen el trabajo si valoran sus míseras vidas! --Kam Deepfury" },
		[317] = { file = "317", len = 19.174, text = "Dun Modr de los Humedales Mi querida Sara, Los indicios son muy fuertes de que nos moveremos para vigilar el Thandol Span en pocos días. No sea que no pueda volver a escribirte. Me siento impulsado a escribirte unas líneas que puedan caer bajo tu mirada cuando yo ya no esté." },
		[318] = { file = "318", len = 19.435, text = "Nuestra misión puede durar unos pocos días y estar llena de placer, y puede ser para mí un duro conflicto y la muerte. Si es necesario que caiga en el campo de batalla por la Alianza, estoy preparado. No tengo ningún recelo ni falta de confianza en la causa en la que estoy comprometido y mi valor no se detiene ni vacila." },
		[319] = { file = "319", len = 21.185, text = "Sé con qué fuerza el Reino de Ironforge se apoya en el triunfo de la Alianza, y cuán grande es la deuda que tenemos con aquellos que nos precedieron a través de la sangre y el sufrimiento de las Grandes Guerras, y estoy dispuesto, perfectamente dispuesto a renunciar a todas mis alegrías en esta vida para ayudar a mantener esta Alianza y pagar esa deuda." },
		[320] = { file = "320", len = 16.562, text = "Sara, mi amor por ti es inmortal, parece atarme con poderosos cables que nada excepto la Omnipotencia podría romper y mi amor por el Reino viene sobre mí como un fuerte viento y me lleva irresistiblemente con todas estas cadenas al campo de batalla." },
		[321] = { file = "321", len = 25.966, text = "Los recuerdos de todos los momentos dichosos que he pasado contigo me invaden y me siento profundamente agradecido a la Luz y a ti por haberlos disfrutado tanto tiempo y lo duro que es para mí renunciar a ellos y quemar en cenizas las esperanzas de años futuros en los que todavía podríamos haber vivido y amado juntos y haber visto crecer a nuestros hijos hasta convertirse en enanos honorables a nuestro alrededor." },
		[322] = { file = "322", len = 29.44, text = "Sé que no tengo más que pocas y pequeñas reclamaciones a la Divina Providencia, pero algo me susurra -quizás sea la plegaria de mi pequeño Edgar- que volveré ilesa junto a mis seres queridos. Si no lo hago, mi querida Sara, nunca olvides lo mucho que te quiero, y cuando se me escape el último aliento en el campo de batalla, susurraré tu nombre. Perdona mis muchas faltas y los muchos dolores que te he causado, qué desconsiderado, qué tonto he sido muchas veces." },
		[323] = { file = "323", len = 25.861, text = "Con cuánto gusto limpiaría con mis lágrimas cada pequeña mancha de tu felicidad y lucharía con todas las desgracias de este mundo para protegerte a ti y a mis queridos hijos de cualquier daño. Pero no puedo. Debo observarte desde el retorcido abismo y cernirme a tu lado mientras sacudes las tormentas con tu preciosa carga y esperas con triste paciencia hasta que nos encontremos para no separarnos más." },
		[324] = { file = "324", len = 27.455, text = "Surgiendo del océano, una torre de agua, Neptulón envió al gran Krakken a la condenada I'lalai. Tan enormes eran sus formas que selvas de algas se balanceaban a través de sus miembros, y leviatanes nadaban a través de los cuerpos. El Krakken más grande alzó entonces sus brazos en alto y los estrelló contra el mar, enviando olas a su alrededor. Y se lanzaron con furia hacia I'lalai." },
		[325] = { file = "325", len = 27.272, text = "El Krakken rugió, y sus voces atronaron como una tormenta oceánica: \"Venimos\". Min'loth, manteniéndose firme, invocó su magia. Las olas enviadas a I'lalia se separaron y bañaron a ambos lados, e inundaron la jungla más allá. Min'loth ordenó entonces a sus esbirros que invocaran hechizos de atadura, y se oyó un estruendo al alzarse docenas de voces de gnomos. Y una voz se alzó por encima de las demás." },
		[326] = { file = "326", len = 26.775, text = "Min'loth bramó y su magia reunió el poder de los hechizos de sus secuaces, y lo lanzó contra el Krakken que se acercaba. Los mares se abrieron y el hechizo de Min'loth se dirigió hacia los siervos de Neptulón. Los relámpagos rasgaron el cielo y el hechizo les alcanzó, y cayeron mil rayos, hirviendo el agua y quemando cráteres en la tierra. Min'loth gritó triunfante, sabiendo que su hechizo derribaría a las grandes bestias." },
		[327] = { file = "327", len = 23.536, text = "Pero los Krakken son viejos, muy viejos. Recordaban cuando la tierra nació del mar. Recordaban cuando los Antiguos gobernaban y cuando los Viajeros vinieron y los expulsaron. Recordaban cuando la magia era nueva. Son viejos y guardan muchos secretos. Y aunque el hechizo de Min'loth era fuerte, como el troll, era mortal. Y por eso falló." },
		[328] = { file = "328", len = 28.421, text = "No consiguió atar al Krakken, pero los enfureció. Hacía eones que ningún mortal les causaba dolor, y el hechizo del trol era doloroso. Así que se deshicieron de las ataduras del hechizo de Minloth, pero luego rugieron y se atascaron de furia. Se oyó un estruendo mientras grandes olas surgían de las profundidades y corrían hacia la tierra. Cuando llegaron a I'lalai proyectaron una sombra sobre la ciudad. Pero antes de destruirla, el Krakken se detuvo, preparado." },
		[329] = { file = "329", len = 29.048, text = "Los brujos trolls temblaban y gritaban a su amo. Min'loth contempló las montañas del mar, condenado y desafiante. Se volvió hacia sus adeptos y susurró, y los trols grabaron sus últimas palabras en piedra. Min'loth se enfrentó entonces al inminente Krakken. Hizo una mueca y lanzó su bastón, su último acto de audacia. El Krakken descargó entonces su furia sobre Min'loth, y un océano cayó sobre I'lalai. Y dejó de existir." },
		[330] = { file = "330", len = 32.47, text = "Y entonces las aguas cayeron sobre la jungla, limpiando todo lo que encontraban a su paso. Trolls y bestias gritaron mientras las aguas los aplastaban y ahogaban. Muchos Gurubashi se preguntaron por qué se los había tragado el océano, pero luego murieron y no supieron nada. Finalmente, cuando las aguas llegaron a las montañas, se detuvieron. Apaciguadas, se retiraron más allá de las costas, y dejaron una estela de muerte. Se retiraron, pero surgieron alrededor de I'lalai y permanecieron, ahogándolo para siempre." },
		[331] = { file = "331", len = 14.655, text = "Y el jefe Var'gazul, a salvo tras las montañas de Zul'Gurub, salió a la selva y la encontró limpia de su gente. Y se desesperó, pues sus sueños de conquista se vieron frustrados. Y nunca se encontró a Min'loth la Serpiente." },
		[332] = { file = "332", len = 32.627, text = "Pero Oh Sara si los muertos pueden volver a Azeroth y revolotear sin ser vistos alrededor de aquellos a quienes aman, yo estaré siempre cerca de ti en el día más alegre y en la noche más oscura en medio de tus escenas más felices y de tus horas más sombrías siempre, siempre y si hay una suave brisa en tus mejillas será mi aliento, cuando el aire fresco abanique tu templo palpitante, será mi espíritu pasando. Sara, no me llores muerta, piensa que me he ido y espérate, pues nos volveremos a encontrar. --Sully" },
		[333] = { file = "333", len = 21.734, text = "A Mi Honorable Rey: No corresponde a la esposa de un humilde soldado cuestionar las acciones de grandes líderes como usted. Las batallas que asolan nuestras tierras se libran para preservar la gran vida que conocemos y amamos, desde las frescas aguas de Loch Modan hasta las cumbres nevadas de Dun Morogh." },
		[334] = { file = "334", len = 20.219, text = "Pero las guerras que libramos en nombre de la preservación, ¿a qué precio? ¿Con la muerte de qué soldado caído nos damos cuenta de que la misma vida que nos esforzamos por salvar se nos escapa en el campo de batalla? ¿Bajo cuántas espadas y hachas debemos arrojar nuestro futuro? ¿Bajo cuántos metros de tierra empapada debemos enterrar nuestro pasado?" },
		[335] = { file = "335", len = 27.585, text = "No corresponde a la humilde esposa de un soldado hacer tales preguntas. Sin embargo, le escribo ahora como la humilde viuda de un soldado. Mi marido podría haber sido un soldado en las filas de miles para usted. Para mí era el gran Sully Balloo, padre de mis hijos y mi único compañero en esta vida. Perdóneme si mis preguntas a usted, oh gran líder, suenan inapropiadas. Pero los muertos no pueden hacer estas preguntas por sí mismos.... Tu leal súbdita, Sara Balloo" },
		[336] = { file = "336", len = 27.69, text = "A los Schneider, Buenos días: Confío en que hacer negocios en el distrito del canal resulta conveniente. Estamos en auge, en la plaza de los comerciantes. Necesitamos prendas de vestir tejidas, ya que nuestras existencias se han acabado. Por favor, envía un cargamento estándar tan pronto como puedas. Buena suerte y confío en que los estudios de tu hijo Thurman progresen adecuadamente, Harlan Bagley" },
		[337] = { file = "337", len = 29.962, text = "Órdenes oficiales para la flota Kul Tiras Yo, el almirante Valiente, dirigiré el primer desembarco en las costas de Kalimdor. En mi ausencia, el teniente Benedict será el segundo en la cadena de mando. Todas las cuestiones militares de Kul Tiras de carácter doméstico serán gestionadas por él. Si no envío mensaje alguno desde el Fuerte de Tiragarde transcurridos 12 meses, el teniente Benedict dirigirá la segunda oleada para conquistar la posición." },
		[338] = { file = "338", len = 34.09, text = "Mientras tanto, envío al teniente Alverold en una misión de exploración por el continente de Kalimdor. Sus fuerzas deben completar la misión y luego deben reunirse con nuestras fuerzas en el Fuerte de Tiragarde. Se da por supuesto que la misión del teniente Alverold tardará tiempo en realizarse. La nueva tierra parece vasta y peligrosa. Pero si la mala fortuna nos alcanza a Benedict o a mí, las tropas de Alverold volverán a tomar el Fuerte. ¡Enviaremos oleada tras oleada hasta que el fuerte sea nuestro! Almirante Valiente" },
		[340] = { file = "340", len = 18.338, text = "Registro de Reclutamiento de la Horda Esta persona ha demostrado tener una gran fuerza y destreza en nombre de la Horda. Debería ser asignado para trabajar inmediatamente en El Cruce. Respetuosamente, Me parece bien. - Takrin Abrecaminos" },
		[341] = { file = "341", len = 20.14, text = "Registro de Reclutamiento de la Horda Esta persona ha demostrado tener una gran fuerza y destreza en nombre de la Horda. Debería ser asignado para trabajar inmediatamente en El Cruce. Respetuosamente: - Kargal Marcaguerra Me parece bien. Takrin Abrecaminos" },
		[342] = { file = "342", len = 35.109, text = "La excavación de Bael Modan El equipo de reconocimiento original enviado por la Liga de Exploradores estaba en lo cierto en sus hallazgos. El suelo aquí contiene artefactos de valor ilimitado para nuestro pueblo. Sin duda encontraremos muchas respuestas en nuestra búsqueda del conocimiento bajo la arena y la roca de Bael Modan. Sin embargo, la geología de la región dicta que utilicemos medidas extremas. Muchos de los depósitos de arena se han solidificado bajo las duras condiciones y las variaciones climáticas." },
		[343] = { file = "343", len = 29.126, text = "Sin embargo, la solución es bastante sencilla. Utilizando pulpa de madera como absorbente, podemos combinar trazas de nitroglicerina con nitrato de sodio para desarrollar una fuerte carga explosiva, capaz de atravesar incluso las masas más densas. El trabajo será ruidoso y molesto, pero nuestra búsqueda es mucho más importante que la comodidad de los habitantes locales. De hecho, ya hemos tenido que expulsar de la zona a una banda de hombres-toro que estaban resultando molestos." },
		[344] = { file = "344", len = 31.556, text = "El hecho de que estemos tratando con varios elementos renegados aquí me lleva a creer que necesitaremos el apoyo del Ejército del Rey. No sólo la excavación requerirá apoyo militar, a mi ojo de novato le parecería que la ubicación de Bael Modan podría ser de valor estratégico para la Alianza, teniendo en cuenta la volatilidad de la política mundial en su estado actual. Por desgracia, he divagado. Hay mucho trabajo que hacer bajo la roca. He pasado demasiado tiempo escribiendo y no lo suficiente excavando..." },
		[350] = { file = "350", len = 41.691, text = "La consola de control de samoflange puede utilizarse para regular automáticamente el flujo de los combustibles, gases, líquidos y otra maquinaria relacionada. Una vez que se ha completado la configuración inicial, debería funcionar sin problemas, con un mantenimiento mínimo. Breve listado de los componentes de la consola de control (de izquierda a derecha) I. Palanca de potencia principal La posición de conexión activa el samoflange. Cuando la palanca esté en posición desactivada, el mecanismo de control no se desconectará de forma automática. Simplemente, esto hará que" },
		[352] = { file = "352", len = 34.821, text = "Supervisor Fizsprocket: Junto a esta nota, encontrarás un listado del equipamiento que has solicitado, aprobado por el presidente Razdunk. Me ha pedido que te recuerde que haga hincapié en el especial interés que tiene Ventura y Cía. en realizar operaciones en Kalimdor. Nuestros puestos de perforación y actividades mineras en los Baldíos han demostrado ser rentables y eficaces, pero aún esperamos conseguir mejores cifras de producción de Mulgore, tu jurisdicción. El consejo consultivo comprende las dificultades que supone poner en marcha" },
		[353] = { file = "353", len = 32.993, text = "una operación a gran escala tan cerca de la patria de los tauren, pero no creemos que supongan un gran impedimento para nuestro plan de negocio general en la zona. Nos complace saber que la minería ha comenzado en las llanuras ricas en minerales de Mulgore. Por ello, la junta ha aprobado su solicitud de equipamiento. Además de la minería, creemos que Mulgore también tiene mucho que ofrecer en el ámbito de la madera, por lo que también se le proporcionará varios de nuestros modelos más recientes de trituradoras y materias primas para construir una fábrica de madera." },
		[354] = { file = "354", len = 0.888, text = "molino." },
		[355] = { file = "355", len = 35.344, text = "comienza el proceso de enfriamiento y, a partir de entonces, tardará aproximadamente uno o dos minutos en desactivarse, dependiendo de la situación. NOTA IMPORTANTE: La palanca de alimentación principal solo puede utilizarse cuando se hayan desconectado las tres válvulas de control en la maquinaria real. Dichas válvulas pueden desconectarse en cualquier orden. La primera es la VÁLVULA DE CONTROL PRINCIPAL, que se encuentra en la base de la gran chimenea vertical. A continuación, la VÁLVULA DE CONTROL DE COMBUSTIBLE se encuentra en la gran tubería que conecta los" },
		[356] = { file = "356", len = 26.305, text = "tanques de combustible (debe haber tres) con la chimenea. Finalmente, la VÁLVULA REGULADORA se encuentra en la parte inferior de los dos grandes tanques cilíndricos que se introducen en la chimenea. II. Indicadores de combustible Muestra la presión actual en los tanques de combustibles primario, secundario y terciario. III. Indicador de flujo Muestra la tasa de flujo actual dentro del sistema." },
		[357] = { file = "357", len = 15.099, text = "IV. Controles de flujo Aumentan o disminuyen las tasas de flujo. Es controlado automáticamente por el mecanismo de control del samoflange. V. Indicador de temperatura Muestra la temperatura operativa del sistema en general." },
		[361] = { file = "361", len = 32.758, text = "Maestro Delgren, Es como te temías. Tu teoría acerca de la Torre de Althalaxx ha resultado ser cierta. Se ha reunido un culto en la torre, incluyendo a muchos brujos, así como a un nauseabundo sátiro. Se llaman a sí mismos el Culto de la Facción Oscura. No puedo imaginarme qué vil propósito los ha reunido, pero me preocupa. Disculpa el carácter lacónico de esta carta, pero el peligro merodea en el bosque y solo puedo decir un par de palabras para describir la situación. Yo..." },
		[371] = { file = "371", len = 39.523, text = "L. F. ha ordenado aumentar la agresión contra los tontos de la Alianza. A continuación se muestra una lista de los materiales necesarios para una importante misión contra Southshore: 1 semana de raciones de viaje para 20 hombres 20 trajes de noche negros 20 pares de zapatos nuevos 25 espadas nuevas 30 cuchillos arrojadizos 20 máscaras negras 10 viales de aceite inflamatorio 50 dosis de veneno paralizante 5 uniformes robados de la guardia de Southshore, si están disponibles 100 monedas de plata --Baron V. Intendente" },
		[372] = { file = "372", len = 20.48, text = "La estrella de Xil'yeh Grel'borg el Avaro tiene la Estrella. Es un ogro codicioso que pasa sus días en las Montañas de Alterac, en las Ruinas de Alterac, buscando baratijas. La mayor parte de su colección es inútil, pero un objeto, la Estrella de Xil'yeh, tiene propiedades valiosas." },
		[373] = { file = "373", len = 33.175, text = "La mano de Dagun Los textos antiguos afirman que las garras de Dagun excretan un veneno que no mata a su presa, sino que la muta en otra cosa: un miembro de las razas antiguas. Su valor para nosotros es incuestionable. Dagun vive en las profundidades marinas, pero una tribu de múrlocs mirefin del pantano de Dustwallow lo atrae regularmente a la superficie. Sus oráculos lo invocan con un alga encantada. Si matas a suficientes oráculos, encontrarás el alga. Colócalo en el altar de los Murlocs y Dagun vendrá." },
		[374] = { file = "374", len = 18.73, text = "El corazón del legado Mogh el Eterno es un brujo trol de Stranglethorn. Y posee el Corazón del Legado, del que se dice que evita la muerte a aquellos que pueden desvelar sus secretos. Encontrarás a Mogh en las Ruinas de Zul'Mamwe. Derrótalo, si puedes, y tráeme el Corazón del Legado." },
		[375] = { file = "375", len = 8.15, text = "Tráeme estos tres objetos, la Estrella, la Mano y el Corazón, y el Digesto de Yagyin será tuyo. -G.B." },
		[376] = { file = "376", len = 23.719, text = "La estrella de Xil'yeh Un ogro de Alterac, Grel'borg el Avaro, fue el último propietario conocido de esta gema, de la que se susurra que otorga a su dueño la capacidad de comunicarse con otros mundos. Las fuentes nos dicen que Grelborg vaga por las Ruinas de Alterac, en las Montañas de Alterac, buscando más reliquias entre los escombros." },
		[377] = { file = "377", len = 23.797, text = "La mano de Dagun Dagun es una criatura de las aguas profundas, venerada por los murlocs del pantano de Dustwallow. Lo atraen a la superficie con un alga marina especial, encantada por sus chamanes. Caza a los Murlocs, recoge sus algas encantadas y colócalas en el altar de los Murlocs. Dagun vendrá, y tú estarás esperando. Quiero esa mano." },
		[378] = { file = "378", len = 20.245, text = "El corazón del legado Dicen los textos antiguos que quien posee el Corazón del Legado no teme a la tumba. Tal vez sea cierto, porque el propietario del corazón, el trol Mogh, es conocido como Mogh el Inmortal. Mogh, brujo de la tribu RompeCráneos, vive en Stranglethorn, en las Ruinas de Zul'Mamwe." },
		[379] = { file = "379", len = 7.784, text = "Tráeme estos objetos, la Estrella, la Mano y el Corazón, y te daré una copia del Yagyin Digest. -El Custodio" },
		[380] = { file = "380", len = 17.319, text = "Informe de la misión Deathstalker Agentes: Rane Yorick, Quinn Yorick, Erland McKree Misión principal: realizar un reconocimiento por el norte de Silverpine, y determinar los niveles de amenaza de la fauna y el Azote." },
		[381] = { file = "381", len = 31.216, text = "Los agentes comenzaron el barrido, encontrando una presencia significativa de gusanos. Recomendar el envío de escuadrones de caza para reducir esta amenaza. Se encontraron gnolls muertos en la granja apodada El Campo Muerto. Se desconoce su propósito en la granja, aunque sus movimientos y nivel de preparación sugieren una acción militar inminente. Durante el tiempo en que fueron observados, no se encontraron líderes notables entre los gnolls. Se supone que esperan la llegada de líderes o refuerzos." },
		[382] = { file = "382", len = 21.473, text = "Continuando con el barrido, nuestros agentes fueron detenidos en la granja de Ivar. Ivar, la mayor parte de su familia y sus trabajadores habían sucumbido al Azote y se habían convertido en sus secuaces. Onuestros agentes fueron atacados y, aunque lograron derrotar a sus emboscadores, sufrieron heridas graves, especialmente el agente Quinn." },
		[383] = { file = "383", len = 21.237, text = "Se tomó una posición defensiva en la antigua casa de Ivar, y mientras Rane vigilaba futuros ataques, Erland continuó la misión de reconocimiento. Erland fue entonces inmovilizado por Worgs en un huerto del norte, escapando sólo con la ayuda de otro agente de los Desamparados. Ese agente es el portador de este informe." },
		[386] = { file = "386", len = 26.07, text = "Cabe señalar aquí que este portador del informe fue fundamental no sólo en el éxito de nuestra misión, sino también en la derrota de Ivar el Sucio, el rescate de Erland, y la entrega de este informe. Extendemos nuestra gratitud, y recomendamos que el mando reconozca a este individuo con premios dignos de tal conducta meritoria como se muestra en el campo. -Deathstalker Rane Yorick, Líder de la misión" },
		[387] = { file = "387", len = 20.166, text = "Y así vagó y buscó. Y su brazo permaneció perdido para él. Así que maldijo y rugió mientras caminaba. Pero Gri'lek hacía tiempo que había apartado su oído de los espíritus, y éstos se enfurecían y no escuchaban sus maldiciones. Gri'lek estaba condenado. Condenado a vagar, sin brazos." },
		[394] = { file = "394", len = 17.319, text = "Una fuerza maligna los creó, Se sienta cómodamente en la Cima Calígine, Se ríe de ti y de tu amigo, Sus elementales no tienen fin, Pronto deberás enfrentarte a este mago, Su furia solo se aplacará con la muerte." },
		[395] = { file = "395", len = 12.304, text = "Santuario de Mel'Thandris \"Que la luz de Elune brille sobre este valle eterno e ilumine los caminos del bosque como lo ha hecho desde tiempos inmemoriales\"." },
		[396] = { file = "396", len = 33.071, text = "Elune ha concedido mis deseos. Las vidas de mis camaradas caídos no serán en vano, y vengaré sus muertes usando la Guadaña de Elune. Es una cosa antigua, una rama, retorcida y nudosa de madera que podría ser más antigua incluso que los Kaldorei. Durante muchas horas examiné la herramienta que la diosa me concedió. No es un arma ordinaria, eso es seguro, ni tampoco un simple implemento mágico. Con ella... es como si las barreras del tiempo y el espacio se debilitaran. Sosteniendo la Guadaña" },
		[397] = { file = "397", len = 37.042, text = "en mis manos, recibí una visión del caos. Hombres lobo... los worgen... luchaban contra un enemigo increíble. Los worgen luchaban salvajemente, como correspondía a su raza primitiva, pero su enemigo era inquebrantable: los Señores de la Llama Esmeralda. Y fue entonces cuando me di cuenta del verdadero poder de la Guadaña. Al concentrarme en ella, pude comunicarme con los worgen. Sin embargo, no era el habla lo que usaba para contactarlos. Era algo diferente... No podría describirlo. Lo que importaba era que los worgen escuchaban" },
		[398] = { file = "398", len = 26.749, text = "y me entendió. Al canalizar más energía hacia la guadaña, las barreras se debilitaron más y pude atraer a los worgen a nuestro mundo. Pude convocar a veintena y media en mi primer intento. Me siguieron a la batalla y, con su fuerza bruta a mis órdenes, destrozamos a los demonios de Felwood. Elune ha concedido mis deseos. El bosque será limpiado. Que las bendiciones de Elune estén sobre mí hasta que mi trabajo esté hecho." },
		[399] = { file = "399", len = 28.003, text = "Todo va bien. He convocado un mayor número de worgen para luchar a mi lado. Aunque son de mente simple, han demostrado una habilidad impresionante para coordinar sus ataques y funcionar como grupo. He identificado líderes en sus manadas. A ellos les he dado el mando de pequeños grupos de guerreros. Atacamos desde muchos lugares del bosque a la vez, y mi campaña contra los demonios es fructífera. Que las bendiciones de Elune estén sobre mí hasta que mi trabajo esté hecho." },
		[400] = { file = "400", len = 29.335, text = "Una manada se ha perdido. Envié a los worgen a recorrer el bosque e identificar las zonas de infestación demoníaca, pero no regresaron. Empiezo a preocuparme por los líderes a los que he confiado el control. Son de mente simple, y esta pequeña porción de autoridad que les he dado, la extienden al máximo. ¿Estoy perdiendo el control? Quizás deba dejar de convocar worgen adicionales por el momento. Que las bendiciones de Elune estén sobre mí hasta que mi trabajo esté hecho." },
		[401] = { file = "401", len = 30.093, text = "Aunque no he invocado más worgen, su número sigue aumentando. Es como si la Guadaña ya no necesitara mi intervención para el proceso de invocación. Esto es preocupante. He reunido a todas las manadas que he podido encontrar y les he ordenado que permanezcan en el Santuario de Mel'Thandris. Mientras tanto, he buscado en las bibliotecas de Darnassus y consultado con el Círculo de los Antiguos en Darkshore. No he encontrado ni una pizca de información sobre estos worgen. He oído informes," },
		[402] = { file = "402", len = 26.54, text = "susurros, de un mago del Kirin Tor llamado Arugal. Por lo que he oído, es posible que también haya invocado worgen. Yo consultaría con este mago, por muy desagradable que sea, a ver qué sabe. Los worgen son peligrosos, y deseo detener la marea. Al día siguiente, viajaré al puerto en los Barrens y reservaré pasaje al Nuevo Mundo. Que las bendiciones de Elune me acompañen hasta que mi trabajo esté hecho." },
		[403] = { file = "403", len = 27.559, text = "Comencé a escribir este diario para guardar notas acerca de mi investigación para ayudar a Vallefresno. Estos acontecimientos ocurridos no hace mucho están envueltos en misterio y, con suerte, podré desvelar algunos de ellos para así ayudar a mi gente. Empezaré comentando ciertos hechos para evitar olvidarlos más adelante. Me he dado cuenta de que los rumores acerca de los esfuerzos del zahorí Dartol son ciertos." },
		[404] = { file = "404", len = 37.851, text = "Si bien antes pensé que sería absurdo que un humano llegara a nuestras tierras y aprendiera nuestras costumbres, este zahorí, este hombre malvado, llegó aquí y no solo sobrevivió, sino que obtuvo parte de nuestra sabiduría. Todavía no sé bien cómo lo hizo... Durante mi investigación, no pude descubrir sus objetivos, pero su plan parecía simple: utilizando magia druídica, intentó primero hacerse amigo y luego controlar a los fúrbolgs. Si hubo un intento de causar daño a mis parientes o cualquier otro propósito malicioso, espero encontrar la explicación antes de acabar mis pesquisas." },
		[405] = { file = "405", len = 30.929, text = "Sin embargo, por lo visto había tenido algo de éxito al llevar a cabo sus planes. ¿Quería probar sus planes con los fúrbolgs antes de ponerlos en práctica con mi gente? ¿Tenían los fúrbolgs algo que él codiciaba? ¿Quién sabe? Usando un objeto que creó (una vara o bastón de algún tipo), intentó infiltrarse en las tribus de fúrbolg de Vallefresno. En algún momento, aquí los detalles aún no están claros, los fúrbolgs lo descubrieron mientras intentaba manipularlos para que actuaran los unos contra" },
		[406] = { file = "406", len = 33.019, text = "los otros. Como estoy seguro de que ocurriría con los elfos, los fúrbolgs estaban airados, pero reaccionaron con mucha mayor fuerza y mataron a Dartol. Los fúrbolgs, al menos en ese momento, no eran las mismas criaturas corruptas que llegaron a ser posteriormente. Entonces, aún eran racionales e inteligentes, y su relación con nuestra gente era amistosa. Tengo la esperanza de que si vuelvo a crear la vara con la ayuda de una dríade llamada Shael'dryn, podré utilizar su poder para ayudar a nuestra gente... y a los fúrbolgs." },
		[407] = { file = "407", len = 35.448, text = "No todos los fúrbolgs han sido corrompidos. Algunos aún viven en el bosque e intentan protegerlo. Durante el periodo en el que se corrompieron, algunos de los fúrbolgs huyeron, muchos fueron asesinados y otros fueron desterrados de sus tribus. Encontré a un venerable fúrbolg de la tribu Maderiza que vive encima del lago Mystral. Su nombre es Krolg. Estuve observándolo durante días y creo que, si me hubiera acercado a él disfrazado de fúrbolg, podría haberle ayudado y haber descubierto una forma de restablecer los lazos entre nuestros pueblos." },
		[408] = { file = "408", len = 26.906, text = "Además de matar a Dartol, los fúrbolgs dividieron la vara en tres partes para que nadie volviera a usarla en su contra. No ha sido fácil, pero creo saber dónde pueden estar. La gema La primera parte de la vara, una gema resplandeciente, fue oculta en un santuario en el noroeste de Vallefresno. Creo que ahora este santuario son las ruinas en el centro del Lago Falathim. Según las centinelas, ahora están invadidas por múrlocs." },
		[409] = { file = "409", len = 34.664, text = "Si no puedo localizar la gema oculta en el santuario, puede que se encuentre en posesión de uno de los múrlocs. El asta Esta parte de la vara fue confiada a los antárboles cerca de lo que hoy se conoce como Frondavil. Ni los fúrbolgs ni nosotros podríamos haber sospechado nunca que estas magníficas criaturas pudieran caer en las garras de la corrupción que asoló la tierra. Mis investigaciones indican que los guardianes conservan la pieza en un pequeño claro, dentro de un arcón. Para averiguar más detalles, tendré que hablar con Shael'dryn." },
		[410] = { file = "410", len = 13.897, text = "1. Conseguir un hombre u ocho 2. Golpear fuerte al hombre 3. Golpear más al hombre 4. Poner al hombre en el fuego 5. Comerse al hombre" },
		[411] = { file = "411", len = 31.556, text = "Shael'dryn es una dríade que protege la Poza de la Luna al noreste del Lago Iris. Se niega a abandonar el bosque o a dejarlo caer en la corrupción. Sé que ella tiene el poder y los conocimientos necesarios para reparar la vara o, al menos, decirme cómo puedo hacerlo por mí mismo. El pomo Se entregó el pomo de la vara a los druidas de Dor'danil. No obstante, esto supone un problema importante: los druidas están muertos. Ahora, sus espíritus ocupan el área y ya no se muestran hospitalarios." },
		[412] = { file = "412", len = 34.847, text = "Puede que esto requiera más investigación. No estoy seguro de tener poder suficiente para luchar contra los espíritus de mis parientes muertos... Intentaré escarbar las profundidades de Dor’danil y encontrar el pomo. (Nota: Durante mis preparativos en Astranaar, me he encontrado recientemente con un enano cazador que pasó bastante tiempo en Vallefresno, intentando ayudar a mi gente. Procedía de un lugar llamado Ventormenta. Una noche estuvimos hablando, mientras tomábamos algunas cervezas, y sus relatos me han dado nuevas esperanzas de poder encontrar el pomo..." },
		[413] = { file = "413", len = 32.235, text = "Me dijo que recorrió todo Dor'danil y que nunca vio un cofre o cualquier otra clase de contenedor que pudiera albergar el pomo. Asimismo, me dijo que babosas en podredumbre habitaban el área y que devoraban prácticamente todo aquello más pequeño que ellas. Vio cómo se \"comían\" mesas, esculturas, osos ¡e incluso gnomos! Las babosas parecen obtener gran parte del alimento a partir de objetos mágicos. Si el cofre que contiene el pomo estuviera encantado, habría muchas posibilidades de que las babosas se hayan comido." },
		[414] = { file = "414", len = 14.237, text = "Se trata de un juego, pero en este momento no dispongo de otras pistas... Cuando averigüe más, lo escribiré en estas páginas, pero hasta entonces, intentaré localizar las partes de la vara y trataré de ayudar a Vallefresno." },
		[415] = { file = "415", len = 27.69, text = "Jin'Zil, Sé que hace un tiempo que no te escribo, pero pensé que te gustaría saber que el último de los Sangrepluma ha sido asesinado. No me lo agradezcas, la persona que entrega la carta es la asesina. Si quieres, puedo entregarte su cabeza después de que la caravana haga sus rondas por los Baldíos. Sé que te gustan esta clase de cosas para tus ceremonias vudú. Cuídate, viejo amigo. -Darsok Movedaga" },
		[417] = { file = "417", len = 39.915, text = "Bien, deberían tener sus cargas NG-5 y detonadores listos. Los he etiquetado para ustedes... El azul es para el aserradero. El rojo es para la mina Windshear. I hizo un poco de exploración, y hay suficientes explosivos en todo Windshear Crag que no debería ser un problema en absoluto para que usted pueda entrar, colocar los explosivos, y luego salir antes de detonarlos. Recuerde, esto es una distracción. Aléjate de los carromatos antes de que lleguen los goblins para comprobar qué ha pasado, y luego entra sigilosamente detrás de ellos." },
		[418] = { file = "418", len = 33.202, text = "Por cierto, ten cuidado con ellos. El nitromirgliceronio por sí solo podría reducirte a polvo. He encapsulado parte del líquido en tubos de cobre que deberían mantenerlo estable y seguro. El pergamino que conseguiste de Collin lo usé en las cajas detonadoras. Ahora enviarán un mensaje silencioso a las cargas NG-5 después de que las hayas puesto. Usé un simple mecanismo Stalthwargon para asegurarme de que la conductividad del cable es óptima y el flujo del Nitrogliceronio entre el fluido diferencial es mejor que la media." },
		[419] = { file = "419", len = 26.384, text = "Antes de entrar en detalles sobre mi diseño, déjame explicarte dónde debes colocar los explosivos. Plan Alfa- el aserradero: Hay un vagón delante del aserradero (está al noreste de su construcción de deforestación y recogida de madera). Sospecho que los planos de ingeniería están dentro del aserradero. Para plantar la carga, dirígete a la parte trasera del vagón. Una vez colocada, date prisa y toma distancia." },
		[420] = { file = "420", len = 25.704, text = "Cuando estés listo, pulsa el detonador. I've aseguró una señal fuerte por el enrutamiento de cobre y plata cables con un Melthusian antenae matriz dentro de la carcasa de la caja. Eso debería darte un buen alcance. Sólo ten cuidado con los goblins cercanos. No apreciarán mi creación si te pillan en su sitio. Oh, por si no era obvio, no estés cerca del carro cuando explote... te dolerá." },
		[421] = { file = "421", len = 27.376, text = "Plan Beta- Mina Windshear: I vio a los goblins usando otro vagón de explosivos al norte de la entrada de la mina. Creo que debería ser un lugar suficientemente bueno para colocar la Carga NG-5 (Roja). Después de colocar la carga en la parte trasera de la vagoneta, toma cierta distancia y pulsa el botón. ISi los goblins no vienen corriendo a ver la conmoción, probablemente sea porque la montaña les ha caído encima." },
		[422] = { file = "422", len = 23.589, text = "La Venture Co. Las cartas están fuera de la mina... Creo que en unas cajas en el nivel inferior. Buena suerte, y recuerda... Carga azul: aserradero Carga roja: mina y destruye esta carta cuando hayas cumplido tu misión. Hmm, tal vez debería buscar una forma de hacer que estas cosas se destruyan solas después de ser leídas. No es mala idea..." },
		[424] = { file = "424", len = 33.071, text = "--Día Uno-- ¡Mi viaje desde Ironforge me lleva finalmente a Kalimdor! El prospector Khazgorm de Bael Modan está haciendo grandes progresos. Hoy ha descubierto un fósil que los eruditos del lugar creen que es un fragmento de hueso de un antiguo dios. Khazgorm está seguro de que el fósil es parte de un gran misterio. Mientras supervisa la excavación, se ha propuesto descubrir más fósiles para reconstruir la historia. Mi misión: dirigirme al sur en busca de más pistas." },
		[425] = { file = "425", len = 27.977, text = "--Día Dos-- Las tierras de los Barrens son vastas y extensas. Mi viaje ha sido largo y arduo, y hasta ahora no he encontrado nada de interés para los archivos de la Liga de Exploradores. El único incidente digno de mención tuvo lugar cerca del camino del oro. A lo lejos vi unas criaturas extrañas. Parecían mitad cerdo y mitad hombre. Me escondí rápidamente y dejé pasar a las asquerosas bestias. ¡Vaya hedor que dejaban tras de sí!" },
		[426] = { file = "426", len = 28.813, text = "--Día tres... ¡Oh gran y espléndido descubrimiento! Mientras exploraba hoy me encontré con un gran hallazgo: restos masivos de lo que parece haber sido una criatura parecida a un jabalí. Su cráneo se elevaba varios metros por encima de mí. Cada diente de la bestia podría empequeñecer incluso a... bueno, a un enano. Debido al gran tamaño del hallazgo, creo que son los restos de uno de los rumoreados Dioses Antiguos." },
		[427] = { file = "427", len = 25.077, text = "Hace tiempo, en la sede de la Liga de Exploradores en Ironforge, recuerdo una conferencia del arqueólogo jefe Greywhisker. El viejo hizo mención de un dios, uno que era venerado por los extraños elfos de Darnassus debido a su rumoreada naturaleza altruista... ¡Bah! Un momento. Oigo resoplar fuera de la tienda. Seguramente sólo son unos jabalíes tratando de llegar a mi reserva de manzanas...." },
		[428] = { file = "428", len = 21.237, text = "--Día 4-- ¡Capturado! Debo... escribir... rápido. Atacado por hombres jabalí de la tribu Razorfen. Creí que me llevaban a los restos del gran jabalí del dios caído. En lugar de eso, bordearon los grandes fósiles y se dirigieron directamente al oeste del cráneo gigante, a través del Camino del Oro." },
		[429] = { file = "429", len = 21.708, text = "Arrastrado con rudeza al interior de una zarza maloliente e infestada de espinas llamada Razorfen Kraul. Arrojado al interior de una choza toscamente construida y mantenido cautivo junto a un elfo nocturno moribundo. Sin posesiones, salvo este diario, mi pluma y mi reloj de bolsillo... Alguien viene ahora..." },
		[430] = { file = "430", len = 21.786, text = "--Día 5-- Mi compañero de celda elfo nocturno sufre graves heridas. Los hombres jabalí le han azotado repetidamente y creo que morirá en poco tiempo a menos que, por algún milagro, un grupo de rescate se enfrente a este traicionero lugar. Pierde y recupera el conocimiento. Cuando despierta, intento darle la poca agua que tengo." },
		[431] = { file = "431", len = 30.642, text = "Anoche pudo hablar por primera vez. Es un druida, llamado Heralath, enviado a estas partes para examinar los rumores del dios jabalí caído. Con voz debilitada me dijo que creía que la gran calavera del jabalí era el lugar donde el gran dios jabalí Agamaggan cayó luchando contra la Legión Ardiente hace unos 10.000 años, durante la Guerra de los Antiguos. Su enorme cuerpo aplastó la tierra y su sangre se hundió en ella. Espinas retorcidas crecen donde cayó su sangre..." },
		[432] = { file = "432", len = 20.114, text = "Heralath y su gente buscan descubrir el origen de la corrupción en este lugar. Se creía que Agamaggan era un dios puro, me dijo. Por qué estas criaturas repugnantes y espinas malignas marcan la tierra es un verdadero misterio. Antes de que pudiera pedirle más información, Heralath volvió a caer en un sueño intranquilo..." },
		[433] = { file = "433", len = 28.186, text = "--Día 6-- El estado de Heralath empeora. Hoy sólo ha abierto los ojos una vez. Hablaba con dolorosa angustia, pero su mensaje era claro. Si pudiera escapar de mi perdición aquí en Razorfen Kraul, Falfindel Waywarder debe saber en Thalanaar que Charlga Razorflank está reuniendo a sus secuaces en los Barrens del sur. El poder crece cada día. La Arpía debe ser detenida antes de que la plaga de corrupción se extienda desde Kraul." },
		[434] = { file = "434", len = 25.992, text = "El pobre Heralath está pálido como un hueso. Su fiebre empeora por momentos. Mientras tanto, los hombres jabalí se preparan para una gran acción militar. Temo que si no intento escapar pronto, tendré un destino similar al de mi compañero de celda elfo. Mi plan es escabullirme cuando los hombres jabalí salgan a su próxima cacería. Mis guardias son perezosos y a menudo duermen durante sus turnos." },
		[435] = { file = "435", len = 21.969, text = "Una vez libre de los Kraul, me dirigiré hacia Mil Agujas y luego hacia el oeste, a Thalanaar, en la frontera del misterioso bosque de Feralas. Allí buscaré al druida conocido como Falfindel Waywarder. Lo que comenzó como un intento de explorar el pasado de mi pueblo se ha convertido en algo mucho más grande. La protección de la Alianza está en mis manos...." },
		[436] = { file = "436", len = 21.133, text = "NÚMERO DE PEDIDO: 45TK-3 COMPRADOR: Kravel Koalbeard FACTURA: Carraca Hidráulica (3) Pernos repetidores (50) Tubo de cobre calibre 20 de 30\" (12) Rapé, marca Deepfury (1) Prisma de alta calidad (3)" },
		[437] = { file = "437", len = 20.532, text = "te debería entregar este mensaje en mano, pero debo irme, no sea que me pierda algún acontecimiento de gran importancia. Si deseas saber más acerca de mis observaciones sobre la torre de Althalaxx, el portador de este mensaje me ha servido de gran ayuda y creo que se puede confiar en él. A toda prisa, Balthule Golpesombra" },
		[438] = { file = "438", len = 30.694, text = "El goblin Nazz Steamboil es en realidad el hijo de un príncipe mercader goblin (¿Qué príncipe? El precio de esa información es alto). Parece que le gusta más gastar el dinero que gana su familia que ganarlo él mismo. Así que robó una pequeña fortuna del tesoro de su familia y ahora se esconde en los Pisos Brillantes. Si su padre supiera dónde está, seguro que lo buscaría y lo arrastraría de vuelta a casa... sin un dedo del pie por su insolencia." },
		[439] = { file = "439", len = 27.376, text = "Sr. Fizzlebub, El portador de esta carta y yo estamos ideando un negocio al que le invitamos a unirse. Como sabe, paso gran parte de mi tiempo en los Pisos Luminosos, y la empresa mencionada tiene que ver con las carreras de estos pisos. Si le interesan las carreras y, más concretamente, apostar en ellas, siga leyendo, porque creo que su conocimiento de Stranglethorn sería útil en nuestro plan." },
		[440] = { file = "440", len = 28.839, text = "Sr. Fizzlebub, La bebida que le dio a mi socio fue un gran éxito. No sólo es una bebida fuerte, que provoca un gran embotamiento del ingenio, sino que parece tener un efecto adictivo. Estoy seguro de que los que la prueben querrán más. Estamos en deuda contigo, Crank. Y te invito a venir a Shimmering Flats, o a enviar a un confidente, para aprovechar las nuevas oportunidades de juego que tenemos aquí. --Kravel" },
		[441] = { file = "441", len = 26.802, text = "Bien Martek, Estoy en un aprieto y necesito tu ayuda. Mi hermano y yo estamos construyendo un coche de carreras y necesitamos pistones fuertes. Nada de lo que intento es lo suficientemente fuerte. Nada puede aguantar la velocidad de nuestro nuevo coche. Así que el motor se rompe constantemente. Tú eres un experto en trabajar el metal. Debes ayudarnos. Eres el único que puede." },
		[442] = { file = "442", len = 27.925, text = "Para enfrentarte a Frostmaw, debes atraerlo con la carne de su presa favorita. Ve a las Montañas Alterac en Azeroth y caza un imponente puma. Mátalo, y luego lleva su cadáver a la Cueva de Growless, un lugar considerado sagrado por el bestial wendigo. Coloca el cadáver sobre la Llama de Uzel y el olor de la carne quemada saldrá de la cueva. Y entonces, con el tiempo, Frostmaw vendrá." },
		[443] = { file = "443", len = 34.664, text = "No deja de maravillarme lo útil que resulta el odio para que los demás cedan a tus deseos. Los orcos y los trols fueron los más fáciles de engañar, ya que su odio a la Alianza los convierte en serviles sujetos de la Facción Oscura. ¿Acaso tienen idea del poder superior al que sirven? Ese paladín exasperante, Delgren el Purificador, se ha estado metiendo en nuestros asuntos del bosque de Vallefresno, mientras que su lacayo, Balthule, espía mi torre, creyendo que no me percato de su presencia. Delgren nos considera" },
		[444] = { file = "444", len = 23.902, text = "una amenaza menor, tal vez otro culto a la muerte. No sabe que somos nada más y nada menos que... una de las facciones del Consejo de la Sombra. Cuando era niño, me hablaron de un insecto cuya picadura era mortal, pero cuyo aspecto era el de una simple mosca, un puntito difícil de reconocer. Son las cosas que subestimas las que más te hieren, si dejas que la herida se encone." },
		[445] = { file = "445", len = 35.84, text = "Los coches cohete que compiten en las pistas planas están muy afinados y requieren un mantenimiento extremo. Así que no es de extrañar que los equipos de boxes se mantengan en escena en todo momento. Estos equipos prueban constantemente los coches y realizan las correcciones y modificaciones necesarias. Es la única manera de mantener los coches en un estado de máximo rendimiento. Así que... estamos buscando un medio para forzar un lapso en la diligencia de uno de los equipos de boxes, ya que cualquier lapso de este tipo haría que el coche de la tripulación cayera rápidamente en mal estado." },
		[446] = { file = "446", len = 23.954, text = "Si podemos controlar qué coche está en plena forma y cuál no, entonces... No necesito explicarte la ventaja en las apuestas que esto nos da. Así que, de ti, buen Fizzlebub, necesitamos ese medio para forzar el lapso de los equipos de boxes. ¿Posee Stranglethorn alguna planta, hierba o bebida que podamos usar para confundir a gnomos y goblins? --K. Koalbeard" },
		[447] = { file = "447", len = 29.571, text = "He investigado mucho sobre los Aspectos y sus creadores titanes, tanto como cualquier humano podría hacerlo en toda su vida. Había cinco Aspectos cuando los titanes abandonaron este mundo; eran poderosos dragones encargados de proteger el mundo de Azeroth. Sus historias son vastas y variadas, e incluso ahora, a pesar de toda la información que he reunido, sé que aún queda mucho por aprender de estas magníficas criaturas." },
		[448] = { file = "448", len = 30.041, text = "Boticario Lydon, Espero que esta carta le llegue rápidamente y a su portador en buenas condiciones. Ha surgido una necesidad en la lejana Kalimdor que creo requerirá de tus habilidades. Seré breve. Una crisis se desarrolla en las Montañas Stonetalon, no lejos de Mulgore, la tierra natal de nuestros aliados Tauren. La compañía goblin Venture está minando y talando ferozmente en esas montañas, enfureciendo a los espíritus de la montaña." },
		[449] = { file = "449", len = 28.839, text = "Debo suponer que la conmoción que estos espíritus causan a través de canales auspiciados por chamanes y druidas tauren los distrae. Porque los Tauren consideran a la Compañía Venture en las Montañas Stonetalon una amenaza terrible. Amenaza o no, debemos ayudar a nuestros aliados. Lydon, tienes un amplio conocimiento de las toxinas. ¿Puedes idear una que podamos usar para propagar un contagio entre los goblins de Stonetalon? Erudito tuyo, P. Zamah" },
		[450] = { file = "450", len = 28.447, text = "Muchos de los conocimientos que tengo ahora no podría haberlos aprendido por mí mismo. Por eso estoy muy agradecido a los elfos de la noche. Sólo con su ayuda tengo tantos detalles como tengo. Como resultado de nuestras interacciones, tengo la impresión de que sus orígenes están mucho más estrechamente ligados a los Aspectos de lo que había pensado en un principio. Sin embargo, guardan sus secretos con demasiada cautela como para que yo pueda saberlo con certeza." },
		[451] = { file = "451", len = 14.08, text = "La información que aprendí de los Aspectos la pongo aquí para que otros puedan consultarla en el futuro. Sé que resultará útil, ya que creo que estos dragones tendrán un efecto mucho mayor en nuestro mundo a medida que pase el tiempo." },
		[452] = { file = "452", len = 24.607, text = "Alexstrasza: Alexstrasza, la antigua y poderosa Reina de los Dragones, fue nombrada la Vinculadora de la Vida por los titanes. Fue la primera en ser creada por los titanes para proteger el mundo tras su partida. Se dice que fue testigo del nacimiento de todas las razas modernas sobre la faz de Azeroth. Sus dragones rojos, conocidos por su porte orgulloso, dominaron en su día a los demás dragones." },
		[453] = { file = "453", len = 10.606, text = "Los rumores entre los elfos de la noche sugieren que Alexstrasza y el semidiós Cenarius eran amigos íntimos, y que fue él quien la llamó durante la primera invasión de la Legión Ardiente." },
		[454] = { file = "454", len = 23.353, text = "Ysera: Ysera la Soñadora representa el subconsciente mortal. Ella abarca el Sueño Esmeralda. Aunque aprecia la imaginación y la creación y aprueba la ambición en las razas mortales, ella y su vuelo de dragón consideran que el mundo real es sólo una ilusión. Ysera es una de las criaturas más elegantes y poderosas que cualquier mortal pueda contemplar." },
		[455] = { file = "455", len = 23.771, text = "Malygos: Malygos es conocido como el Administrador de la Magia o el Tejedor de Hechizos. Su forma natural no es la de un dragón típico, y se dice que puede cambiarla a voluntad. Raramente visto tras su retirada al lejano norte, casi siempre tiene la forma de una criatura parecida a un insecto, pero mientras está en forma de dragón, él y su dragonflight son de color azul variado." },
		[456] = { file = "456", len = 32.444, text = "Nozdormu: Nozdormu es conocido como el Maestro del Tiempo y el Atemporal. Él y su dragonflight son de color bronce y muestran una gran astucia en todas las cosas. La atención de Nozdormu siempre se ha centrado en coleccionar artefactos del pasado, ya que le importan poco los asuntos actuales de las razas mortales, o incluso los tratos de sus compañeros Aspectos. Sin embargo, su indiferencia hacia la política de los demás no significa que sea complaciente con los acontecimientos que ocurren en el mundo." },
		[457] = { file = "457", len = 23.484, text = "Considerados protectores, los dragonflight de bronce se sienten muy atraídos por las zonas de civilización. El dragón y su vuelo son muy pacientes por naturaleza, siempre se basan en la observación y actúan con un plan antes de precipitarse. Nozdormu siempre intentará proteger la corriente del tiempo y a las razas mortales cuando se vean amenazadas por enemigos mayores." },
		[458] = { file = "458", len = 31.295, text = "Neltharion: Neltharion, llamado el Guardián de la Tierra tras su creación, fue más leal y protector de Azeroth que cualquiera de los otros Aspectos. Su vuelo de dragón negro fue responsable de la creación de las montañas y otras formaciones de las tierras, incluidas las fronteras entre las razas mortales. Lo que causó su corrupción sigue siendo un misterio; ya sea una influencia externa o algo que se pudrió desde dentro. Me pregunto si tal vez los Dioses Antiguos no tuvieron algo que ver en la corrupción del gran negro." },
		[459] = { file = "459", len = 34.351, text = "El dragón negro sufrió una transformación completa y, al final, Neltharion dejó de existir. Se convirtió en Alamuerte, una criatura de malicia y odio. Dejó de ser el Guardián de la Tierra a ojos de razas como los altos elfos y pasó a llamarse Aspecto de la Muerte y Xaxas en lugar del nombre que le había dado el titán. Alamuerte es la encarnación del caos y el mal, y siempre está hambriento de destrucción. Podría decirse que es el primer mal de Azeroth que apareció tras el destierro de los Dioses Antiguos." },
		[467] = { file = "467", len = 39.367, text = "¡ENHORABUENA! ¡Eres la primera persona en poseer el asombroso husmeador taltuza! Aunque se trata de una criatura asustadiza, estamos seguros de que su mullido pelaje y su increíble poder olfativo te atraparán. En las siguientes páginas, encontrarás información sobre tu husmeador taltuza: 1. Alimentación y cuidados 2. Comportamiento excéntrico (y adorable) 3. Uso de la vara de mando del Husmeador(marca registrada) Nuevamente, enhorabuena. No te defraudará, -Marwig Pernoxidado Propietario de Snuff Inc." },
		[507] = { file = "507", len = 33.071, text = "--Día 13 El movimiento de tropas cerca de Theramore ha aumentado. Un gran número de humanos abandonaron la ciudad y se mueven hacia el oeste, a toda prisa. --Día 14 Más tropas abandonan la ciudad. Seguí a un pequeño grupo y observé cómo se quitaban el uniforme tras dejar Theramore a tiro de arco. ¿Quizás sean desertores? --Día 15 Hoy he oído hablar a algunas tropas de Theramore de guardias que abandonaban sus puestos. Mis sospechas sobre los desertores deben ser ciertas" },
		[527] = { file = "527", len = 31.66, text = "El gorrión sangrante: Manifiesto (20) barriles de ron. Destino: Theramore (50) sacos de harina. Destino: Theramore: Theramore (2) cajas de herramientas variadas para gnomos. Destino: Carraca (30) pernos de tela de algodón. Destino: Theramore: Theramore (4) cajas de especias. Destino: Theramore: Theramore (3) pasajeros. Destino: Theramore: Theramore" },
		[528] = { file = "528", len = 34.011, text = "Jorgen, Mis temores se han hecho realidad, y han actuado de formas que nunca creí capaces. Nunca pensé que llegarían tan cerca, pero lo han hecho. Por favor, ayuda al portador de esta nota, y envíaselos a ÉL. Sinceramente, creo que nos ayudará debido a la seriedad de este asunto. Si fuera cualquier otra amenaza, probablemente seguiría ignorándonos a nosotros y a los problemas de nuestra bella ciudad. Gracias, viejo pescador. Estoy en deuda contigo como siempre. Su amigo, DeLavey" },
		[547] = { file = "547", len = 32.104, text = "Capitán, les deseo fortuna en sus viajes. Lamentablemente, la fortuna no favoreció nuestro primer intento de secuestro. Cuando nuestro equipo hizo contacto con el objetivo en los túneles de Stormwind/Ironforge, sólo encontraron un señuelo. Parece que mostró más sabiduría de la que le acreditamos. Pero nuestro segundo plan ya está en marcha. Los agentes de Defias están preparados para interceptar al objetivo cuando se acerque a Theramore. Pronto Stormwind sentirá nuestro mordisco con demasiada intensidad.. -M" },
		[548] = { file = "548", len = 22.988, text = "--Día 16 Uleg y Thargil regresaron de su misión a los muelles de Theramore. Vieron un nuevo barco en el puerto: el Gorrión Sangriento. El barco llegó del puerto de Menethil en Azeroth. Mañana, Uleg y Thargil volverán a los muelles y robarán a bordo del barco. Esperan encontrar documentos políticos, que revelen las relaciones entre Theramore y la Alianza." },
		[572] = { file = "572", len = 24.999, text = "Con el éxito de Kel'Thuzad en Lordaeron, el Rey Exánime hizo los preparativos finales para su asalto contra la civilización humana. Ner'zhul colocó sus energías de peste en una serie de artefactos portátiles llamados calderos de peste y ordenó a Kel'Thuzad que transportara los calderos a Lordaeron, donde serían escondidos en varias aldeas controladas por el culto." },
		[573] = { file = "573", len = 27.011, text = "Los calderos, protegidos por los cultistas leales, actuarían entonces como generadores de la plaga, enviándola a través de las desprevenidas granjas y ciudades del norte de Lordaeron. El plan del Rey Exánime funcionó a la perfección. Muchos de los pueblos del norte de Lordaeron se contaminaron casi de inmediato. Al igual que en Rasganorte, los ciudadanos que contrajeron la plaga murieron y se convirtieron en esclavos voluntarios del Rey Exánime." },
		[574] = { file = "574", len = 28.813, text = "Los sectarios de Kel'Thuzad estaban ansiosos por morir y resucitar al servicio de su señor oscuro. Se regocijaban ante la perspectiva de la inmortalidad a través de la no muerte. A medida que la plaga se extendía, más y más zombis salvajes surgieron en las tierras del norte. Kel'Thuzad observó el creciente ejército del Rey Exánime y lo bautizó como el Azote, pues pronto marcharía hacia las puertas de Lordaeron... y borraría a la humanidad de la faz del mundo." },
		[575] = { file = "575", len = 26.958, text = "Nadie sabe exactamente cómo empezó el universo. Algunos teorizan que una catastrófica explosión cósmica envió a los infinitos mundos hacia la inmensidad de la Gran Oscuridad, mundos que un día albergarían formas de vida de una diversidad maravillosa y terrible. Otros creen que el universo, tal y como existe, fue creado en su conjunto por una entidad singular y todopoderosa." },
		[576] = { file = "576", len = 30.093, text = "Aunque los orígenes exactos del caótico universo siguen sin estar claros, está claro que surgió una raza de seres poderosos para poner orden en los distintos mundos y garantizar un futuro seguro a los seres que seguirían sus pasos. Los Titanes, dioses colosales de piel metálica procedentes de los confines del cosmos, se adelantaron y se pusieron a trabajar en los mundos que encontraron. Dieron forma a sus mundos levantando poderosas montañas y dragando vastos mares." },
		[577] = { file = "577", len = 28.003, text = "Crearon cielos y atmósferas embravecidas, todo ello como parte de su insondable y previsor plan de crear orden a partir del caos. Incluso otorgaron poderes a razas primitivas para que se ocuparan de sus obras y mantuvieran la integridad de sus respectivos mundos. Los Titanes, gobernados por una secta de élite conocida como el Panteón, pusieron orden en cien millones de mundos dispersos por el Gran Más Allá Oscuro durante las primeras eras de la creación." },
		[578] = { file = "578", len = 27.559, text = "El benévolo Panteón, que buscaba salvaguardar sus mundos estructurados, estaba siempre alerta ante la amenaza de ataque de las viles entidades extradimensionales del Nether Retorcido. El Infierno, una dimensión etérea de magia caótica que conectaba los innumerables mundos del universo, era el hogar de un número infinito de seres maléficos y demoníacos que sólo buscaban destruir la vida y devorar las energías del universo viviente." },
		[579] = { file = "579", len = 21.708, text = "--Día 17 Uleg regresó de su misión. Fracasó, y Thargil fue capturado. Envié a Uleg a entregar este informe a Nazeer. Yo permaneceré aquí. He presenciado un aumento de la actividad naviera en la costa de Theramore. Continuaré mi vigilancia y reportaré personalmente cualquier evento digno de mención." },
		[580] = { file = "580", len = 28.97, text = "Nuestro primer plan ya ha fracasado. Fist logró cambiar la lista de guardias para los turnos del túnel esa noche, pero debido a algunos esfuerzos imprevistos de algunos ciudadanos de Stormwind, nuestro objetivo pudo huir de la escena antes de que pudiéramos capturarlo. Pero habíamos previsto tales contingencias. El Plan 2 se ha puesto en marcha y estaba muy avanzado antes de que se desencadenara nuestra emboscada en Stormwind." },
		[581] = { file = "581", len = 16.692, text = "El plan 2 es igual de sencillo, pero requerirá más paciencia por nuestra parte. Nuestro hombre infiltrado en Menethil ya ha sido pagado por sus esfuerzos, y ha tenido un éxito brillante. No deberíamos tener problemas para adquirir a nuestro objetivo y capturarlo una vez que hayamos zarpado." },
		[582] = { file = "582", len = 25.208, text = "Esperen que el ataque ocurra a pocos kilómetros de su destino. Ahí es donde nuestros aliados estarán esperando. No estoy seguro de por qué hemos sido forzados a formar una alianza con las criaturas, pero no puedo evitar sentir que nosotros mismos estamos siendo coaccionados. Al final, no importará. Con el objetivo bajo nuestra custodia, ¡estaremos bien encaminados para recuperar Stormwind de aquellos que nos lo robaron!" },
		[607] = { file = "607", len = 19.775, text = "Maestro Barbalarga Como podrás saber, los Pico Tormenta sabemos apreciar lo bueno y la calidad de tus escudos es famosa entre nosotros. Por ello, es un placer para mí encomendarte la fabricación de un escudo. He incluido las especificaciones en la siguiente página:" },
		[627] = { file = "627", len = 33.829, text = "La devastadora Segunda Guerra contra la horda orca dejó la Alianza de Lordaeron en un estado de desolación y confusión. Los sanguinarios orcos, dirigidos por el poderoso jefe de guerra Orgrim Martillo Maldito, no solo destrozaron todo lo que encontraron a su paso en las tierras de Khaz Modan, en poder de los enanos, sino que también arrasaron muchas provincias centrales de Lordaeron. Los orcos implacables llegaron a arrasar el remoto reino elfo de Quel’Thalas antes de que les pararan los pies." },
		[628] = { file = "628", len = 34.142, text = "Los ejércitos de la Alianza, dirigidos por Sir Anduin Lothar, Uther el Iluminado y el almirante Valiente, expulsaron a los orcos hacia el sur, hasta la tierra desolada de Azeroth, el primer reino que cayó ante el ataque despiadado de los orcos. Las fuerzas de la Alianza, bajo las órdenes de Sir Lothar, lograron expulsar a los clanes de Martillo Maldito de Lordaeron, confinándolos en las tierras de Azeroth controladas por los orcos. Las fuerzas de Lothar rodearon la ciudadela volcánica de la Cumbre de Roca Negra y sitiaron sus defensas." },
		[629] = { file = "629", len = 28.97, text = "En su encarnizada defensa, Martillo Maldito y sus lugartenientes llevaron a cabo una audaz ofensiva desde la Cumbre y combatieron a los paladines de Lothar en el centro de las Estepas Ardientes. Martillo Maldito y Lothar se enzarzaron en una titánica batalla que dejó a los dos poderosos combatientes apaleados y exhaustos. Si bien por poco Martillo Maldito derrota a Lothar, la muerte del gran héroe no tuvo el efecto que el jefe de guerra habría deseado." },
		[630] = { file = "630", len = 22.047, text = "Turalyon, el lugarteniente más leal de Lothar, cogió el escudo de este manchado de sangre y convocó a sus hermanos apesadumbrados para emprender un atroz contraataque. Bajo los raídos estandartes de Lordaeron y Azeroth, las tropas de Turalyon masacraron a casi todas las fuerzas restantes de Martillo Maldito, sometiéndolas a una gloriosa, pero terrible derrota." },
		[631] = { file = "631", len = 29.806, text = "Para los andrajosos y dispersos supervivientes orcos no quedaba otra opción que escapar al último bastión de las fuerzas orcas: el Portal Oscuro. Turalyon y sus guerreros persiguieron a los orcos supervivientes por el inmundo Pantano de las Penas, hasta las corruptas Tierras Devastadas en las que se hallaba el Portal Oscuro. Allí, junto al colosal portal, la horda destrozada y la inquebrantable Alianza se enfrentaron en lo que sería la última y más sangrienta batalla de la Segunda Guerra." },
		[632] = { file = "632", len = 18.756, text = "Inferiores en número y enloquecidos por la maldición de su sed de sangre, los orcos sucumbieron inevitablemente a la ira de la Alianza. A Martillo Maldito lo hicieron prisionero y lo escoltaron hasta Lordaeron, mientras sus clanes rotos fueron acorralados y expulsados al norte, de nuevo en Lordaeron." },
		[633] = { file = "633", len = 29.022, text = "Unos pocos meses tras el final de la batalla de Nethergarde, las fuerzas del Portal Oscuro se unieron y abrieron una nueva entrada a Draenor. Los clanes orcos restantes, bajo el mando del anciano chamán Ner’zhul, volvieron a atacar Azeroth. En el intento de robar ciertos artefactos mágicos que aumentarían el poder de Ner'zhul, los orcos planearon abrir nuevos portales en Draenor que les permitieran escapar a su mundo maldito para siempre." },
		[634] = { file = "634", len = 30.72, text = "Convencidos de que Ner'zhul estaban planeando una nueva ofensiva contra la Alianza, el rey Terenas de Lordaeron envió sus tropas a Draenor para acabar con la amenaza orca de una vez por todas. Bajo las órdenes de Khadgar y el general Turalyon, las fuerzas de la Alianza pelearon contra los orcos en las tierras ardientes. Aun con la ayuda de la élfica capitana especialista Alleria, el enano Kurdran y el soldado veterano Danath, Khadgar no pudo evitar que Ner'zhul abriera sus portales a otros mundos." },
		[635] = { file = "635", len = 31.086, text = "Las terribles tormentas mágicas causadas por las energías convergentes de los portales empezaron a destruir el mundo, ya devastado. Ner'zhul, seguido de sus más fieles siervos, logró escapar a través de uno de los portales, mientras Khadgar luchaba desesperadamente para devolver a sus compañeros a Azeroth. Ante la certeza de que estaban atrapados en el mundo agonizante, Khadgar y sus compañeros decidieron destruir el Portal Oscuro para evitar que Azeroth fuera destruido por el violento ataque de Draenor." },
		[636] = { file = "636", len = 10.501, text = "Según cuentan todos, los héroes lograron destruir el portal y salvar a Azeroth, pero tanto si escaparon como si no, el terrible final de Draenor resulta evidente." },
		[637] = { file = "637", len = 31.242, text = "Diez mil años antes de que los orcos y los humanos se enfrentaran en la Primera Guerra, el mundo de Azeroth era un vasto continente rodeado por mares infinitos. Aquella masa de tierra, conocida como Kalimdor, albergaba numerosas razas y criaturas dispares, pugnando por sobrevivir entre los salvajes elementos del mundo naciente. En el centro del continente oscuro había un lago misterioso de energías incandescentes." },
		[638] = { file = "638", len = 31.007, text = "El lago, que más tarde recibiría el nombre de Pozo de la Eternidad, era el verdadero corazón de la magia y el poder natural del mundo. Extrayendo sus energías de la infinita Gran Oscuridad, más allá del mundo, el Pozo actuaba como una fuente mística, enviando sus potentes energías por todo el mundo para alimentar la vida en todas sus maravillosas formas. Con el tiempo, una tribu primitiva de humanoides nocturnos se acercó cautelosamente a las orillas del fascinante lago encantado." },
		[639] = { file = "639", len = 30.25, text = "Los asilvestrados humanoides nómadas, atraídos por las extrañas energías del Pozo, construyeron toscos hogares en sus tranquilas orillas. Con el tiempo, el poder cósmico del pozo afectó a la extraña tribu, haciéndola fuerte, sabia y prácticamente inmortal. La tribu adoptó el nombre de Kaldorei, que significaba \"hijos de las estrellas\" en su lengua nativa. Para celebrar su incipiente sociedad, construyeron grandes estructuras y templos alrededor de la periferia del lago." },
		[640] = { file = "640", len = 30.746, text = "Los kaldorei, o elfos nocturnos, como se les conocería más tarde, adoraban a la diosa de la luna, Elune, y creían que dormía en las brillantes profundidades del Pozo durante las horas diurnas. Los primeros sacerdotes y videntes elfos nocturnos estudiaban el Pozo con una curiosidad insaciable, impulsados a sondear sus secretos y poderes inconfesables. A medida que su sociedad crecía, los elfos de la noche exploraron la Kalimdor y se encontraron con sus innumerables habitantes." },
		[641] = { file = "641", len = 22.909, text = "Las únicas criaturas que les hacían dudar eran los antiguos y poderosos dragones. Aunque las grandes bestias serpentinas eran a menudo solitarias, hacían mucho por salvaguardar las tierras conocidas de posibles amenazas. Los elfos de la noche creían que los dragones se consideraban los protectores del mundo, y que era mejor dejarlos en paz a ellos y a sus secretos." },
		[642] = { file = "642", len = 30.041, text = "Con el tiempo, la curiosidad de los elfos nocturnos les llevó a conocer y entablar amistad con varias entidades poderosas, entre ellas Cenarius, un poderoso semidiós de los bosques primigenios. El bondadoso Cenarius se encariñó con los curiosos elfos nocturnos y pasó mucho tiempo enseñándoles sobre el mundo natural. El tranquilo Kaldorei desarrolló una fuerte empatía por los bosques vivientes de Kalimdor y se deleitó con el armonioso equilibrio de la naturaleza." },
		[643] = { file = "643", len = 28.264, text = "Sin embargo, con el paso de los siglos, aparentemente interminables, la civilización de los elfos de la noche se expandió tanto territorial como culturalmente. Sus templos, caminos y moradas se extendían por todo el continente oscuro. Azshara, la hermosa y dotada reina de los elfos de la noche, construyó un inmenso y maravilloso palacio en la orilla del Pozo que albergaba a sus sirvientes favoritos en sus salones enjoyados." },
		[644] = { file = "644", len = 28.5, text = "Sus sirvientes, a los que llamaba Quel'dorei o \"de alta cuna\", adoraban todas sus órdenes y se creían superiores al resto de sus hermanos de casta inferior. Aunque la reina Azshara era amada por igual por todo su pueblo, los de la casta superior eran odiados en secreto por las celosas masas. Azshara, que compartía la curiosidad de los sacerdotes por el Pozo de la Eternidad, ordenó a los altos mandos que sondearan sus secretos y revelaran su verdadero propósito en el mundo." },
		[645] = { file = "645", len = 27.481, text = "Los de alta cuna se sumergieron en su trabajo y estudiaron el Pozo sin cesar. Con el tiempo, desarrollaron la capacidad de manipular y controlar las energías cósmicas del Pozo. A medida que avanzaban sus temerarios experimentos, los Highborne descubrieron que podían utilizar sus nuevos poderes para crear o destruir a su antojo. Los desventurados Highborne habían descubierto la magia primitiva y ahora estaban decididos a dedicarse a dominarla." },
		[646] = { file = "646", len = 25.156, text = "Aunque estaban de acuerdo en que la magia era intrínsecamente peligrosa si se manejaba de forma irresponsable, Azshara y sus highborne empezaron a practicar su hechicería con temerario abandono. Cenarius y muchos de los eruditos elfos de la noche advirtieron que jugar con las volátiles artes de la magia sólo podía provocar calamidades. Pero Azshara y sus seguidores siguieron expandiendo obstinadamente sus crecientes poderes." },
		[647] = { file = "647", len = 24.555, text = "A medida que crecían sus poderes, Azshara y la alta sociedad experimentaron un cambio evidente. La altiva y distante clase alta se volvió cada vez más insensible y cruel con sus congéneres elfos de la noche. Un manto oscuro y melancólico cubrió la belleza de Azshara. Comenzó a alejarse de sus amados súbditos y se negó a relacionarse con nadie más que con sus sacerdotes de confianza." },
		[648] = { file = "648", len = 22.256, text = "Un joven y audaz estudiante llamado Furion Tempestira, que había dedicado gran parte del tiempo al estudio de los efectos del Pozo, empezó a sospechar que un terrible poder estaba corrompiendo a los nobles y a su amada reina. Si bien consideraba inconcebible el mal que los acechaba, sabía que las vidas de los elfos de la noche pronto cambiarían para siempre..." },
		[649] = { file = "649", len = 18.86, text = "-Totalmente redondo, cubre toda el área, desde el puño hasta el codo. - Clavos en los bordes. Pieza de plata. - Un clavo grande de plata en el centro, con un ancho de tres dedos. - De roble, reforzado con hierro. - Mi nombre, Gringer Pico Tormenta, grabado en el borde superior." },
		[650] = { file = "650", len = 14.602, text = "El pago se realizará a través de los canales habituales. Y dé al portador de esta petición un estipendio estándar de entrega. Puede añadirlo al coste del escudo. Sinceramente, y muchas gracias, --Gringer Stormpike" },
		[669] = { file = "669", len = 21.525, text = "Los inicios de los no muertos en Azeroth no comenzaron realmente con la corrupción del príncipe Arthas, sino mucho antes. Los acontecimientos que provocaron la caída de Lordaeron se pusieron en marcha mucho antes de ese momento; comenzaron con la llegada de los clanes orcos y la Legión Ardiente." },
		[670] = { file = "670", len = 25.051, text = "Los orcos de Draenor (el mundo del que procedían originalmente) eran nobles y chamanes. Eran guerreros poderosos, fuertes de cuerpo y voluntad. Fue por estas razones que la Legión Ardiente los buscó. Kil'jaeden, un demonio de gran poder entre la Legión, deseaba esclavizar a los clanes orcos y utilizarlos como su ejército contra los mundos que la Legión Ardiente aún tenía que conquistar." },
		[671] = { file = "671", len = 20.114, text = "Kil'jaeden acudió al líder de los clanes, un poderoso chamán llamado Ner'zhul. Le prometió a Ner'zhul un poder y un conocimiento místicos incalculables si hacía un pacto con el demonio que esclavizaría a los clanes a la Legión Ardiente. Este pacto selló no sólo su destino, sino el de su mundo para siempre." },
		[672] = { file = "672", len = 18.077, text = "Con el paso del tiempo, Ner'zhul se dio cuenta del destino de los clanes a manos de la Legión Ardiente, y el chamán orco empezó a desafiar a Kil'jaeden. El demonio, enfurecido por Ner'zhul, recurrió al propio aprendiz del chamán, Gul'dan, que era mucho más corruptible que Ner'zhul." },
		[673] = { file = "673", len = 26.41, text = "Fue Gul'dan el responsable del declive del chamanismo en todos los clanes. La promesa de poder y control sobre los enemigos hacía sus ofertas aún más tentadoras. Con la ayuda de Kil'jaeden, Gul'dan comenzó su manipulación de los clanes. Los orcos, antes nobles, se convirtieron en salvajes corruptos y descerebrados. Con la introducción de sangre de demonio en sus cuerpos, los orcos eran aún más despiadados y bárbaros." },
		[674] = { file = "674", len = 32.052, text = "Aunque Kil'jaeden había corrompido a Gul'dan tras su fracaso con Ner'zhul, odiaba al chamán y juró hacer cumplir su pacto original. Kil'jaeden capturó a Ner'zhul y comenzó una tortura física increíblemente lenta sobre el chamán. Mientras Ner'zhul suplicaba la muerte, Kil'jaeden le recordó que su pacto original seguía siendo vinculante. Kil'jaeden mató al orco, pero sólo físicamente. Kil'jaeden retuvo el espíritu del chamán orco antes de que pudiera encontrar su camino hacia el Infierno Retorcido." },
		[675] = { file = "675", len = 16.927, text = "Kil'jaeden colocó el espíritu de Ner'zhul dentro de un bloque de hielo recogido del Nether Retorcido. Mientras estaba atrapado en el hielo, le infundió aún más poder. La pérdida de su cuerpo y la introducción de tan increíble poder fue la línea definitoria en la transformación de Ner'zhul." },
		[676] = { file = "676", len = 22.047, text = "Kil'jaeden lanzó el bloque de hielo a través de las dimensiones de vuelta a Azeroth, donde aterrizó en el continente de Rasganorte, introduciendo este gran mal en nuestro mundo. Ner'zhul se había ido para siempre; en su lugar había un trono de hielo y odio. El otrora respetado líder chamán se había convertido en el increíblemente poderoso Rey Exánime." },
		[677] = { file = "677", len = 21.081, text = "Como Kil'jaeden no confiaba en el Rey Exánime, envió a sus Señores del Terror para que vigilaran el espíritu y se aseguraran de que el Rey Exánime cumplía sus órdenes. Los siervos vampíricos llegaron a Azeroth voluntariamente, atraídos por la destrucción y el poder del Rey Exánime y el genocidio potencial de toda la raza de un planeta." },
		[678] = { file = "678", len = 29.78, text = "Pasó más de una década. Durante este tiempo, el Rey Exánime utilizó sus vastos poderes para hacerse con el control de las mentes de las criaturas de Rasganorte, a las que ordenó erigir una gran ciudadela sobre su trono helado. Ahora que todo Rasganorte estaba bajo su dominio, el Rey Exánime sabía que necesitaba comenzar su infiltración en Lordaeron. Atrapado en el hielo, el antiguo chamán orco empezó a buscar más mentes que manipular y controlar. Su llamada llegó a todos los continentes." },
		[679] = { file = "679", len = 29.753, text = "La convocatoria del Rey Exánime no pasó desapercibida, especialmente para un pequeño puñado de poderosos individuos. Entre ellos se encontraba el Archimago Kel'Thuzad, que era un poderoso miembro del cuerpo gobernante de Dalaran, el Kirin Tor. Su búsqueda de todo tipo de magia violaba las políticas del Kirin Tor contra el aprendizaje de magias oscuras. Kel'Thuzad abandonó el Kirin Tor y todos sus vínculos con el pensamiento convencional y juró aprender todo lo que pudiera del Rey Exánime." },
		[680] = { file = "680", len = 24.555, text = "Se hizo un pacto entre ambos. Kel'Thuzad recibiría la inmortalidad y un inmenso poder a cambio de servir al Rey Exánime. La primera tarea de Kel'Thuzad fue utilizar su riqueza e influencia en Lordaeron para fundar el Culto de los Condenados. El Culto prometía igualdad y vida eterna a todos sus miembros siempre que hicieran un juramento a Ner'zhul, el dios del Culto de los Condenados." },
		[681] = { file = "681", len = 16.588, text = "Ner'zhul creó entonces artefactos diseñados para propagar la plaga entre las civilizaciones humanas de Lordaeron. Se los dio a Kel'Thuzad, y ordenó al mago que los extendiera por toda la tierra. Los seguidores de su Culto debían proteger los artefactos a toda costa." },
		[682] = { file = "682", len = 22.256, text = "Una vez en el lugar, la plaga comenzó a filtrarse en la tierra y a afectar a sus ignorantes ciudadanos. Mientras Kel'Thuzad observaba, el ejército del Rey Exánime creció rápidamente y pronto se hizo con el control de grandes porciones de la tierra. Este ejército pasó a conocerse como el Azote, pues su único propósito era azotar a la humanidad de todo Azeroth." },
		[690] = { file = "690", len = 19.827, text = "La palabra TRAIDOR aparece escrita toscamente sobre el epitafio finamente grabado, cuyo texto dice: Aquí yace Yuriv. Padre, esposo y paladín. Sus hijos deberán saber que su dedicación a la Luz fue incuestionable. Nunca exigió a los demás nada que él no hiciera." },
		[696] = { file = "696", len = 36.153, text = "Diario - Día 4 I Llevo 4 días varado en la isla, solo con mis pensamientos. Los plátanos son muy sabrosos, pero hay que subir mucho para llegar a ellos. Cuando no estoy consiguiendo comida o protegiéndome de la lluvia periódica, todos mis pensamientos son de rescate. I no tendría tantas esperanzas si no fuera por las cajas de papel y botellas que llegaron a la orilla conmigo. Ahora me río al pensar en todo el tiempo que pasé en aquel barco maldiciendo que me hubiera tocado con un barco lleno de alquimistas y escribas." },
		[697] = { file = "697", len = 35.918, text = "Diario - Día 512 Los plátanos han empezado a hablar conmigo y he aprendido mucho acerca de su cultura. He abandonado la insensible destrucción de sus hogares y el consumo de sus crías. Cuán poco sabía de la gran civilización que estaba destruyendo. Pasando a otra cosa, creo que se me están acabando las botellas y el papel. Cuando veía inicialmente las enormes pilas de papel que llegaron hasta aquí, pensé que nunca se acabarían. Ay de mí, mi diario pronto llegará a su fin." },
		[698] = { file = "698", len = 29.074, text = "La tierra de Azeroth alberga un sinfín de maravillas. Flora, fauna, culturas y magia pululan por su superficie. De hecho, los curiosos encontrarán una variedad ilimitada en este mundo. Basta con mirar. Pero si se mira con suficiente profundidad, se encuentran ventanas a mundos completamente nuevos, y cada mundo alberga sus propias maravillas. Al igual que cada uno alberga sus propios horrores." },
		[699] = { file = "699", len = 18.651, text = "Este es el propósito de mi libro: catalogar a esos seres, esos demonios de otro mundo que destruirían nuestras tierras, para que los exploradores que se topen con ellos sepan a qué se enfrentan. Así que si te consideras un guardián de Azeroth, sigue leyendo. Y conoce a tu enemigo. -Ur Mago de Dalaran" },
		[700] = { file = "700", len = 22.413, text = "El demonio del que escribo es el worgen. El folclore rural antiguo puede evocar a estas criaturas, pues ¿qué hijo de granjero no ha oído historias de hombres lobo bestiales que acechan los bosques y pantanos de las afueras de su pueblo? Y la verdad puede esconderse en esos cuentos: tal vez sean advertencias contra los worgen, veladas como mitos para asustarnos." },
		[701] = { file = "701", len = 21.682, text = "Pero antes de que se descarten estas historias, permítanme asegurar al lector que los worgen son reales. Puede que no sean de nuestro mundo, pero existen avenidas entre su hogar y el nuestro y poderosos hechizos pueden atraerlos hasta aquí. Es mejor no pronunciar tales cantos, porque dondequiera que pisen los worgen, traen consigo el terror y el derramamiento de sangre." },
		[702] = { file = "702", len = 28.63, text = "Los ferocanis se reconocen por su similitud con los lobos de nuestro mundo. Los ferocanis se distinguen fácilmente por su grueso pelaje, sus orejas puntiagudas y sus alargados hocicos, similares a los de los lobos que conocemos. Pero las diferencias también son claras: el grueso pelaje cubre el cuerpo musculoso de la bestia, que luce dos largos colmillos y zarpas afiladas como puñales. Su aullido esconde una malevolencia que ninguna otra bestia natural posee." },
		[703] = { file = "703", len = 31.869, text = "El hogar de los worgen es un lugar oscuro, un lugar de pesadilla. Si ese mundo alberga lugares a salvo de los malditos worgen, mi investigación no ha revelado tales bastiones. Y si uno considera la ferocidad y maldad de los worgen, entonces es probable que no existan tales bastiones. Se supone que los worgen se contentan con permanecer en su mundo, ya que aunque algunos worgen poseen magia poderosa, no han hecho intentos de llegar a Azeroth por su propia voluntad. Y por esto, somos afortunados." },
		[704] = { file = "704", len = 17.58, text = "Como ya se ha mencionado, algunos worgen son expertos en artes místicas, y su magia es de oscuridad y corrupción. Las maldiciones y los venenos sobrenaturales son comunes, así que prepárate: aquellos que se enfrenten a magos worgen deben armarse con protecciones contra las sombras." },
		[705] = { file = "705", len = 20.297, text = "Espero que ningún mago de Dalaran busque a los Worgen, aunque lo haga con la conciencia tranquila. Porque no se puede hacer ningún pacto, no se pueden aprender secretos, nada bueno puede venir de estas bestias. Es mejor dejarlos en su mundo. Porque si las encuentran en el nuestro y no las destruyen, nuestro peligro será terrible..." },
		[711] = { file = "711", len = 26.984, text = "Helgrum, Mis felicitaciones a quien dio la orden de establecer nuestra base de Kargath en las Tierras Baldías. Es un lugar ideal para entrenar a nuestras tropas. Su duro clima, su feroz vida salvaje, sus belicosos nativos y su completa falta de apoyo exterior hacen de este lugar un crisol del que sólo saldrán los mejores guerreros y exploradores. Buena planificación. Bien hecho." },
		[751] = { file = "751", len = 32.653, text = "Estas son las especificaciones del pistón: Longitud: 32 WW Anchura: 12 WW Peso: 23,5 IBG a 25,5 IBG Conducción 70 TC Resistencia al corte: 98 o superior Clasificación Combobule: \"Super stout\" o superior Por si has olvidado las medidas gnómicas: WW = \"Anchura del bigote\" IBG = \"Itty-Bitty Grams\" (gramos pequeños) TC = \"Curvatura de los dedos de los pies\"" },
		[752] = { file = "752", len = 32.653, text = "Aye, mon. Lleva esta carta a Frang en el Valle de las Pruebas. Suele estar fuera de la Madriguera azotando a jóvenes guerreros para que luchen por la Horda. Necesita guerreros astutos como tú para enseñar a los orcos a luchar con algo más que sus músculos. Eres más rápido e inteligente que la mayoría, pero no te jactes de eso... a los orcos no les gustan los insultos. Ellos son buenos aliados, y tal vez te enseñen una o dos cosas también. -Tar'sere" },
		[771] = { file = "771", len = 35.03, text = "ALIMENTACIÓN Y CUIDADOS: Nos comprometemos a proporcionarte todo lo que necesitas para cuidar a tu mascota. Nuestros clientes esperan este nivel de servicio de Snuff Inc, ¡y estamos de acuerdo en ofrecerlo! Para ello, hemos diseñado unos robustos cajones para husmeador taltuza con pequeños orificios, perfectos para mantener a tu mascota en un lugar seguro, alejado de la luz. Para tu comodidad, dentro de cada cajón hay un recipiente con gránulos de comida, ¡impregnados con el atrayente aroma de los tubérculos hojazul (el alimento favorito de husmeadores taltuza)!" },
		[791] = { file = "791", len = 29.962, text = "Describiré las tierras circundantes tal y como las han inspeccionado los exploradores de Kargath: -Colinas rocosas y rojizas y llanuras secas que ofrecen poco soporte para la vida. -Un sol abrasador y fuertes vientos. -No hay lagos ni arroyos. Ni siquiera charcas dispersas. Para encontrar agua, los habitantes deben cavar pozos profundos y fangosos, o chupar la escasa humedad de los raros cactus o hierbas espinosas. En resumen: una vida dura y calurosa." },
		[792] = { file = "792", len = 36.153, text = "Las Tierras Baldías están llenas de enemigos. Los ogros vagan por las abrasadoras arenas, tendiendo emboscadas a los incautos. Los enanos de Hierro Oscuro habitan un cuartel al este de Kargath y luchan contra sus primos de piel más clara en Loch Modan, al norte. Unas bestias brutales y primitivas llamadas Troggs acechan cualquier trozo de sombra que encuentran y lo defienden salvajemente. Y en el este de las Tierras Baldías, en el Barranco de Lethlor, hay dragones. No sabemos cuántos ni cómo de grandes son, ya que los exploradores que se acercan demasiado nunca regresan." },
		[793] = { file = "793", len = 15.909, text = "No hace falta decir que nosotros, los de la guarnición de Kargath, estamos muy contentos con nuestra misión. Aquí somos duros, porque si nos ablandamos, morimos. Y yo no lo haría de otra manera. Neeka Bloodscar Jefe Explorador, Kargath" },
		[794] = { file = "794", len = 26.044, text = "Nuestro mundo rebosa historia. Historia de razas nuevas y antiguas. Historia de guerras ya muertas y de guerras que aún arden. Historia de dioses que nos visitan desde los cielos. E historia de dioses más antiguos que duermen en la tierra. Hablo ahora de esos seres: los Dioses Antiguos. Aquellos que habitaron y arrasaron Azeroth cuando el mundo era nuevo." },
		[795] = { file = "795", len = 35.683, text = "Los Dioses Antiguos son la voluntad de nuestro mundo. En cada tormenta ruge la risa de un Dios Antiguo. El resplandor de un incendio forestal es el calor de su mirada. Cuando los Dioses Antiguos caminan, la tierra tiembla y se rompe, y los seres inferiores gritan y se desgarran la carne con desesperación. Y deberían desesperarse, porque al igual que el fuego no tiene piedad de la mano curiosa de un niño, los Dioses Antiguos no se preocupan por los que están por debajo de ellos. En el mejor de los casos, somos peones. En el peor, somos juguetes." },
		[796] = { file = "796", len = 27.22, text = "Fueron los primeros amos del mundo y gobernaron con poder y terror. Aunque ahora están encadenados y dormidos, sus siervos siguen vagando y nosotros, pequeños y frágiles mortales, no podemos igualar su fuerza. Los que lo intentan son devorados. Pero aquellos que conocen su lugar, que se arrodillan suplicantes ante los siervos de los Dioses Antiguos, que sacrifican voluntariamente mente y alma... sólo ellos encontrarán favor." },
		[797] = { file = "797", len = 27.742, text = "Aku'mai, Princesa de las Profundidades, sirve a los Dioses Antiguos. Habita en las Profundidades de Blackfathom y bendice sus cuevas con su sabiduría ancestral. Traída a las Profundidades por los antiguos mortales, Aku'mai es un símbolo de la divinidad. No tiene más que una pizca del poder y el salvajismo de los Dioses Antiguos, pero el suyo está más allá de toda medida. Y por eso es venerada. Y es temida y amada. --Lorgalis" },
		[811] = { file = "811", len = 31.112, text = "El plan se ha puesto en marcha. Utiliza como campamento base el que antaño fuera el gran bastión de fe, la Vigilia de los Héroes, y empezaremos a enviarte refuerzos desde los Páramos de Poniente cuando nos mandes un mensaje que indique que ya está preparado. El área en cuestión no ha sido olvidada por los ciudadanos y soldados de Ventormenta y debería ser un centro de operaciones perfecto desde el cual realizar nuestros ataques. ¡Los Defias recuperarán Ventormenta! Aguardo tu respuesta." },
		[812] = { file = "812", len = 36.519, text = "Los sucios troggs son tan fáciles de engañar. Su odio hacia nuestros parientes hace que sea mucho más fácil dirigirlos y usarlos como peones. Me sorprende que se haya podido forjar algún tipo de alianza, pero nuestros parientes suponen una amenaza mucho mayor para su existencia... al menos por ahora. Asin embargo, cuando comiencen los ataques, ambos bandos quedarán debilitados y propensos a nuestro propio ataque. Tomen la granja al sur del lago Helm's Bed y esperen más instrucciones. Ironforge será nuestra." },
		[831] = { file = "831", len = 13.845, text = "En las páginas siguientes, encontrarás una lista de los materiales necesarios para fabricar una armadura endurecida por el fuego. Buena suerte, guerrero. -Furen Barba Larga" },
		[832] = { file = "832", len = 16.875, text = "Colmillos de araña chamuscados: El mineral de incendicita que se encuentra en una cueva cercana a las inmediaciones de la Roca de Thelgen ha chamuscado a las arañas que allí habitan. El veneno de sus colmillos hierve y reacciona con los propios colmillos para crear una sustancia muy dura." },
		[833] = { file = "833", len = 19.957, text = "Cuernos carbonizados: Al igual que los colmillos chamuscados de araña, los cuernos carbonizados de las quimeras que residen en el Valle Carbonizado, en las Montañas Stonetalon de Kalimdor, poseen una cualidad muy apreciada. Machacados y tratados adecuadamente, se vuelven extremadamente resistentes al estrés físico." },
		[834] = { file = "834", len = 13.636, text = "Cuerno galvanizado: La dureza del raro cuerno galvanizado es el eje de toda la armadura que voy a crear, así que también hay que conseguirlo. ISe puede obtener de la rara matriarca quimera del Valle Carbonizado." },
		[835] = { file = "835", len = 24.921, text = "Frasco de flogisto: La última etapa de la creación de la armadura requerirá una forja extremadamente caliente. Para producir el nivel de calor necesario necesito un frasco de flogisto. El único fabricante conocido de esta sustancia es el legendario Quilboar, Roogug, y no se rendirá sin luchar. Roogug habita en las profundidades de Razorfen Kraul, en los Barrens del sur." },
		[855] = { file = "855", len = 12.069, text = "A continuación encontrarás lo necesario para mi hechizo de invocación del gran Ciclón. Que la fortuna te acompañe. --Bath'rah el Vigilante del Viento" },
		[856] = { file = "856", len = 12.277, text = "Liferoot: Este puede ser recogido de la naturaleza, o adquirido de las bestias Withervine de Dustwallow Marsh. Su poder será necesario para atraer la esencia vital de Cyclonian a este mundo." },
		[857] = { file = "857", len = 16.039, text = "Bloodscalp Tusks: Los colmillos de los Trolls Bloodscalp del Valle Stranglethorn tienen una cualidad poco común. La depravación de los Bloodscalps se concentra en sus colmillos, y si se muelen en polvo pueden desatarse sus viles poderes." },
		[858] = { file = "858", len = 18.469, text = "Esencia del Exilio: Esta esencia se obtiene mediante la fusión de los tres amuletos de los exiliados elementales de las Tierras Altas de Arathi. Reúne los amuletos Trueno, Ardor y Cresta de los elementales y coloca ocho de cada uno en mi caldero. De los amuletos se formará la esencia del exiliado." },
		[871] = { file = "871", len = 33.567, text = "$N, Antes de continuar, permítame agradecerle de nuevo todo lo que ha hecho por mi esposa y por mí. Le salvó la vida, y por eso, le debo mucho más de lo que podría pagarle en cien vidas. Ella lo es todo para mí. Si hubiera muerto... bueno, no sé lo que habría hecho. Aquí está la lista de cosas que necesitarás recuperar si voy a forjar un arma sagrada para ti. Las puse en orden de lo que me pareció más fácil a lo más difícil... espero que eso te lo haga más sencillo." },
		[872] = { file = "872", len = 32.522, text = "Algo de buen roble blanqueado - Antes de que se apoderaran de él, las minas situadas bajo Moonbrook, en Westfall, tenían abundancia de esta madera; la utilizaban en la construcción de algunas de sus celosías y herramientas más importantes por su resistencia al calor y la presión. La trajeron allí después de transportarla desde algún lugar del extranjero. Es una madera poco común y lo bastante resistente como para utilizarla en la fabricación de tu arma. Si queda algo de ella en las minas, los goblins talladores de madera la tendrían." },
		[873] = { file = "873", len = 27.585, text = "Mineral refinado - Hay un enano en Thelsamar, un herrero con el que entrené durante algún tiempo, llamado Bailor Stonehand. Hace una aleación muy especial que creo que sería perfecta para tu arma. Esperaba que llegara un cargamento de la aleación mientras estaba en Ironforge, pero aún no he sabido nada de él. Encuéntralo y comprueba el envío. Y si ya no está en Loch Modan, al menos sabría qué ha sido de mi antiguo maestro." },
		[874] = { file = "874", len = 30.563, text = "Martillo herrero - Antes de la llegada de la Plaga y de la traición de Arthas, vivía en un pueblo llamado Pyrewood, en las profundidades del hermoso bosque de Silverpine. El bosque ya no es tan hermoso como antes, y el torreón donde aprendí el secreto del acero hace tiempo que se ha corrompido y ensuciado, invadido por criaturas de una maldad inimaginable. Cuando mi esposa y yo escapamos de lo que ahora se llama la Fortaleza de Colmillo Sombrío, dejamos algunas de nuestras posesiones más preciadas." },
		[875] = { file = "875", len = 31.007, text = "Entre ellos, el martillo de herrero que me regaló mi padre. Lo dudé en mi juventud, pero siempre me dijo que el martillo estaba encantado, y es el último recuerdo que tuve de él antes de que lo matara el Azote. Tráeme mi martillo, $N, para que pueda usarlo como foco de mi pasión. Si en verdad está encantado, entonces sólo nos ayudará a ambos. Lo dejé en los establos del patio principal de la fortaleza. A menos que las criaturas de allí se hayan dedicado a la herrería, espero que siga allí." },
		[876] = { file = "876", len = 34.482, text = "Una Gema Kor - Por lo que me han contado, las gemas son utilizadas por algunos lanzadores de conjuros para retener energía para sus magias, haciéndolas aún más mortíferas. Un elfo nocturno al que ayudé una vez, Thundris Windweaver, puede contarte más, ya que hablarás en mi nombre. Creo que una de las energías almacenadas en la gema puede usarse en la creación de tu arma. La última vez que hablamos, Thundris estaba en Auberdine, una ciudad en lo profundo de Darkshore, el bosque corrupto que salpica la costa bajo la sombra de la patria de los elfos de la noche." },
		[891] = { file = "891", len = 10.998, text = "Los arremolinados símbolos y pictogramas que llenan las páginas de este manual son esotéricos más allá de la comprensión." },
		[911] = { file = "911", len = 13.375, text = "Consigue un Jade. Se esconden en muchos lugares diferentes. Son raros, pero si hablas con un herrero o ingeniero puede que tengan uno o dos de sobra." },
		[931] = { file = "931", len = 26.984, text = "$N, a continuación están los elementos necesarios para crear tu armadura: Lingotes de hierro ahumado de los kobolds Windshear en la mina Windshear en las montañas Stonetalon. Azurita en polvo de los mineros de Hillsbrad en Hillsbrad. Lingotes de hierro de los mineros, o de depósitos de hierro si eres minero. Frasco de flogisto, de un quilboar llamado Roogug en Razorfen Kraul." },
		[951] = { file = "951", len = 38.269, text = "(Sólo partes del diario son legibles a través de las manchas). Uldaman, Día 3 No puedo creer lo tonto que fui. Ser sorprendido a ciegas por los asquerosos enanos de Shadowforge fue una hazaña de novato. Mis heridas sanan lentamente; seguramente estoy envenenado. Siento que mi energía se agota. Sin embargo, debo seguir explorando... ...para empeorar las cosas, ¡el collar que me hizo el gnomo se ha hecho añicos! Tres de las gemas más grandes se han perdido. Debo encontrarlas; sin ellas el collar no tiene poder..." },
		[971] = { file = "971", len = 24.059, text = "Uldaman, Día 4 ...la primera pista se reveló en las profundidades de Uldaman, cuando uno de los troggs más salvajes que he visto blandía un gran zafiro, uno que apuesto encajaría perfectamente en el collar. Escuché a uno de los enanos de Shadowforge mencionar el nombre de la bestia: Grimlok. El grupo de guardianes que este bruto Grimlok tiene, sin embargo..." },
		[972] = { file = "972", len = 33.306, text = "Uldaman, Día 5 ...el trogg, luego tomando el topacio de sus \"hermanos\" asesinados, marchó a la cueva lateral cerca del frente de la sala... ...se apresuró a colocar el topacio en una urna grande y llamativa hacia el fondo de la sala... ...de todas las cosas, ¡enanos! Tres de ellos, para arrancar. Están atrincherados contra los troggs. Llamarlos habría sido una llamada al suicidio, no fuera que me invadieran los asquerosos troggs en mi debilitado estado. Sin embargo, una vez que conozca la tercera gema..." },
		[973] = { file = "973", len = 15.438, text = "Uldaman, Día 6 ...muy hambriento. Estoy sin provisiones, y consideraría pan mohoso un festín en este momento. Fui testigo de cómo la cabeza de un trogg se convertía en un jugoso filete delante de mis propios ojos..." },
		[974] = { file = "974", len = 30.563, text = "Uldaman, Día 7 ...última oportunidad de redención por mis fracasos. Creo que el rubí está en la última zona atrincherada que los enanos tienen contra los troggs. Sus batallas, sin duda por las gemas y los otros artefactos de este sitio, arrecian continuamente. Sería propio de esos viles enanos esconderla en algún lugar de allí. En cualquier caso, debo hacer un movimiento de una manera u otra. Tal vez una carrera loca hacia la superficie sea lo mejor..." },
		[991] = { file = "991", len = 25.286, text = "Consigue una Zarza cargada de rayos. Para conseguirla, reúne 10 varas de tótem Witherbark de los trols Witherbark de las tierras altas de Arathi. Lleva los palos al Círculo del Vínculo Exterior, un círculo de piedras en esas mismas tierras altas. Coloca los palos en la piedra central del círculo y espera a que caiga un rayo. Cuando lo haga, se formará la Zarza Cargada de Rayos." },
		[992] = { file = "992", len = 10.109, text = "El portador de este certificado tiene derecho al respeto y la consideración que merece cualquier ladrón de primera categoría." },
		[1011] = { file = "1011", len = 26.41, text = "¡He encontrado un método para entrar en la Cámara de Khaz'mul! Coge el Medallón de Gni'kiv de mi pecho. Derrota al trogg Revelosh en la cámara anterior a la sala de mapas y recupera el Pozo de Tsol. Une el medallón y el eje en el Báculo de la Prehistoria. Usa el bastón en la sala de mapas para desbloquear la puerta de la Cámara de Khaz'mul. Haz estas cosas, ¡y la cámara será tuya! -Baelog" },
		[1051] = { file = "1051", len = 33.254, text = "Los guardias de esta torre parecen ser especialmente débiles a mis ataques. Mientras exploraba la parte trasera de la torre, un patrullero me vio y atacó. Pude deshacerme fácilmente del guardia con un golpe oportuno seguido de una puñalada por la espalda. Esperé escondido a que su compañero viniera a investigar la conmoción. El patrullero se acercó a los arbustos donde yo había arrastrado el cadáver e inició una búsqueda. Lentamente, con cuidado, me acerqué por detrás, sin querer que descubrieran mi emboscada." },
		[1052] = { file = "1052", len = 25.156, text = "Cuando se presentó la oportunidad, le clavé mi daga en el trasero. Sus pulmones cedieron rápidamente ante la fuerza del ataque y su cadáver cayó al suelo con un ruido sordo. Había sido una emboscada tan rápida y violenta que el pobre imbécil ni siquiera tuvo tiempo de gritar de dolor. Curiosamente, cuando le quité la espada del trasero, un olor nauseabundo se filtró por el perforado patrullero." },
		[1053] = { file = "1053", len = 21.264, text = "Parece que lo que sea que Klaven ha encerrado en el cofre está teniendo efectos adversos sobre los habitantes de la torre. Sospecho que los otros guardias pueden tener debilidades similares y tal vez, incluso el propio Klaven ha sido víctima de las consecuencias. Agente Amber Kearnen SI:7 Operativo a nivel del suelo, R8" },
		[1071] = { file = "1071", len = 19.54, text = "Comandante, Regresa a Orgrimmar. Sus fuerzas son inadecuadas. Debemos reanalizar nuestra posición basándonos en nueva información. Gran número de Shadowsworn y Ogros presentes. Demonios custodian el Portal Oscuro. -Thrall, Jefe de la Horda" },
		[1091] = { file = "1091", len = 22.387, text = "El mazo de Zul'Farrak Para crear el Mazo de Zul'Farrak, primero hay que viajar al Altar de Zul y obtener el mazo sagrado de un Guardián trol. Después, hay que llevar el mazo sagrado al altar de la ciudad trol de Jintha'alor. El uso del mazo sagrado en el altar le infundirá poder y lo transformará en el Mazo de Zul'Farrak." },
		[1131] = { file = "1131", len = 79.726, text = "TARJETA DE DATOS SUPERCRÍTICOS CON TRIPLE CODIFICACIÓN 01010100 01101000 01110010 01100001 01101100 01101100 00100000 01100001 01101110 01100100 00100000 01001010 01100001 01101001 01101110 01100001 00100000 01110011 01101001 01110100 01110100 01101001 01101110 01100111 00100000 01101001 01101110 00100000 01100001 00100000 01110100 01110010 01100101 01100101 00101100 00100000 01001011 00101101 01001001 00101101 01010011 00101101 01010011 00101101 01001001 00101101 01001110 00101101 01000111" },
		[1151] = { file = "1151", len = 16.98, text = "La Compañía Venture\010texto ilegible\010Parece que los tontos casi aniquilaron toda su operación al tratar de estabilizar la mezcla.\010varias páginas parecen estar arrancadas" },
		[1152] = { file = "1152", len = 9.221, text = "Lo que he notado es que las consecuencias son extremadamente letales. Imagínate si\010texto ilegible\010¡Jajaja!" },
		[1153] = { file = "1153", len = 13.113, text = "¿Me estoy volviendo loco? Hoy he cortado la cabeza de uno de mis patrulleros de confianza para ver mejor su alma. Mientras miraba por el conducto respiratorio cortado, se me ocurrió: ¡Hacía días que no comía nada!" },
		[1154] = { file = "1154", len = 12.826, text = "Mathias Shaw ha enviado un recadero para matarme.\010texto ilegible\010Ahora patrulla afuera. Sin sentido, zángano sin vida. ¡Hahahah!" },
		[1155] = { file = "1155", len = 14.968, text = "VanCleef...\010texto ilegible\010¿Me llamó? ¿QUIÉN SE CREE QUE ES? ¡Soy Klaven Mortwake! ¡No dejaré que un insecto me diga qué hacer!\010falta el resto de las páginas del libro" },
		[1156] = { file = "1156", len = 16.431, text = "Curgle, He estado esperando ansiosamente su nuevo invento. Estoy impaciente por empezar a utilizarlo para documentar mis estudios. Por favor, confíalo a mi mensajero. Saludos cordiales, Daryn Lightwind" },
		[1191] = { file = "1191", len = 59.742, text = "¡DATOS ULTRA VITALES! ÍNDICE DE SEGURIDAD 5122 01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101" },
		[1192] = { file = "1192", len = 59.559, text = "¡NO permita que esta información caiga en manos del enemigo! 01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010" },
		[1193] = { file = "1193", len = 85.969, text = "Índice de seguridad 10^10000 ¡datos supersensibles! 01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001" },
		[1194] = { file = "1194", len = 9.927, text = "¡El grado de seguridad de estos datos es tan alto que está pendiente la invención de un nuevo número para describirlos!" },
		[1211] = { file = "1211", len = 33.593, text = "SACAR A PASEAR AL HUSMEADOR TALTUZA Al husmeador taltuza le gustan los lugares oscuros y pequeños. Y es muy asustadizo. Si deseas sacar a pasear al tu husmeador taltuza, deberás llevarlo a lugares en los que se sienta a gusto. ¡Y DEBES llevarlo allí donde pueda oler su comida favorita: tubérculos hojazul! El lugar que más adecuado es la zona de las \"zanjas\" del Horado Rajacieno. Si abres la caja del husmeador taltuza cerca de la zanja y el animalillo huele los tubérculos hojazul que hay cerca de ahí, se atreverá a salir y te seguirá." },
		[1212] = { file = "1212", len = 25.704, text = "LA VARA DE MANDO DEL HUSMEADOR (mr) El husmeador taltuza es un animal sorprendente. No solo inspira amor y afecto en el zancudo de llanura más irritable, ¡sino que puede oler un tubérculo hojazul enterrado a unos 45 metros! Si deseas que tu husmeador taltuza vaya a buscar un tubérculo hojazul, puedes usar tu vara de mando patentada (se adquiere por separado). En la página siguiente encontrarás la dirección..." },
		[1213] = { file = "1213", len = 36.467, text = "\"Todos nuestros husmeadores están altamente adiestrados. Un simple movimiento de la vara de mando hará que cualquier husmeador taltuza que esté cerca entre en el \"modo de búsqueda.\" A continuación, olfateará el suelo en busca de tubérculos hojazul y, si encuentra uno, irá a buscarlo y lo desenterrará. Si vuelves a mover el mando mientras el husmeador busca su tubérculo, abandonará la búsqueda y regresará contento a tu lado. ¡Confiamos en que nuestros husmeadores taltuza te parezcan animales bien adiestrados, útiles y esponjosos, que querrás apretujar a todas horas\"." },
		[1214] = { file = "1214", len = 32.418, text = "Lamentamos tener que informar que en Snuff Inc. sabemos de la existencia de ciertos glotones cazadores de tubérculos a los que poco importa la seguridad de sus adorables mascotas, enviándolas a lugares oscuros y peligrosos en busca de tubérculos. No aprobamos esta conducta irresponsable, así que con el propósito de satisfacer a nuestros clientes, hemos incluido una garantía con cada husmeador taltuza vendido, ofreciendo a los nuevos dueños la posibilidad de volver al punto de venta y recuperar a su husmeador taltuza perdido. ¡Feliz caza!" },
		[1231] = { file = "1231", len = 18.939, text = "Esta prueba de hazaña es para verificar que $n mató a Margol el Rager, azote del desfiladero abrasador. El museo de Ironforge reconoce este logro y agradece al portador su generosa contribución. -Conservador jefe Thorius Stonetender" },
		[1251] = { file = "1251", len = 40.098, text = "En estos meses he podido reflexionar y he cuestionado mis antiguas creencias e intolerancias. ¿Alianza? ¿Horda? ¿Bien? ¿Mal? El significado de estas palabras, que antes parecía tan claro, ahora se difumina mientras mis ojos se pierden en el mar infinito. Ahora sé lo que importa. Los plátanos me persiguen. Colgados en sus árboles, me observan con fría malevolencia. ¡Y el último que intenté comerme me produjo arcadas! Creo haber oído cómo gritaba mientras lo arrojaba, a medio comer, sobre las rocas marinas. Es la guerra, y la ganaré." },
		[1271] = { file = "1271", len = 36.937, text = "Las Disciplinas de la Ingeniería Si bien es discutible qué raza fue la primera en idear la ciencia de la ingeniería en Azeroth, hay poca discusión sobre qué razas son las principales defensoras de la misma en los tiempos modernos: los gnomos y los goblins. Su dedicación a la ingeniería como un todo colectivo no sólo ha impulsado fantásticos inventos en lo que podría decirse que es una mágica Era de la Invención, sino que también ha alimentado su intensa rivalidad racial. En ninguna parte es esto más evidente que en sus disciplinas divergentes." },
		[1272] = { file = "1272", len = 29.649, text = "Ingeniería gnoma Los gnomos tienden a destacar en el diseño de objetos destinados a manipular y controlar el mundo que les rodea. Aunque tienen conocimientos básicos de explosivos y armamento, la ingeniería gnoma se centra en objetos que, literalmente, intentan hacer la vida más fácil y accesible. Es una disciplina de posibilidades teóricas hechas realidad gracias al saber hacer gnomo. Algunas posibilidades, sin embargo, nunca llegan a realizarse del todo." },
		[1273] = { file = "1273", len = 31.895, text = "Ingeniería Goblin A Como raza que se considera neutral en casi todos los conflictos, los goblins han dado grandes pasos para convertir la ciencia en beneficio. Adoptan las aplicaciones prácticas de la ingeniería, como demuestran sus radicales diseños de explosivos, armas de fuego y maquinaria. La ingeniería goblin sólo mantiene un interés pasajero por la teoría de la ingeniería; sus inventos no suelen tener el problema de no funcionar, sino de funcionar demasiado bien. Desde luego, no es para los débiles de corazón." },
		[1274] = { file = "1274", len = 31.007, text = "Estudio de Disciplinas Los gnomos y los trasgos protegen sus conocimientos entre sí hasta tal punto que es casi imposible acceder a ambos conjuntos de disciplinas simultáneamente. Cada raza, independientemente de sus afiliaciones políticas, mantiene el conocimiento de estas disciplinas disponible sólo para aquellos que aceptan renunciar a la búsqueda de la disciplina de la otra. Si, por ejemplo, un estudiante opta por la ingeniería gnoma, nunca tendrá acceso a los conocimientos de la ingeniería goblin." },
		[1275] = { file = "1275", len = 33.175, text = "Decisiones permanentes La sección anterior destacaba un punto importante sobre las dos disciplinas de la ingeniería que debe reiterarse por el bien de la educación. La decisión de dedicarse a una de las dos disciplinas significa que los esquemas de la disciplina opuesta no estarán disponibles para su estudio. Aunque tal finalidad puede resultar desalentadora para el ingeniero profano, el experimentado comprende que gnomos y duendes guardan sus secretos con total fervor; siempre es mejor un poco de conocimiento que ninguno." },
		[1276] = { file = "1276", len = 25.286, text = "Quotes \"¿Quieres saber algo de ingeniería goblin? Pregúntaselo a uno de sus mejores y más brillantes ingenieros. Creo que se llama 'Nubby Stumpfingers'. ¿Quieres saber por qué se llama así? ESO ES ingeniería goblin.\" -- Ringo Tragediction, ingeniero gnomo \"Di lo que quieras de nosotros los goblins, pero te diré una cosa: ¡TENEMOS EXPLOSIVOS!\" -- Yazz Nitrospork, duende bombardero." },
		[1277] = { file = "1277", len = 25.469, text = "Más citas: \"¿Conoces esa sensación que tienes cuando terminas de hacer algo y lo enciendes por primera vez para experimentar el poder y la alegría de la invención cuando tu dispositivo cobra vida? Los gnomos no la tienen.\" -- Nixx Sprocketspring, Maestro Ingeniero Goblin de Gadgetzan \"¡La ingeniería consiste en tomar la fantasía y hacerla fantástica!\" -- Rovis McCrankenspank, inventor gnomo" },
		[1291] = { file = "1291", len = 32.235, text = "El conjuro de la bestia: Para conjurar al Felhound Rastreador, debes usar el Fel Orb suministrado. Notas: El Felhound Tracker conjurado sólo permanecerá como entidad en este mundo durante treinta minutos. El Felhound Rastreador conjurado solo te ayudará a encontrar formaciones de Azsharita. El Felhound Rastreador conjurado NO hará lo siguiente: Trucos, atacar nada, ayudar nada, bailar, destruir seres arcanos. Siguiente página por favor..." },
		[1292] = { file = "1292", len = 27.402, text = "El control de la bestia: Los Felhound Rastreadores sólo responden a rugidos bestiales. Para que tu Felhound Rastreador rastree formaciones azsharitas, ¡debes rugirle con vigor! (Apunta al Felhound Rastreador y /rugido). Cuando el rastreador Felhound localice una formación, correrá hacia ella sin importarle las entidades que le rodean. Aunque no necesitas proteger al Felhound, es posible que quieras permanecer cerca para no perderlo." },
		[1293] = { file = "1293", len = 16.353, text = "La eliminación de la bestia: Después de treinta minutos, la bestia volverá a su hogar en el Nether. Nota: En su fervor, la bestia PUEDE despeñarse o caer por una montaña. No llores la pérdida del Felhound Tracker, invoca a otro en su lugar." },
		[1311] = { file = "1311", len = 22.518, text = "A quien corresponda: Si usted está leyendo esta nota, entonces usted está en uno de dos lugares: (1) En la península sur de Azshara. (2) Dentro del vientre de un Gigante del Acantilado. Ambos igualmente indeseables. Cabe señalar que yo fui lo primero en su día y, en el momento de escribir esta carta, lo segundo." },
		[1312] = { file = "1312", len = 19.095, text = "Estar dentro del vientre de un gigante da tiempo para la reflexión. Mientras mi cuerpo se cristaliza, he llegado a la conclusión de que quizá ya haya suficientes héroes en este mundo. Si de algún modo salgo de este apuro, ¡voy a hacer sonar el cuello fantasmal de ese orco! - Windan Shay" },
		[1313] = { file = "1313", len = 29.336, text = "¿En qué estaba pensando? Tal vez una pregunta mejor sería: ¿Qué hago escribiendo una nota mientras estoy cautivo en el estómago de un gigante? Ambas son buenas preguntas para las que no tengo respuesta inmediata... Hay que reconocer que la mía no fue una misión de buena voluntad. Vine en busca de Azsharita, un cristal único del sur de Azshara. ¡Oh, las riquezas que habría tenido! ¡Bah! Ahora mírame..." },
		[1314] = { file = "1314", len = 10.083, text = "Si algún tipo de vida inteligente encuentra esta nota, debe preguntarse algo: \"¿Por qué demonios retozan con violentos gigantes de nueve metros?\". - Mook" },
		[1392] = { file = "1392", len = 25.704, text = "Hermano Neals, ¡Mis uvas se han salvado! $N, el portador de este manifiesto, entró en mi viñedo lleno de matones y recogió todas las uvas que yo no pude cosechar. Si bien los Defias siguen deambulando por el río, casi toda mi cosecha se ha salvado. Puedes agregar a tus almacenes un cargamento de varias fanegas de uvas. Que la Luz nos proteja, Milly Osworth" },
		[1431] = { file = "1431", len = 13.244, text = "Vorfalk Irongourd Vorfalk trabaja en el almacén del Grim Guzzler, y su sacrificio a los Guardianes de la Oscuridad es profundo. Que su espíritu se mantenga fuerte." },
		[1432] = { file = "1432", len = 12.826, text = "Bethek Ceja de Tormenta Las andanzas de Bethek le llevan a lo más profundo de Blackrock. Los secretos de la montaña le atraen. Que su espíritu nunca decaiga." },
		[1433] = { file = "1433", len = 12.878, text = "Uggel Hammerhand Uggel es un cincelador hábil y solemne, y cuando no está cargado con la llave oscura, sus manos dan forma a grandes obras en la Sala de la Artesanía." },
		[1434] = { file = "1434", len = 18.547, text = "Zimrel Diente Oscuro Cuando la locura de la llave oscura se apodera de Zimrel, sólo los gritos de los moribundos pueden calmarlo. Por su sacrificio, siempre tendrá un banco sobre la arena. Que nuestros deportes de sangre templen la rabia de su corazón." },
		[1435] = { file = "1435", len = 18.782, text = "Ofgut Stonefist Los caídos ante el martillo del Guardián Oscuro Ofgut no pueden contarse. Los soldados de la Guarnición del Oeste se inclinan sobrecogidos a su paso. ¿Quién de ellos puede mirar a los ojos de Ofgut y ver los secretos que susurra la llave oscura?" },
		[1436] = { file = "1436", len = 23.745, text = "Pelver Deepstomp El Guardián Oscuro Pelver es nuestro discípulo más honrado. Ha llevado la llave durante más tiempo que nadie, y le ha costado caro. Cuando es llamado por su carga, es custodiado en el Domicilio. Su sacrificio es apreciado, y permanecerá en nuestros corazones durante muchos años... después de que la oscuridad se lo lleve." },
		[1471] = { file = "1471", len = 31.112, text = "Solomon, Al portador de este decreto se le ha concedido estatus oficial como diputado en funciones de Stormwind. Puedes utilizarlo para encontrar pruebas de la implicación del dragonflight negro con los orcos de Blackrock. Si tal prueba fuera encontrada, este diputado me devolverá dicha prueba a Stormwind, momento en el cual yo liberaré la orden de dispensar suficiente fuerza militar para ayudar a Lakeshire. Regards, Highlord Bolvar Fordragon" },
		[1551] = { file = "1551", len = 29.858, text = "¡Saludos y Salutaciones, Aventureros! Yo, Krinkle Goodsteel, necesito a aquellos dispuestos a arriesgarse para completar algunas de mis tareas más arduas. Debido a mis muchas obligaciones y a la carga de trabajo que he conseguido asumir, aseguro que cualquiera que sea lo bastante valiente como para completar esta lista de objetos y devolvérmela intacta recibirá una generosa paga. La lista figura en las páginas siguientes..." },
		[1552] = { file = "1552", len = 25.286, text = "Piernas de cristal macizo - Las arañas Glassweb de Searing Gorge están hechas de un increíble material parecido al cristal. Sus patas, si no se dañan al matarlas, sirven de magnífico conductor en algunos de los experimentos de ingeniería de mis compañeros. Necesitaré varias de ellas para hacer pruebas. Las arañas tienen ocho patas y no deberían ser un problema para un guerrero robusto o un mago experimentado." },
		[1553] = { file = "1553", len = 30.642, text = "Un paquete atrasado - Contraté a alguien que creía que era un piloto de confianza para que me trajera un paquete de Theramore. Al parecer, me equivoqué. Y aunque el piloto vivió para contarlo, dejó atrás todo su zepplin y toda su carga para salvar el pellejo. Bueno, necesito ese paquete de vuelta. Por lo que Beezil me dice, se estrelló justo al oeste de la bahía en Dustwallow Marsh. Cayó justo después de cruzar las colinas a lo largo de la orilla del agua. Hmmm... nunca me dijo qué le hizo estrellarse..." },
		[1554] = { file = "1554", len = 30.302, text = "Goodsteel's Balanced Flameberge - Por último, quiero una de mis mejores obras de herrería hasta la fecha. Esta flameberge era una espada increíble que otorgué a quien yo creía que era un guerrero muy honorable y grande. Bueno, fue derrotado por un murloc llamado Jarquai... Algo así. Fue mientras viajaba por la costa del Pantano de los Pesares cuando se le ocurrió atacar a la criatura. Fracasó y, al parecer, huyó, pero no sin antes dejar el arma para que este murloc se la llevara." },
		[1556] = { file = "1556", len = 7.262, text = "Encuéntrame estos objetos y regresa a Gadgetzan con todos ellos, junto con este libro de cuentas, y te recompensaré." },
		[1591] = { file = "1591", len = 7.758, text = "Este yunque es propiedad de Jordan Fontana. ¡NO lo utilicéis! Jordan" },
		[1611] = { file = "1611", len = 30.903, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para fabricar arcanos menores. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[1631] = { file = "1631", len = 33.463, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para fabricar arcanos menores. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[1632] = { file = "1632", len = 32.392, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para fabricar arcanos menores. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[1633] = { file = "1633", len = 31.451, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para fabricar arcanos menores. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[1634] = { file = "1634", len = 32.601, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para fabricar arcanos menores. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[1691] = { file = "1691", len = 29.362, text = "¡Hola Felnok! Mis estudios en las Estepas Ardientes marchan espléndidamente. Y le debo mucho a $N por toda su ayuda. Esto es lo que necesito para continuar: Un bumber-bitzel de bobina de acero Una llave para hielo de 17 galgas 12 libras de plumas de pato Un frasco de ese pegamento que haces Muchas gracias Felnok, y cuando nos volvamos a ver recuérdame que no te ponga carbón en las botas. -Tinkee" },
		[1711] = { file = "1711", len = 21.446, text = "Mensaje urgente a Cliffwatcher Longhorn Una gran fuerza centauro del Campamento E'thok ha asaltado una de nuestras caravanas de suministros. Todos los miembros de la caravana se perdieron, así como todos los suministros. Este fue un ataque audaz y sin precedentes por parte de los centauros y me temo que puede haber más." },
		[1731] = { file = "1731", len = 18.024, text = "Aquí yace el rey Terenas Menethil II, último rey verdadero de Lordaeron. Grandes fueron sus hazañas, largo su reinado, inconcebible su muerte. \"Que el padre no sea inculpado por los actos de su hijo. Que la corona manchada de sangre permanezca en el olvido.\"" },
		[1751] = { file = "1751", len = 15.778, text = "Los restos del pantagruélico dragón rojo se encontraron en los Humedales poco después de la batalla de Grim Batol. Se dice que Tyrannistrasz fue el consorte más anciano de Alextrasza, reina de los dragones." },
		[1752] = { file = "1752", len = 21.368, text = "Esta garra petrificada se encontró en las costas del sur de Stranglethorn. Los ecologistas creen que esta garra es la de un antiguo roc sol. Aunque estas criaturas ocupan un lugar destacado en los ciclos mitológicos de los tauren primitivos, la existencia de esta garra sugiere que existieron de verdad en algún momento." },
		[1753] = { file = "1753", len = 8.255, text = "Los zancudos más grandes de la llanura, los geru, son aves raras y escasas en número." },
		[1754] = { file = "1754", len = 20.532, text = "Esta es una réplica a escala de un esqueleto de rechinador. Este legendario carnero fue el asombro de Khaz Modan y el protagonista de muchas historias del folklore popular enano. Hasta el momento, los ecologistas no han podido determinar el tamaño descomunal o la resistencia física de este carnero." },
		[1755] = { file = "1755", len = 21.238, text = "Encontrado en la remota selva tropical del cráter de Un’Goro, su huevo albergaba un embrión de devilsaurio. El material genético de los saurios ha resultado ser de incalculable valor para los ecologistas de la liga, que están más cerca que nunca de inventar un suero para atenuar el veneno del devilsaurio." },
		[1756] = { file = "1756", len = 18.704, text = "Este esqueleto intacto de pteradón se recuperó en el remoto cráter Un'Goro. A juzgar por la estructura del esqueleto, está claro que aún no se ha encontrado este género específico. Este esqueleto podría haberse conservado durante siglos bajo el rico suelo de la región." },
		[1757] = { file = "1757", len = 26.984, text = "Recuperado de las ruinas submarinas de Suramar, este astrolabio funcional fue fabricado por los elfos de la noche highborne hace casi doce mil años. Los highborne, obsesionados con la magia, lo oculto y la astronomía, desarrollaron una serie de ingeniosos aparatos. Este dispositivo proporciona una valiosa información sobre el nivel de conocimiento científico de los antiguos elfos de la noche." },
		[1758] = { file = "1758", len = 18.756, text = "Estas antiguas piezas de barro se extrajeron de las excavaciones de Uldaman. Si bien es poco probable que se trate de sugerentes runas o jeroglíficos, ofrecen un aspecto revelador de la destreza con que la antigua raza enana fabricaba sus accesorios de uso cotidiano." },
		[1759] = { file = "1759", len = 23.249, text = "Estos corredores en relieve grabados fueron quizás el hallazgo más significativo dentro de las primeras cámaras de Uldaman. Los grabados sugieren claramente un vínculo entre los gólems terrestres y la raza enana. Si surgen más pruebas, las teorías de nuestra supuesta creación por los titanes míticos podrían resultar ciertas." },
		[1760] = { file = "1760", len = 26.436, text = "Hallado en los sofocantes restos del desierto de Tanaris, este peculiar huevo sigue siendo un misterio para los ecologistas modernos. Las pruebas sugieren que el huevo podría tener hasta mil años de antigüedad. Si bien ciertos elementos indican estructuras insectoides, no resulta posible determinar sus verdaderos orígenes. Las especies que pusieron huevos tan distintos siguen sin conocerse." },
		[1761] = { file = "1761", len = 10.397, text = "Estos restos de la Segunda Guerra constituyen un conmovedor recuerdo de lo cerca que la Horda estuvo de conquistar la montaña de Forjaz." },
		[1762] = { file = "1762", len = 26.149, text = "Estas placas demoníacas fueron utilizadas por la criatura que por primera vez inoculó en nuestra gente la sed de sangre. Por el heroico acto de un valiente orco, que fue derrotado. Mannoroth el destructor ha desaparecido para siempre. Que estas placas nos recuerden siempre lo lejos que llegamos y lo mucho que luchamos para recuperar nuestro honor. -Thrall, Jefe de Guerra de la Horda" },
		[1771] = { file = "1771", len = 12.042, text = "Este vestigio de la Segunda Guerra sirve como conmovedor recordatorio de lo peligrosamente cerca que estuvo la Horda de conquistar la Montaña de Forja de Hierro." },
		[1772] = { file = "1772", len = 22.204, text = "Wyrmthalak, he recibido órdenes directas de tu amo, Nefarian, de castigarte como crea conveniente si más forasteros consiguen entrar en la ciudadela. No olvides quién te manda, reptil. El hijo de Blackhand: Maestro de la espada y la batalla. El único y verdadero Jefe Supremo. -Rend" },
		[1773] = { file = "1773", len = 35.683, text = "Con el tiempo, entidades demoníacas se abrieron camino hacia los mundos de los Titanes desde el Nether Retorcido, y el Panteón eligió a su mayor guerrero, Sargeras, para actuar como su primera línea de defensa. Sargeras, un noble gigante de bronce fundido, cumplió con su deber durante incontables milenios, buscando y destruyendo a estos demonios allí donde los encontraba. A lo largo de los eones, Sargeras se encontró con dos poderosas razas demoníacas, ambas empeñadas en obtener poder y dominio sobre el universo físico." },
		[1774] = { file = "1774", len = 15.255, text = "Los eredar, una insidiosa raza de hechiceros diabólicos, utilizaron su magia para invadir y esclavizar varios mundos. Las razas indígenas de esos mundos fueron mutadas por los poderes malévolos de los eredar y convertidas en demonios." },
		[1775] = { file = "1775", len = 26.384, text = "Aunque los poderes casi ilimitados de Sargeras eran más que suficientes para derrotar a los viles eredar, le preocupaba enormemente la corrupción de las criaturas y la maldad que las consumía. Incapaz de comprender tal depravación, el gran Titán comenzó a sumirse en una melancólica depresión. A pesar de su creciente malestar, Sargeras libró al universo de los hechiceros atrapándolos en un rincón del Infierno Tortuoso." },
		[1776] = { file = "1776", len = 20.036, text = "Mientras su confusión y miseria aumentaban, Sargeras se vio obligado a enfrentarse a otro grupo que pretendía alterar el orden de los Titanes: los Nathrezim. Esta oscura raza de demonios vampíricos (también conocidos como dreadlords) conquistó varios mundos poblados poseyendo a sus habitantes y convirtiéndolos a la sombra." },
		[1777] = { file = "1777", len = 15.151, text = "Los nefastos e intrigantes Señores del Terror enfrentaron a naciones enteras manipulándolas hasta provocar un odio y una desconfianza irreflexivos. Sargeras derrotó fácilmente a los Nathrezim, pero su corrupción le afectó profundamente." },
		[1778] = { file = "1778", len = 22.073, text = "A medida que la duda y la desesperación abrumaban los sentidos de Sargeras, éste perdió toda fe no sólo en su misión, sino también en la visión de los Titanes de un universo ordenado. Con el tiempo, llegó a creer que el propio concepto de orden era una locura, y que el caos y la depravación eran los únicos absolutos dentro del oscuro y solitario universo." },
		[1779] = { file = "1779", len = 23.458, text = "Sus compañeros Titanes intentaron persuadirle de su error y calmar sus furiosas emociones, pero él despreció sus creencias más optimistas como delirios interesados. Abandonando sus filas para siempre, Sargeras se dispuso a encontrar su propio lugar en el universo. Aunque el Panteón lamentó su partida, los Titanes nunca hubieran podido predecir lo lejos que llegaría su hermano perdido." },
		[1780] = { file = "1780", len = 18.965, text = "Cuando la locura de Sargeras consumió los últimos vestigios de su valeroso espíritu, creyó que los propios Titanes eran responsables del fracaso de la creación. Decidido, por fin, a deshacer sus obras en todo el universo, resolvió formar un ejército imparable que incendiaría el universo físico." },
		[1781] = { file = "1781", len = 15.987, text = "Incluso la forma titánica de Sargeras se distorsionó a causa de la corrupción que asolaba su otrora noble corazón. Sus ojos, su pelo y su barba estallaron en fuego, y su piel de bronce metálico se abrió para revelar un horno infinito de odio abrasador." },
		[1782] = { file = "1782", len = 23.04, text = "En su furia, Sargeras destrozó las prisiones de los eredar y los Nathrezim y liberó a los repugnantes demonios. Estas astutas criaturas se inclinaron ante la vasta furia del Titán oscuro y se ofrecieron a servirle de todas las formas maliciosas que pudieran. De entre las filas de los poderosos eredar, Sargeras eligió a dos campeones para comandar su demoníaco ejército de destrucción." },
		[1783] = { file = "1783", len = 18.312, text = "Kil'jaeden el Engañador fue elegido para buscar a las razas más oscuras del universo y reclutarlas en las filas de Sargeras. El segundo campeón, Archimonde el Profanador, fue elegido para liderar los vastos ejércitos de Sargeras en la batalla contra cualquiera que pudiera resistirse a la voluntad del Titán." },
		[1784] = { file = "1784", len = 30.955, text = "El primer movimiento de Kil'jaeden fue esclavizar a los vampíricos Señores del Terror bajo su terrible poder. Los Señores del Terror actuaban como sus agentes personales por todo el universo, y se complacían en localizar razas primitivas para que su amo las corrompiera y las trajera al redil. El primero de ellos fue Tichondrius el Oscurecedor. Tichondrius sirvió a Kil'jaeden como el soldado perfecto y aceptó llevar la ardiente voluntad de Sargeras a todos los rincones oscuros del universo." },
		[1785] = { file = "1785", len = 15.909, text = "El poderoso Archimonde también dio poderes a sus propios agentes. Invocando a los maléficos señores de la fosa y a su bárbaro líder, Mannoroth el Destructor, Archimonde esperaba establecer una élite de combate que barriera la creación de toda forma de vida." },
		[1786] = { file = "1786", len = 20.95, text = "Una vez que Sargeras vio que sus ejércitos estaban reunidos y listos para seguir todas sus órdenes, lanzó sus furiosas fuerzas a la inmensidad de la Gran Oscuridad. Se refería a su creciente ejército como la Legión Ardiente. A día de hoy, aún no está claro cuántos mundos consumieron y quemaron en su impía Cruzada Ardiente por el universo." },
		[1787] = { file = "1787", len = 20.376, text = "Desconociendo el empeño de Sargeras en destruir sus grandes hazañas, los titanes continuaron viajando de un planeta a otro, ordenando y sembrando de paz los sitios a los que iban. Durante el trayecto, hallaron un pequeño planeta cuyos habitantes llamaron Azeroth." },
		[1788] = { file = "1788", len = 19.017, text = "Cuando los titanes iniciaron la exploración del universo primigenio, encontraron a su paso numerosos enemigos elementales. Estos elementales, que veneraban a una raza de seres de insondable maldad conocida como los antiguos dioses, juraron detener a los titanes y proteger su entorno de la presencia metálica de los invasores." },
		[1789] = { file = "1789", len = 23.745, text = "El Panteón, inquieto por las inclinaciones malignas de los antiguos dioses, declararon la guerra a los elementales y a sus maestros oscuros. Los ejércitos de los antiguos dioses actuaban bajo las órdenes de los tenientes elementales más poderosos: Ragnaros el Señor de Fuego, Therazane la Madre Pétrea, Al'Akir el Señor del Viento y Neptulon el Cazamareas." },
		[1790] = { file = "1790", len = 19.148, text = "Sus caóticas fuerzas rugieron por todo el universo y se enfrentaron a los colosales titanes. Aunque los elementales tenían un poder más allá de toda comprensión, sus fuerzas conjuntas no podían detener a los invencibles titanes. Uno a uno, los señores elementales cayeron y sus fuerzas se dispersaron." },
		[1791] = { file = "1791", len = 32.104, text = "Los miembros del Panteón arrasaron los reductos de los antiguos dioses y encadenaron a los cinco dioses malignos en el subsuelo del planeta. Sin el poder de los antiguos dioses para mantener sus furiosos espíritus atados al mundo físico, los elementales fueron desterrados a un plano abisal, donde lucharían entre sí por toda la eternidad. Tras la partida de los elementales, la naturaleza se apaciguó y en el mundo reinó una pacífica armonía. Al acabar con la amenaza, los titanes se pusieron manos a la obra." },
		[1792] = { file = "1792", len = 29.466, text = "Así, otorgaron poderes a numerosas razas para que les ayudaran a construir un nuevo mundo. Para ayudarles a cavar las insondables cavernas subterráneas, los titanes crearon a los terráneos enanoides utilizando mágicas piedras vivientes. Para crear los mares y elevar la tierra por encima del nivel del mar, los titanes crearon a los inmensos, pero gentiles gigantes marinos. Durante varias eras, los titanes moldearon la tierra hasta crear un continente perfecto." },
		[1793] = { file = "1793", len = 29.962, text = "En el centro del continente, los titanes crearon un lago misterioso de energías incandescentes. El lago, llamado Pozo de la Eternidad, constituía la fuente de la vida de todos los seres que habitaban el planeta. Sus poderosas energías alimentaron los huesos de todo ser viviente y sembraron de vida aquel rico suelo. Con el tiempo, plantas, árboles, monstruos y criaturas de todas las clases empezaron a prosperar en el continente primigenio." },
		[1794] = { file = "1794", len = 10.005, text = "En el crepúsculo del última día de su obras de creación del mundo, los titanes dieron al continente el nombre de Kalimdor: \"tierra de eterna luz estelar\"." },
		[1795] = { file = "1795", len = 23.353, text = "Satisfechos con el pequeño universo que habían creado, los titanes se prepararon para abandonar Azeroth. No obstante, antes de partir, encomendaron a las grandes especies del planeta la tarea de vigilar Kalimdor, para evitar que fuerzas adversas amenazaran su perfecta armonía. En aquella época, existían muchas clases de dragones." },
		[1796] = { file = "1796", len = 24.372, text = "Sin embargo, había cinco grupos que dominaban a sus hermanos. Estos cinco grupos fueron elegidos por los titanes para guiar al mundo naciente. Los miembros más destacados del Panteón transmitieron parte de su poder a los jefes de las bandadas de dragones. Estos dragones majestuosos (que se describen a continuación) eran conocidos como los Grandes Aspectos o los Aspectos Dragones." },
		[1797] = { file = "1797", len = 22.857, text = "Aman'Thul, Alto Padre del Panteón volcó parte de su poder cósmico sobre el gigantesco dragón de bronce Nozdormu. El Alto Padre otorgó poderes a Nozdormu para que vigilara él mismo el transcurrir del tiempo y supervisara los intrincados caminos de la fortuna y el destino. El estoico y honorable Nozdormu era conocido con el nombre de El Atemporal." },
		[1798] = { file = "1798", len = 22.962, text = "Eonar, guardiana de la vida, otorgó parte de su poder a la gigantesca Alexstrasza. Mucho tiempo después, Alexstrasza recibió el nombre de la Protectora, pues su misión era defender a todas las criaturas vivientes del planeta. Gracias a su suprema sabiduría y a su ilimitada compasión por todos los seres vivos, Alexstrasza fue nombrada reina de los dragones por los de su especie." },
		[1799] = { file = "1799", len = 21.917, text = "Eonar también bendijo a la hermana menor de Alexstrasza, la ágil dragona verde Ysera, con una porción de su influencia sobre la naturaleza. Ysera cayó en un trance eterno, atada al Sueño de la Creación. Conocida como la Soñadora, vigilaría las extensas áreas salvajes del mundo desde su reino verde, el Sueño Esmeralda." },
		[1800] = { file = "1800", len = 14.498, text = "Norgannon, titán guardián del conocimiento y mago maestro, cedió al dragón azul Malygos parte de su vasto poder. A partir de entonces, Malygos fue conocido como el Tejechizos, el guardián de la magia y el arcano oculto." },
		[1801] = { file = "1801", len = 22.883, text = "Khaz'goroth, creador de titanes y forjador del mundo, confirió parte de su extenso poder al poderoso wyrm negro Neltharion. Al bondadoso Neltharion, conocido posteriormente como el Guardián de la Tierra, se le otorgó el dominio de la tierra y los rincones más recónditos del orbe. Encarnaba la fortaleza del mundo y actuaba como gran protector de Alexstrasza." },
		[1802] = { file = "1802", len = 18.991, text = "Con estos poderes, los Cinco Aspectos tenían la misión de defender al mundo en ausencia de los titanes. Cuando los dragones ya estaban preparados para vigilar su creación, los titanes abandonaron Azeroth para siempre. Desafortunadamente, el descubrimiento del nuevo mundo por parte de Sargeras era solo cuestión de tiempo." },
		[1803] = { file = "1803", len = 26.436, text = "El uso temerario de la magia de los altonatos envió ondas energéticas desde el Pozo de la Eternidad hasta la Gran Oscuridad en el más allá. Las ondas expansivas de energía fueron percibidas por terribles mentes de otros mundos. Sargeras, el Gran Enemigo de la vida y Destructor de los Mundos, percibió las poderosas ondas y se sintió atraído por su distante punto de origen." },
		[1804] = { file = "1804", len = 17.58, text = "Al divisar el mundo primordial de Azeroth y percibir las energías ilimitadas del Pozo de la Eternidad, Sargeras se sintió consumido por un hambre insaciable. El gran dios oscuro del Vacío sin Nombre decidió destruir el mundo incipiente y reclamar sus energías como propias." },
		[1805] = { file = "1805", len = 24.999, text = "Sargeras reunió a su vasta Legión Ardiente y se dirigió hacia el desprevenido mundo de Azeroth. La Legión estaba compuesta por un millón de demonios gritones, todos arrancados de los rincones más lejanos del universo, y los demonios ansiaban la conquista. Los lugartenientes de Sargeras, Archimonde el Profanador y Mannoroth el Destructor, prepararon a sus esbirros infernales para atacar." },
		[1806] = { file = "1806", len = 27.35, text = "La reina Azshara, abrumada por el terrible éxtasis de su magia, cayó víctima del innegable poder de Sargeras y accedió a concederle la entrada a su mundo. Incluso sus sirvientes Highborne se entregaron a la inevitable corrupción de la magia y comenzaron a adorar a Sargeras como a su dios. Para mostrar su lealtad a la Legión, los Highborne ayudaron a su reina a abrir un vasto y arremolinado portal en las profundidades del Pozo de la Eternidad." },
		[1807] = { file = "1807", len = 24.242, text = "Una vez realizados todos sus preparativos, Sargeras comenzó su catastrófica invasión de Azeroth. Los demonios guerreros de la Legión Ardiente irrumpieron en el mundo a través del Pozo de la Eternidad y asediaron las ciudades dormidas de los elfos de la noche. Liderada por Archimonde y Mannoroth, la Legión invadió las tierras de Kalimdor, dejando sólo cenizas y dolor a su paso." },
		[1808] = { file = "1808", len = 37.12, text = "Los brujos demoníacos invocaron abrasadores infiernos que se estrellaron como meteoritos infernales contra las elegantes agujas de los templos de Kalimdor. Una banda de asesinos ardientes y sanguinarios conocidos como la Guardia del Destino marchó por los campos de Kalimdor, masacrando a todo el que se cruzaba en su camino. Manadas de felinos salvajes y demoníacos asolaban la campiña sin oposición. Aunque los valientes guerreros kaldorei se apresuraron a defender su antigua patria, se vieron obligados a ceder terreno, palmo a palmo, ante la furia de la embestida de la Legión." },
		[1809] = { file = "1809", len = 21.734, text = "Correspondió a Malfurion Stormrage encontrar ayuda para su atribulado pueblo. Stormrage, cuyo propio hermano, Illidan, practicaba la magia de los Highborne, estaba indignado por la creciente corrupción entre la clase alta. Convenciendo a Illidan de que abandonara su peligrosa obsesión, Malfurion partió en busca de Cenarius y reunió una fuerza de resistencia." },
		[1810] = { file = "1810", len = 23.04, text = "La bella y joven sacerdotisa, Tyrande, aceptó acompañar a los hermanos en nombre de Elune. Aunque Malfurion e Illidan compartían el amor por la idealista sacerdotisa, el corazón de Tyrande sólo pertenecía a Malfurion. Illidan resentía el incipiente romance de su hermano con Tyrande, pero sabía que su dolor de corazón no era nada comparado con el dolor de su adicción mágica." },
		[1811] = { file = "1811", len = 19.931, text = "Illidan, que se había vuelto dependiente de las energías potenciadoras de la magia, luchó por mantener el control de su ansia casi abrumadora de aprovechar de nuevo las energías del Pozo. Sin embargo, con el paciente apoyo de Tyrande, fue capaz de contenerse y ayudar a su hermano a encontrar al solitario semidiós Cenarius." },
		[1812] = { file = "1812", len = 21.786, text = "Cenarius, que habitaba en las sagradas Llanuras de la Luna del lejano Monte Hyjal, accedió a ayudar a los elfos de la noche encontrando a los antiguos dragones y solicitando su ayuda. Los dragones, liderados por el gran leviatán rojo Alexstrasza, acordaron enviar sus poderosos vuelos para enfrentarse a los demonios y a sus amos infernales." },
		[1813] = { file = "1813", len = 28.552, text = "Cenarius, invocando a los espíritus de los bosques encantados, reunió a un ejército de antiguos hombres-árbol y los dirigió contra la Legión en un audaz asalto terrestre. Cuando los aliados de los elfos de la noche convergieron sobre el templo de Azshara y el Pozo de la Eternidad, estalló una guerra sin cuartel. A pesar de la fuerza de sus recién descubiertos aliados, Malfurion y sus colegas se dieron cuenta de que la Legión no podía ser derrotada sólo con su fuerza marcial." },
		[1814] = { file = "1814", len = 32.392, text = "Mientras la titánica batalla se desencadenaba en torno a la capital de Azshara, la delirante reina esperaba con impaciencia la llegada de Sargeras. El señor de la Legión se preparaba para atravesar el Pozo de la Eternidad y entrar en el mundo devastado. Mientras su sombra imposiblemente enorme se acercaba cada vez más a la superficie del Pozo, Azshara reunió a los más poderosos de sus seguidores Highborne. Sólo uniendo sus magias en un hechizo concentrado podrían crear un portal lo suficientemente grande para que Sargeras entrara." },
		[1815] = { file = "1815", len = 33.646, text = "Mientras la batalla se extendía por los campos ardientes de Kalimdor, se produjo un terrible giro en los acontecimientos. Los detalles del suceso se han perdido en el tiempo, pero se sabe que Neltharion, el Dragón Aspecto de la Tierra, enloqueció durante un enfrentamiento crítico contra la Legión Ardiente. Comenzó a desintegrarse a medida que las llamas y la rabia brotaban de su oscura piel. Rebautizándose a sí mismo como Alamuerte, el dragón en llamas se volvió contra sus hermanos y expulsó a los cinco dragonflights del campo de batalla." },
		[1816] = { file = "1816", len = 21.185, text = "La repentina traición de Alamuerte fue tan destructiva que los cinco dragonflights nunca se recuperaron del todo. Heridos y conmocionados, Alexstrasza y los demás dragones nobles se vieron obligados a abandonar a sus aliados mortales. Malfurion y sus compañeros, ahora en inferioridad numérica, apenas sobrevivieron al ataque." },
		[1817] = { file = "1817", len = 29.1, text = "Malfurion, convencido de que el Pozo de la Eternidad era el vínculo umbilical de los demonios con el mundo físico, insistió en que debía ser destruido. Sus compañeros, que sabían que el Pozo era la fuente de su inmortalidad y sus poderes, se horrorizaron ante la imprudente idea. Sin embargo, Tyrande vio la sabiduría de la teoría de Malfurion, así que convenció a Cenarius y a sus compañeros para que asaltaran el templo de Azshara y encontraran una forma de cerrar el Pozo para siempre." },
		[1828] = { file = "1828", len = 29.492, text = "Los pocos elfos de la noche que sobrevivieron a la terrible explosión se reunieron en balsas de fabricación rudimentaria y se dirigieron lentamente hacia la única masa de tierra a la vista. De algún modo, por la gracia de Elune, Malfurion, Tyrande y Cenarius habían sobrevivido al Gran Destructor. Los cansados héroes acordaron liderar a sus compañeros supervivientes y establecer un nuevo hogar para su pueblo." },
		[1829] = { file = "1829", len = 19.513, text = "Mientras viajaban en silencio, contemplaron los restos de su mundo y se dieron cuenta de que sus pasiones habían provocado la destrucción que les rodeaba. Aunque Sargeras y su Legión habían sido arrancados del mundo por la destrucción del Pozo, Malfurion y sus compañeros tuvieron que reflexionar sobre el terrible coste de la victoria." },
		[1830] = { file = "1830", len = 17.476, text = "Hubo muchos Highborne que sobrevivieron ilesos al cataclismo. Llegaron a las costas de la nueva tierra junto con otros elfos de la noche. Aunque Malfurion desconfiaba de las motivaciones de los Highborne, estaba convencido de que no podrían causar ningún daño real sin las energías del Pozo." },
		[1831] = { file = "1831", len = 32.993, text = "Cuando la cansada masa de elfos de la noche desembarcó en las costas de la nueva tierra, descubrieron que la montaña sagrada, Hyjal, había sobrevivido a la catástrofe. Buscando un nuevo hogar, Malfurion y los elfos de la noche escalaron las laderas de Hyjal y alcanzaron su cima azotada por el viento. Al descender a la cuenca boscosa, enclavada entre los enormes picos de la montaña, encontraron un pequeño y tranquilo lago. Para su horror, descubrieron que las aguas del lago habían sido contaminadas por la magia." },
		[1832] = { file = "1832", len = 18.86, text = "Illidan, que también había sobrevivido al Sundering, había llegado a la cumbre de Hyjal mucho antes que Malfurion y los elfos de la noche. En su loco intento por mantener los flujos de magia en el mundo, Illidan había vertido sus viales, que contenían las preciadas aguas del Pozo de la Eternidad, en el lago de la montaña." },
		[1833] = { file = "1833", len = 29.048, text = "Las potentes energías del Pozo se encendieron rápidamente y se fusionaron en un nuevo Pozo de la Eternidad. El exultante Illidan, que creía que el nuevo Pozo era un regalo para las generaciones futuras, se sorprendió cuando Malfurion le dio caza. Malfurion explicó a su hermano que la magia era innatamente caótica y que su uso conduciría inevitablemente a la corrupción y la lucha generalizadas. Aun así, Illidan se negó a renunciar a sus poderes mágicos." },
		[1834] = { file = "1834", len = 30.093, text = "Malfurion, que sabía muy bien adónde conducirían los despiadados planes de Illidan, decidió acabar de una vez por todas con su hermano, loco por el poder. Con la ayuda de Cenarius, Malfurion encerró a Illidan en una vasta prisión subterránea, donde permanecería encadenado e impotente hasta el fin de los tiempos. Para garantizar la contención de su hermano, Malfurion otorgó poderes al joven alcaide, Maiev Shadowsong, para que fuera el carcelero personal de Illidan." },
		[1835] = { file = "1835", len = 26.88, text = "Preocupados por la posibilidad de que la destrucción del nuevo Pozo provocara una catástrofe aún mayor, los elfos de la noche decidieron abandonarlo. Sin embargo, Malfurion declaró que nunca volverían a practicar las artes de la magia. Bajo la atenta mirada de Cenarius, comenzaron a estudiar las antiguas artes del druidismo que les permitirían sanar la tierra devastada y hacer crecer de nuevo sus amados bosques en la base del Monte Hyjal." },
		[1836] = { file = "1836", len = 26.488, text = "Durante muchos años, los elfos de la noche trabajaron incesantemente para reconstruir su antigua tierra natal. Abandonando sus templos destruidos a merced de la maleza, construyeron sus nuevos hogares en medio de frondosos árboles y frescas colinas junto al Monte Hyjal. Con el tiempo, los dragones que habían sobrevivido al gran Diluvio salieron de sus secretas moradas." },
		[1837] = { file = "1837", len = 19.905, text = "Alexstrasza la roja, Ysera la verde y Nozdormu la de bronce descendieron a los tranquilos claros de los druidas y observaron los frutos del trabajo de los elfos de la noche. Malfurion, que se había convertido en un archidruida de inmenso poder, saludó a los poderosos dragones y les habló de la creación del nuevo Pozo de la Eternidad." },
		[1838] = { file = "1838", len = 22.23, text = "Los grandes dragones se alarmaron al oír las oscuras noticias y especularon que mientras el Pozo permaneciera, la Legión podría regresar algún día y asaltar el mundo una vez más. Malfurion y los tres dragones hicieron un pacto para mantener el Pozo a salvo y asegurarse de que los agentes de la Legión Ardiente nunca encontrarían la forma de volver al mundo." },
		[1839] = { file = "1839", len = 20.976, text = "Alexstrasza, la Encadenadora de Vidas, colocó una única bellota encantada en el corazón del Pozo de la Eternidad. La bellota, activada por las potentes aguas mágicas, cobró vida como un árbol colosal. Las raíces del poderoso árbol brotaron de las aguas del pozo y su frondosa copa parecía rozar el techo del cielo." },
		[1840] = { file = "1840", len = 20.036, text = "El inmenso árbol sería un símbolo eterno del vínculo de los elfos de la noche con la naturaleza, y sus energías vivificadoras se extenderían para sanar el resto del mundo con el paso del tiempo. Los elfos de la noche dieron a su Árbol del Mundo el nuevo nombre de Nordrassil, que significaba \"corona de los cielos\" en su lengua nativa." },
		[1841] = { file = "1841", len = 13.296, text = "Nozdormu, el Eterno, puso un encantamiento sobre el Árbol del Mundo para garantizar que, mientras el colosal árbol se mantuviera en pie, los elfos de la noche nunca envejecerían ni serían presa de enfermedades." },
		[1842] = { file = "1842", len = 24.607, text = "Ysera, la Soñadora, también encantó el Árbol del Mundo vinculándolo a su propio reino, la dimensión etérea conocida como el Sueño Esmeralda. El Sueño Esmeralda, un vasto mundo espiritual en constante cambio, existía fuera de los límites del mundo físico. Desde el Sueño, Ysera regulaba el flujo y reflujo de la naturaleza y el camino evolutivo del propio mundo." },
		[1843] = { file = "1843", len = 27.873, text = "Los druidas elfos de la noche, incluido el propio Malfurion, estaban ligados al Sueño a través del Árbol del Mundo. Como parte del pacto místico, los druidas aceptaron dormir durante siglos para que sus espíritus pudieran recorrer los infinitos senderos de los Caminos del Sueño de Ysera. Aunque los druidas estaban apenados ante la perspectiva de perder tantos años de sus vidas por la hibernación, aceptaron desinteresadamente mantener su pacto con Ysera." },
		[1844] = { file = "1844", len = 30.824, text = "Con el transcurso de los siglos, la nueva sociedad de los elfos de la noche se fortaleció y se expandió por el bosque en ciernes conocido como Vallefresno. Muchas de las criaturas y especies que abundaban antes del Gran Diluvio, como los furbolgs y los jabaespines, reaparecieron y prosperaron en aquellas tierras. Bajo la benévola mirada de los druidas, los elfos de la noche disfrutaron de una era de paz y tranquilidad sin precedentes bajo las estrellas." },
		[1845] = { file = "1845", len = 32.313, text = "Sin embargo, muchos de los supervivientes originales de Highborne se volvieron inquietos. Al igual que Illidan antes que ellos, cayeron víctimas del retraimiento provocado por la pérdida de sus codiciadas magias. Tuvieron la tentación de aprovechar las energías del Pozo de la Eternidad y exultar en sus prácticas mágicas. Dath'Remar, el audaz y franco líder de los Highborne, empezó a burlarse públicamente de los druidas, llamándolos cobardes por negarse a usar la magia que, según él, les pertenecía por derecho." },
		[1846] = { file = "1846", len = 20.219, text = "Malfurion y los druidas rechazaron los argumentos de Dath'Remar y advirtieron a los Highborne que cualquier uso de la magia sería castigado con la muerte. En un insolente y malogrado intento de convencer a los druidas de que anularan su ley, Dath'Remar y sus seguidores desataron una terrible tormenta mágica sobre Ashenvale." },
		[1847] = { file = "1847", len = 30.485, text = "Los druidas no se atrevían a dar muerte a tantos de los suyos, así que decidieron exiliar a los temerarios Highborne de sus tierras. Dath'Remar y sus seguidores, contentos de haberse librado por fin de sus primos conservadores, se embarcaron en una serie de naves especialmente construidas y se hicieron a la mar. Aunque ninguno de ellos sabía lo que les esperaba más allá de las aguas del furioso Maelstrom, estaban ansiosos por establecer su propia patria, donde podrían practicar sus codiciadas magias con impunidad." },
		[1848] = { file = "1848", len = 25.495, text = "Los Highborne, o Quel'dorei, como Azshara los había llamado en el pasado, acabarían por asentarse en la tierra oriental que los hombres llamarían Lordaeron. Planeaban construir su propio reino mágico, Quel'Thalas, y rechazar los preceptos de los elfos de la noche de adoración a la luna y actividad nocturna. Para siempre, abrazarían el sol y serían conocidos únicamente como los altos elfos." },
		[1849] = { file = "1849", len = 19.958, text = "Con la partida de sus primos díscolos, los elfos de la noche volvieron a centrar su atención en la salvaguarda de su patria encantada. Los druidas, sintiendo que se acercaba su tiempo de hibernación, se prepararon para dormir y dejar atrás a sus seres queridos y a sus familias." },
		[1850] = { file = "1850", len = 20.036, text = "Tyrande, que se había convertido en la Gran Sacerdotisa de Elune, pidió a su amor, Malfurion, que no la dejara por el Sueño Esmeralda de Ysera. Pero Malfurion, obligado por su honor a entrar en los cambiantes Caminos del Sueño, se despidió de la sacerdotisa y juró que nunca se separarían mientras fueran fieles a su amor." },
		[1851] = { file = "1851", len = 25.678, text = "Al quedarse sola para proteger Kalimdor de los peligros del nuevo mundo, Tyrande reunió una poderosa fuerza de combate entre sus hermanas elfas de la noche. Las intrépidas y altamente entrenadas guerreras que se comprometieron a defender Kalimdor pasaron a conocerse como las Centinelas. Aunque preferían patrullar solas los sombríos bosques de Ashenvale, contaban con muchas aliadas a las que podían recurrir en momentos de urgencia." },
		[1852] = { file = "1852", len = 22.596, text = "El semidiós Cenarius permaneció cerca, en las Llanuras de la Luna del Monte Hyjal. Sus hijos, conocidos como los Guardianes de la Arboleda, vigilaban de cerca a los elfos nocturnos y ayudaban regularmente a los Centinelas a mantener la paz en la tierra. Incluso las tímidas hijas de Cenarius, las dríades, aparecían al descubierto con creciente frecuencia." },
		[1853] = { file = "1853", len = 27.664, text = "La tarea de vigilar Ashenvale mantenía ocupada a Tyrande, pero sin Malfurion a su lado, apenas conocía la alegría. A medida que pasaban los siglos mientras los druidas dormían, sus temores de una segunda invasión demoníaca aumentaban. No podía deshacerse de la inquietante sensación de que la Legión Ardiente podría seguir ahí fuera, más allá de la Gran Oscuridad del cielo, tramando su venganza contra los elfos de la noche y el mundo de Azeroth." },
		[1854] = { file = "1854", len = 29.388, text = "\"Los altos elfos, dirigidos por Dath'Remar, abandonaron Kalimdor y desafiaron las tormentas de la Vorágine. Sus flotas recorrieron las ruinas del mundo durante muchos años, descubriendo a su paso nuevos misterios y reinos perdidos. Dath'Remar, que había adoptado el nombre de \"Caminante del Sol” (o \"el que camina de día\"), buscó lugares que resultaran aptos para construir en ellos un nuevo hogar para su gente\"." },
		[1855] = { file = "1855", len = 31.869, text = "Su flota finalmente desembarcó en las playas del reino cuyos habitantes denominaron Lordaeron. Tomando posiciones en tierra, los altos elfos fundaron su sede en los tranquilos Claros de Tirisfal. Transcurridos unos años, muchos de ellos empezaron a enloquecer. Existía la teoría de que bajo aquellas tierras se ocultaba una fuerza maligna, pero estos rumores nunca se confirmaron. Los altos elfos llevaron su campamento a otra parte y se dirigieron al norte en dirección a otras tierras ricas en energías naturales." },
		[1856] = { file = "1856", len = 23.171, text = "Durante el trayecto de los altos elfos por las escarpadas montañas de Lordaeron, el viaje se hizo cada vez más peligroso. Puesto que fueron totalmente privados de las energías vivificadoras del Pozo de la Eternidad, muchos de ellos enfermaron a causa del gélido clima o murieron de hambre. Sin embargo, el hecho más desconcertante era que ya no eran inmortales ni inmunes a los elementos." },
		[1857] = { file = "1857", len = 23.85, text = "También encogieron de tamaño y su piel perdió la tonalidad violeta que los caracterizaba. A pesar de las penurias, conocieron maravillosas criaturas jamás vistas en Kalimdor. Asimismo, encontraron tribus de humanos primitivos que cazaban en los antiguos bosques. No obstante, la mayor amenaza que los acechaba la constituían los voraces y maliciosos trols del bosque de Zul’Aman." },
		[1858] = { file = "1858", len = 29.727, text = "Estos trols con la piel recubierta de musgo tenía el poder de regenerar sus miembros mutilados y curar graves heridas físicas, pero conformaban, sin duda, una raza bárbara y maligna. El imperio Amani se extendió por la mayor parte del territorio del norte de Lordaeron y sus trols lucharon incansablemente para mantener a los forasteros alejados de sus tierras. Los elfos desarrollaron una profunda aversión contra los despiadados trols y los mataban siempre que podían." },
		[1859] = { file = "1859", len = 31.869, text = "Transcurridos muchos años, los elfos de la noche finalmente encontraron una tierra que les recordaba a Kalimdor. En el interior del bosque que había al norte del continente, fundaron el reino de Quel’Thalas y prometieron crear un vasto imperio que eclipsaría al de sus primos kaldorei. Desafortunadamente, pronto descubrieron que Quel’Thalas había sido fundada sobre una antigua ciudad trol que esta raza aún consideraba sagrada. Casi de inmediato, los trols empezaron a atacar en masa los asentamientos de los elfos." },
		[1860] = { file = "1860", len = 28.447, text = "Los tozudos elfos, que no estaban dispuestos a ceder su nuevo territorio, utilizaron la magia que habían obtenido del Pozo de la Eternidad y mantuvieron a raya a los salvajes trols. Liderados por Dath'Remar, pudieron derrotar a las bandas de guerra Amani, que eran diez veces más numerosas. Algunos elfos, que recordaban las antiguas advertencias de los kaldorei, temían que el uso de la magia pudiera atraer la atención de la desterrada Legión Ardiente." },
		[1861] = { file = "1861", len = 24.424, text = "Por ello, decidieron proteger sus tierras con una barrera que les permitiera seguir desarrollando sus encantamientos. Construyeron una serie de runas monolíticas en varios puntos de los alrededores de Quel’Thalas, marcando las fronteras de la barrera mágica. Las runas no solo encubrían la magia de los elfos ante amenazas extradimensionales, sino que también les ayudaban a ahuyentar a las supersticiosas bandas trol." },
		[1862] = { file = "1862", len = 25.757, text = "Transcurrido cierto tiempo, Quel'Thalas se convirtió en un bello monumento a los esfuerzos de los altos elfos y a sus hazañas mágicas. Sus hermosos palacios fueron construidos siguiendo el mismo estilo arquitectónico que el de las antiguas salas de Kalimdor, si bien se entremezclaban con la topografía natural de la tierra. Quel'Thalas se había convertido en una joya que los elfos siempre habían deseado crear." },
		[1863] = { file = "1863", len = 28.917, text = "A continuación, se fundó la Asamblea de Lunargenta para gobernar Quel’Thalas, si bien la dinastía de los Caminantes del Sol conservaba cierto poder político. Compuesto por siete altos elfos mayores, la Asamblea se encargó de velar por la seguridad de la tierra de los elfos y de sus gentes. Rodeados por su barrera protectora, los altos elfos hicieron caso omiso a las advertencias de los kaldorei y continuaron usando la magia con total libertad en todos los aspectos de sus vidas." },
		[1864] = { file = "1864", len = 27.167, text = "Durante unos cuatro mil años, los altos elfos vivieron pacíficamente en su reino aislado y protegido. No obstante, los vengativos trols no se conformaban fácilmente con su derrota. Planearon su venganza en las profundidades de los bosques y esperaron a que sus tropas crecieran. Finalmente, un poderoso ejército de trols partió de los oscuros bosques y, nuevamente, sitiaron las relucientes cumbres de Quel’Thalas." },
		[1865] = { file = "1865", len = 22.779, text = "Mientras los altos elfos luchaban por sus vidas contra la feroz embestida de los trolls, los dispersos y nómadas humanos de Lordaeron luchaban por consolidar sus propias tierras tribales. Las tribus de la humanidad primitiva asaltaban los asentamientos de los demás sin apenas preocuparse por la unificación racial o el honor." },
		[1866] = { file = "1866", len = 14.681, text = "No obstante, una tribu conocida como los arathi advirtió que los trols se estaban convirtiendo en una amenaza demasiado importante como para ignorarla. Los arathi deseaban dominar a las demás tribus para unificar fuerzas contra el ejército trol." },
		[1867] = { file = "1867", len = 22.726, text = "En seis años, los astutos arathi se mostraron más hábiles y derrotaron a las tribus rivales. Tras cada victoria, los arathi ofrecieron paz e igualdad al pueblo conquistado, obteniendo la lealtad de los pueblos derrotados. Finalmente, la tribu de los arathi conquistó numerosas tribus dispares, logrando que su ejército creciera de forma significativa." },
		[1868] = { file = "1868", len = 30.354, text = "Confiando en su capacidad de contener a las bandas de los trols con sus tropas o, incluso, con los aislados elfos si era necesario, los señores de la guerra arathi decidieron construir una poderosa ciudad fortificada en las tierras del sur de Lordaeron. La ciudad estado, llamada Strom, se convirtió en la capital de la nación arathi, Arathor. A medida que Arathor prosperaba, los humanos que habitaban en todo el continente viajaban hacia el sur para garantizar la protección y la seguridad de Strom." },
		[1869] = { file = "1869", len = 32.757, text = "Unidos bajo la misma bandera, las tribus humanas desarrollaron una cultura sólida y optimista. Thoradin, rey de Arathor, sabía que los elfos misteriosos de las tierras del norte padecían el constante asedio de los trols, pero se negó a arriesgar la seguridad de su gente en defensa de los desconocidos. Varios meses después, llegaron rumores del norte sobre una supuesta derrota de los elfos. De no ser porque los embajadores de Quel’Thalas llegaron agotados a Strom, Thoradin no se habría percatado de la magnitud de la amenaza de los trols." },
		[1870] = { file = "1870", len = 22.883, text = "Los elfos informaron a Thoradin acerca del tamaño de los ejércitos de los trols, asegurando que una vez que estos hubieran destruido Quel’Thalas, irían a las tierras del sur para atacarlas. Los elfos, desesperados, ante la necesidad real de ayuda militar, accedieron a enseñar a unos cuantos humanos escogidos a utilizar la magia a cambio de su ayuda para combatir a las bandas trol." },
		[1871] = { file = "1871", len = 12.565, text = "Thoradin, receloso ante cualquier tipo de magia, aceptó ayudar a los elfos. Casi de inmediato, los hechiceros élficos llegaron a Arathor y empezaron a instruir a un grupo de humanos en las artes de la magia." },
		[1872] = { file = "1872", len = 31.922, text = "Los elfos observaron que, si bien los humanos eran torpes por naturaleza en el uso de la magia, mostraban, por el contrario, una natural afinidad hacia todo lo mágico. Cien hombres adquirieron conocimientos básicos sobre los secretos mágicos de los elfos: solo los que eran absolutamente necesarios para combatir a los trols. Convencidos de que sus discípulos humanos estaban preparados para ayudarles en la lucha, los elfos abandonaron Strom y viajaron hacia el norte junto con los poderosos ejércitos del rey Thoradin." },
		[1873] = { file = "1873", len = 22.439, text = "Los ejércitos unidos de elfos y humanos se enfrentaron a las abrumadoras bandas de trolls al pie de las montañas Alterac. La batalla duró muchos días, pero los infatigables ejércitos de Arathor nunca se cansaron ni cedieron un ápice de terreno ante la embestida de los trolls. Los señores elfos consideraron que había llegado el momento de liberar los poderes de su magia sobre el enemigo." },
		[1874] = { file = "1874", len = 16.875, text = "Los cien magos humanos y la multitud de hechiceros élficos invocaron la furia de los cielos, prendiendo fuego a los ejércitos de los trols. Los fuegos elementales impidieron que los trols regeneraran sus heridas y quemaron sus cuerpos torturados desde las entrañas hasta la superficie." },
		[1875] = { file = "1875", len = 30.955, text = "Cuando los ejércitos trol se desbandaron e intentaron huir, los ejércitos de Thoradin los arrollaron y masacraron hasta el último de sus soldados. Los trolls nunca se recuperarían del todo de su derrota, y la historia nunca volvería a ver a los trolls alzarse como una nación. Asegurados de que Quel'Thalas se salvaba de la destrucción, los elfos hicieron un juramento de lealtad y amistad a la nación de Arathor y al linaje de su rey, Thoradin. Humanos y elfos mantendrían relaciones pacíficas durante siglos." },
		[1876] = { file = "1876", len = 17.032, text = "Sin la presencia de los trols en las tierras del norte, los elfos de Quel'Thalas centraron sus esfuerzos en reconstruir su gloriosa tierra. Los ejércitos victoriosos de Arathor volvieron a casa, en las tierras del sur de Strom." },
		[1877] = { file = "1877", len = 26.07, text = "La sociedad humana de Arathor creció y prosperó, no obstante Thoradin, temeroso de que su reino se desintegrase al adquirir un tamaño demasiado grande, afirmó que Strom sería el centro del imperio de Arathor. Tras muchos años de paz y crecimiento económico, el poderoso Thoradin murió en edad avanzada, ofreciendo a las jóvenes generaciones de Arathor libertad para expandir el imperio más allá de las fronteras de Strom." },
		[1878] = { file = "1878", len = 28.996, text = "Los cien magos originales, que fueron instruidos en la magia por los elfos, ampliaron sus poderes y estudiaron con mayor detenimiento las disciplinas místicas de los hechizos. Estos magos, inicialmente escogidos por su fuerza de voluntad y nobleza de espíritu, siempre habían practicado su magia con cuidado y responsabilidad. No obstante, transmitieron sus secretos y poderes a una nueva generación que no tenía idea de los rigores de la guerra o del principio de moderación." },
		[1879] = { file = "1879", len = 8.464, text = "Estos jóvenes magos empezaron a practicar la magia para darle un uso personal, sin tener en cuenta su responsabilidad hacia sus congéneres." },
		[1880] = { file = "1880", len = 28.055, text = "A medida que el imperio creció y adquirió nuevas tierras, los jóvenes magos también se establecieron en las tierras del sur. Mediante el uso de sus poderes místicos, los magos protegían a sus hermanos de las criaturas salvajes de la tierra e hicieron posible la construcción de nuevas ciudades estado en medio de la jungla. No obstante, a medida que aumentaba su poder, los magos se hicieron cada vez más engreídos y se aislaron del resto de la sociedad." },
		[1881] = { file = "1881", len = 22.152, text = "La segunda ciudad estado de Arathor, Dalaran, fue fundada en las tierras del norte de Strom. Muchos magos noveles abandonaron los confines de Strom y viajaron a Dalaran, en donde esperaban usar sus poderes con mayor libertad. Así, emplearon sus habilidades para construir las cimas encantadas de Dalaran y centrarse en la continuación de sus estudios." },
		[1882] = { file = "1882", len = 17.711, text = "Los ciudadanos de Dalaran toleraron los esfuerzos de los magos y consolidaron una economía ágil bajo la protección de sus defensores magos. Sin embargo, a medida que aumentaba el número de magos que ponían en práctica sus artes, el manto de realidad que rodeaba Dalaran empezó a resquebrajarse." },
		[1883] = { file = "1883", len = 22.831, text = "Los siniestros agentes de la Legión Ardiente, que habían sido desterrados durante la desaparición del Pozo de la Eternidad, se interesaron nuevamente por el planeta, gracias a la atención que en ellos despertaron los hechizos de los magos de Dalaran. Si bien estos demonios relativamente débiles no manifestaban su poder, sí sembraban la confusión y el caos en las calles de Dalaran." },
		[1884] = { file = "1884", len = 21.995, text = "La mayoría de estos encuentros demoníacos eran acontecimientos aislados, de manera que los magócratas en el poder hicieron lo que pudieron para mantener estas ceremonias en secreto. Los magos más poderosos fueron enviados a capturar a los escurridizos demonios, pero muchas veces se vieron superados por los solitarios agentes de la imponente Legión." },
		[1885] = { file = "1885", len = 33.332, text = "Transcurridos unos cuantos meses, los supersticiosos campesinos empezaron a sospechar que sus hechiceros gobernantes les estaban ocultando algo terrible. Rumores de revolución empezaron a extenderse por las calles de Dalaran, al tiempo que los ciudadanos paranoicos cuestionaban los motivos y las prácticas de los magos a quienes habían admirado en el pasado. Los magócratas, temiendo que los campesinos se levantarían y que Strom actuaría en su contra, acudieron al único grupo que consideraron capaz de comprender su particular problema: los elfos." },
		[1886] = { file = "1886", len = 30.772, text = "Tras conocer las actividades demoníacas de los magócratas en Dalaran, los elfos rápidamente enviaron a sus zahoríes más poderosos hacia tierras humanas. Los zahoríes élficos estudiaron las corrientes energéticas que fluían en Dalaran y realizaron informes detallados sobre toda la actividad demoníaca que encontraron. Concluyeron que, si bien solo había unos cuantos demonios dispersos por aquel territorio, la Legión sí constituía una verdadera amenaza si los humanos continuaban utilizando poderes mágicos." },
		[1887] = { file = "1887", len = 25.234, text = "El Consejo de Lunargenta, que gobernaba sobre los elfos de Quel'Thalas, firmó un pacto secreto con los señores magócratas de Dalaran. Los elfos contaron a los magócratas la historia del antiguo continente de Kalimdor y la Legión Ardiente, historia que aún amenazaba al planeta. Advirtieron a los humanos que, siempre que utilizaran la magia, debían proteger a sus ciudadanos de los agentes malvados de la Legión." },
		[1888] = { file = "1888", len = 28.134, text = "Los magócratas propusieron la idea de asignar poderes a un solo campeón mortal para librar una guerra secreta interminable contra la Legión. Resaltaron que la mayor parte de los humanos no debía saber nada acerca de los Guardianes o de la amenaza de la Legión, para evitar disturbios causados por el miedo y la paranoia. Los elfos aceptaron la propuesta y fundaron una sociedad secreta para supervisar la elección del Guardián, ayudando a contener el aumento del caos en el mundo." },
		[1889] = { file = "1889", len = 31.843, text = "La sociedad mantuvo sus reuniones secretas en los Claros de Tirisfal, donde los altos elfos se habían establecido por primera vez en Lordaeron. Así, llamaron a su secta secreta los Guardianes de Tirisfal. Los campeones mortales que fueron elegidos por los Guardianes recibieron increíbles poderes élficos y humanos. Si bien solo podía existir un Guardián cada vez, su poder era tan inconmensurable que podía responder a los ataques de la Legión sin ayuda de nadie en cualquier parte del planeta." },
		[1890] = { file = "1890", len = 21.368, text = "El poder del Guardián era tal, que solo el Consejo de Tirisfal podía elegir a los potenciales sucesores. Cada vez que un Guardián envejecía demasiado, o se cansaba de guardar los secretos de guerra contra el caos, el Consejo elegía a un nuevo campeón y, bajo un estricto control, transmitían formalmente los poderes del Guardián a su nuevo agente." },
		[1891] = { file = "1891", len = 22.648, text = "Con el transcurso de las generaciones, los Guardianes defendieron a la humanidad de la invisible amenaza de la Legión Ardiente por todo el territorio de Arathor y Quel'Thalas. Arathor creció y prosperó, al tiempo que el uso de la magia se extendió por todo el imperio. Mientras tanto, los Guardianes vigilaban cuidadosamente cualquier señal de actividad demoníaca." },
		[1892] = { file = "1892", len = 23.824, text = "En la antigüedad, cuando los titanes partieron de Azeroth, sus hijos, conocidos como los terráneos, continuaron dando forma y vigilando los oscuros recovecos del planeta. Los terráneos eran indiferentes a los asuntos de las razas que poblaban la superficie y solo les interesaba sondear las lóbregas profundidades de la tierra." },
		[1893] = { file = "1893", len = 34.246, text = "Los terráneos quedaron muy afectados tras la implosión del Pozo de la Eternidad que había destruido el planeta. Al no poder recuperarse del dolor causado por la destrucción de la tierra, los terráneos perdieron gran parte de su identidad y se encerraron en las cámaras de piedra en las que habían sido creados inicialmente. Uldaman, Uldum, Ulduar... eran los nombres de las antiguas ciudades de los titanes que los terráneos habían construido inicialmente. Enterrados en las profundidades del planeta, los terráneos descansaron en paz durante casi ocho mil años." },
		[1894] = { file = "1894", len = 24.424, text = "Aunque se desconoce qué fue lo que los despertó, los terráneos confinados en Uldaman finalmente despertaron de su sueño autoimpuesto. Se dieron cuenta de que habían cambiado significativamente durante la hibernación. Sus rocosos pelajes se habían suavizado, convirtiéndose en tersas pieles, mientras que sus poderes sobre la piedra y la tierra habían menguado. Se habían convertido en criaturas mortales." },
		[1895] = { file = "1895", len = 16.039, text = "Los últimos terráneos se hicieron llamar enanos y abandonaron las salas de Uldaman para aventurarse en el mundo de los seres despiertos. Adormecidos aún por la paz y las maravillas de las profundidades, fundaron un vasto reino bajo la montaña más alta de la tierra." },
		[1896] = { file = "1896", len = 19.095, text = "Llamaron a su tierra Khaz Modan, o \"Montaña de Khaz\", en honor a su creador, el titán Khaz'goroth. Al construir un altar para su padre titán, los enanos crearon una gran fragua en el corazón de la montaña. Por ello, la ciudad que creció en torno a la fragua recibió el nombre de Forjaz." },
		[1897] = { file = "1897", len = 15.726, text = "Los enanos, fascinados por la talla de la piedra y las gemas, se dedicaron a excavar las montañas vecinas para encontrar ricos y preciosos minerales. Satisfechos con sus trabajos subterráneos, permanecían aislados de lo que acontecía a sus vecinos de la superficie." },
		[1898] = { file = "1898", len = 26.122, text = "Strom siguió actuando como eje central de Arathor, pero al igual que ocurrió con Dalaran, surgieron muchas nuevas ciudades-estado por todo el continente de Lordaeron. Gilneas, Alterac y Kul Tiras fueron las primeras ciudades-estado en surgir, y aunque cada una tenía sus propias costumbres y funcionamiento comercial, todas se aferraban a la autoridad unificadora de Strom." },
		[1899] = { file = "1899", len = 22.126, text = "Bajo la atenta mirada de la Orden de Tirisfal, Dalaran se convirtió en el principal centro de aprendizaje para los magos de todo el país. Los Magócratas que gobernaban Dalaran fundaron el Kirin Tor, una secta especializada encargada de catalogar e investigar todos los hechizos, artefactos y objetos mágicos conocidos por la humanidad en aquella época." },
		[1900] = { file = "1900", len = 28.526, text = "Gilneas y Alterac se convirtieron en firmes partidarios de Strom y desarrollaron poderosos ejércitos que exploraron las montañosas tierras del sur de Khaz Modan. Fue durante este periodo cuando los humanos conocieron por primera vez a la antigua raza de los enanos y viajaron a su cavernosa ciudad subterránea de Ironforge. Los humanos y los enanos compartieron muchos secretos de orfebrería e ingeniería y descubrieron un amor común por la batalla y la narración de historias." },
		[1901] = { file = "1901", len = 27.82, text = "La ciudad-estado de Kul Tiras, fundada en una gran isla al sur de Lordaeron, desarrolló una próspera economía basada en la pesca y la navegación. Con el tiempo, Kul Tiras construyó una poderosa flota de barcos mercantes que navegaban por las tierras conocidas en busca de mercancías exóticas para comerciar y vender. Sin embargo, incluso cuando la economía de Arathor florecía, sus elementos más fuertes empezaron a desintegrarse." },
		[1902] = { file = "1902", len = 22.491, text = "Con el tiempo, los señores de Strom intentaron trasladar sus propiedades a las exuberantes tierras del norte de Lordaeron y abandonar las áridas tierras del sur. Los herederos del rey Thoradin, los últimos descendientes de la estirpe Arathi, argumentaron que Strom no debía abandonarse, lo que provocó el disgusto de la ciudadanía, que también deseaba marcharse." },
		[1903] = { file = "1903", len = 25.574, text = "Los señores de Strom, en busca de pureza e iluminación en el indómito norte, decidieron abandonar su antigua ciudad. Muy al norte de Dalaran, los señores de Strom construyeron una nueva ciudad-estado a la que llamaron Lordaeron. Todo el continente tomaría su nombre de esta ciudad-estado. Lordaeron se convirtió en la meca de los viajeros religiosos y de todos aquellos que buscaban paz interior y seguridad." },
		[1904] = { file = "1904", len = 27.455, text = "Los descendientes de los Arathi, abandonados en los muros derruidos de la antigua Strom, decidieron viajar hacia el sur, más allá de las montañas rocosas de Khaz Modan. Su viaje terminó finalmente tras muchas largas estaciones, y se asentaron en la región septentrional del continente que llamarían Azeroth. En un fértil valle fundaron el reino de Stormwind, que rápidamente se convirtió en una potencia autosuficiente por derecho propio." },
		[1905] = { file = "1905", len = 33.097, text = "Los pocos guerreros que aún quedaban en Strom decidieron quedarse y vigilar las antiguas murallas de su ciudad. Strom dejó de ser el centro del imperio y se convirtió en una nueva nación conocida como Stromgarde. Aunque cada una de las ciudades-estado llegó a ser próspera por derecho propio, el imperio de Arathor se había desintegrado. A medida que cada nación desarrollaba sus propias costumbres y creencias, se segregaban cada vez más unas de otras. La visión del rey Thoradin de una humanidad unificada se había desvanecido por fin." },
		[1906] = { file = "1906", len = 26.54, text = "Mientras las relaciones políticas y las rivalidades de las siete naciones humanas experimentaban altibajos, la línea de los guardianes mantuvo una vigilancia constante contra el caos. Durante años, hubo muchos guardianes, pero solo uno mantuvo siempre los poderes mágicos de Tirisfal. Una de las últimas guardianas de la era destacó como una poderosa guerrera en la lucha contra el mal." },
		[1907] = { file = "1907", len = 17.293, text = "Aegwynn, una humana muy temperamental, obtuvo la aprobación de la orden que le concedió el manto de la custodia. Aegwynn luchó valerosamente para dar caza y erradicar a los demonios allí donde los encontró, pero, a menudo, cuestionó la autoridad del Consejo de Tirisfal." },
		[1908] = { file = "1908", len = 29.205, text = "Creía que los elfos antiguos y los elfos ancianos que presidían el consejo eran demasiado rígidos en su forma de pensar y que, a la hora de terminar de una vez por todas con el conflicto contra el caos, resultaban cortos de miras. Mostrándose impaciente cuando se trataba de discutir largamente, siempre quería probarse a sí misma ante sus pares y sus superiores y, como resultado de todo ello, frecuentemente escogió el valor antes que la sabiduría en situaciones cruciales." },
		[1909] = { file = "1909", len = 27.246, text = "A medida que creció su dominio sobre el poder cósmico de Tirisfal, Aegwynn se dio cuenta de la existencia de un gran número de poderosos demonios que acechaban la helada parte norte del continente de Rasganorte. Viajando al distante norte, Aegwynn rastreó a los demonios en las montañas. Allí cayó en la cuenta de que los demonios estaban cazando a uno de los últimos Vuelos supervivientes, despojando a las antiguas criaturas de su magia innata." },
		[1910] = { file = "1910", len = 24.006, text = "Los poderosos dragones, que habían huido de las amenazantes sociedades mortales, se encontraron enfrentados en igualdad de condiciones a los siniestros poderes de la Legión. Aegwynn se enfrentó a los demonios y, con la ayuda de los nobles dragones, terminó por erradicarlos. Aun así, cuando el último demonio desapareció del mundo mortal, se desató una gran tormenta por todo el norte." },
		[1911] = { file = "1911", len = 19.957, text = "Un enorme rostro oscuro apareció en el cielo por encima de Rasganorte. Sargeras, el rey demonio y señor de la Legión Ardiente, apareció ante Aegwynn y manifestó su infernal cólera. Comunicó a la joven guardiana que el tiempo de Tirisfal estaba a punto de llegar a su fin y que pronto el mundo perecería a manos de la Legión." },
		[1912] = { file = "1912", len = 30.668, text = "La orgullosa Aegwynn, creyendo estar a la altura del dios amenazante, dio rienda suelta a sus poderes contra el avatar de Sargeras. Con una facilidad desconcertante, Aegwynn batió al señor de los demonios con sus poderes y logró acabar con su envoltura física. Ante el temor de que el espíritu de Sargeras sobreviviera, Aegwynn encerró los despojos de su cuerpo en una de las antiguas salas de Kalimdor que se habían hundido en las profundidades del mar cuando el Pozo de la Eternidad se desintegró." },
		[1913] = { file = "1913", len = 23.38, text = "Aegwynn nunca llegaría a saber que hizo justamente lo que Sargeras pretendía. Sin saberlo, selló el destino del mundo mortal, ya que Sargeras, en el momento de su muerte corpórea, transfirió su espíritu al debilitado cuerpo de Aegwynn. Sin que la joven guardiana fuera consciente de ello, Sargeras permanecería encubierto en las profundidades más oscuras de su alma durante muchos años." },
		[1914] = { file = "1914", len = 24.555, text = "Los enanos de la montaña de Forjaz vivieron en paz durante muchos siglos. Sin embargo, su sociedad creció demasiado dentro de los confines de sus montañosas ciudades. Aunque el poderoso gran rey Modimus Yunquemar reinó entre los enanos con justicia y sabiduría, tres poderosas facciones se habían rebelado contra la sociedad enana." },
		[1915] = { file = "1915", len = 25.051, text = "El clan Barbabronce, dirigido por el señor feudal Madoran Barbabronce, mantenía estrechos lazos con el gran rey, siendo los tradicionales defensores de la montaña de Forjaz. El clan Martillo Salvaje, dirigido por el señor feudal Khardros Martillo Salvaje, habitaba en las estribaciones y los riscos situados alrededor de la base de la montaña e intentaba incrementar su grado de control sobre la ciudad." },
		[1916] = { file = "1916", len = 14.916, text = "La tercera facción, el clan Hierro Negro, estaba dirigido por el hechicero y señor feudal Thaurissan. Los Hierro Negro se ocultaban entre las oscuras sombras de la montaña y complotaban contra sus primos Barbabronce y Martillo Salvaje." },
		[1917] = { file = "1917", len = 26.88, text = "Durante un tiempo, las tres facciones mantuvieron una frágil paz, pero las tensiones terminaron por explotar cuando murió el gran rey Yunquemar. Los tres clanes lucharon por el control de Forjaz. La guerra civil de los enanos se desarrolló bajo tierra durante muchos años. Finalmente, los Barbabronce, que disponían del ejército más poderoso, desterraron a los Hierro Negro y a los Martillo Salvaje de las profundidades de la montaña." },
		[1918] = { file = "1918", len = 33.463, text = "Khardros y sus guerreros Martillo Salvaje viajaron hacia el norte, atravesando las puertas de la barrera de Dun Algaz y fundaron su propio reino en las entrañas de la distante montaña de Grim Batol. Allí, los Martillo Salvaje prosperaron y volvieron a recuperar sus tesoros. A Thaurissan y a los Hierro Negro no les fue tan bien. Humillados y airados por su derrota, juraron venganza contra Forjaz. Conduciendo a su gente hacia el sur, Thaurissan fundó una ciudad (a la que puso su propio nombre) dentro de las bellas montañas Crestagrana." },
		[1919] = { file = "1919", len = 18.704, text = "La prosperidad y el paso de los años no lograron calmar el rencor de los Hierro Negro contra sus primos. Thaurissan y su mujer hechicera Modgud, lanzó un asalto en dos flancos contra Forjaz y Grim Batol al mismo tiempo. Los Hierro Negro intentaron reclamar la posición de la totalidad de Khaz Modan." },
		[1920] = { file = "1920", len = 28.891, text = "Los ejércitos de los Hierro Negro se lanzaron contra las fortalezas de sus primos y estuvieron muy cerca de tomar ambos reinos. No obstante, Madoran Barbabronce condujo a su clan a una victoria decisiva sobre el ejército de hechiceros de Thaurissan. Thaurissan y sus siervos huyeron para refugiarse en su ciudad, sin ser conscientes de lo que estaba ocurriendo en Grim Batol, donde el ejército de Modgud no lo estaba haciendo mejor contra Khardros y sus guerreros Martillo Negro." },
		[1921] = { file = "1921", len = 31.425, text = "Al enfrentarse a los guerreros enemigos, Modgud utilizó sus poderes para insuflar el temor en sus corazones. Bajo sus órdenes, las sombras se pusieron en marcha y surgieron oscuros objetos desde las profundidades de la tierra que acecharon a los Martillo Salvaje en sus propias salas. Finalmente, Modgud atravesó las puertas y puso la fortaleza bajo sitio. Los Martillo Salvaje lucharon desesperadamente y el propio Khardros acometió las agitadas masas para asesinar a la reina hechicera." },
		[1922] = { file = "1922", len = 19.931, text = "Perdida su reina, los Hierro Negro huyeron ante la furia de los Martillo Salvaje. Escaparon hacia el sur en dirección a la fortaleza de su rey y se encontraron con los ejércitos de Forjaz, que habían acudido en ayuda de Grim Batol. Cogidas entre dos fuegos, las fuerzas restantes de los Hierro Negro fueron destruidas por completo." },
		[1923] = { file = "1923", len = 37.042, text = "Posteriormente, los ejércitos conjuntos de Forjaz y Grim Batol se dirigieron al sur, intentando destruir a Thaurissan y a sus Hierro Negro de una vez por todas. No pudieron ir muy lejos cuando la furia de Thaurissan se materializó en un encantamiento de proporciones catastróficas. Al intentar conseguir la ayuda de un esbirro sobrenatural que garantizara su victoria, Thaurissan despertó antiguos poderes que dormían en el submundo. Para su sorpresa y, finalmente, para su condena, la criatura que emergió fue más terrible que cualquier pesadilla que pudiera imaginar." },
		[1924] = { file = "1924", len = 25.548, text = "Ragnaros, el Señor de Fuego, señor inmortal de todos los elementos flamígeros, había sido desterrado por los titanes cuando el mundo era joven. Ahora, liberado por la llamada de Thaurissan, Ragnaros volvió a la existencia una vez más. El renacimiento apocalíptico de Ragnaros en Azeroth hizo añicos las montañas Crestagrana y creó un rugiente volcán situado en el centro de la devastación." },
		[1925] = { file = "1925", len = 21.786, text = "El volcán, conocido como la montaña Roca Negra, limitaba al norte con la Garganta de Fuego y al sur con las Estepas Ardientes. Si bien Thaurissan fue asesinado por las fuerzas que lo habían liberado, sus hermanos que le sobrevivieron finalmente fueron esclavizados por Ragnaros y sus elementales. Hasta el día de hoy, permanecen en las profundidades de Roca Negra." },
		[1926] = { file = "1926", len = 17.476, text = "Habiendo presenciado la horrenda devastación, donde los fuegos se extendían a lo largo de las montañas del sur, el rey Madoran y el rey Khardros detuvieron sus ejércitos y regresaron a toda prisa hacia sus respectivos reinos, incapaces de hacer frente a la ira de Ragnaros." },
		[1927] = { file = "1927", len = 16.927, text = "Los Barbabronce regresaron a Forjaz y reconstruyeron la gloriosa ciudad. Asimismo, los Martillo Salvaje regresaron a casa en Grim Batol. Sin embargo, la muerte de Modgud dejó una pátina maléfica sobre la fortaleza de la montaña y resultó ser inhabitable." },
		[1928] = { file = "1928", len = 37.12, text = "Los corazones de los Martillo Salvaje sentían la amargura que suponía la pérdida de su amado hogar. El rey Barbabronce ofreció a los Martillo Salvaje un lugar donde vivir, situado en los límites de Forjaz, pero estos se negaron en redondo. Khardros condujo a su gente hacia el norte en dirección a las tierras de Lordaeron. Asentados en los exuberantes bosques de las tierras del interior, los Martillo Salvaje construyeron la ciudad de Pico Nidal, en donde los Martillo Salvaje crecieron cerca de la naturaleza e, incluso, se vincularon a los poderosos grifos de la región." },
		[1929] = { file = "1929", len = 24.66, text = "Al intentar conservar las relaciones y el comercio con sus primos, los enanos de Forjaz construyeron dos grandes arcos, el Puente Thandol, que une Khaz Modan con Lordaeron. Enriquecidos mediante el comercio mutuo, los dos reinos prosperaron. Tras las muertes de Madoran y Khardros, sus hijos encargaron conjuntamente la construcción de dos grandes estatuas en honor a sus padres." },
		[1930] = { file = "1930", len = 18.573, text = "Las dos estatuas guardarían el paso hacia las tierras del sur que, en presencia del ardiente Ragnaros, se habían convertido en tierras volcánicas. Sirvieron tanto como advertencia a aquellos que pretendían atacar los reinos de los enanos, como recordatorio del precio que pagaron los Hierro Negro por sus crímenes." },
		[1931] = { file = "1931", len = 24.686, text = "Los dos reinos mantuvieron estrechos lazos durante años, pero los Martillo Salvaje cambiaron en gran medida a causa de los horrores que presenciaron en Grim Batol. En lugar de excavar un vasto reino en el interior de la montaña, decidieron vivir en la superficie, en las laderas de Pico Nidal. Las diferencias ideológicas entre los dos clanes de enanos que quedaban condujeron finalmente a su separación." },
		[1932] = { file = "1932", len = 28.369, text = "Con el paso de los años, la guardiana Aegwynn se hizo cada vez más poderosa y utilizó las energías de Tirisfal para extender con mucho el alcance de su vida. Creyendo erróneamente que había derrotado a Sargeras para bien, continuó salvaguardando el mundo de los esbirros del rey de los demonios durante aproximadamente novecientos años. Sin embargo, el Consejo de Tirisfal decretó que su administración había llegado a su fin." },
		[1933] = { file = "1933", len = 13.113, text = "El consejo ordenó a Aegwynn que regresara a Dalaran, de manera que pudieran elegir un nuevo sucesor para la guardiana. Aun así, Aegwynn, desconfiando del consejo, decidió escoger a un sucesor por sí misma." },
		[1934] = { file = "1934", len = 23.38, text = "La orgullosa Aegwynn decidió traer un hijo al mundo al que transferir su poder. No tenía intención alguna de permitir que la orden de Tirisfal manipulara a su sucesor de la misma forma que intentaron manipularla a ella. Dirigiéndose a la nación sureña de Azeroth, Aegwynn encontró al hombre perfecto para convertirlo en padre de su hijo: un hábil mago humano conocido como Nielas Aran." },
		[1935] = { file = "1935", len = 27.376, text = "Aran era el mago y consejero de la corte del rey de Azeroth. Aegwynn sedujo al mago y tuvo un hijo de él. La afinidad natural hacia la magia de Nielas habría de influir profundamente en el niño aún no nacido y terminaron por definir los trágicos pasos que posteriormente seguiría el niño. Asimismo, el poder de Tirisfal pasó al niño, si bien no fue consciente de ello hasta alcanzar la madurez física." },
		[1936] = { file = "1936", len = 32.548, text = "Pasó el tiempo y Aegwynn dio a luz a su hijo en un bosquecillo apartado. Dándole el nombre de Medivh, que significa \"guardián de los secretos\" en la lengua de los elfos nobles, Aegwynn creyó que cuando el niño creciera, se convertiría en el próximo guardián. Desafortunadamente, el espíritu maligno de Sargeras, que se ocultaba en ella, tomó posesión del indefenso niño mientras permanecía en el seno materno. Aegwynn no tenía la menor idea de que el próximo guardián del mundo ya estaba poseído por su mayor enemigo." },
		[1937] = { file = "1937", len = 23.197, text = "Habiéndose asegurado de que su hijo estaba sano, Aegwynn envió al joven Medivh a la corte de Azeroth y lo dejó allí para que creciera junto a su padre mortal y a su gente. Luego, se internó en la jungla y se preparó para acudir a la cita con el más allá. Medivh creció hasta convertirse en un joven fuerte y no tenía idea del potencial que implicaba su derecho de nacimiento en Tirisfal." },
		[1938] = { file = "1938", len = 31.608, text = "Sargeras esperó el momento oportuno, hasta que los poderes del joven se manifestaron por sí solos. Cuando Medivh alcanzó la adolescencia, se convirtió en un personaje muy popular en Azeroth debido a sus poderes mágicos y, a menudo, corrió aventuras junto con sus dos amigos: Llane, príncipe de Azeroth, y Anduin Lothar, uno de los últimos descendientes de la línea de sangre arathi. Los tres muchachos no hacían más que meterse constantemente en líos, pero eran muy apreciados por el pueblo." },
		[1939] = { file = "1939", len = 13.897, text = "Cuando Medivh cumplió la edad de catorce años, el poder cósmico que residía en él despertó y chocó con el espíritu invasor de Sargeras que acechaba en su alma. Medivh entró en un estado catatónico que se prolongó durante varios años." },
		[1940] = { file = "1940", len = 20.689, text = "Cuando despertó de su estado de coma, cayó en la cuenta de que se había convertido en un adulto y vio que sus amigos eran los regentes de Azeroth. Si bien deseaba utilizar sus increíbles poderes para proteger la tierra que consideraba su casa, el oscuro espíritu de Sargeras tergiversó sus propósitos y emociones, conduciéndole a un final insidioso." },
		[1941] = { file = "1941", len = 11.076, text = "Sargeras se rebeló en el corazón de Medivh, ya que sabía que sus planes para una invasión del mundo estaban a punto de materializarse y el último guardián del mundo los llevaría a buen término." },
		[1942] = { file = "1942", len = 20.349, text = "Alrededor de la época del nacimiento de Medivh en Azeroth, Kil'jaeden el Engañador se sentaba a meditar entre sus seguidores en el Infierno Tortuoso. El astuto señor de los demonios, bajo las órdenes de su amo, Sargeras, planeaba la segunda invasión de Azeroth por parte de la Legión Ardiente." },
		[1943] = { file = "1943", len = 25.077, text = "Esta vez no permitiría ningún error. Kil'jaeden supuso que necesitaba una nueva fuerza para debilitar las defensas de Azeroth antes incluso de que la Legión pusiera un pie en el mundo. Si las razas mortales, como los elfos de la noche y los dragones, se veían obligadas a enfrentarse a una nueva amenaza, serían demasiado débiles para plantear una resistencia real cuando llegara la verdadera invasión de la Legión." },
		[1944] = { file = "1944", len = 13.766, text = "Fue entonces cuando Kil'jaeden descubrió el exuberante mundo de Draenor flotando pacíficamente en el Gran Más Allá Oscuro. Hogar de los orcos chamanes y de los pacíficos draenei, Draenor era tan idílico como vasto." },
		[1945] = { file = "1945", len = 19.618, text = "Los nobles clanes orcos vagaban por las praderas abiertas y cazaban por deporte, mientras que los inquisitivos draenei construían toscas ciudades en los elevados acantilados y picos del mundo. Kil'jaeden sabía que los habitantes de Draenor tenían un gran potencial para servir a la Legión Ardiente si se les cultivaba adecuadamente." },
		[1946] = { file = "1946", len = 21.629, text = "De las dos razas, Kil'jaeden vio que los orcos guerreros eran más susceptibles a la corrupción de la Legión. Atrajo al anciano chamán orco, Ner'zhul, del mismo modo que Sargeras controló a la reina Azshara en el pasado. Utilizando al astuto chamán como conducto, el demonio extendió la sed de batalla y el salvajismo entre los clanes orcos." },
		[1947] = { file = "1947", len = 22.1, text = "En poco tiempo, la raza espiritual se transformó en un pueblo sediento de sangre. Kil'jaeden instó entonces a Ner'zhul y a su pueblo a dar el último paso: entregarse por completo a la búsqueda de la muerte y la guerra. Sin embargo, el viejo chamán, presintiendo que su pueblo quedaría esclavizado al odio para siempre, se resistió de algún modo a la orden del demonio." },
		[1948] = { file = "1948", len = 21.473, text = "Frustrado por la resistencia de Ner'zhul, Kil'jaeden buscó a otro orco que entregara a su pueblo en manos de la Legión. El astuto señor de los demonios finalmente encontró al discípulo dispuesto que buscaba: el ambicioso aprendiz de Ner'zhul, Gul'dan. Kil'jaeden prometió a Gul'dan un poder incalculable a cambio de su total obediencia." },
		[1949] = { file = "1949", len = 22.544, text = "El joven orco se convirtió en un ávido estudiante de magia demoníaca y se convirtió en el hechicero mortal más poderoso de la historia. Enseñó a otros jóvenes orcos las artes arcanas y se esforzó por erradicar las tradiciones chamánicas de los orcos. Gul'dan mostró un nuevo tipo de magia a sus hermanos, un nuevo y terrible poder que apestaba a perdición." },
		[1950] = { file = "1950", len = 35.553, text = "Kil'jaeden, buscando reforzar su dominio sobre los orcos, ayudó a Gul'dan a fundar el Concilio de la Sombra, una secta secreta que manipulaba a los clanes y extendía el uso de la magia bruja por todo Draenor. A medida que más y más orcos empezaron a usar magias de hechicero, los apacibles campos y arroyos de Draenor empezaron a ennegrecerse y desvanecerse. Con el tiempo, las vastas praderas que los orcos habían llamado hogar durante generaciones se marchitaron, dejando sólo un suelo rojo y estéril. Las energías demoníacas estaban matando lentamente al mundo." },
		[1951] = { file = "1951", len = 22.047, text = "Bajo el secreto control de Gul'dan y su Consejo de la Sombra, los orcos se volvieron cada vez más agresivos. Construyeron grandes estadios en donde ponían a punto sus virtudes guerreras en pruebas de combate y muerte. Durante este periodo, algunos jefes del clan clamaron contra la creciente depravación de su raza." },
		[1952] = { file = "1952", len = 20.14, text = "Uno de esos jefes, Durotan, del clan Lobo de Hielo, advirtió que los orcos no debían perderse en el odio y la furia. Sin embargo, sus palabras cayeron en oídos sordos, ya que jefes más fuertes como Grom Hellscream, del clan Warsong, se adelantaron para defender la nueva era de la guerra y el dominio." },
		[1953] = { file = "1953", len = 23.458, text = "Kil'jaeden sabía que los clanes orcos estaban casi listos, pero necesitaba estar seguro de su lealtad definitiva. En secreto, hizo que el Consejo de la Sombra invocara a Mannoroth el Destructor, el recipiente viviente de la destrucción y la ira. Gul'dan reunió a los jefes de clan y los convenció de que beber la sangre furiosa de Mannoroth los haría completamente invencibles." },
		[1954] = { file = "1954", len = 17.058, text = "Liderados por Grom Grito Infernal, todos los jefes de clan excepto Durotan bebieron y sellaron así su destino como esclavos de la Legión Ardiente. Impulsados por la furia de Mannoroth, los jefes extendieron inconscientemente este sometimiento a sus desprevenidos hermanos." },
		[1955] = { file = "1955", len = 15.308, text = "Consumidos por la maldición de esta nueva sed de sangre, los orcos buscaron desatar su furia sobre cualquiera que se les pusiera por delante. Sintiendo que había llegado el momento, Gul'dan unió a los clanes enfrentados en una única e imparable Horda." },
		[1956] = { file = "1956", len = 25.365, text = "Sin embargo, sabiendo que varios jefes como Hellscream y Orgrim Doomhammer se disputarían la supremacía general, Gul'dan creó un jefe marioneta para gobernar esta nueva Horda. Blackhand el Destructor, un señor de la guerra orco particularmente depravado y despiadado, fue elegido para ser la marioneta de Gul'dan. Bajo el mando de Blackhand, la Horda se puso a prueba contra los simples draenei." },
		[1957] = { file = "1957", len = 27.089, text = "En el transcurso de unos pocos meses, la Horda erradicó a casi todos los draenei que vivían en Draenor. Sólo un puñado disperso de supervivientes logró evadir la impresionante ira de los orcos. Sonrojado por la victoria, Gul'dan se deleitó con el poder y la fuerza de la Horda. Sin embargo, sabía que sin enemigos contra los que luchar, la Horda se consumiría en interminables luchas internas en su imparable apetito de gloriosas matanzas." },
		[1958] = { file = "1958", len = 16.927, text = "Kil'jaeden sabía que la Horda estaba finalmente preparada. Los orcos se habían convertido en la mayor arma de la Legión Ardiente. El astuto demonio compartió sus conocimientos con su maestro en espera, y Sargeras estuvo de acuerdo en que por fin había llegado el momento de su venganza." },
		[1959] = { file = "1959", len = 18.678, text = "Mientras Kil'jaeden preparaba a la Horda para su invasión de Azeroth, Medivh seguía luchando por su alma contra Sargeras. El rey Llane, noble monarca de Ventormenta, recelaba de la oscuridad que parecía contaminar el espíritu de su antiguo amigo." },
		[1960] = { file = "1960", len = 17.345, text = "El rey Llane compartió sus preocupaciones con Anduin Lothar, el último descendiente del linaje Arathi, a quien nombró su lugarteniente de armas. Aun así, ninguno de los dos podía imaginar que el lento descenso de Medivh hacia la locura provocaría los horrores que estaban por llegar." },
		[1961] = { file = "1961", len = 22.387, text = "Como incentivo final, Sargeras prometió otorgar un gran poder a Gul'dan si accedía a liderar a la Horda hacia Azeroth. A través de Medivh, Sargeras le dijo al hechicero que podría convertirse en un dios viviente si encontraba la tumba submarina donde la Guardiana Aegwynn había depositado el cuerpo lisiado de Sargeras casi mil años antes." },
		[1962] = { file = "1962", len = 15.02, text = "Gul'dan estuvo de acuerdo y decidió que, una vez derrotados los habitantes de Azeroth, encontraría la tumba legendaria y reclamaría su recompensa. Asegurado de que la Horda serviría a sus propósitos, Sargeras ordenó que comenzara la invasión." },
		[1963] = { file = "1963", len = 31.112, text = "Mediante un esfuerzo conjunto, Medivh y los brujos del Consejo de la Sombra abrieron el portal dimensional conocido como el Portal Oscuro. Este portal salvaba la distancia entre Azeroth y Draenor, y era lo bastante grande como para que pudieran atravesarlo ejércitos. Gul'dan envió exploradores orcos a través del portal para inspeccionar las tierras que iban a conquistar. Los exploradores que regresaron aseguraron al Consejo de la Sombra que el mundo de Azeroth estaba listo para ser conquistado." },
		[1964] = { file = "1964", len = 25.574, text = "Aún convencido de que la corrupción de Gul'dan destruiría a su pueblo, Durotan volvió a hablar contra los hechiceros. El valiente guerrero afirmó que los brujos estaban destruyendo la pureza del espíritu orco y que esta temeraria invasión sería su perdición. Gul'dan, incapaz de arriesgarse a matar a un héroe tan popular, se vio obligado a exiliar a Durotan y a su Clan Lobo Gélido a los confines de este nuevo mundo." },
		[1965] = { file = "1965", len = 24.033, text = "Después de que los Lobos Escarchados exiliados atravesaran el portal, sólo les siguieron unos pocos clanes de orcos. Estos orcos establecieron rápidamente una base de operaciones en el Pantano Negro, una zona oscura y pantanosa al este del reino de Ventormenta. Cuando los orcos empezaron a explorar las nuevas tierras, entraron en conflicto inmediato con los defensores humanos de Stormwind." },
		[1966] = { file = "1966", len = 19.252, text = "Aunque estas escaramuzas solían terminar rápidamente, servían para ilustrar las debilidades y fortalezas de ambas especies rivales. Llane y Lothar nunca fueron capaces de reunir datos precisos sobre el número de orcos y sólo podían hacer conjeturas sobre la magnitud de la fuerza a la que tendrían que enfrentarse." },
		[1967] = { file = "1967", len = 14.916, text = "Al cabo de unos años, la mayor parte de la Horda de orcos había cruzado a Azeroth, y Gul'dan consideró que había llegado el momento del golpe principal contra la humanidad. La Horda lanzó todo su poder contra el desprevenido reino de Stormwind." },
		[1968] = { file = "1968", len = 27.846, text = "Mientras las fuerzas de Azeroth y la Horda se enfrentaban por todo el reino, los conflictos internos empezaron a hacer mella en ambos ejércitos. El rey Llane, que creía que los bestiales orcos eran incapaces de conquistar Azeroth, mantuvo despectivamente su posición en su capital de Stormwind. Sin embargo, Sir Lothar se convenció de que la batalla debía llevarse directamente contra el enemigo, y se vio obligado a elegir entre sus convicciones y su lealtad al rey." },
		[1969] = { file = "1969", len = 14.785, text = "Optando por seguir sus instintos, Lothar asaltó la torre-fortaleza de Medivh en Karazhan con la ayuda del joven aprendiz del mago, Khadgar. Khadgar y Lothar lograron derrotar al Guardián poseído, a quien confirmaron como origen del conflicto." },
		[1970] = { file = "1970", len = 16.692, text = "Al matar el cuerpo de Medivh, Lothar y el joven aprendiz desterraron sin querer el espíritu de Sargeras al abismo. Como consecuencia, al espíritu puro y virtuoso de Medivh también se le permitió seguir viviendo... y vagar por el plano astral durante muchos años." },
		[1971] = { file = "1971", len = 17.868, text = "Aunque Medivh había sido derrotado, la Horda seguía dominando a los defensores de Stormwind. A medida que se acercaba la victoria de la Horda, Orgrim Doomhammer, uno de los más grandes jefes orcos, empezó a ver la depravada corrupción que se había extendido por los clanes desde su época en Draenor." },
		[1972] = { file = "1972", len = 28.447, text = "Su viejo camarada, Durotan, regresó del exilio y le advirtió una vez más de la traición de Gul'dan. En rápida venganza, los asesinos de Gul'dan mataron a Durotan y a su familia, dejando con vida sólo a su hijo pequeño. Doomhammer desconocía que el hijo pequeño de Durotan fue encontrado por el oficial humano Aedelas Blackmoore y tomado como esclavo. Ese niño orco se convertiría un día en el mayor líder que su pueblo hubiera conocido jamás." },
		[1973] = { file = "1973", len = 19.566, text = "Indignado por la muerte de Durotan, Orgrim se propuso liberar a la Horda de la corrupción demoníaca y finalmente asumió el papel de jefe de la Horda al matar a la marioneta corrupta de Gul'dan, Mano Negra. Bajo su decisivo liderazgo, la implacable Horda finalmente sitió la Fortaleza de Stormwind." },
		[1974] = { file = "1974", len = 16.457, text = "El rey Llane había subestimado gravemente el poder de la Horda, y vio impotente cómo su reino caía ante los invasores de piel verde. Finalmente, el rey Llane fue asesinado por uno de los mejores asesinos del Consejo de la Sombra: la semiorca Garona." },
		[1975] = { file = "1975", len = 27.115, text = "Lothar y sus guerreros, de vuelta a casa desde Karazhan, esperaban detener la pérdida de vidas y salvar su antaño gloriosa patria. Sin embargo, regresaron demasiado tarde y encontraron su amado reino en ruinas humeantes. La Horda orca seguía asolando el campo y reclamaba las tierras circundantes para sí. Obligados a esconderse, Lothar y sus compañeros juraron recuperar su patria a cualquier precio." },
		[1976] = { file = "1976", len = 26.828, text = "Lothar reunió los restos de los ejércitos de Azeroth tras su derrota en el Castillo de Ventormenta y luego puso en marcha un éxodo masivo por mar hacia el norteño reino de Lordaeron. Convencido de que si no se controlaba a la Horda, derrotaría a toda la humanidad, los líderes de las siete naciones humanas se reunieron y acordaron unir esfuerzos en lo que se conocería como la Alianza de Lordaeron." },
		[1977] = { file = "1977", len = 16.562, text = "Por primera vez en prácticamente tres mil años, las naciones separadas de Arathor estaban unidas una vez más bajo un estandarte común. Nombrado Comandante Supremo de las Fuerzas Aliadas, Lord Lothar preparó a sus ejércitos para hacer frente a la llegada de la Horda." },
		[1978] = { file = "1978", len = 18.599, text = "Ayudado por sus lugartenientes, Uther el Luminoso, el almirante Daelin Valiente y Turalyon, Lothar fue capaz de convencer a las razas semihumanas de Lordaeron de la inminente amenaza. La Alianza obtuvo el apoyo de los estoicos enanos de Forjaz y de un pequeño número de elfos nobles de Quel'Thalas." },
		[1979] = { file = "1979", len = 17.972, text = "Los elfos, dirigidos en aquel tiempo por Anasterian Caminante del Sol, no estaban interesados en modo alguno en el conflicto que se aproximaba. Sin embargo, estaban dispuestos a ayudar a Lothar, ya que se trataba del último descendiente de la línea de sangre arathi, que había ayudado a los elfos en el pasado." },
		[1980] = { file = "1980", len = 21.211, text = "La Horda, ahora dirigida por el Jefe de Guerra Martillo Maldito, trajo ogros procedentes de su hogar de Draenor y reclutó trols procedentes del bosque de Amani. Comprometidos en una campaña masiva para borrar el reino $r de Khaz Modan y los límites sureños de Lordaeron, la Horda diezmó casi sin esfuerzo cualquier clase de oposición." },
		[1981] = { file = "1981", len = 30.955, text = "Las épicas batallas de la Segunda Guerra incluyeron desde escaramuzas navales a gran escala hasta ataques aéreos masivos. De alguna manera, la Horda logró desenterrar un poderoso artefacto conocido como Alma Demoníaca y lo utilizó para esclavizar a Alexstrasza, antigua reina de los dragones. Amenazando destruir sus preciosos huevos, la Horda obligó a Alexstrasza a enviar a sus hijos mayores a la guerra. Los nobles dragones rojos fueron obligados a luchar para la Horda y eso es lo que hicieron." },
		[1982] = { file = "1982", len = 34.821, text = "La guerra rugió a través de los continentes de Khaz Modan, Lordaeron y el propio Azeroth. Como parte de su campaña en el norte, la Horda consiguió incendiar las tierras fronterizas de Quel'Thalas y, de esta manera, se aseguraron el compromiso final de los elfos con la causa de la Alianza. Las ciudades y los pueblos más grandes de Lordaeron quedaron destruidos y devastados por el conflicto. A pesar de la ausencia de refuerzos y de que todas las probabilidades estaban en contra, Lothar y sus aliados lograron mantener a sus enemigos a raya." },
		[1983] = { file = "1983", len = 25.104, text = "Sin embargo, durante los días finales de la Segunda Guerra, cuando la victoria de la Horda parecía casi garantizada, una terrible contienda surgió entre los dos orcos más poderosos de Azeroth. Cuando Martillo Maldito preparaba su asalto final a la ciudad capital de Lordaeron, un asalto que habría de destruir las últimas reservas de la Alianza, Gul'dan y sus seguidores abandonaron sus puestos y marcharon hacia el mar." },
		[1984] = { file = "1984", len = 12.643, text = "El perplejo Martillo Maldito, habiendo perdido prácticamente la mitad de sus fuerzas a causa de la traición de Gul'dan, se vio obligado a retroceder y a olvidar la posibilidad de obtener la mayor victoria contra la Alianza." },
		[1985] = { file = "1985", len = 22.1, text = "Gul'dan, hambriento de poder y obsesionado con convertirse en un dios, se lanzó a una carrera desesperada para llegar hasta la tumba sumergida de Sargeras, que creía guardaba los secretos de un gran poder. Habiendo condenado a sus compañeros orcos a convertirse en esclavos de la Legión Ardiente, Gul'dan consideraba que no le debía nada a Martillo Maldito." },
		[1986] = { file = "1986", len = 14.002, text = "Con el apoyo de los clanes Cazatormentas y Martillo Crepuscular, Gul'dan logró extraer la tumba de Sargeras del lecho marino. Sin embargo, cuando abrió la antigua e inundada bóveda, solo halló demonios enloquecidos que lo aguardaban." },
		[1987] = { file = "1987", len = 23.014, text = "Con la intención de castigar a los díscolos orcos por su costosa traición, Martillo Maldito envió sus fuerzas para acabar con Gul'dan y traer a los renegados de vuelta al redil. Por su imprudencia, Gul'dan fue destrozado por los demonios enloquecidos que había liberado. Con su líder muerto, los clanes renegados cayeron rápidamente ante las enfurecidas legiones de Martillo Maldito." },
		[1988] = { file = "1988", len = 16.509, text = "Aunque la rebelión había sido aplastada, la Horda fue incapaz de recuperarse de las terribles pérdidas que había sufrido. La traición de Gul'dan había permitido que la Alianza no solo renovara sus esperanzas, sino que le había concedido tiempo para reagruparse y contraatacar." },
		[1989] = { file = "1989", len = 33.62, text = "Lothar, viendo que la Horda estaba fracturada desde dentro, reunió al resto de sus fuerzas y empujó a Martillo Maldito hacia el sur, obligándole a internarse en el destruido corazón de Ventormenta. Allí, las fuerzas de la Alianza atraparon a la Horda en retirada, dentro de la fortaleza volcánica Cumbre de Roca Negra. Aunque Lord Lothar cayó en la batalla en la base de la cumbre, su lugarteniente Turalyon volvió a reunir a las fuerzas de la Alianza en la hora undécima y empujó nuevamente a la Horda hacia el abismo del Pantano de las Penas." },
		[1990] = { file = "1990", len = 17.528, text = "Las fuerzas de Turalyon lograron destruir el Portal Oscuro, la puerta mística que conectaba a los orcos con su hogar de Draenor. Sin posibilidades de obtener refuerzos y fracturada por las luchas internas, la Horda finalmente se derrumbó y terminó sucumbiendo al poder de la Alianza." },
		[1991] = { file = "1991", len = 29.074, text = "Los dispersos clanes orcos fueron rápidamente rodeados y conducidos a campos de internamiento vigilados. Aunque parecía que la Horda había sido derrotada para bien, algunos fueron muy escépticos acerca de la posibilidad de la paz. Khadgar, convertido en archimago de cierto renombre, persuadió al alto mando de la Alianza para que construyera la Fortaleza de Nethergarde, que vigilaría las ruinas del Portal Oscuro y garantizaría que no se produjeran futuras invasiones procedentes de Draenor." },
		[1992] = { file = "1992", len = 23.771, text = "Cuando los fuegos de la Segunda Guerra se apagaron, la Alianza tomó medidas agresivas para contener la amenaza orca. En el sur de Lordaeron se construyeron grandes campos de internamiento para albergar a los orcos cautivos. Vigilados tanto por los paladines como por los soldados veteranos de la Alianza, los campos resultaron ser un gran éxito." },
		[1993] = { file = "1993", len = 14.002, text = "Aunque los orcos cautivos estaban tensos y ansiosos por combatir una vez más, los diversos guardianes del campamento, con base en la antigua prisión-fortaleza de Durnholde, mantuvieron la paz y una fuerte apariencia de orden." },
		[1994] = { file = "1994", len = 24.189, text = "Sin embargo, en el mundo infernal de Draenor, un nuevo ejército orco se preparaba para atacar a la desprevenida Alianza. Ner'zhul, el antiguo mentor de Gul'dan, reunió a los clanes orcos restantes bajo su oscuro estandarte. Ayudado por el clan Shadowmoon, el viejo chamán planeaba abrir una serie de portales en Draenor que llevarían a la Horda a nuevos mundos vírgenes." },
		[1995] = { file = "1995", len = 11.807, text = "Para alimentar sus nuevos portales, necesitaba una serie de artefactos encantados de Azeroth. Para conseguirlos, Ner'zhul reabrió el Portal Oscuro y envió a sus voraces siervos a través de él." },
		[1996] = { file = "1996", len = 20.558, text = "La nueva Horda, liderada por veteranos jefes como Grom Hellscream y Kilrogg Deadeye (del clan Bleeding Hollow), sorprendió a las fuerzas de defensa de la Alianza y arrasó el campo. Bajo el mando quirúrgico de Ner'zhul, los orcos reunieron rápidamente los artefactos que necesitaban y huyeron de vuelta a la seguridad de Draenor." },
		[1997] = { file = "1997", len = 29.701, text = "El rey Terenas de Lordaeron, convencido de que los orcos preparaban una nueva invasión de Azeroth, reunió a sus lugartenientes de mayor confianza. Ordenó al general Turalyon y al archimago Khadgar que lideraran una expedición a través del Portal Oscuro para acabar de una vez por todas con la amenaza orca. Las fuerzas de Turalyon y Khadgar marcharon hacia Draenor y se enfrentaron repetidamente a los clanes de Ner'zhul en la devastada Península del Fuego Infernal." },
		[1998] = { file = "1998", len = 12.826, text = "Incluso con la ayuda de la alta elfa Alleria Windrunner, el enano Kurdran Wildhammer y el veterano soldado Danath Trollbane, Khadgar fue incapaz de impedir que Ner'zhul abriera sus portales a otros mundos." },
		[1999] = { file = "1999", len = 32.653, text = "Ner'zhul finalmente abrió sus portales a otros mundos, pero no previó el terrible precio que pagaría. Las tremendas energías de los portales comenzaron a desgarrar el tejido mismo de Draenor. Mientras las fuerzas de Turalyon luchaban desesperadamente por regresar a Azeroth, el mundo de Draenor empezó a derrumbarse sobre sí mismo. Grom Hellscream y Kilrogg Deadeye, al darse cuenta de que los locos planes de Ner'zhul condenarían a toda su raza, reunieron a los orcos restantes y escaparon de vuelta a la relativa seguridad de Azeroth." },
		[2000] = { file = "2000", len = 30.276, text = "En Draenor, Turalyon y Khadgar acordaron hacer el sacrificio definitivo destruyendo el Portal Oscuro desde su lado. Aunque les costaría la vida, y la de sus compañeros, sabían que era la única forma de garantizar la supervivencia de Azeroth. Mientras Hellscream y Deadeye se abrían paso a hachazos entre las filas humanas en un intento desesperado por alcanzar la libertad, el Portal Oscuro estalló tras ellos. Para ellos, y para los orcos que quedaban en Azeroth, no habría vuelta atrás." },
		[2001] = { file = "2001", len = 20.48, text = "Ner'zhul y su leal clan de la Luna Sombría atravesaron el mayor de los portales recién creados, mientras enormes erupciones volcánicas comenzaban a separar los continentes de Draenor. Los mares ardientes se alzaron y agitaron el paisaje destrozado mientras el torturado mundo se consumía finalmente en una explosión masiva y apocalíptica." },
		[2002] = { file = "2002", len = 26.305, text = "Ner'zhul y sus seguidores entraron en el Twisting Nether, el plano etéreo que conecta todos los mundos dispersos por el Gran Más Allá Oscuro. Por desgracia, Kil'jaeden y sus secuaces demoníacos les estaban esperando. Kil'jaeden, que había jurado vengarse de Ner'zhul por su orgulloso desafío, desgarró lentamente el cuerpo del viejo chamán, pedazo a pedazo." },
		[2003] = { file = "2003", len = 23.797, text = "Kil'jaeden mantuvo vivo e intacto el espíritu del chamán, dejando así a Ner'zhul dolorosamente consciente del grosero desmembramiento de su cuerpo. Aunque Ner'zhul suplicó al demonio que liberara su espíritu y le concediera la muerte, el demonio le respondió sombríamente que el Pacto de Sangre que habían hecho tiempo atrás seguía siendo vinculante, y que Ner'zhul aún tenía un propósito que cumplir." },
		[2004] = { file = "2004", len = 26.175, text = "El fracaso de los orcos a la hora de conquistar el mundo para la Legión Ardiente obligó a Kil'jaeden a crear un nuevo ejército para sembrar el caos en todos los reinos de Azeroth. No podía permitirse que este nuevo ejército fuera presa de las mismas rivalidades mezquinas y luchas internas que habían asolado a la Horda. Tendría que ser despiadado y decidido en su misión. Esta vez, Kil'jaeden no podía permitirse fracasar." },
		[2005] = { file = "2005", len = 23.745, text = "Manteniendo el espíritu de Ner'zhul indefenso en estasis, Kil'jaeden le dio una última oportunidad de servir a la Legión o sufrir un tormento eterno. Una vez más, Ner'zhul aceptó imprudentemente el pacto del demonio. El espíritu de Ner'zhul fue colocado dentro de un bloque especialmente fabricado de hielo duro como el diamante, recogido de los confines del Nether Retorcido." },
		[2006] = { file = "2006", len = 19.461, text = "Encerrado en el barril helado, Ner'zhul sintió que su conciencia se multiplicaba por diez. Deformado por los poderes caóticos del demonio, Ner'zhul se convirtió en un ser espectral de poder insondable. En ese momento, el orco conocido como Ner'zhul quedó destrozado para siempre, y nació el Rey Exánime." },
		[2007] = { file = "2007", len = 20.375, text = "Los leales caballeros de la muerte de Ner'zhul y los seguidores de Shadowmoon también fueron transformados por las energías caóticas del demonio. Los malvados hechiceros fueron despedazados y rehechos como liches esqueléticos. Los demonios se habían asegurado de que, incluso en la muerte, los seguidores de Ner'zhul le sirvieran incondicionalmente." },
		[2008] = { file = "2008", len = 22.726, text = "Cuando llegó el momento, Kil'jaeden explicó la misión para la que había creado al Rey Exánime. Ner'zhul iba a extender una plaga de muerte y terror por Azeroth que acabaría con la civilización humana para siempre. Todos los que murieran a causa de la temida plaga resucitarían como muertos vivientes, y sus espíritus quedarían atados para siempre a la férrea voluntad de Ner'zhul." },
		[2009] = { file = "2009", len = 11.206, text = "Kil'jaeden prometió que si Ner'zhul cumplía su oscura misión de barrer a la humanidad del mundo, sería liberado de su maldición y se le concedería un cuerpo nuevo y sano en el que habitar." },
		[2010] = { file = "2010", len = 31.033, text = "Aunque Ner'zhul se mostraba agradable y parecía ansioso por desempeñar su papel, Kil'jaeden seguía mostrándose escéptico sobre la lealtad de su peón. Mantener al Rey Exánime sin cuerpo y atrapado en el barril de cristal garantizaba su buena conducta a corto plazo, pero el demonio sabía que tendría que vigilarlo de cerca. Con este fin, Kil'jaeden llamó a su guardia demoníaca de élite, los vampíricos señores del terror, para que vigilaran a Ner'zhul y se aseguraran de que cumplía su terrible tarea." },
		[2011] = { file = "2011", len = 11.624, text = "Tichondrius, el más poderoso y astuto de los dreadlords, se entusiasmó con el desafío; le fascinaba la gravedad de la plaga y el potencial desenfrenado de genocidio del Rey Exánime." },
		[2012] = { file = "2012", len = 29.91, text = "Kil'jaeden volvió a emplazar la urna congelada de Ner'zhul en el mundo de Azeroth. El cristal endurecido centelleaba bajo la noche estrellada y chocó en el desolado continente ártico de Rasganorte, enterrándose en las profundidades del glaciar Corona de Hielo. El cristal congelado, deformado y marcado por su violento descenso, adquirió el aspecto de un trono y el vengativo espíritu de Ner'zhul pronto comenzó a moverse en su interior." },
		[2013] = { file = "2013", len = 29.544, text = "Desde los confines del Trono Helado, Ner'zhul comenzó a expandir su vasta conciencia y a entrar en contacto con las mentes de los habitantes de Rasganorte. Casi sin esfuerzo, logró esclavizar la mente de muchas criaturas indígenas, incluyendo trols de hielo wendigo, y atrajo a sus maléficos hermanos hacia su creciente sombra. Sus poderes psíquicos resultaron prácticamente ilimitados y los utilizó para crear un pequeño ejército que habitó en los intrincados laberintos de Corona de Hielo." },
		[2014] = { file = "2014", len = 20.14, text = "A medida que el rey Exánime aprendía a dominar sus crecientes facultades bajo la persistente vigilancia de los Señores del Terror, descubrió un remoto asentamiento humano situado en la periferia del vasto territorio de Desolación de los dragones. En un abrir y cerrar de ojos, Ner'zhul decidió probar sus poderes con los despreocupados humanos." },
		[2015] = { file = "2015", len = 31.347, text = "Ner'zhul propagó una peste de los no-muertos, que se había originado desde las profundidades, en el interior del Trono Helado, en los páramos del ártico. Controlando la peste con su sola voluntad, la lanzó directamente hacia el poblado humano. En un plazo de tres días, todos los habitantes del asentamiento estaban muertos, pero poco después, los pobladores empezaron a revivir como cadáveres zombis. Ner'zhul podía sentir sus espíritus y pensamientos individuales, como si fueran suyos." },
		[2016] = { file = "2016", len = 15.438, text = "La colérica cacofonía en su mente hizo que Ner'zhul acumulara aún más poder, como si sus espíritus le proporcionaran el alimento necesario. Descubrió que era un juego de niños controlar las acciones de los zombis y hacer que realizaran todo aquello que deseaba." },
		[2017] = { file = "2017", len = 15.752, text = "En los siguientes meses, Ner'zhul continuó experimentando con su peste de los no-muertos, sometiendo a todos los habitantes humanos de Rasganorte. Con su ejército de no-muertos creciendo a diario, sabía que se acercaba el momento de realizar la verdadera prueba." },
		[2018] = { file = "2018", len = 32.575, text = "Mientras tanto, en las atormentadas tierras del sur, los dispersos supervivientes de la Horda luchaban por su mera supervivencia. Aunque Grom Grito Infernal y su clan Grito de Guerra habían logrado evitar ser capturados, Mortojo y su clan Foso Sangrante fueron rodeados y conducidos a campos de internamiento en Lordaeron. A pesar de estos costosos levantamientos, pronto los guardianes de los campos lograron recuperar el control sobre sus salvajes prisioneros." },
		[2019] = { file = "2019", len = 31.791, text = "Sin embargo, sin que la Alianza lo supiera, una gran fuerza de orcos aún vagaba libre en los páramos del norte de Khaz Modan. El clan Faucedraco, dirigido por el infame brujo Nekros, estaba utilizando un viejo artefacto conocido como Alma Demoníaca para controlar a la reina de los dragones Alexstrasza y a su Vuelo. Teniendo a la reina de los dragones como rehén, Nekros creó un ejército secreto en el interior de la abandonada fortaleza de Martillo Salvaje de Grim Batol (algunos decían que estaba maldita)." },
		[2020] = { file = "2020", len = 23.223, text = "Con la intención de liberar sus fuerzas y a los poderosos dragones rojos de la Alianza, Nekros esperaba reunir a la Horda y continuar su conquista de Azeroth. Su visión no llegó a realizarse: un pequeño grupo de luchadores de la resistencia, dirigido por el mago humano Rhonin, logró destruir el Alma Demoníaca y liberar a la reina de los dragones del yugo de Nekros." },
		[2021] = { file = "2021", len = 24.79, text = "En su furia, los dragones de Alexstrasza destruyeron Grim Batol e incineraron a la mayor parte del clan Faucedraco. Los grandes planes de reunificación de Nekros cayeron por los suelos cuando las tropas de la Alianza rodearon a los orcos supervivientes y los arrojaron a los campos de internamiento. La derrota del clan Faucedraco señaló el fin de la Horda y el fin de la furiosa sed de sangre de los orcos." },
		[2022] = { file = "2022", len = 26.54, text = "Pasaron los meses y más prisioneros orcos fueron capturados, tras lo cual fueron conducidos a los campos de internamiento. Cuando los campos empezaron a estar superpoblados, la Alianza tuvo que construir nuevos campos en las planicies del sur de las montañas de Alterac. Para mantener adecuadamente el creciente número de campos, el rey Terenas impuso un nuevo impuesto a las naciones de la Alianza." },
		[2023] = { file = "2023", len = 15.621, text = "Este impuesto, junto con el aumento de las tensiones políticas por las disputas fronterizas, creó un malestar generalizado. Parecía que el frágil pacto que había unido a las naciones humanas en su momento más oscuro se rompería en cualquier momento." },
		[2024] = { file = "2024", len = 18.939, text = "En medio de la agitación política, muchos de los guardas de los campos empezaron a notar un cambio inquietante en sus cautivos orcos. Los esfuerzos de los orcos por escapar de los campamentos o incluso luchar entre ellos habían disminuido enormemente con el tiempo. Los orcos eran cada vez más distantes y letárgicos." },
		[2025] = { file = "2025", len = 17.345, text = "Aunque resultaba difícil de creer, los orcos -antaño considerados la raza más agresiva jamás vista en Azeroth- habían perdido por completo las ganas de luchar. El extraño letargo confundía a los líderes de la Alianza y seguía haciendo mella en los orcos, que se debilitaban rápidamente." },
		[2026] = { file = "2026", len = 23.171, text = "Algunos especulaban con que alguna extraña enfermedad, contraíble sólo por los orcos, provocaba el desconcertante letargo. Pero el Archimago Antonidas de Dalaran planteó una hipótesis diferente. Investigando lo poco que pudo encontrar de la historia orca, Antonidas se enteró de que los orcos habían estado bajo la influencia paralizante del poder demoníaco durante generaciones." },
		[2027] = { file = "2027", len = 16.457, text = "Especuló que los orcos habían sido corrompidos por estos poderes incluso antes de su primera invasión de Azeroth. Evidentemente, los demonios habían corrompido la sangre de los orcos y, a su vez, habían dotado a los brutos de una fuerza, resistencia y agresividad antinaturales." },
		[2028] = { file = "2028", len = 13.401, text = "Antonidas teorizó que el letargo comunal de los orcos no era en realidad una enfermedad, sino una consecuencia de la abstinencia racial de las volátiles magias hechiceras que los habían convertido en temibles guerreros sanguinarios." },
		[2029] = { file = "2029", len = 23.092, text = "Aunque los síntomas eran claros, Antonidas fue incapaz de encontrar una cura para el estado actual de los orcos. Además, muchos de sus compañeros magos, así como algunos líderes notables de la Alianza, argumentaron que encontrar una cura para los orcos sería una empresa imprudente. Antonidas llegó a la conclusión de que la cura para los orcos tendría que ser espiritual." },
		[2030] = { file = "2030", len = 40.385, text = "El guardián jefe de los campos de internamiento, Aedelas Lodonegro, vigilaba a los orcos cautivos desde su prisión-fortaleza Durnholde. Un orco en particular había llamado siempre su atención: el niño huérfano que había encontrado aproximadamente hacía dieciocho años. Lodonegro se ocupó de que el joven, aunque esclavo, tuviera un trato de favor y lo llamó Thrall. Lodonegro enseñó a los orcos táctica, filosofía y técnicas de combate. Incluso, Thrall fue entrenado como gladiador. Durante todo el tiempo, el guardián corrupto trató de moldear al orco, convirtiéndolo en un arma." },
		[2031] = { file = "2031", len = 33.855, text = "A pesar de su dura educación, el joven Thrall se convirtió en un orco fuerte y listo, y sabía de corazón que la vida de esclavo no era para él. A medida que maduraba, aprendió sobre su pueblo, los orcos, a los que nunca había conocido: tras su derrota, la mayoría de ellos habían sido internados en campos. Se rumoreaba que Doomhammer, el líder orco, había escapado de Lordaeron y se había escondido. Sólo un clan de pícaros seguía operando en secreto, tratando de eludir los ojos vigilantes de la Alianza." },
		[2032] = { file = "2032", len = 25.495, text = "El ingenioso pero inexperto Thrall decidió escapar de la fortaleza de Blackmoore y partió en busca de otros de su especie. Durante sus viajes, Thrall visitó los campos de internamiento y descubrió que su antaño poderosa raza estaba extrañamente acobardada y aletargada. Al no encontrar a los orgullosos guerreros que esperaba descubrir, Thrall partió en busca del último jefe orco invicto, Grom Hellscream." },
		[2033] = { file = "2033", len = 30.119, text = "Constantemente perseguido por los humanos, Hellscream se aferró sin embargo a la insaciable voluntad de lucha de la Horda. Con la única ayuda de su devoto clan Warsong, Hellscream continuó librando una guerra clandestina contra la opresión de su asediado pueblo. Por desgracia, Hellscream nunca pudo encontrar la forma de despertar a los orcos capturados de su estupor. El impresionable Thrall, inspirado por el idealismo de Hellscream, desarrolló una fuerte empatía por la Horda y sus tradiciones guerreras." },
		[2034] = { file = "2034", len = 24.816, text = "En busca de la verdad sobre sus propios orígenes, Thrall viajó al norte para encontrar al legendario clan de los Lobos de Hielo. Thrall se enteró de que Gul'dan había exiliado a los Loboescarcha durante los primeros días de la Primera Guerra. También descubrió que era el hijo y heredero del héroe orco Durotan, el verdadero jefe de los Lobos de Hielo que había sido asesinado en las tierras salvajes casi veinte años antes." },
		[2035] = { file = "2035", len = 29.022, text = "Bajo la tutela del venerable chamán Drek'Thar, Thrall estudió la antigua cultura chamánica de su pueblo, que había sido olvidada bajo el malvado dominio de Gul'dan. Con el tiempo, Thrall se convirtió en un poderoso chamán y ocupó el lugar que le correspondía como jefe de los exiliados Lobos de Hielo. Empoderado por los propios elementos e impulsado a encontrar su destino, Thrall partió para liberar a los clanes cautivos y curar a su raza de la corrupción demoníaca." },
		[2036] = { file = "2036", len = 24.555, text = "Durante sus viajes, Thrall encontró al anciano caudillo Orgrim Doomhammer, que llevaba muchos años viviendo como ermitaño. Doomhammer, que había sido amigo íntimo del padre de Thrall, decidió seguir al joven orco visionario y ayudarle a liberar a los clanes cautivos. Apoyado por muchos de los jefes veteranos, Thrall consiguió finalmente revitalizar la Horda y dotar a su pueblo de una nueva identidad espiritual." },
		[2037] = { file = "2037", len = 19.043, text = "Para simbolizar el renacimiento de su pueblo, Thrall regresó a la fortaleza de Blackmoore en Durnholde y puso fin de forma decisiva a los planes de su antiguo amo asediando los campos de internamiento. Esta victoria no fue gratuita: durante la liberación de uno de los campos, Doomhammer cayó en combate." },
		[2038] = { file = "2038", len = 28.5, text = "Thrall empuñó el legendario martillo de guerra de Doomhammer y se enfundó su armadura de placas negras para convertirse en el nuevo jefe de la Horda. Durante los meses siguientes, la pequeña pero volátil Horda de Thrall arrasó los campos de internamiento y frustró los esfuerzos de la Alianza por contrarrestar sus inteligentes estrategias. Alentado por su mejor amigo y mentor, Grom Hellscream, Thrall trabajó para asegurarse de que su pueblo nunca volviera a ser esclavo." },
		[2039] = { file = "2039", len = 24.869, text = "Mientras Thrall liberaba a sus hermanos en Lordaeron, Ner'zhul continuaba incrementando su base de poder en Rasganorte. Se erigió una gran ciudadela por encima del glaciar Corona de Hielo y fue ocupada por las crecientes legiones de muertos. Aun cuando el rey Exánime extendía su influencia sobre la tierra, un misterioso imperio resistió su poder." },
		[2040] = { file = "2040", len = 23.484, text = "El antiguo reino subterráneo de Azjol-Nerub, que había sido fundado por una raza de siniestras arañas humanoides, envió a su guardia de élite para atacar Corona de Hielo y terminar con el loco apetito de dominio del rey Exánime. Para su frustración, Ner'zhul comprobó que los malvados nerubianos resultaban inmunes no solo a la peste, sino también a su dominio mediante la telepatía." },
		[2041] = { file = "2041", len = 36.859, text = "Los señores araña nerubianos dirigían grandes ejércitos y tenían una red subterránea que abarcaba prácticamente la mitad de Rasganorte. Sus tácticas, que consistían en golpear y escapar de las fortalezas del rey Exánime, frustraron sus esfuerzos por acabar con ellos una y otra vez. Finalmente, Ner'zhul ganó la guerra contra los nerubianos mediante una estrategia de desgaste. Con la ayuda de los siniestros Señores del Terror y de innumerables guerreros no-muertos, el rey Exánime invadió Azjol-Nerub y tomó sus templos subterráneos, aplastando las cabezas de los señores araña." },
		[2042] = { file = "2042", len = 20.637, text = "Aunque los nerubianos eran inmunes a su peste, los crecientes poderes necrománticos de Ner'zhul le permitieron resucitar los cadáveres de los guerreros araña, logrando que siguieran su voluntad. Como testamento de su tenacidad y valor, Ner'zhul adoptó el estilo arquitectónico distintivo de los nerubianos en sus propias fortalezas y estructuras." },
		[2043] = { file = "2043", len = 16.562, text = "Pudiendo gobernar su reino sin oposición, el rey Exánime empezó a prepararse para llevar a cabo su verdadera misión en el mundo. Intentando alcanzar las tierras humanas con su vasta conciencia, el rey Exánime convocó a todas las almas oscuras que pudieron escucharle..." },
		[2044] = { file = "2044", len = 30.328, text = "Había un puñado de individuos poderosos esparcidos por el mundo, que oyeron las peticiones mentales del rey Exánime desde Rasganorte. El más destacable de estos personajes era el archimago de Dalaran, Kel'Thuzad, que era uno de los miembros principales del consejo de gobierno de Dalaran, el Kirin Tor. Durante años, había sido considerado un inconformista, debido a su insistencia en estudiar las prohibidas artes de la necromancia." },
		[2045] = { file = "2045", len = 34.612, text = "Decidido a aprender todo lo que pudiera del mundo mágico y de sus oscuras maravillas, se vio frustrado por lo que consideró una serie de preceptos pasados de moda y carentes de imaginación de sus pares. Tras oír las poderosas invocaciones procedentes de Rasganorte, el archimago concentró toda su voluntad, intentando comunicarse con la misteriosa voz. Convencido de que el Kirin Tor era demasiado impresionable como para adoptar el poder y el conocimiento inherente a las artes oscuras, se resignó a aprender todo cuanto podía del inmensamente poderoso rey Exánime." },
		[2046] = { file = "2046", len = 23.458, text = "Olvidando su fortuna y su prestigio político, Kel’Thuzad abandonó los caminos del Kirin Tor, dejando Dalaran para siempre. Empujado por la persistente voz del rey Exánime que oía en su mente, vendió sus vastas posesiones y guardó su fortuna. Atravesando a solas muchas leguas tanto por tierra como por mar, finalmente alcanzó las heladas costas de Rasganorte." },
		[2047] = { file = "2047", len = 23.118, text = "Intentando llegar a Corona de Hielo para ofrecer sus servicios al rey Exánime, el archimago atravesó las saqueadas y destruidas ruinas de Azjol-Nerub. Kel'Thuzad comprobó de primera mano el alcance y la ferocidad del poder de Ner'zhul. Empezó a darse cuenta de que aliarse con el misterioso rey Exánime podía ser al mismo tiempo una decisión sabia y potencialmente fructífera." },
		[2048] = { file = "2048", len = 19.226, text = "Tras arduos meses recorriendo las duras y baldías tierras árticas, finalmente Kel'Thuzad llegó al oscuro glaciar de Corona de Hielo. Con audacia, se acercó a la ciudadela negra de Ner'zhul y quedó muy impresionado cuando los guardias no-muertos le dejaron pasar silenciosamente, como si estuvieran esperándole." },
		[2049] = { file = "2049", len = 14.785, text = "Kel'Thuzad descendió a las profundidades de la tierra helada y se dirigió hacia la base del glaciar. Allí, en la interminable caverna de hielo y sombras, se postró ante el Trono Helado y ofreció su alma al oscuro señor de los muertos." },
		[2050] = { file = "2050", len = 23.014, text = "El rey Exánime estaba muy complacido con su más reciente adepto. Prometió a Kel'Thuzad la inmortalidad y grandes poderes a cambio de su lealtad y obediencia. Hambriento de conocimientos y poderes oscuros, Kel'Thuzad aceptó su primera gran misión: adentrarse en el mundo de los hombres y fundar una nueva religión que adoraría al rey Exánime como a un dios." },
		[2051] = { file = "2051", len = 30.224, text = "Para ayudar al archimago a cumplir su misión, Ner'zhul dejó intacta la humanidad de Kel'Thuzad. El viejo, pero aún carismático mago, recibió el don de utilizar sus poderes de ilusión y persuasión para adormecer a las oprimidas masas de Lordaeron y lograr que confiaran y creyeran de nuevo. Luego, una vez que lograra captar su atención, les ofrecería una nueva visión de lo que podría ser la sociedad - y un nuevo mascarón de proa al que pudieran considerar rey." },
		[2052] = { file = "2052", len = 21.995, text = "Kel'Thuzad regresó a Lordaeron disfrazado y, por espacio de tres años, utilizó su fortuna y su intelecto para reunir a una hermandad clandestina de hombres y mujeres de ideas afines. La hermandad, a la que denominó el Culto de los Malditos, prometió a sus acólitos igualdad social y la vida eterna en Azeroth a cambio de su servicio y obediencia a Ner'zhul." },
		[2053] = { file = "2053", len = 31.06, text = "A medida que pasaron los meses, Kel'Thuzad encontró muchos voluntarios ansiosos para su nuevo culto entre los cansados y explotados trabajadores de Lordaeron. Kel'Thuzad alcanzó sus objetivos con sorprendente facilidad: concretamente, logró convertir la fe de los ciudadanos en la Luz Sagrada en una creencia en la oscura sombra de Ner'zhul. A medida que el Culto de los Malditos creció en tamaño e influencia, Kel'Thuzad se aseguró de que sus actividades quedaran ocultas a ojos de las autoridades de Lordaeron." },
		[2054] = { file = "2054", len = 21.316, text = "Gracias al éxito de Kel'Thuzad en Lordaeron, el rey Exánime realizó los preparativos finales para asaltar la civilización humana. Tras volcar su energía corrupta sobre diversos artefactos portátiles llamados calderas de la peste, Ner'zhul ordenó a Kel'Thuzad que llevara las calderas a Lordaeron, ocultándolas en varios poblados leales." },
		[2055] = { file = "2055", len = 9.77, text = "Las calderas, protegidas por fieles seguidores, actuarían como generadores de peste, dispersándola a través de los indefensos campos y ciudades del norte de Lordaeron." },
		[2056] = { file = "2056", len = 15.255, text = "El plan del rey Exánime funcionó a la perfección. Muchos poblados del norte de Lordaeron se contaminaron casi de inmediato. Como ocurrió en Rasganorte, los ciudadanos que contrajeron la peste murieron y renacieron como esclavos del rey Exánime." },
		[2057] = { file = "2057", len = 26.697, text = "Los seguidores de Kel'Thuzad deseaban morir para renacer al servicio del señor de las tinieblas. Se regocijaban ante la perspectiva de alcanzar la inmortalidad de los no-muertos. Con la propagación de la peste, cada vez más zombis ferales se alzaron en las tierras del norte. Kel'Thuzad observó el ejército del rey Exánime y lo nombró la Plaga, pues pronto marcharía hasta las puertas de Lordaeron... borrando a la humanidad de la faz de la tierra." },
		[2064] = { file = "2064", len = 26.044, text = "Tras largos meses de preparación, Kel'Thuzad y su Culto de los Malditos finalmente dieron el primer golpe, lanzando la peste de los no-muertos sobre Lordaeron. Uther y sus compañeros paladines investigaron las regiones infectadas con la esperanza de encontrar un medio de detener la peste. A pesar de sus esfuerzos, la peste continuó extendiéndose, amenazando con destrozar la Alianza." },
		[2065] = { file = "2065", len = 34.586, text = "Cuando las filas de no-muertos marcharon sobre Lordaeron, el único hijo de Terenas, el príncipe Arthas, asumió la dirección de la lucha contra la Plaga. Arthas logró acabar con Kel'Thuzad, pero, incluso así, los ejércitos de no-muertos aumentaron con cada uno de los soldados que caía defendiendo la tierra. Frustrado y descorazonado por enfrentarse a un enemigo aparentemente imposible de detener, Arthas tomó una serie de medidas extremas para conquistarlos. Finalmente, los compañeros de Arthas le advirtieron que estaba perdiendo su propia humanidad." },
		[2066] = { file = "2066", len = 22.178, text = "El miedo y la resolución de Arthas resultaron ser su perdición. Siguió el rastro del origen de la peste hasta Rasganorte, intentado acabar con esta amenaza para siempre. En su lugar, el príncipe Arthas sucumbió ante el tremendo poder del rey Exánime. Creyendo que esto salvaría a su gente, tomó la espada rúnica maldita, Pica de Escarcha." },
		[2067] = { file = "2067", len = 23.458, text = "Aunque la espada le concedió un poder inefable, también robó su alma y lo transformó en el más grande de los caballeros de la muerte del rey Exánime. Con su alma apartada de sí y perdida su cordura, Arthas dirigió a la Plaga contra su propio reino. Finalmente, Arthas mató a su propio padre, el rey Terenas, y aplastó Lordaeron bajo la bota de hierro del rey Exánime." },
		[2068] = { file = "2068", len = 27.507, text = "Aunque había derrotado a todos los que ahora consideraba sus enemigos, Arthas seguía atormentado por el fantasma de Kel'Thuzad. El fantasma le dijo a Arthas que debía revivirlo para la siguiente fase del plan del Rey Exánime. Para revivirlo, Arthas debía llevar los restos de Kel'Thuzad al místico Pozo del Sol, oculto en el reino eterno de los altos elfos de Quel'Thalas." },
		[2069] = { file = "2069", len = 28.5, text = "Arthas y su Azote invadieron Quel'Thalas y asediaron las desmoronadas defensas de los elfos. Sylvanas Windrunner, la guardabosques general de Silvermoon, opuso una valerosa resistencia, pero Arthas acabó erradicando el ejército de los altos elfos y luchó hasta el Pozo del Sol. En un gesto cruel de su dominio, incluso alzó el cuerpo derrotado de Sylvanas como una banshee, maldita a una muerte sin fin al servicio del conquistador de Quel'Thalas." },
		[2070] = { file = "2070", len = 22.073, text = "Finalmente, Arthas sumergió los restos de Kel'Thuzad en las aguas sagradas del Pozo del Sol. Aunque las potentes aguas de la Eternidad se ensuciaron con este acto, Kel'Thuzad renació como un liche hechicero. Resucitado como un ser mucho más poderoso, Kel'Thuzad explicó la siguiente fase del plan del Rey Exánime." },
		[2071] = { file = "2071", len = 14.733, text = "Para cuando Arthas y su ejército de muertos volvieron hacia el sur, no quedaba ni un solo elfo vivo en Quel'Thalas. La gloriosa patria de los altos elfos, que había permanecido en pie durante más de nueve mil años, ya no existía." },
		[2072] = { file = "2072", len = 33.071, text = "Una vez que Kel'Thuzad volvió a estar completa, Arthas condujo al Azote hacia el sur, a Dalaran. Allí, el liche obtendría el poderoso libro de hechizos de Medivh y lo utilizaría para invocar a Archimonde de vuelta al mundo. A partir de ese momento, el propio Archimonde iniciaría la invasión final de la Legión. Ni siquiera los magos del Kirin Tor pudieron impedir que las fuerzas de Arthas robaran el libro de Medivh, y pronto Kel'Thuzad tuvo todo lo que necesitaba para realizar su hechizo." },
		[2073] = { file = "2073", len = 22.544, text = "Después de diez mil años, el poderoso demonio Archimonde y su hueste emergieron una vez más sobre el mundo de Azeroth. Sin embargo, Dalaran no era su destino final. Bajo las órdenes del mismísimo Kil'jaeden, Archimonde y sus demonios siguieron al Azote no muerto hasta Kalimdor, empeñados en destruir Nordrassil, el Árbol del Mundo." },
		[2074] = { file = "2074", len = 21.864, text = "En medio de este caos, apareció un profeta solitario y misterioso para orientar a las razas mortales. Este profeta no era otro que Medivh, el último Guardián, que regresó milagrosamente del Más Allá para redimirse de sus pecados pasados. Medivh habló a la Horda y a la Alianza de los peligros a los que se enfrentaban y les instó a unirse." },
		[2075] = { file = "2075", len = 21.891, text = "Los orcos y los humanos, hastiados por generaciones de odio, no lo permitieron. Medivh se vio obligado a tratar con cada raza por separado, utilizando la profecía y el engaño para guiarlos a través del mar hasta la legendaria tierra de Kalimdor. Los orcos y los humanos pronto se encontraron con la civilización de los kaldorei, oculta durante mucho tiempo." },
		[2076] = { file = "2076", len = 27.507, text = "Los orcos, liderados por Thrall, sufrieron una serie de reveses en su viaje a través de los Yermos de Kalimdor. Aunque entablaron amistad con Cairne Pezuña de Sangre y sus poderosos guerreros tauren, muchos orcos empezaron a sucumbir a la sed de sangre demoníaca que los había atormentado durante años. El mejor lugarteniente de Thrall, Grom Grito Infernal, incluso traicionó a la Horda entregándose a sus bajos instintos." },
		[2077] = { file = "2077", len = 26.096, text = "Mientras Hellscream y sus leales guerreros Warsong acechaban por los bosques de Ashenvale, se enfrentaron a los antiguos centinelas elfos de la noche. Seguro de que los orcos habían vuelto a sus costumbres guerreras, el semidiós Cenarius se presentó para hacer retroceder a Hellscream y sus orcos. Sin embargo, Hellscream y sus orcos, invadidos por un odio y una rabia sobrenaturales, consiguieron matar a Cenarius y corromper los antiguos bosques." },
		[2078] = { file = "2078", len = 14.42, text = "Al final, Hellscream redimió su honor ayudando a Thrall a derrotar a Mannoroth, el señor demoníaco que maldijo por primera vez a los orcos con su línea de sangre de odio y rabia. Con la muerte de Mannoroth, la maldición de los orcos llegó a su fin." },
		[2079] = { file = "2079", len = 30.798, text = "Mientras Medivh se esforzaba por convencer a orcos y humanos de la necesidad de una alianza, los elfos de la noche luchaban contra la Legión a su manera. Tyrande Whisperwind, la Suma Sacerdotisa inmortal de los Centinelas de los elfos de la noche, luchaba desesperadamente para evitar que los demonios y los muertos vivientes invadieran los bosques de Ashenvale. Tyrande se dio cuenta de que necesitaba ayuda, así que se dispuso a despertar a los druidas elfos de la noche de su sueño milenario." },
		[2080] = { file = "2080", len = 14.263, text = "Invocando a su antiguo amor, Malfurion Furia de Tormentas, Tyrande consiguió galvanizar sus defensas y hacer retroceder a la Legión. Con la ayuda de Malfurion, la propia naturaleza se alzó para derrotar a la Legión y a sus aliados del Azote." },
		[2081] = { file = "2081", len = 19.853, text = "Mientras buscaba a más druidas hibernantes, Malfurion encontró la antigua prisión del túmulo en la que había encadenado a su hermano Illidan. Convencida de que Illidan les ayudaría contra la Legión, Tyrande lo liberó. Aunque Illidan les ayudó durante un tiempo, acabó huyendo en pos de sus propios intereses." },
		[2082] = { file = "2082", len = 23.536, text = "Los elfos de la noche se prepararon y lucharon contra la Legión Ardiente con firme determinación. La Legión nunca había cesado en su deseo del Pozo de la Eternidad, durante mucho tiempo la fuente de fuerza del Árbol del Mundo y a su vez el corazón del reino de los elfos de la noche. Si su asalto planeado contra el Árbol tenía éxito, los demonios destrozarían literalmente el mundo." },
		[2083] = { file = "2083", len = 20.976, text = "Durante la invasión de Ashenvale por parte de la Legión, Illidan fue liberado de su prisión tras diez mil años de cautiverio. Aunque intentó apaciguar a sus camaradas, pronto volvió a su verdadera forma y consumió las energías de un poderoso artefacto brujo conocido como el Cráneo de Gul'dan." },
		[2084] = { file = "2084", len = 16.823, text = "Al hacerlo, Illidan desarrolló rasgos demoníacos y un poder enormemente magnificado. También adquirió algunos de los viejos recuerdos de Gul'dan, especialmente los de la Tumba de Sargeras, la mazmorra isleña donde se rumorea que se encuentran los restos del Titán Oscuro Sargeras." },
		[2085] = { file = "2085", len = 21.812, text = "Erizado de poder y libre para recorrer el mundo una vez más, Illidan se dispuso a encontrar su propio lugar en el gran esquema de las cosas. Sin embargo, Kil'jaeden se enfrentó a Illidan y le hizo una oferta que no pudo rechazar. Kil'jaeden estaba furioso por la derrota de Archimonde en el monte Hyjal, pero sus preocupaciones iban más allá de la venganza." },
		[2086] = { file = "2086", len = 21.708, text = "Sintiendo que su creación, el Rey Exánime, se estaba volviendo demasiado poderoso para controlarlo, Kil'jaeden ordenó a Illidan que destruyera a Ner'zhul y acabara con el Azote no muerto de una vez por todas. A cambio, Illidan recibiría un poder incalculable y un verdadero lugar entre los señores restantes de la Legión Ardiente." },
		[2087] = { file = "2087", len = 23.954, text = "Illidan accedió e inmediatamente se dispuso a destruir el Trono Helado, el gélido tonel de cristal en el que residía el espíritu del Rey Exánime. Illidan sabía que necesitaría un poderoso artefacto para destruir el Trono Helado. Utilizando los conocimientos que había obtenido de los recuerdos de Gul'dan, Illidan decidió buscar la Tumba de Sargeras y reclamar los restos del Titán Oscuro." },
		[2088] = { file = "2088", len = 16.17, text = "Recurrió a algunas viejas deudas de Highborne y atrajo a la naga serpentina de sus oscuras guaridas submarinas. Liderados por la astuta bruja Lady Vashj, los naga ayudaron a Illidan a llegar a las Islas Quebradas, donde se rumoreaba que se encontraba la Tumba de Sargeras." },
		[2089] = { file = "2089", len = 24.869, text = "Cuando Illidan partió con la naga, el alcaide Maiev Shadowsong empezó a darle caza. Maiev había sido la carcelera de Illidan durante diez mil años y ansiaba volver a capturarlo. Sin embargo, Illidan fue más listo que Maiev y sus Vigilantes y consiguió hacerse con el Ojo de Sargeras a pesar de sus esfuerzos. Con el poderoso Ojo en su poder, Illidan viajó a la antigua ciudad-mago de Dalaran." },
		[2090] = { file = "2090", len = 25.704, text = "Fortalecido por las líneas ley de la ciudad, Illidan utilizó el Ojo para lanzar un hechizo destructor contra la ciudadela de Corona de Hielo del Rey Exánime, en la lejana Rasganorte. El ataque de Illidan destrozó las defensas del Rey Exánime y rompió el techo del mundo. En el último momento, el hechizo destructor de Illidan fue detenido cuando su hermano Malfurion y la sacerdotisa Tyrande llegaron para ayudar a Maiev." },
		[2091] = { file = "2091", len = 17.763, text = "Sabiendo que Kil'jaeden no estaría contento con su fracaso en destruir el Trono Helado, Illidan huyó a la dimensión yerma conocida como Outland: los últimos restos de Draenor, el antiguo mundo natal de los orcos. Allí planeó evadir la ira de Kil'jaeden y planear sus próximos movimientos." },
		[2092] = { file = "2092", len = 16.144, text = "Tras conseguir detener a Illidan, Malfurion y Tyrande regresaron a su hogar en el Bosque de Ashenvale para velar por su pueblo. Maiev, sin embargo, no se rendiría tan fácilmente, y siguió a Illidan hasta Outland, decidida a llevarlo ante la justicia." },
		[2093] = { file = "2093", len = 25.13, text = "En ese tiempo, la Plaga de los no-muertos había convertido Lordaeron y Quel'Thalas en las tóxicas Tierras de la Peste. Hubo muy pocas bolsas de resistencia de la Alianza que le hicieran frente. Uno de estos grupos, que constaba fundamentalmente de elfos nobles, estaba dirigido por el último miembro de la dinastía Caminante del Sol: el príncipe Kael'thas." },
		[2094] = { file = "2094", len = 20.611, text = "Kael, un mago consumado, empezó a recelar de la Alianza en decadencia. Los altos elfos lloraron la pérdida de su patria y decidieron llamarse elfos de sangre en honor a su pueblo caído. Sin embargo, mientras trabajaban para mantener a raya al Azote, sufrieron mucho al verse separados del Pozo del Sol que les había dado poder." },
		[2095] = { file = "2095", len = 22.962, text = "Desesperado por encontrar una cura para la adicción racial de su pueblo a la magia, Kael hizo lo impensable: abrazó la ascendencia Highborne de su pueblo y se unió a Illidan y su naga con la esperanza de encontrar una nueva fuente de poder mágico de la que alimentarse. Los restantes comandantes de la Alianza condenaron a los elfos de sangre como traidores y los expulsaron para siempre." },
		[2096] = { file = "2096", len = 26.149, text = "Sin ningún lugar al que ir, Kael y sus elfos de sangre siguieron a Lady Vashj hasta Outland para ayudar a enfrentarse a la guardiana, Maiev, que había vuelto a capturar a Illidan. Con las fuerzas combinadas de nagas y elfos de sangre, consiguieron derrotar a Maiev y liberar a Illidan de sus garras. Con base en Outland, Illidan reunió a sus fuerzas para un segundo ataque contra el Rey Exánime y su fortaleza de Icecrown." },
		[2097] = { file = "2097", len = 31.53, text = "Ner'zhul, el rey Exánime, sabía que le quedaba poco tiempo. Prisionero en el Trono de Hielo, sospechaba que Kil'jaeden enviaría a sus agentes para destruirlo. El daño causado por el encantamiento de Illidan había roto el Trono de Hielo. De esa manera, el rey Exánime perdía su poder diariamente. Desesperado por salvarse, trajo a su lado a su mayor sirviente mortal: el caballero muerto, el príncipe Arthas." },
		[2098] = { file = "2098", len = 27.585, text = "Aunque sus poderes fueron consumidos por la debilidad del rey Exánime, Arthas participó en una guerra civil en Lordaeron. La mitad de las fuerzas de no-muertos aún en pie, conducidos por el alma en pena Sylvanas Brisaveloz, dieron un golpe de mano para controlar el imperio de los no-muertos. Arthas, llamado por el rey Exánime, fue obligado a abandonar la Plaga en manos de su lugarteniente, Kel'Thuzad, cuando la guerra se extendió por las Tierras de la Peste." },
		[2099] = { file = "2099", len = 19.017, text = "Finalmente, Sylvanas y sus no-muertos rebeldes (conocidos como los Renegados) reclamaron la propiedad de la destruida ciudad capital de Lordaeron. Tras construir su propio bastión bajo la ciudad en ruinas, los Renegados juraron derrotar a la Plaga y expulsar a Kel'Thuzad y a sus esbirros de aquellas tierras." },
		[2100] = { file = "2100", len = 18.051, text = "Debilitado, pero decidido a salvar a su maestro, Arthas llegó a Rasganorte para descubrir que los nagas y los elfos de sangre de Illidan estaban esperándole. Él y sus aliados nerubianos lucharon contra las fuerzas de Illidan para alcanzar el glaciar de Corona de Hielo y defender el Trono de Hielo." },
		[2101] = { file = "2101", len = 19.043, text = "A pesar de lo debilitado que estaba, Arthas acabó superando a Illidan y llegó primero al Trono Helado. Con su espada rúnica, Frostmourne, Arthas destrozó la prisión helada del Rey Exánime y liberó el yelmo y la coraza encantados de Ner'zhul." },
		[2102] = { file = "2102", len = 25.6, text = "Arthas se colocó el inimaginablemente poderoso yelmo en la cabeza y se convirtió en el nuevo Rey Exánime. Los espíritus de Ner'zhul y Arthas se fusionaron en un único y poderoso ser, tal y como Ner'zhul siempre había planeado. Illidan y sus tropas se vieron obligados a huir de vuelta a Outland en desgracia, mientras Arthas se convertía en una de las entidades más poderosas que el mundo había conocido jamás." },
		[2103] = { file = "2103", len = 22.544, text = "Actualmente Arthas, el nuevo e inmortal Rey Exánime, reside en Rasganorte; se rumorea que está reconstruyendo la ciudadela de Corona de Hielo. Su lugarteniente de confianza, Kel'Thuzad, comanda el Azote en las Tierras Plagadas. Sylvanas y sus Forsaken rebeldes sólo controlan los Claros de Tirisfal, una pequeña porción del reino devastado por la guerra." },
		[2104] = { file = "2104", len = 36.702, text = "Aunque la victoria fue suya, las razas mortales se encontraron en un mundo destrozado por la guerra. El Azote y la Legión Ardiente prácticamente habían destruido las civilizaciones de Lordaeron, y casi habían terminado el trabajo en Kalimdor. Había bosques que sanar, rencores que enterrar y tierras que colonizar. La guerra había herido profundamente a todas las razas, pero se habían unido desinteresadamente para intentar un nuevo comienzo, empezando por la incómoda tregua entre la Alianza y la Horda." },
		[2105] = { file = "2105", len = 16.405, text = "Thrall condujo a los orcos al continente de Kalimdor, donde fundaron una nueva patria con la ayuda de sus hermanos tauren. Llamaron a su nueva tierra Durotar, en honor al padre asesinado de Thrall, y los orcos se establecieron para reconstruir su antaño gloriosa sociedad." },
		[2106] = { file = "2106", len = 20.741, text = "Ahora que la maldición demoníaca había terminado, la Horda dejó de ser un monstruo guerrero para convertirse en una coalición flexible, dedicada a la supervivencia y la prosperidad más que a la conquista. Ayudados por los nobles tauren y los astutos trolls de la tribu Darkspear, Thrall y sus orcos esperaban una nueva era de paz en su propia tierra." },
		[2107] = { file = "2107", len = 28.604, text = "Las fuerzas restantes de la Alianza, bajo el mando de Jaina Proudmoore, se asentaron en el sur de Kalimdor. Frente a la costa oriental del Pantano de Dustwallow, construyeron la escarpada ciudad portuaria de Theramore. Allí, los humanos y sus aliados enanos trabajaron para sobrevivir en una tierra que siempre les sería hostil. Aunque los defensores de Durotar y Theramore mantuvieron una tímida tregua entre ellos, la frágil serenidad colonial no estaba destinada a durar." },
		[2108] = { file = "2108", len = 24.268, text = "La paz entre orcos y humanos se hizo añicos con la llegada de una enorme flota de la Alianza a Kalimdor. La poderosa flota, al mando del Gran Almirante Daelin Proudmoore (padre de Jaina), había abandonado Lordaeron antes de que Arthas destruyera el reino. Tras haber navegado durante muchos meses agotadores, el almirante Proudmoore buscaba a cualquier superviviente de la Alianza que pudiera encontrar." },
		[2109] = { file = "2109", len = 16.875, text = "La armada de Proudmoore suponía una seria amenaza para la estabilidad de la región. Como héroe de renombre de la Segunda Guerra, el padre de Jaina era un enemigo acérrimo de la Horda, y estaba decidido a destruir Durotar antes de que los orcos pudieran afianzarse en la tierra." },
		[2110] = { file = "2110", len = 23.719, text = "El Gran Almirante obligó a Jaina a tomar una terrible decisión: apoyarle en la batalla contra los orcos y traicionar a sus recién descubiertos aliados, o luchar contra su propio padre para mantener la frágil paz que la Alianza y la Horda habían alcanzado por fin. Tras un largo examen de conciencia, Jaina optó por lo segundo y ayudó a Thrall a derrotar a su enloquecido padre." },
		[2111] = { file = "2111", len = 17.006, text = "Por desgracia, el almirante Proudmoore murió en combate antes de que Jaina pudiera reconciliarse con él o demostrar que los orcos ya no eran monstruos sedientos de sangre. Por su lealtad, los orcos permitieron que las fuerzas de Jaina regresaran sanas y salvas a Theramore." },
		[2131] = { file = "2131", len = 30.798, text = "Throm-Ka, $c. No te adularé por tus hazañas, tu fortaleza o tu valor. Ya son historia. ¿Has matado a algún humano últimamente? Apuesto a que no han sido muchos. Te estás haciendo viejo. Necesito otro par de manos y me da igual si me das coba: necesitas la instrucción que solo yo puedo darte. Cuando eso te entre en la mollera, te estaré esperando bajo el dosel que está en el exterior del Cubil. Frang, entrenador de guerreros" },
		[2151] = { file = "2151", len = 11.755, text = "Arellas Hoja de Fuego Alto Mago de la Cruzada Escarlata Ciudadano de Quel'Thalas Enfrentado en combate eterno con el Nigromante Diesalven" },
		[2152] = { file = "2152", len = 12.199, text = "Almirante Barean Westwind Gran Almirante de la Flota Escarlata Ciudadano de Kul'Tiras Perdido en la Costa Helada de Rasganorte" },
		[2153] = { file = "2153", len = 10.449, text = "Dorgar Stoenbrow Guerrero de la Cruzada Escarlata Señor de las Cavernas Rojas Visto por última vez en las Montañas de Alterac" },
		[2171] = { file = "2171", len = 9.848, text = "Fellari Swiftarrow Capitán Ranger de la Cruzada Escarlata Ciudadano de Quel'Thalas Perdido en los bosques de Silverpine" },
		[2172] = { file = "2172", len = 8.986, text = "Ferren Marcus Alto Abad del Monasterio Escarlata Ciudadano de Stratholme Muerto defendiendo el Monasterio Escarlata en el primer asalto estival" },
		[2173] = { file = "2173", len = 12.434, text = "Harthal Truesight Lord Paladín de la Cruzada Escarlata Ciudadano de Azeroth - Caballero de la Mano de Plata Visto por última vez entrando en la ciudad maldita de Stratholme" },
		[2174] = { file = "2174", len = 8.725, text = "Holia Escudo Solar Defensora de la Cruzada Escarlata Muerta al matar al Señor del Terror Beltheris" },
		[2175] = { file = "2175", len = 11.05, text = "Invar Brazo Único Primer Asesino en Jefe de la Cruzada Escarlata Ciudadano de Dalaran Visto por última vez en las costas de Rasganorte" },
		[2176] = { file = "2176", len = 9.117, text = "Orman de Stromgarde El primer Capitán General de la Cruzada Escarlata Ciudadano de Stromgarde Perdido en la desembocadura del glaciar Icecrown" },
		[2177] = { file = "2177", len = 11.102, text = "Valea Twinblades Guerrera de la Cruzada Escarlata Ciudadana de Alterac Vista por última vez en las profundidades de Plaguelands Oriental" },
		[2178] = { file = "2178", len = 9.9, text = "Yana Bloodspear Segunda Asesina en Jefe de la Cruzada Escarlata Ciudadana de Dalaran Perdida en los Claros de Tirisfal" },
		[2191] = { file = "2191", len = 26.201, text = "Hace aproximadamente unos 16.000 años, antes de que los elfos de la noche provocaran imprudentemente la ira de la Legión Ardiente, los trols se enseñoreaban sobre la mayor parte de Kalimdor (entonces, un solo continente). Había dos imperios trol, el imperio Gurubashi de las junglas del sudeste y el imperio Amani de las tierras boscosas del interior." },
		[2192] = { file = "2192", len = 14.785, text = "Había tribus más pequeñas que vivían muy al norte (en la región que ahora se conoce como Rasganorte). Estas tribus fundaron una pequeña nación conocida como Gundrak, pero nunca alcanzaron el tamaño ni la prosperidad de los imperios del sur." },
		[2193] = { file = "2193", len = 28.264, text = "Los imperios Gurubashi y Amani se querían poco, pero rara vez guerreaban entre sí. En aquella época, su mayor enemigo común era un tercer imperio: la civilización de Azj'Aqir. Los aqir eran insectoides inteligentes que gobernaban las tierras del lejano oeste. Estos inteligentes insectoides eran muy expansionistas e increíblemente malvados. Los aqir estaban obsesionados con erradicar toda vida no insectoide de los campos de Kalimdor." },
		[2194] = { file = "2194", len = 19.566, text = "Los trolls lucharon contra ellos durante miles de años, pero nunca consiguieron una verdadera victoria sobre los aqir. Finalmente, debido a la persistencia de los trolls, el reino aqiri se dividió en dos, ya que sus ciudadanos huyeron a colonias separadas en las regiones más septentrionales y meridionales del continente." },
		[2195] = { file = "2195", len = 14.602, text = "Surgieron dos ciudades-estado aqiri: Azjol-Nerub, en los páramos del norte, y Ahn'Qiraj, en el desierto del sur. Aunque los gnomos sospechaban que había otras colonias aqiri bajo Kalimdor, nunca se comprobó su existencia." },
		[2196] = { file = "2196", len = 23.797, text = "Tras el exilio de los insectoides, los dos imperios trolls volvieron a la normalidad. A pesar de su gran victoria, ninguna de las dos civilizaciones se expandió mucho más allá de sus fronteras originales. Sin embargo, los textos antiguos hablan de una pequeña facción de trols que se separó del Imperio Amani y fundó su propia colonia en el corazón del continente oscuro." },
		[2197] = { file = "2197", len = 16.17, text = "Allí, estos valientes pioneros descubrieron el Pozo cósmico de la Eternidad, que los transformó en seres de inmenso poder. Algunas leyendas sugieren que estos trolls aventureros fueron los primeros elfos nocturnos, aunque esta teoría nunca se ha demostrado." },
		[2198] = { file = "2198", len = 36.624, text = "Aparte de sus oscuros orígenes, está claro que los elfos de la noche llegaron al poder poco después de descubrir el Pozo de la Eternidad. A pesar de los intentos de los trols por impedir que expandieran sus territorios, los elfos de la noche construyeron un poderoso imperio que se expandió rápidamente por el Kalimdor primordial. Blandiendo feroces magias nunca antes imaginadas por los supersticiosos trols, los elfos de la noche no tuvieron demasiados problemas para hacer lo que el malvado aqir nunca pudo: derrocar a los dos mayores imperios del mundo." },
		[2199] = { file = "2199", len = 25.469, text = "Los elfos de la noche desmantelaron sistemáticamente las defensas y las cadenas de suministro de los trolls. Los trolls, incapaces de contrarrestar la magia destructiva de los elfos, sucumbieron ante el ataque. Los elfos nocturnos demostraron ser tan astutos y sanguinarios como los salvajes trolls, lo que les granjeó su odio y desprecio eternos. Los imperios Gurubashi y Amani se fragmentaron en pocos años." },
		[2200] = { file = "2200", len = 25.992, text = "Finalmente, los elfos de la noche fueron abrasados por los fuegos arcanos que habían intentado controlar. Su imprudente uso de la magia atrajo al mundo a la demoníaca Legión Ardiente. Los demonios aplastaron gran parte de la civilización de los elfos de la noche. Aunque no hay registros que indiquen que la Legión atacara a ninguna de las civilizaciones troll, es probable que se produjeran batallas a lo largo y ancho del continente." },
		[2201] = { file = "2201", len = 18.077, text = "Al final de este terrible conflicto, conocido como la Guerra de los Antiguos, el Pozo de la Eternidad implosionó. La onda expansiva resultante destrozó la gran masa continental de Kalimdor. El centro del continente se hundió bajo el mar, dejando sólo un pequeño grupo de continentes rotos." },
		[2202] = { file = "2202", len = 31.19, text = "Así, grandes partes de los Imperios Amani y Gurubashi siguen existiendo en las actuales tierras de Quel'Thalas y Stranglethorn (respectivamente). Los reinos Azj'Aqir de Azjol-Nerub y Ahn'Qiraj también han sobrevivido en las actuales Rasganorte y Tanaris (respectivamente). Ambas civilizaciones trol retrocedieron ante la vasta destrucción del mundo primordial que habían conocido. Los valientes trols reconstruyeron sus devastadas ciudades y se dispusieron a recuperar parte de su antiguo poder." },
		[2203] = { file = "2203", len = 29.022, text = "Los largos siglos que siguieron a la Gran Separación del mundo fueron difíciles para la raza troll. El hambre y el terror eran moneda corriente en los reinos destruidos. Los trols de Gurubashi, desesperados, buscaron ayuda en fuerzas místicas ancestrales. Aunque ambos reinos trol compartían una creencia central en un gran panteón de dioses primitivos, los Gurubashi cayeron bajo el dominio del más oscuro." },
		[2204] = { file = "2204", len = 22.857, text = "Hakkar el Mataalmas, un espíritu vil y sanguinario, escuchó la llamada de los gnomos y decidió ayudarles. Hakkar entregó sus secretos de sangre a los Gurubashi y les ayudó a extender su civilización por la mayor parte del Valle de Stranglethorn y algunas islas de los Mares del Sur. Aunque les aportó un gran poder, Hakkar quería más y más por sus esfuerzos." },
		[2205] = { file = "2205", len = 23.38, text = "El dios sanguinario exigía que se le sacrificaran almas a diario. Soñaba con acceder al mundo físico para poder devorar la sangre de todas las criaturas mortales. Con el tiempo, los Gurubashi se dieron cuenta de la clase de criatura que habían cortejado y se volvieron contra él. Las tribus más fuertes se alzaron contra Hakkar y sus leales sacerdotes, los Atal'ai." },
		[2206] = { file = "2206", len = 21.838, text = "De la terrible guerra que siguió entre los seguidores de Hakkar y el resto de las tribus Gurubashi sólo se habla en susurros. El imperio en ciernes quedó destrozado por la magia desatada entre el dios enfurecido y sus hijos rebeldes. Justo cuando la batalla parecía más desesperada, los trolls consiguieron destruir el avatar de Hakkar y desterrarlo del mundo." },
		[2207] = { file = "2207", len = 18.416, text = "Incluso sus sacerdotes Atal'ai fueron finalmente expulsados de la capital de Zul'Gurub y obligados a sobrevivir en las inexploradas tierras pantanosas del norte. En esos pantanos tenebrosos construyeron un gran templo a su dios caído, Atal'Hakkar, donde podían seguir haciendo el trabajo de su maestro..." },
		[2208] = { file = "2208", len = 29.048, text = "El resto de las tribus Gurubashi tomaron caminos separados después de que la gran guerra civil dejara sus tierras en ruinas. Las tribus Skullsplitter, Bloodscalp y Darkspear partieron para reclamar sus propias tierras dentro de las vastas junglas de Stranglethorn. Aunque una frágil paz se había asentado sobre el imperio roto, algunos hablaban de una profecía según la cual Hakkar renacería un día en el mundo... y ese día... lo consumiría entero." },
		[2211] = { file = "2211", len = 30.511, text = "Aquí yace Grommash Hellscream, Jefe del Clan Warsong. En muchos sentidos, la maldición de nuestro pueblo empezó y terminó con Grom. Su nombre significaba \"corazón de gigante\" en nuestra antigua lengua. Se ganó ese nombre cien veces cuando se enfrentó solo al demonio Mannoroth - y ganó nuestra libertad con su sangre. Lok'Tar ogar, hermano mayor. Que el Warsong nunca se desvanezca. -Thrall, Jefe de la Horda" },
		[2212] = { file = "2212", len = 34.011, text = "¡Oh, estoy maldito! Una vez fui un gran mago ogro del clan Spirestone, desafié a Urok Doomhowl y él me robó mi magia y me maldijo. ¡Ahora, debo caminar por los pasillos de Hordemar como esta criatura miserable! Aidme! ¡Enfréntate a Urok y róbame mi magia! No será fácil, porque Urok permanece en las sombras y sólo puede ser invocado a través de un gran desafío. Ese desafío será la muerte de su más fiel ayudante, el Highlord Omokk. Read on, and you will see." },
		[2213] = { file = "2213", len = 23.014, text = "El Señor Supremo Omokk gobierna los Spirestones, pero lo hace a través de la magia de Urok. Urok encantó a Omokk con un hechizo que puede dar muerte a cualquier ogro que le desafíe. Ha usado ese hechizo muchas veces, y guarda los cráneos de sus víctimas en una pila, en un lugar de poder sobre la cámara de Omokk. Ahí es donde debes ir para enfrentarte a Urok." },
		[2214] = { file = "2214", len = 19.879, text = "Encuentra una pica áspera entre los campamentos de Scarshield. Suelen apilarlas junto a sus colchonetas cerca de la entrada a los dominios del ogro de Spirestone. Cuando tengas la pica, dirígete a la carga hacia el Señor Supremo Omokk. Mátalo y coloca su cabeza en la pica. Entonces estarás listo para el verdadero desafío." },
		[2215] = { file = "2215", len = 29.257, text = "Ve al lugar de poder sobre el dominio de Spirestone, más allá de los túneles de Skitterweb. En ese lugar se apilan los cráneos de los enemigos y rivales de Urok. Es aquí donde debes clavar la pica con la cabeza de Omokk! Cuando la cabeza esté en su sitio, Urok vendrá seguro... pero antes enviará a sus esbirros contra ti. Derrótalos, y con el tiempo el mismo Urok será invocado. Mata a Urok y recupera mi magia. Con mis poderes devueltos, te recompensaré." },
		[2216] = { file = "2216", len = 23.197, text = "Que tengas suerte. Y aquí tienes una pista que puede ayudarte en tus pruebas contra los esbirros de Urok: El hechizo que Omokk usa contra los ogros, el que los fulmina, puede seguir teniendo poder después de que mates a Omokk. Durante tu lucha contra los esbirros de Urok, invoca el poder en la cabeza de Omokk... ¡con suerte, Omokk derribará a los esbirros de Urok! Una ironía muy apropiada." },
		[2217] = { file = "2217", len = 4.362, text = "En memoria de Jesse Morales" },
		[2232] = { file = "2232", len = 14.472, text = "Agasham, ¡Nuestros planes deben mantenerse en secreto a toda costa! Será un desastre si las otras tribus tauren descubren nuestra afiliación. Firmado, Harbinger Elm" },
		[2233] = { file = "2233", len = 20.715, text = "Agasham, ¡Trabajando juntos, nuestras fuerzas serán más poderosas que todas las tribus tauren juntas! Sin embargo, requerimos su total obediencia. ¡Recuerden, su gente será recompensada sólo después de que nuestros planes lleguen a buen puerto! Firmado, Harbinger Rex" },
		[2234] = { file = "2234", len = 15.412, text = "Agasham, Nuestros agentes de Lordaeron se reunirán con sus delegados, pronto. Le notificaremos una vez que hayamos encontrado un lugar apropiado para nuestra cumbre. Firmado, Harbinger Grakus" },
		[2251] = { file = "2251", len = 16.562, text = "Atacantes... de todos lados. CPuedo verlo en sus ojos. Los Timbermaw son malvados. Enemigo. Debo proteger tribu. Debemos proteger Winterfall. Debemos expulsar a los intrusos de nuestra tierra." },
		[2271] = { file = "2271", len = 33.149, text = "Nataka, todo va bien en Mil Agujas. La molestia de los centauros no es más que eso... ataques ocasionales, nada sustancial como amenaza real. Sin embargo, parece que hay noticias de clanes de centauros unidos. Siempre hemos ponderado la amenaza de una raza despiadada unida como la de los centauros... Intento no pensar en esas ideas, como sabes... nada podría penetrar el odio puro que sienten... incluso entre ellos. -Cliffwatcher Longhorn" },
		[2291] = { file = "2291", len = 31.19, text = "Arzobispo Alonsus Faol Benevolente patrón de la Iglesia de la Luz. Aunque inició su excelente trabajo en Stratholme, Lordaeron, el arzobispo Faol fue un gran amigo del pueblo de Ventormenta. En los peores momentos tras la Segunda Guerra, ayudó a reformar la Hermandad de Villanorte y consiguió muchos fondos para reconstruir la propia ciudad de Ventormenta. Esta catedral no solo se alza como bastión de la Luz Sagrada, sino como testamento duradero del noble espíritu y la generosidad de un hombre." },
		[2292] = { file = "2292", len = 8.986, text = "Rey Llane I de la Casa de Wrynn Señor Feudal de Ventormenta Defensor de Azeroth" },
		[2293] = { file = "2293", len = 7.654, text = "Comandante de las flotas de la Alianza Amigo de Ventormenta" },
		[2294] = { file = "2294", len = 12.513, text = "Lady Mara Fordragón Alta Cleriga de Stormwind Patrona de los Refugiados que huyeron a Lordaeron tras la Primera Guerra. Fue la madre brillante de nuestro futuro. Que descanse en la Luz." },
		[2295] = { file = "2295", len = 19.122, text = "Antes de la Edad de la Memoria, la gentil Madre Tierra respiraba sobre las doradas brumas del amanecer. Donde las nubes de ámbar se posaban, había interminables campos de trigo y cebada. Esta era la cuenca de sus obras: la gran cesta de la vida y la esperanza." },
		[2296] = { file = "2296", len = 27.873, text = "Los ojos de la Madre Tierra brillaban sobre las tierras que ella había creado. Su ojo derecho, An'she (el sol), daba calor y luz a la tierra. Su ojo izquierdo, Mu'sha (la luna), daba paz y sueño a las agitadas criaturas del amanecer. Tal era el poder de su mirada que la Madre Tierra cerraba un ojo soñador por cada giro del cielo. Así, su mirada amorosa convirtió el día en noche para el primer amanecer del mundo." },
		[2297] = { file = "2297", len = 29.806, text = "Mientras el ojo derecho brillaba sobre el dorado amanecer, las suaves manos de la Madre Tierra se extendían por las doradas llanuras. Por donde pasaba la sombra de sus brazos, un noble pueblo surgía de la rica tierra. Los Shu'halo (los tauren) se levantaron para dar gracias y rezar a su amada madre. Allí, en los interminables campos del amanecer, los hijos de la tierra se juraron a sí mismos a su gracia y juraron bendecir su nombre hasta el oscurecimiento final del mundo." },
		[2298] = { file = "2298", len = 27.376, text = "Cuando los hijos de la tierra vagaban por los campos del alba, escuchaban oscuros susurros procedentes de las profundidades del mundo. Los susurros les hablaban de las artes de la guerra y el engaño. Muchos de los Shu'halo cayeron bajo el dominio de las sombras y abrazaron los caminos de la malicia y la maldad. Se volvieron contra sus hermanos puros y dejaron su inocencia a la deriva en las llanuras." },
		[2299] = { file = "2299", len = 25.548, text = "La Madre Tierra, con el corazón encogido por la difícil situación de sus hijos, no podía soportar verlos caer en desgracia. En su dolor, se arrancó los ojos y los puso a girar por los cielos infinitos y estrellados. An'she y Mu'sha, tratando de aliviar el dolor de la otra, sólo pudieron perseguirse mutuamente con su débil brillo por el cielo. Las gemelas siguen persiguiéndose con cada giro del mundo." },
		[2300] = { file = "2300", len = 17.815, text = "Aunque sin vista, la Madre Tierra no podía alejarse mucho tiempo del mundo de su corazón. Mantenía el oído atento a los vientos y escuchaba todo lo que ocurría en los campos del amanecer. Su gran corazón siempre estaba con sus hijos, y su amorosa sabiduría nunca se alejaba de ellos." },
		[2301] = { file = "2301", len = 26.331, text = "En los valientes corazones de sus hijos puros, la Madre Tierra depositó el amor a la caza. Porque las criaturas del primer amanecer eran salvajes y feroces. Se escondían de la Madre Tierra, encontrando consuelo en las sombras y en los lugares salvajes de la tierra. Los Shu'halo cazaban a estas bestias allí donde se encontraban y las domesticaban con la bendición de la Madre Tierra." },
		[2302] = { file = "2302", len = 25.313, text = "Sin embargo, un gran espíritu los eludió. Apa'ro (conocido como Malorne por los elfos de la noche), era un orgulloso ciervo de pelaje blanco como la nieve. Su cornamenta raspaba el techo de los cielos y sus poderosas pezuñas surcaban las profundidades del mundo. Los Shu'halo persiguieron a Apa'ro hasta los rincones del mundo naciente y se acercaron para atrapar al orgulloso ciervo." },
		[2303] = { file = "2303", len = 26.932, text = "Tratando de escapar, el gran ciervo saltó al cielo. Sin embargo, cuando su huida parecía asegurada, su poderosa cornamenta se enredó en las estrellas que lo sujetaban. Aunque pataleó y luchó, Apa'ro no pudo soltarse de los cielos. Fue entonces cuando Mu'sha lo encontró mientras perseguía a su hermano, An'she, hacia el amanecer. Mu'sha vio al poderoso ciervo mientras luchaba y se enamoró de él de inmediato." },
		[2304] = { file = "2304", len = 25.104, text = "La astuta luna hizo un trato con el gran ciervo: lo liberaría de la trampa de las estrellas si él la amaba y ponía fin a su soledad. Mu'sha amó a Apa'ro y concibió un hijo suyo. El niño, un semidiós según algunos, nació en los sombríos bosques de la noche. Se llamaría Cenarius y caminaría por la senda estrellada entre el mundo de la vigilia y el reino de los cielos." },
		[2305] = { file = "2305", len = 24.189, text = "Con el tiempo, el niño Cenario alcanzó la estatura de su orgulloso padre. Hermano de los árboles y las estrellas, el gran $c vagó por las cuatro esquinas del mundo, entonando bellas canciones de la aurora. Todas las criaturas saludaban su gracia y su belleza: no había nadie tan bello como el hijo de la luna y el ciervo blanco." },
		[2306] = { file = "2306", len = 14.602, text = "Con el tiempo, Cenarius se hizo amigo de los Shu'halo y les habló del mundo cambiante. Los hijos de la tierra le conocieron como hermano y juraron ayudarle a cuidar de los campos de vida y de las criaturas predilectas de su gran Madre Tierra." },
		[2307] = { file = "2307", len = 19.435, text = "Cenarius enseñó a los hijos de la tierra a hablar con los árboles y las plantas. Los Shu'halo se convirtieron en druidas y realizaron grandes hazañas mágicas para devolver la salud a la tierra. Durante muchas generaciones, los Shu'halo cazaron con Cenarius y mantuvieron el mundo a salvo de las sombras que se agitaban bajo él." },
		[2308] = { file = "2308", len = 32.392, text = "Cuando las brumas del amanecer se desvanecieron y avanzó la Era de la Memoria, el semidiós Cenarius siguió su propio camino por los campos del mundo. Los Shu'halo (tauren) se entristecieron con su muerte y olvidaron gran parte del druidismo que les había enseñado. Con el paso de las generaciones, olvidaron cómo hablar con los árboles y las cosas salvajes de la tierra. Los oscuros susurros de las profundidades del mundo llegaron a sus oídos una vez más." },
		[2309] = { file = "2309", len = 25.574, text = "Aunque los hijos de la tierra cerraron el paso a los susurros malignos, una terrible maldición cayó sobre sus tribus errantes. De las negras tierras del oeste llegó una horda de criaturas asesinas: los centauros. Caníbales y devastadores, los centauros cayeron sobre los Shu'halo como una plaga. Aunque los valientes y cazadores lucharon con la bendición de la Madre Tierra en sus corazones, el centauro no pudo ser derrotado." },
		[2310] = { file = "2310", len = 17.894, text = "Los Shu'halo se vieron obligados a abandonar sus tierras ancestrales y a vagar por las interminables llanuras como nómadas para siempre. Se creía que un día volvería la esperanza y las tribus dispersas de los Shu'halo encontrarían un nuevo hogar bajo los amorosos brazos de la Madre Tierra." },
		[2311] = { file = "2311", len = 18.808, text = "Este esqueleto de pteradon intacto fue descubierto en el remoto cráter de Un’Goro. Basándonos en la estructura del esqueleto, resulta evidente que aún no se ha determinado su género. Este esqueleto quizás se conservó durante varios siglos bajo el rico suelo de la región." },
		[2371] = { file = "2371", len = 25.6, text = "Los Anales de Darrowshire Darrowshire, llamado así por el lago Darrowmere que se encuentra al oeste, es un pueblo enclavado en las estribaciones meridionales de Lordaeron. Conocido por sus habitantes humildes pero trabajadores, Darrowshire permaneció en un segundo plano de la historia de Lordaeron hasta la Segunda Guerra. Durante esa guerra se hicieron héroes. Y se perdieron héroes." },
		[2372] = { file = "2372", len = 24.999, text = "La Batalla de Darrowshire La Batalla de Darrowshire tuvo lugar en plena Segunda Guerra, cuando las fuerzas del Azote arrasaban Lordaeron. Darrowshire quedó aislada del grueso de las fuerzas de la Alianza, pero la ciudad fue reforzada por una compañía de tropas, un contingente de paladines de la Mano de Plata y un grupo incondicional de milicianos locales dirigidos por el capitán Joseph Redpath." },
		[2373] = { file = "2373", len = 29.048, text = "Los primeros asaltos del Azote a Darrowshire fueron escasos. Pequeños grupos de esqueletos y cadáveres merodeaban por las afueras de la aldea y fueron repelidos. Pero el Azote no se amilanó ante la tenacidad de los defensores y respondió de la misma manera; poco después de la primera oleada de ataques surgió una segunda. Los ghouls campeones, siervos del señor ghoul Horgus, bajaron gritando de las colinas y se enfrentaron a los asediados defensores de Darrowshire." },
		[2374] = { file = "2374", len = 31.19, text = "Los Defensores se debilitaron, pero fueron relevados por paladines, discípulos de la Mano de Plata. Su líder, Davil Crokford, era natural de Darrowshire. Trajo a sus seguidores a la aldea cuando se enteró del inminente ataque, y junto con los defensores contuvieron a los siervos de Horgus. Cuando el propio Horgus entró en la batalla, se encontró con Davil. Durante muchos minutos lucharon y Davil acabó imponiéndose, pero sufrió una herida mortal y murió poco después de derrotar al señor de los necrófagos." },
		[2375] = { file = "2375", len = 23.04, text = "La batalla continuó, y el Capitán Redpath lideró a su milicia con valentía. Y podría haber ganado, si el capitán no hubiera sido corrompido por el caballero de la muerte Marduk el Negro. En medio de la refriega, Marduk cabalgó hasta Sendero Rojo, y con magia negra desgarró el espíritu de Sendero Rojo, convirtiéndolo en una sombra maligna del valiente capitán." },
		[2376] = { file = "2376", len = 28.839, text = "El corrupto Capitán Redpath extendió entonces su maligna mancha entre los defensores de Darrowshire, que traicionaron a sus aliados y los masacraron. A continuación, se volvieron contra el pueblo de Darrowshire y mataron a todos los que se escondieron en sus casas. El ejército del azote restante, junto con el espíritu corrupto del Capitán Redpath, abandonó entonces el devastado pueblo de Darrowshire y arrasó Lordaeron, sumándose al dolor y la muerte de la Segunda Guerra." },
		[2377] = { file = "2377", len = 27.455, text = "Los Anales de Darrowshire Darrowshire, llamado así por el lago Darrowmere que se encuentra al oeste, es un pueblo escondido en las estribaciones meridionales de Lordaeron. Conocido por sus habitantes humildes pero trabajadores, Darrowshire permaneció en un segundo plano de la historia de Lordaeron hasta la Segunda Guerra. Durante esa guerra se forjaron héroes. Y se perdieron héroes." },
		[2378] = { file = "2378", len = 24.294, text = "La batalla de Darrowshire La Batalla de Darrowshire tuvo lugar en plena Segunda Guerra, cuando las fuerzas del Azote arrasaron Lordaeron. Darrowshire quedó aislada del grueso de las fuerzas de la Alianza, pero la ciudad fue reforzada por una compañía de tropas, un contingente de paladines de la Mano de Plata y un grupo incondicional de milicianos locales dirigidos por el capitán Joseph Redpath." },
		[2379] = { file = "2379", len = 27.82, text = "Los primeros asaltos del Azote a Darrowshire fueron escasos. Pequeños grupos de esqueletos y cadáveres merodeaban por las afueras del pueblo y fueron derrotados con facilidad. Pero el Azote percibió la tenacidad de los defensores y respondió de la misma manera; poco después de la primera oleada de ataques surgió una segunda. Los ghouls campeones, siervos del señor ghoul Horgus, bajaron gritando de las colinas y se enfrentaron a los asediados defensores de Darrowshire." },
		[2380] = { file = "2380", len = 32.235, text = "Los Defensores se debilitaron, pero fueron relevados por paladines, discípulos de la Mano de Plata. Su líder, Davil Crokford, era natural de Darrowshire. Trajo a sus seguidores a la aldea cuando se enteró del inminente ataque, y junto con los defensores contuvieron a los siervos de Horgus. Cuando Horgus entró en la batalla, se encontró con Davil. Durante muchos minutos lucharon y Davil acabó imponiéndose, pero sufrió una herida mortal y murió poco después de derrotar al señor de los necrófagos." },
		[2381] = { file = "2381", len = 22.622, text = "La batalla continuó, y el Capitán Redpath lideró a su milicia valientemente. Y se podría haber ganado, si el capitán no hubiera sido corrompido por el caballero de la muerte Marduk el Negro. En medio de la refriega, Marduk cabalgó hasta Redpath y, con magia negra, desgarró el espíritu de Redpath, convirtiéndolo en una sombra maligna del valiente capitán." },
		[2382] = { file = "2382", len = 27.272, text = "El corrupto capitán Redpath propagó su maldad entre los defensores de Darrowshire, que traicionaron a sus aliados y los masacraron. Luego se volvieron contra la ciudad de Darrowshire y mataron a todos los que se escondieron en sus casas. El ejército azote restante, junto con el espíritu corrupto del Capitán Sendero Rojo, abandonó entonces el devastado pueblo de Darrowshire y arrasó Lordaeron, sumándose al dolor y la muerte de la Segunda Guerra." },
		[2383] = { file = "2383", len = 30.093, text = "El destino de Horgus el asolador Horgus el Asolador cayó en la Batalla de Darrowshire. Pero el mal que llevaba dentro no se había consumido del todo. Las fuerzas victoriosas del Azote se llevaron su cráneo del campo de batalla de Darrowshire para sembrar el terror entre los vivos a los que se enfrentaban. Días después, la compañía de Azote que poseía la cabeza fue derrotada por los Paladines de la Mano de Plata. La cabeza de Horgus fue arrojada al Lago Blackwood." },
		[2384] = { file = "2384", len = 32.078, text = "El destino de Marduk el Negro Marduk sobrevivió a la Segunda Guerra, causando grandes muertes y sufrimientos con su asquerosa espada cargada de runas. Aunque Marduk aún vive, su espada se perdió en una batalla cerca del Cruce de Corin. Un capitán enano hizo añicos la espada en su escudo encantado, obligando a Marduk a huir del campo de batalla y ganando el día para la Alianza. La espada de Marduk se hundió en la tierra y la corrompió, comiéndose un desfiladero en la tierra, ahora conocido como la Cicatriz Infectis." },
		[2385] = { file = "2385", len = 23.928, text = "El destino de Davil Lightforge Davil Lightforge murió en la batalla de Darrowshire, pero su valentía inspiró a la Alianza durante toda la guerra. Su libro, su libram de paladín, fue recuperado por las tropas de la Cruzada Escarlata. Ahora reside en el ayuntamiento de Hearthglen, controlado por la Cruzada Escarlata, y a menudo lo leen los cruzados deseosos de aprovechar la fuerza de Davil." },
		[2386] = { file = "2386", len = 31.556, text = "El destino de Joseph Redpath Joseph Redpath fue asesinado durante la Batalla de Darrowshire. Su espíritu se corrompió y adoptó una nueva forma, y esta criatura propagó un gran mal en Lordaeron. En el Marchitamiento de Gahrron, al este de Andorhal, el Corrompido Sendero Rojo fue finalmente derrotado por las fuerzas de la Alianza. Su escudo aún descansa cerca del granero de la granja plagada, y los esbirros del Azote aún se sienten atraídos por el recuerdo de su maldad." },
		[2391] = { file = "2391", len = 33.202, text = "El destino de Carlin Redpath Hermano del capitán Joseph Redpath, Carlin cayó durante la batalla de Darrowshire. Pero aunque terriblemente herido, no fue asesinado. Días después de la batalla, agentes del Amanecer Argentino encontraron a Carlin vagando, débil por la sed y la fiebre, cerca del Cruce de Corin. Atendieron sus heridas y lo llevaron a la Capilla de la Esperanza de la Luz. Agradecido por su caridad, Carlin se unió a las filas del Amanecer Argentino y ahora lucha en una batalla de venganza contra el Azote." },
		[2411] = { file = "2411", len = 14.289, text = "OoOoOO OOoOOoo OOOoO OOoOO OOoOOoO OOooooO Oooooo OooOOOO OOoOOO OOoOOoo OOoOOoo OOoOOO OOoOOo OOooOoO Oooooo Oooo Oooo Oooo Oooo Oooooo Oooooo Oooo Oooo Oooo Oooo OoooO OOoOOoo OOoOOoo OOooOO OOOOO Oooooo OoooOO OOoOOo OOoOooO OOooOOO OOoOooo OOOoOO OOOoOO Oooooo OOoOOOO OOooo Oooooo Oooooo Oooooo Oooo Oooo Oooo Oooo Oooo Oooo Oooo Oooo Oooo Oooo Oooo Oooo Oooooo Oooo Oooo Oooo Oooo Oooo" },
		[2413] = { file = "2413", len = 7.366, text = "Nieve, cegadora... Debo proteger a la tribu. Hacerlos fuertes. Ser fuertes. No saber..." },
		[2414] = { file = "2414", len = 13.218, text = "Más aguardiente. Más aguardiente. El aguardiente hace fuerte a Winterfall. Derrotar a nuestros enemigos. Winterfall no tiene aliados. Winterfall son fuertes. Tener gran poder." },
		[2415] = { file = "2415", len = 5.303, text = "Más. Debe tener más... Winterfall... no... débil..." },
		[2431] = { file = "2431", len = 25.469, text = "Fecha de entrada: Desconocido Nombre: Nathanos Marris, Guardabosques Humano Señor de Lordaeron. Entrada: Se toma nota de la discrepancia de Kael'thas Sunstrider respecto a mi decisión de permitir a Nathanos Marris entrar en la orden. También hay que señalar que Nathanos -aunque humano- es uno de los guardabosques más dotados que he tenido el placer de entrenar. (continúa)" },
		[2432] = { file = "2432", len = 37.956, text = "Nunca he estado más orgulloso de participar en este negocio como en estos últimos años. La demanda de asesinos, espías y exploradores nunca ha sido tan acuciante. Es lógico pensar que la demanda aumenta durante la guerra, pero, sorprendentemente, la guerra no es un periodo tan próspero como este: un momento en que la paz empieza a deteriorarse. Me han dicho que vendrías por aquí para aprender algunas cosas. Cuando tengas tiempo, ven a verme en los establos situados en la parte trasera de la abadía. Jorik Kerridan, instructor de pícaros" },
		[2433] = { file = "2433", len = 31.19, text = "Apuesto a que esperabas que esta fuera una nota normal escrita por tu rey o por cualquier otra persona. Bueno, digamos que algo sé acerca de cómo forjar notas y quería asegurarme de que recibieras esta. No puedo ir llamando la atención, ¿verdad? Me he refugiado en Yunquemar, así que me encontrarás cerca de la fosa de lava. Cuando estés preparado, ven a hablar conmigo. Solo quiero presentarme ahora que tenemos tiempo. Solm Hargrin, instructor de pícaros" },
		[2434] = { file = "2434", len = 40.359, text = "Saludos, $N. Estaba absorto en mis pensamientos, cuando sentí la necesidad de escribirte. Muchos en nuestra cultura rezan a nuestros chamanes por tratarse de nuestros líderes espirituales, como nuestro gran Jefe de Guerra. Otros piensan que la espada y el hacha tienen propósitos más nobles, pero nunca olvides que las batallas, e incluso las guerras, se ganan por el empeño de aquellos que tienen habilidades más especializadas. De todo esto es de lo que me gustaría hablarte, Grakzul. Puedes encontrarme en las profundidades de El Cubil en el Valle de los Retos. Rwag, instructor de pícaros" },
		[2435] = { file = "2435", len = 25.966, text = "Hermana, espero que esta runa te encuentre bien. Quería tomarme un momento para haceros saber que estoy dentro de Anvilmar, sobre el Valle Coldridge. I sé lo importante que es que todos permanezcamos unidos, y en estos tiempos de tensa paz es aún más importante tener a los nuestros cerca. Búscame cuando tengas tiempo. -Solm Hargrin, Entrenador de Pícaros" },
		[2436] = { file = "2436", len = 32.94, text = "No tomes mis palabras a la ligera, $N. Ha llegado la hora de llevar nuestras artimañas de engaño a todas las naciones… incluso a nuestra grandiosa Entrañas. Todos los fieles de Sylvanas se esfuerzan por crear un área nueva bajo el control exclusivo de los Renegados. Incluso aunque no poseamos habilidades mágicas, nuestro papel sigue siendo igual de importante. Ven a verme a la posada de Camposanto y seguiremos hablando. -David Trias, intructor de pícaros" },
		[2437] = { file = "2437", len = 36.258, text = "Sael'ah, amigo mío. Espero que este sigilo te encuentre bien. Me pidieron que te ofreciera mis servicios. Yo también estoy en Shadowglen, en el gran árbol de Aldrassil, y quería que supieras que si necesitas algún tipo de entrenamiento puedes buscarme. En estos tiempos tan cuestionables, he creído prudente que aquellos que se dedican al sigilo permanezcan aún más cerca los unos de los otros. Si no, ¿cómo podremos proteger Teldrassil y nuestras costumbres? Encuéntrame cuando puedas. -Frahun Shadewhisper, Entrenador de Pícaros" },
		[2438] = { file = "2438", len = 33.097, text = "Saludos, $gHermano:Hermana;. La Mano Destrozada te envía saludos y espera que encuentres en el Valle un lugar cómodo para aplicar tu oficio. Esta es una época de pruebas para ti, así que no creas que no te vigilan constantemente. IEs mi deber evaluar tus habilidades ante la Mano, y luego informarles cuando considere que estás listo para pasar a retos mayores. Cuando estés listo, ven a buscarme a las profundidades de la Guarida. Allí te estaré esperando. -Rwag, Rogue Trainer" },
		[2439] = { file = "2439", len = 36.833, text = "Dime, $c, ¿has oído el grito de un orco? ¿No defendías tal vez tu casa de los gnolls mientras ellos intentaban cortarte el cuello? Sí, suena horrible, ¿verdad? Bueno, si deseas proteger a los tuyos, necesitarás mi ayuda. Me encontrarás en la abadía de Rasganorte. Mis conocimientos no son fáciles de obtener, pero si tienes suficiente experiencia, puedo instruirte, enseñándote una serie de estilos y movimientos que te ayudarán a hacer frente a las amenazas de Ventormenta y más allá. Llane Beshere, instructor de guerreros" },
		[2441] = { file = "2441", len = 23.641, text = "Seré breve, $N. Admiro tu gracia y tu astucia, y no te he quitado el ojo de encima. Pero la gracia y la astucia no siempre son suficientes para mantenerte con vida. Si quieres aprender a ser un gran pícaro, yo puedo enseñarte. Reúnete conmigo en el interior de la torre de vigilancia. - Akeri Hoja Umbría, instructor de pícaros" },
		[2442] = { file = "2442", len = 35.971, text = "Por las barbas de Magni, hay mucho que discutir y muy poco tiempo, $N. Búscame en Yunquemar, frente al Valle de Crestanevada tan pronto como puedas. Tenemos que empezar. Tengo que decirte muchas cosas sobre cómo ganar velocidad, pero nada de eso tiene que ver con nosotros... por ahora. Lo que ahora debe centrar nuestra atención es la empuñadura de un hacha, el peso de nuestra armadura y el olor de nuestro propio sudor rodando por la frente cuando nos enfrentamos al enemigo. Empezaremos por ahí. Thran Khorman, instructor de guerreros" },
		[2443] = { file = "2443", len = 32.784, text = "Muchos de los nuestros recurren a lo arcano y lo divino como medio para darse fuerza, pero nosotros lo sabemos mejor, ¿verdad, $c? Sabemos que nuestras armas son nuestros símbolos sagrados, nuestro escudo es nuestro libro de hechizos, y nuestra cota de malla es nuestra sabiduría. Incluso en la no-muerte somos fuertes, y sólo nos haremos más fuertes. Encuéntrame en la posada de Deathknell. Te hablaré más de estos asuntos y de otras cosas. -Dannal Stern, Entrenador de Guerreros" },
		[2444] = { file = "2444", len = 34.638, text = "Espero que cuando recibas este sigilo te encuentres bien, $c. Te escribo porque nuestra gente necesita esa fuerza con la espada, la guja y otras armas. Han ocurrido muchas cosas desde que nuestro pueblo volvió a enfrentarse a las otras razas de Azeroth, de manera que tenemos una necesidad aún mayor de protectores de todas las clases. Aquí es donde apareces tú. Ya te contaré, pero creo que debo hacerlo en persona. Puedes encontrarme en Aldrassil... en los niveles inferiores. Alyissia, instructor de guerreros" },
		[2445] = { file = "2445", len = 34.09, text = "La magia tiene cuatro reglas: La Magia es poderosa. La magia corrompe. La magia es adictiva. La magia acerca a los moradores del Vacío Abisal a aquellos que empuñan lo arcano. Estas reglas son siempre seguras. Si decides continuar tu camino como mago, gobernarán tu destino. Si eres tan iluso como para ignorar esta advertencia, ven nuevamente a hablar conmigo en el ala de la biblioteca de la abadía de Rasganorte. Te esperaré arriba. Khelden Bremen, instructor de magos" },
		[2446] = { file = "2446", len = 34.22, text = "Para: Nuevos Estudiantes de las Artes Arcanas: Se te pide que busques y estudies bajo la tutela del gnomo Marryk Nurribit hasta que llegue el momento en que seas llamado para ayudar a tu pueblo a restablecerse en un nuevo hábitat. Por favor, sin temor, prepárate para rigurosos procedimientos de prueba y un difícil proceso de aclimatación mientras encuentras un domicilio y/o cualquier forma de compañía con los habitantes locales. Las preguntas sobre tus deberes y habilidades deben dirigirse a Marrek Nurribit." },
		[2447] = { file = "2447", len = 31.556, text = "La corrupción y la maldad que los rumores afirman subyace en lo arcano no son nada comparado con el dolor que ya hemos experimentado. Ya no somos víctimas, $N. Somos los únicos que controlamos nuestro propio destino. Sylvanas ha preparado el camino para todos nosotros: ha demostrado que la voluntad es nuestra, que ya no somos esclavos del maldito Arthas. Búscame en la iglesia y, si lo deseas, te seguiré instruyendo... Isabella, instructora de magos" },
		[2448] = { file = "2448", len = 32.784, text = "Bienvenida al despertar, colega. Los secretos arcanos están a tu alcances si eres lo suficientemente fuerte para aferrarte a ellos. Cuando estés preparada, busca a Mai’ah. Te enseñará mucho acerca de la magia y acerca de los encantamientos que necesitas para destruir a tus enemigos. Mai'ah está cerca de El Cubil, en el Valle de los Retos. Allí la encontrarás y podrás hacerte fuerte. Podrás mostrar a otros magos cómo la magia se supedita a ti... y no tú a ella." },
		[2449] = { file = "2449", len = 37.747, text = "A menudo, algunos, como los seguidores de la Luz Sagrada, asustan a los profanos sobre lo que significa el verdadero poder, haciéndoles creer que no pueden tener acceso a ninguna de las facetas de lo arcano. Lo cierto es que no todo lo que hay en el más allá es maligno. No todas las entidades buscan dominar o subyugar a otros. Si eres bastante poderoso, estas mismas entidades pueden convertirse en tus seguidores. Esto es algo que quiero analizar más en detalle contigo. Búscame en el cementerio, a la derecha de la abadía. Drusilla La Salle, instructora de brujos" },
		[2450] = { file = "2450", len = 33.646, text = "ATENCIÓN: ¡Guarda silencio! ¡No mires a tu alrededor! Es posible que alguien te esté vigilando. Mi nombre es Alamar Grimm, $N. Entreno a aquellos que buscan el conocimiento y obtener un mayor poder de... los mundos del más allá. Me han pedido que entre en contacto contigo de forma discreta y que te haga saber que puedo instruirte más a fondo, enseñándote una variante real de la magia. Cuando puedas, búscame en la parte trasera de Yunquemar. Alamar Grimm, instructor de brujos" },
		[2451] = { file = "2451", len = 37.747, text = "Escribo este mensaje en las tintas más poderosas que puedo crear, $N. Maldeciría instantáneamente a cualquiera que se atreviera a leerlo además de a ti mismo. Soy así de poderoso. Invoco demonios de las tinieblas a mi antojo. Asedio a mis enemigos mientras duermen y en el campo de batalla. Y ahora tú también has visto el poder de mi camino. Mis hermanos están complacidos por eso. Búscame en las profundidades de la Guarida una vez que te hayas orientado. Me gustaría hablar contigo sobre asuntos importantes. -Nartok, Entrenador de Brujos" },
		[2452] = { file = "2452", len = 40.202, text = "Un terrible aprieto en el que encontrarnos, ¿no es así, $N? Plagados por el Príncipe Sucio. Condenados al ostracismo y despreciados por nuestros propios seres queridos. Por fin tenemos voluntad propia gracias a la bella Sylvanas, pero ¿qué nos proporciona eso ahora? Esclavo de un amo diferente sigue siendo un esclavo, o eso digo yo. B¿Pero y si nosotros fuéramos los amos? Sí, sabes a lo que me refiero, ¿verdad? Estamos aún más separados del resto de los Desamparados, $N. Y es por eso que debemos hablar más. Encuéntrame en la iglesia de Deathknell." },
		[2453] = { file = "2453", len = 39.68, text = "Poderosos guerreros defienden nuestro hogar. Nuestros chamanes guían a nuestros espíritus y nos muestran el pasado de nuestros antepasados. Y nuestros druidas nos ayudan a descubrir la voluntad de la Madre Tierra. BPero tú eres uno de nuestros cazadores, y nuestros cazadores aprenden muchos aspectos de esos papeles y los mezclan. Descubrirás que representas el corazón de nuestro pueblo: algunos de nuestra tribu te buscarán para que les guíes, otros para que les protejas. Es mi deber asegurarme de que estéis preparados para ello. Buscadme en el Campamento Narache. -Lanka Farshot, Entrenadora de Cazadores" },
		[2454] = { file = "2454", len = 24.372, text = "Tú estas en buenas manos, colega. Jen’shan sabe que quieres conocer los trucos del cazador y está preparada para enseñarte... si estás preparado para escuchar. Ven a buscarme en el Valle de los Retos. Jen'shan empezará a instruirte y a mostrarte lo poderosas que pueden llegar a ser las artes de la caza. Jen'shan, instructora de cazadores" },
		[2455] = { file = "2455", len = 32.914, text = "$gDomador:domadora; de bestias, $gmaestro:maestra; de la puntería, $gprobado rastreador:probada rastreadora;: ¿qué más quieres ser en esta vida? Estos dones implican inteligencia y grandes dosis de paciencia. La vida del cazador no es fácil, tenlo por seguro. Si quieres ser tan bueno como incluso el peor de nuestros tiradores, tendrás que entrenarte a conciencia. Pero esa es la razón por la que estoy aquí. Búscame en Yunquemar, frente al Valle de Crestanevada. Te estaré esperando. Thorgas Grimson, instructor de cazadores" },
		[2456] = { file = "2456", len = 40.542, text = "Elune está contigo, $N. El viento me lo ha susurrado y estoy contenta de poder tomar parte directamente en la formación de nuestra próxima generación de cazadores. Según me han dicho, estás cerca de Aldrassil. Cuando tengas tiempo, nos reuniremos en el gran árbol. Nuestros mayores me han pedido que me asegure de que nuestros nuevos cazadores reciban la instrucción necesaria para hacer frente a los retos que tienen por delante. Eres uno de los estudiantes que se ha incorporado más recientemente, de manera que es inexcusable que me visites. Hasta entonces, que te vaya bien. Ayanna Semprerguida, instructora de cazadores" },
		[2457] = { file = "2457", len = 28.996, text = "Me alegra saber que uno de los hermanos de Jen'shan vendrá al Valle para probar su habilidad. Jen'shan lo está deseando. No tengo que decirte lo fuerte y astuto cazador que eres, eso ya lo sabes. Es tarea de Jen'shan decirte cómo hacerte más fuerte y más astuto. Encuentra a Jen'shan en el Valle de las Pruebas. Ella te enseñará el bien. Te enseñará a domar a las bestias más grandes, entre otras cosas. -Jen'shan, Cazadora Entrenadora" },
		[2458] = { file = "2458", len = 35.814, text = "La pasada noche, los espíritus se manifestaron en mis sueños. Me dijeron que vendrías y que mi tarea consistiría en ayudarte. Tenemos mucho que hacer en un corto espacio de tiempo: disquisiciones sobre la naturaleza, los espíritus, la Madre Tierra e incluso los elfos de la noche. Pero guardaré las lecciones para cuando llegues y haré todo lo que esté en mi mano para asegurarme de que estés preparado para afrontar las pruebas que tienes por delante. Que la sabiduría te guíe. Te estaré esperando. Gart Correbruma, instructor de druidas" },
		[2459] = { file = "2459", len = 36.598, text = "Cuando me llegó la noticia de que estabas preparado, envié inmediatamente este sigilo. Todos los druidas de Cenarius han mostrado gran satisfacción al ver que nuestros números aumentan. Incluso, los espíritus parecen ser más fuertes, debido a nuestra presencia reforzada. Con el tiempo y con un poco de paciencia, esperemos recuperar algo de nuestro antiguo esplendor. Cuando estés preparado, búscame cerca de la cima de Aldrassil. Seré tu guía durante todo el tiempo que estés en Cañada Umbría. Mardant Cebaforte, instructor de druidas" },
		[2460] = { file = "2460", len = 32.366, text = "Te saludo, joven $c. Los vientos me hablaron de tu llegada. La tierra alabó tu fuerza. Y ahora los espíritus ancestrales susurran de tus logros por venir. Nuestro pueblo siempre necesita líderes sabios y grandes. A menudo recurren a los nuestros por ambas virtudes. Si estás dispuesta, te enseñaré más de nuestras costumbres. -Búscame en el Campamento Narache en Red Cloud Mesa... hablaremos más entonces. -Meela Dawnstrider, Entrenadora Chamán" },
		[2461] = { file = "2461", len = 30.851, text = "Lok-tar, hermano. Los elementos te han traído hasta aquí y me han encargado que te muestre el camino del chamán. Los espíritus de nuestros ancestros nos vigilan desde el más allá y están henchidos de orgullo, sabiendo que te has unido a nuestras filas. Cuando estés preparado, búscame cerca de El Cubil. Allí es donde instruyo a otros individuos de nuestra clase. Hasta entonces, que tengas vientos favorables. Shikrik, instructor de chamanes" },
		[2462] = { file = "2462", len = 31.19, text = "Saludos a ti, $ghermano:hermana;. Los espíritus dicen que estás lista para ayudar a nuestros aliados. Tienes grandes lazos con los elementos, y eres mucho más poderosa que cuando empezaste tus lecciones conmigo. Ahora te envío a reunirte con Shikrik, la entrenadora de chamanes orcos en el Valle de las Pruebas. Ella ya sabe que vas a estudiar con ella. Enorgullece a nuestros ancestros. Hasta que nos volvamos a ver, que la llama te mantenga caliente y el viento te acompañe." },
		[2463] = { file = "2463", len = 35.082, text = "Espero que cuando recibas esta carta, estés bien, $c. Digo esto con mucho orgullo, ya que muchos no profesan una fe tan profunda, pero también saben que están entre la élite de los protectores de Azeroth. Recuerda siempre, por encima de todo, que tu deber consiste en luchar contra todos aquellos que quieran dañar nuestro mundo y llevar la corrupción a nuestros hogares. He recibido autorización para ocuparme de tu instrucción. Cuando estés preparado, búscame en la Abadía de Villanorte. Hermano Sammuel, instructor de paladines" },
		[2464] = { file = "2464", len = 38.74, text = "Algunos nos temen más que a los dragones. Otros nos envidian más que a los herreros más hábiles. Otros desearían tener nuestra fuerza en la batalla. Otros se deleitan con nuestra fe. ¡Algunos nos tienen envidia porque les damos cien mil vueltas bebiendo! Pero debes saber, paladín, que estás entre la élite de los protectores de todo Azeroth. La Luz Sagrada nos da tanto poder como nosotros a ella. Cuando conozcas más estas tierras, profundizaré más sobre esto último. Búscame en Yunquemar, en lo alto del valle. Bromos Grummner, instructor de paladines" },
		[2465] = { file = "2465", len = 18.024, text = "Tu conexión con el mundo, así como la conexión del mundo contigo, resultan esenciales para tu éxito como $c para tu instrucción, búscame en el ala de la biblioteca de la Abadía de Rasganorte. $C Anetta, instructora de sacerdotes" },
		[2466] = { file = "2466", len = 35.004, text = "Al calor de Luz Sagrada y con tantos descubrimientos hechos por nuestra gente, ser hijos de Forjaz constituye todo un orgullo. La Liga de Expedicionarios progresa cotidianamente en su búsqueda de respuestas duraderas incluso a las preguntas más antiguas. Y ahora te tenemos a ti entre nuestros fieles para ayudarnos en la batalla contra los troggs o cualquier otra amenaza para nuestras fronteras. Cuando tengas tiempo, ven a buscarme. Estaré en la parte trasera de Yunquemar, justo encima de la colina. Branstock Khalder, instructor de sacerdotes" },
		[2467] = { file = "2467", len = 38.792, text = "Siéntete bendecida, ya que tu espíritu no ha sido arrojado al Abismo Abisal, $N. Incluso, siéntete más bendecida aún, ya que he decidido que tú vales la pena y escribir este pergamino tiene sentido. El pueblo que una vez conociste, incluso que quizás cuidaste, ¡ya no existe! Debes aprender a \"vivir\" con este convencimiento durante el resto de tu vida no natural. Sugiero que asumas esto cuanto antes. Si piensas que estás preparada para los retos que tienes por delante, búscame en la iglesia de Camposanto. Clérico oscuro Duesten, instructor de sacerdotes" },
		[2468] = { file = "2468", len = 37.512, text = "Espero que cuando recibas este sigilo, te encuentres bien, $N. Los espíritus me han dicho que vas a venir y te he enviado este mensaje inmediatamente. Estoy ansioso por compartir mis experiencias contigo y guiarte de tal manera que puedas prepararte para abandonar Teldrassil y realizar cometidos más importantes. Con todo lo que ha pasado en los últimos años, es mucho lo que podemos hacer para ayudar a otras razas de Azeroth. Cuando estés listo, búscame en Aldrassil, en el segundo nivel. Shanda, instructor de sacerdotes" },
		[2469] = { file = "2469", len = 26.906, text = "Espero que los espíritus te hayan protegido hasta ahora, colega. Tienes muchas pruebas por delante y, cuando estés preparada, estoy dispuesta a compartir mis experiencias contigo. Depende de ti decidir cuán $grápido y poderoso quieres ser. Solo podré guiarte cuando estés preparada. Para algunos, esto puede llevar poco tiempo, mientras que para otros, mucho más. Pero, por el momento, no te preocupes de eso. Cuando vengas a mi encuentro, hablaremos más ampliamente. Ken'jai, instructora de sacerdotes" },
		[2471] = { file = "2471", len = 26.88, text = "Durante milenios nos hemos aislado de los de fuera. Seré el primero de nosotros en admitir que se cometieron errores en el pasado. Los humanos nunca deberían haber estado expuestos a la magia. No lo negaré, pero no nos condenaré a esta existencia vigilada por los errores de nuestros predecesores. Hay mucho que una coexistencia entre los Quel'dorei y otras razas de este mundo puede aportar. Debemos practicar la tolerancia." },
		[2472] = { file = "2472", len = 14.132, text = "Es con estas palabras, entonces, que deniego la petición de Kael con respecto a Nathanos Marris. Demostrará ser un aliado inestimable. Recuerda mis palabras. Signed, Sylvanas Windrunner Ranger General de Silvermoon" },
		[2491] = { file = "2491", len = 17.058, text = "Grish- YTu petición de tiempo libre ha sido aceptada. Voy a enviar a un guerrero Tauren de reserva para que vigile tu puesto mientras te tomas un tiempo libre para estar con tu familia. ¡Vuelve en una semana! -Maggran Earthbinder" },
		[2511] = { file = "2511", len = 36.833, text = "Querido Zargh: Los filetes que enviaste están muy buenos. Tienen sus buenas vetas de grasa, son anchos y están recubiertos de grasa de jabalí. Justo como a mí me gustan. Cuando vaya a comerlos, pensaré en ti mientras me dedique a roer hasta el tuétano. Cerraré los ojos y veré tus fuertes manos llenas de cicatrices picando y cortando... ¡Ja! Esto me recuerda aquella vez que tuviste el accidente y perdiste un dedo... ¡Oh, Zargh! Pensar en aquel día hace que me ría como una niña pequeña. ¡Estás tan guapo cuando sangras! Gryshka" },
		[2512] = { file = "2512", len = 31.086, text = "Osric: A continuación, encontrarás un listado de las armaduras que necesitamos: 10 cotas de malla 20 yelmos 30 refuerzos de armadura 15 botas de malla. Como siempre, estamos en deuda contigo. Y cuando Páramos de Poniente se libre de los ladrones que lo amenazan, dejaré de sentirme culpable si puedo invitarte a comer a mi casa, con la generosidad propia de esta tierra por la que fue famosa en tiempos. Lewis El intendente, Colina del Centinela" },
		[2513] = { file = "2513", len = 34.717, text = "Nessa, Me alegra tener noticias tuyas. La colección de huesos y escamas que me enviaste era increíble. Nunca había visto peces de ese tamaño cerca del continente. ¡Los pescadores de Rut'theran deben conseguir toneladas de pescados por día sin esfuerzo! Me da envidia el tamaño de sus presas, pero también hay algo que me inquieta. ¿Qué tal si nuestro nuevo Árbol del Mundo hace que los peces crezcan hasta ese tamaño? Y en ese caso, ¿qué otros efectos podría tener? Tantas preguntas... -Laird" },
		[2514] = { file = "2514", len = 18.86, text = "A continuación, adjunto la lista de los estudiantes que han obtenido la Estrella de Platino en la Escuela de Minas y Topografía de Brock, adquiriendo un Pico de Minero Honorario: Melia Agitapiedras Bardin Vetaferro Umi Voltiflop Rumi Voltiflop Vorel Agujacero" },
		[2515] = { file = "2515", len = 28.735, text = "Por orden el Sumo Ejecutor Hadrec, he aquí un listado de los elementos necesarios para mantener las existencias de El Sepulcro: 12 espadas largas 9 dagas 8 escudos redondos 15 hachas 1000 flechas Esta orden debe considerarse como una orden directa de la Dama Oscura y los responsables serán llevados ante Su presencia, como ocurriría con cualquiera que se opusiera u obstaculizara Sus deseos." },
		[2531] = { file = "2531", len = 5.695, text = "Este documento de 3 páginas está en blanco." },
		[2551] = { file = "2551", len = 23.458, text = "Layo: Hemos recibido la generosa ayuda de este buen aventurero. Os he enviado al aventurero a Silithus como recurso. Por favor, procura que tan valioso recurso no se desperdicie en tus esfuerzos por desvelar los secretos que allí se esconden. El Círculo espera ansiosamente noticias del progreso. Que Cenarius os cuide... Rabine" },
		[2571] = { file = "2571", len = 30.903, text = "La Fiesta del Velo de Invierno Las últimas estaciones de Azeroth están marcadas como una época de cambio en muchas culturas. Los enanos y los tauren, en particular, consideran que la leyenda del Velo de Invierno -la nevada que cubre la tierra y anuncia una época de renovación- es un momento de celebración. Aunque la comprensión de las leyendas que comparten las razas de Azeroth no es distinta, las formas en que eligen reconocerlas son tan diversas como las propias razas." },
		[2572] = { file = "2572", len = 30.119, text = "La leyenda del Gran Padre Invierno Se dice que el término \"Velo de Invierno\" procede de un ser sobrenatural al que muchas culturas se refieren como el Gran Padre Invierno. Cuando recorría la tierra al final de las estaciones, el propio invierno era su ondulante manto. A su paso, la tierra se cubría de nieve, por lo que se dice que el Gran Padre Invierno arrojaba su velo invernal sobre la tierra. Aunque algunas partes de Azeroth estén nevadas, esto da a la tierra tiempo para renacer y renovarse." },
		[2573] = { file = "2573", len = 25.313, text = "Los enanos Ever consumidos por la investigación de sus orígenes, los enanos eligen celebrar la estación como un reconocimiento al mismísimo Gran Padre Invierno. Lo consideran la personificación de uno de los antiguos de Azeroth: los titanes. Por mucho que reivindiquen su linaje en un grado u otro con estos seres místicos, consideran su hogar nevado de Dun Morogh como el principal ejemplo de las bendiciones del Gran Padre Invierno." },
		[2574] = { file = "2574", len = 30.171, text = "Los tauren Los tauren y su comprensión chamánica del invierno, junto con su reciente aparición en los esfuerzos druídicos, encajan bien con la leyenda del Velo Invernal. Sin embargo, se centran casi por completo en los aspectos renovadores de la tradición, dejando el culto a la leyenda a aquellas razas (según ellos) menos en sintonía con la naturaleza de las cosas. Muchos tauren eligen esta época como el momento adecuado para dar gracias por las bendiciones de su nuevo hogar en Mulgore." },
		[2575] = { file = "2575", len = 30.015, text = "Festines La idea de los festines durante esta época del año tiene su origen en la propia leyenda. Se dice que cuando el Gran Padre Invierno caminaba por Azeroth, trayendo el invierno a su paso, ofrecía una gran recompensa a aquellos que acogían su presencia. Por ello, la idea de celebrar un banquete durante el Velo de Invierno unía a las comunidades, que compartían lo que tenían. Por lo general, el cambio se celebraba en un solo día de alegría y banquetes, como anticipo de la renovación de la tierra." },
		[2576] = { file = "2576", len = 30.798, text = "Observación moderna Otras culturas han empezado a reconocer la Fiesta del Velo de Invierno como un momento de gran celebración, aunque no en las mismas tradiciones en las que se basa la leyenda. Las costumbres, a menudo ajenas a cualquier otra cosa que no sea una oportunidad para la celebración y el intercambio de regalos, se han abierto camino en la observación moderna de la temporada. A veces se utiliza incluso la imagen del Gran Padre Invierno, pero más como presagio de explotación comercial que como titán sobrenatural." },
		[2591] = { file = "2591", len = 35.265, text = "En lo más recóndito del Valle de las Lanzas se encuentra el templo sagrado de Maraudon. Si eso no fuera suficiente transgresión, verás rápidamente por qué he pedido a un no-centauro que me ayude en mi difícil situación. Allí, justo más allá de las puertas donde sólo los espíritus y nuestros sacerdotes y sacerdotisas más sagrados pueden viajar, se encuentra uno llamado El Profeta Sin Nombre. Él es el más alto de cualquier tribu en asuntos espirituales y es uno de los más antiguos de cualquier tribu." },
		[2592] = { file = "2592", len = 18.469, text = "El Profeta es poderoso y se comunica con los espíritus de nuestros antepasados. Pero es un tonto. No tiene ni idea del verdadero poder que posee. En su persona lleva el Amuleto de los Espíritus, de donde proviene la mayor parte de su fuerza. He aprendido que el Amuleto es poderoso, pero está incompleto." },
		[2593] = { file = "2593", len = 24.607, text = "Faltan cinco gemas en el amuleto. Y si esas gemas se encontraran y se volvieran a colocar en el símbolo, su poder superaría con creces el de su forma actual. He encontrado las cinco gemas, pero necesito a alguien de tu habilidad para ayudar a reunirlas. Matar al Profeta Sin Nombre es una herejía, al igual que robar de su cadáver, pero lo que te pido a continuación condenaría a cualquier centauro por siquiera pensarlo." },
		[2595] = { file = "2595", len = 16.692, text = "Por las cavernas de Maraudon vagan los espíritus de nuestros primeros Khans. Los primeros hijos de nuestra Madre y nuestro Padre, y nuestros mayores líderes: Gelk, Kolk, Magra, Maraudos y Veng. Cada uno de estos espíritus guarda una de las gemas perdidas." },
		[2596] = { file = "2596", len = 22.413, text = "Usa el poder del Amuleto de los Espíritus para obligarlos a manifestarse y quítales las gemas. Después, coloca las gemas dentro del Amuleto de los Espíritus y devuélvemelo. ¡Una vez que tenga el Amuleto de la Unión, seré lo suficientemente poderoso como para reformar las tribus para que por fin podamos ser como nuestros antepasados querían que fuéramos!" },
		[2611] = { file = "2611", len = 12.487, text = "... y ahí es donde encontrarás la legendaria espada del Señor Escarlata, Ashbringer. ¿No es asombroso lo que te encuentras en un día ordinario de pesca?" },
		[2631] = { file = "2631", len = 31.556, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para elaborar el arcano mayor. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[2632] = { file = "2632", len = 3.448, text = "No puedes entender nada de lo escrito en estas páginas." },
		[2633] = { file = "2633", len = 32.392, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para elaborar el arcano mayor. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[2634] = { file = "2634", len = 26.253, text = "<La tinta se arremolina y se desplaza por la página. Tienes la sensación de que el libro se burla de ti." },
		[2635] = { file = "2635", len = 31.295, text = "Las páginas están cubiertas de antiguas runas élficas.\010Estas páginas contienen recuerdos de los acontecimientos que tuvieron lugar durante la recolección y creación de los reactivos necesarios para elaborar el arcano mayor. Que nuestros enemigos nunca tengan acceso a este libram. Que viva para ver la pálida luz de la luna brillar de nuevo sobre Quel'Thalas. Que muera por la gracia de Kael'thas. Que mate por la gloria de Illidan. -Maestro Kariel Winthalus" },
		[2636] = { file = "2636", len = 3.37, text = "Sientes un dolor punzante al ojear estas páginas." },
		[2637] = { file = "2637", len = 12.826, text = "Foror's Compendium of Dragon Slaying es un grueso libro lleno de escritura. Desgraciadamente, el texto parece confuso y no tiene sentido para ti." },
		[2654] = { file = "2654", len = 27.193, text = "TRATADO SOBRE LOS RANGOS MILITARES Lo que sigue son los rangos militares de la Alianza, precedido por la información tal y como la conocen las razas de la Horda. Cada rango se muestra en dos secciones: los oficiales y luego, los soldados rasos, con los rangos correspondientes a cada uno, enumerados en orden descendente, del superior al inferior. ¡Larga vida a la Alianza!" },
		[2659] = { file = "2659", len = 28.944, text = "Cuando te asomas al Ojo, las imágenes de una gran batalla llenan tu mente... Este terrorífico conflicto parece estar teniendo lugar en algún lugar de Lordaeron... Apenas puedes distinguir una solitaria figura femenina, de pie entre un millar de cadáveres, defendiéndose de un mar de Azote... La superan en número sin remedio... De sus manos escapan zarcillos de luz que atraviesan a cientos de muertos vivientes." },
		[2666] = { file = "2666", len = 9.822, text = "Al parecer, todo fue en vano. Momentos después, los cadáveres de los campesinos que la rodeaban invaden a la sacerdotisa: .... Los caídos se han levantado." },
		[2671] = { file = "2671", len = 14.393, text = "Simone, la seductora: Encontrarás a Simone ensuciando el cráter Un'Goro. No te dejes engañar por su disfraz. Acércate a ella con precaución y desafíala a luchar." },
		[2672] = { file = "2672", len = 9.456, text = "Klinfran el Enloquecido: Klinfran vaga por las Estepas Ardientes. Acércate a él con precaución y oblígale a mostrar su verdadera forma." },
		[2673] = { file = "2673", len = 13.296, text = "Solenor el Asesino: En el árido paisaje de Silithus acecha el demonio, Solenor el Asesino. Sin duda disfrazado, sin duda un peligro. Acércate a él y oblígale a transformarse." },
		[2674] = { file = "2674", len = 8.882, text = "Artorius, el Agorero: Artorius trae la corrupción y la perdición a todo lo que toca en Primavera Invernal. Encuéntralo y mátalo." },
		[2675] = { file = "2675", len = 8.986, text = "Ten cuidado, cazador, estos demonios deben ser combatidos en sus propios términos. Si sienten que no te superan, huirán. GO SOLO." },
		[2676] = { file = "2676", len = 15.621, text = "RANGOS MILITARES DE LA ALIANZA OFICIALES Gran mariscal Mariscal de campo Mariscal Comandante Teniente coronel Campeón caballero Capitán caballero Teniente caballero Caballero TROPA Alférez Sargento primero Sargento Cabo Soldado" },
		[2677] = { file = "2677", len = 15.386, text = "RANGOS MILITARES DE LA HORDA OFICIALES Gran Señor de la Guerra Señor de la Guerra Gran general General Campeón Centurión Legionario Guardia de sangre Guardia de piedra TROPA Gran capataz Capataz primero Capataz Bruto Explorador" },
		[2691] = { file = "2691", len = 32.914, text = "Para atar un dreadsteed, debes hacer estas tres cosas: Crea un Círculo de Invocación Mayor. Dentro del Círculo, abre un portal a Xoroth y atrae al dreadsteed a través de él. Derrota al dreadsteed y domina su espíritu. En las páginas siguientes se detalla cómo llevar a cabo cada uno de estos pasos. No será fácil, pero has demostrado ser muy capaz. Con concentración y habilidad, estoy seguro de que el dreadsteed será tuyo. Sigue leyendo, -Mor'zul Bloodbringer" },
		[2692] = { file = "2692", len = 25.731, text = "Instrumentos del ritual Antes de comenzar tu tarea, debes tener los siguientes implementos mágicos: Jarra de J'eevee Una piedra caliza negra Glifos Xorothianos Mi sirviente Gorzeeki los tendrá para ti, por un precio. No intentes ningún paso de tu ritual sin todos estos utensilios. Cada uno es esencial. En las próximas páginas, describiré cómo debe usarse cada implemento." },
		[2693] = { file = "2693", len = 28.735, text = "Círculo de mayor vinculación Un Círculo de Vinculación Mayor debe crearse en un lugar donde la magia sea fuerte. Existe un lugar así en las profundidades de las ruinas de Eldre'Thalas, también llamado Dire Maul. En Eldre'Thalas está encarcelado un ser de gran poder, Immol'thar; es en el pedestal de su prisión donde debes realizar el ritual para crear el Círculo. Lucha hasta llegar al Pedestal y deja salir a J'eevee de su frasco." },
		[2694] = { file = "2694", len = 31.451, text = "La campana, la rueda y la vela Después de liberar a J'eevee, colocará la Campana, la Rueda y la Vela, y aparecerá un círculo. Este es el comienzo del ritual. Debes estar atento; los objetos mencionados conducen grandes energías y son propensos a fallar. Cuando esto ocurra, deberás usar rápidamente tu Piedra Negra para reiniciarlos antes de que todo el ritual falle. Si los tres objetos fallan antes de que puedas reiniciarlos, tu ritual termina y debes empezarlo de nuevo." },
		[2695] = { file = "2695", len = 32.679, text = "Además de conducir las energías del ritual, la Campana, la Rueda y la Vela tienen propiedades únicas propias. La Campana de Dethmoora, al sonar, confiere vigor y energía a los hechiceros del círculo. La Rueda de la Marcha Negra, al girar, protege de todo mal a los participantes en el círculo. La Vela del Juicio Final, cuando arde, envía energía eldritch a los enemigos que entran en el círculo. Debido a estas bendiciones, es muy importante mantener todos estos objetos en funcionamiento durante el ritual." },
		[2696] = { file = "2696", len = 20.767, text = "También hay que tener en cuenta que la Piedra Negra, utilizada para reiniciar la Campana, la Rueda o la Vela si fallan, requiere fragmentos de alma. Cada vez que reinicies un objeto ritual con la Piedra Lodestone se consumirá una de tus esquirlas de alma, así que asegúrate de tener una gran reserva de ellas antes de que comience el ritual." },
		[2711] = { file = "2711", len = 29.466, text = "Completar el ritual Puedes seguir tu progreso mediante las runas mágicas que aparecen en el borde del círculo. Cuando aparezcan nueve runas, el ritual se habrá completado y verás cómo la energía del Círculo se eleva. A partir de ahí, puedes invocar los Glifos Xorothianos y abrir un portal a Xoroth y arrastrar un dreadsteed a través de él. Derrota al dreadsteed y libera su espíritu. Enfréntate al espíritu y quedará cautivado, y serás recompensado con el secreto de su invocación." },
		[2771] = { file = "2771", len = 19.54, text = "Pelando la cebolla Guía para desmontar el Stormpike -Por Drek'Thar En estas páginas encontrarás una gran cantidad de conocimientos sobre tácticas de batalla y política. El soldado erudito es el soldado que se apoya en el hombro de la experiencia. Deja que este libro te sirva de guía en tu batalla por el Valle de Alterac." },
		[2772] = { file = "2772", len = 31.713, text = "Capítulo 1 - La primera línea Desmantelar el ejército de Stormpike es muy parecido a pelar una cebolla. Para llegar al núcleo, hay que empezar por quitar las capas más externas. Las primeras líneas, compuestas en su mayoría por Stormpike Mountaineers y Alliance Sentinels, están atadas al búnker del Capitán. Es la Capitana Balinda Stonehearth quien da poder a estas unidades y proporciona refuerzos cuando las líneas están bajo asedio. Golpea a la Capitana y las fuerzas de primera línea se desmoronarán." },
		[2773] = { file = "2773", len = 22.622, text = "Capítulo 2 - Las Torres Gemelas No te equivoques: Vanndar Stormpike es un enemigo astuto y, desde luego, no es tonto. Una vez atravesada la línea del frente, aún hay que destruir los objetivos defensivos secundarios. Son las torres gemelas de Stonehearth y Icewing las que controlan a los guardias de Stormpike fuera de Dun Baldar y a las patrullas de Stormpike." },
		[2774] = { file = "2774", len = 18.677, text = "Ten cuidado, soldado, ya que estas dos torres están fuertemente fortificadas y gobernadas por uno de los comandantes de élite de Vanndar. Si tus fuerzas rompen las fortificaciones, asegúrate de que el Comandante ha sido... silenciado. Esto también será parte del desmantelamiento del Stormpike." },
		[2775] = { file = "2775", len = 32.496, text = "Capítulo 3 - Los cuatro comandantes La tercera capa de la cebolla de Stormpike está formada por los cuatro Comandantes. En este sentido, Vanndar ha imitado nuestras propias gloriosas defensas Frostwolf. Claro que él te dirá lo contrario... Pero estoy divagando. Los cuatro Comandantes controlan el flujo y reflujo de los Guardias Stormpike que guardan ferozmente Dun Baldar. Siléncialos a todos y los Guardias Stormpike caerán. Entonces solo queda una capa que pelar." },
		[2776] = { file = "2776", len = 26.958, text = "Capítulo 4 - Los búnkeres de Dun Baldar Como sin duda habrás notado, las capas defensivas de Stormpike están dispuestas para evitar que un poderoso movimiento de poder desmantele todo el ejército. Antes de que preguntes, sí, así es exactamente como están dispuestas nuestras propias fuerzas y no, no cambiaré nuestra estructura defensiva. Ellos nos copiaron, ¿por qué tendríamos que cambiar nosotros?" },
		[2777] = { file = "2777", len = 19.566, text = "¿Dónde estaba? Sí, así que los búnkeres de Dun Baldar (que se encuentran en Dun Baldar) controlan a los Defensores de Stormpike, las unidades de guardia de élite y de mayor confianza de Vanndar. Destruye esas dos torres y los refuerzos enviados para ayudar a Vanndar dejarán de existir." },
		[2778] = { file = "2778", len = 20.558, text = "Epílogo Después de haber hecho todo esto, le queda el centro de la cebolla: El núcleo dulce. Vanndar Stormpike quedará indefenso y solo. Las normas de conducta militar exigen que pidamos su rendición antes de llevar a cabo cualquier ejecución. Asegúrate de mencionar lo de la rendición cuando lo veas... y luego mátalo." },
		[2779] = { file = "2779", len = 34.56, text = "La alcachofa de Frostwolf: Cuentos de la Gloria de Stormpike -Por Vanndar Stormpike ¿Qué es Frostwolf? La respuesta es sencilla: Los Frostwolf son salvajes que intentan detener nuestro imperativo imperialista soberano. Al igual que una alcachofa, los Frostwolf tienen un conjunto de defensas espinosas y blindadas, y al igual que una alcachofa, una vez que se pela la capa exterior, el corazón queda al descubierto, listo para ser comido con una fina salsa de ajo. ¡Delicioso!" },
		[2780] = { file = "2780", len = 29.022, text = "Capítulo 1 - La primera línea Las primeras líneas de las defensas Frostwolf están formadas por Guerreros Frostwolf. Los guerreros se despliegan en primera línea desde la fortaleza del Capitán Galvangar: Guarnición Sangre de Hielo. La forma más eficaz de acabar con esta capa de las defensas es destruir la Guarnición Sangre de Hielo. Asedia la fortaleza y destruye al capitán Galvangar. Una vez hecho esto, las líneas del frente se desmoronarán." },
		[2781] = { file = "2781", len = 29.989, text = "Capítulo 2 - Iceblood y Tower Point Una vez derribada la primera capa, la segunda de la \"alcachofa\" quedará al descubierto. Destruir las torres Frostwolf que se encuentran cerca de las líneas del frente paralizará al Legionario y a las patrullas que pululan por el flanco trasero. Las torres están fuertemente fortificadas, y cada una alberga a uno de los comandantes de élite de Drek'Thar. Hay que matarlos. Esto acelerará el desmantelamiento de las defensas Frostwolf." },
		[2782] = { file = "2782", len = 30.798, text = "Capítulo 3 - Los cuatro comandantes Si has seguido la sabiduría de esta guía, a estas alturas, dos de los Comandantes de Drek'Thar están muertos. ¡Buen trabajo, soldado! Su determinación ya se está debilitando. Ahora debes completar la diseminación de la cadena de mando matando a los dos comandantes restantes. Con los cuatro Comandantes muertos, los Legionarios Lobo Escarcha que custodian la Fortaleza Lobo Escarcha se dispersarán y quedarán sin mando. ¡Preparados para la cosecha!" },
		[2783] = { file = "2783", len = 27.324, text = "Capítulo 4 - Las torres Este y Oeste de Frostwolf Ahora solo hay una capa que se interponga entre tú y la victoria: las unidades de guardia más poderosas y de mayor confianza de Drek'Thar: Los Guardianes Lobo Escarcha. Los guardianes Frostwolf se envían desde los pelotones que se mantienen en reserva en las torres Frostwolf este y oeste. Destruye esas torres y observa cómo huyen avergonzados los restantes guardianes." },
		[2784] = { file = "2784", len = 26.488, text = "Epílogo \"Asfixie el corazón de la alcachofa con mantequilla de ajo y mayonesa. Complementa la comida con una cerveza añeja y embriagadora\". Drek'Thar está ahora solo, con sus dos chuchos a su lado. Captura el Refugio del Lobo Escarchado para que te ayude en la batalla y destruye a Drek'Thar. Cuando el General caiga, esta tierra será finalmente entregada a su legítimo dueño: El Pico de Tormenta." },
		[2785] = { file = "2785", len = 19.801, text = "Te invocamos, Zanza de Zuldazar. Bendice a aquellos que piden tu ayuda, Loa Zanza. Bendice a aquellos que se alíen con el pueblo Zandalarian. Ayúdanos en estos tiempos de necesidad. Ayúdanos Loa. Danos el poder para derrotar a nuestros enemigos. Danos el poder para derrotar una vez más al Dios de la Sangre." },
		[2786] = { file = "2786", len = 42.423, text = "Torneo de pesca Stranglethorn Domingo por la tarde - de 14:00 a 16:00. Pesca en cualquier punto de la costa de Stranglethorn (excepto en Booty Bay) y busca los bancos de Tastyfish que aparecerán a lo largo de la costa. Asegúrate de que tu caña de pescar cae en el banco y capturarás peces especiales en lugar de la variedad normal de Stranglethorn. La primera persona que pesque cuarenta peces sabrosos podrá convertirlos en cebo Fishmaster en la bahía del Botín y llevarse un premio. Incluso si no eres la primera persona en pescar cuarenta peces sabrosos, puedes entregarlos para ganar dinero y también hay peces especiales que se pueden pescar y que darán premios especiales." },
		[2787] = { file = "2787", len = 13.662, text = "Su nombre trajo la Luz al Azeroth más oscuro. Su valor derribó los muros de la miseria. La Mano de Plata nunca haría nada mejor que dar al mundo el caballero que se daría a sí mismo." },
		[2788] = { file = "2788", len = 10.318, text = "Su fama no era lo que buscaba, ni tampoco el señorío sobre los suyos. En su lugar, eligió luchar por Lordaeron para esperar que los suyos no tuvieran que luchar más." },
		[2789] = { file = "2789", len = 10.736, text = "La trágica historia de este santísimo caballero no terminará nunca con su impía muerte. ¡Le honramos, y le daremos gracias! ¡Siempre conocerá la gloria y la Luz!" },
		[2790] = { file = "2790", len = 12.957, text = "Su nombre no morirá. Su sacrificio siempre servirá para mostrar el camino. Los grilletes que una vez ahogaron el aliento del honor ya no nos atan." },
		[2791] = { file = "2791", len = 11.076, text = "¿Puedes oír su grito? A lamento de batalla para la Horda: Victoria o muerte! Debemos recordar su fuerza frente a la muerte. Hsu sueño, ahora hecho realidad." },
		[2793] = { file = "2793", len = 22.831, text = "Han pasado casi mil años desde la \"Guerra de las Arenas movedizas\". Fue durante esta guerra, en el corazón del desierto de Silithus, cuando una gran tragedia y una carga aún mayor acosaron a Fandral Staghelm. Se cree que los sucesos aquí descritos fueron los que acabaron por moldear la desagradable disposición del Archidruida." },
		[2794] = { file = "2794", len = 14.498, text = "Una antigua raza insectoide conocida como los Qiraji compitió por el dominio de gran parte de Kalimdor en un momento dado. Fue el pomposo e imperialista Staghelm y su ejército de elfos de la noche quienes se enfrentaron a los Qiraji." },
		[2795] = { file = "2795", len = 17.606, text = "Padre e hijo lucharon fervientemente para contener la creciente marea del enjambre insectoide en Silithus. Desde la fortaleza de Ahn'Qiraj, un flujo aparentemente interminable de silítidos seguía reforzando las filas de las fuerzas invasoras Qiraji. Todo Silithus estaba bajo asedio." },
		[2796] = { file = "2796", len = 19.252, text = "En una decisión que Staghelm lamentaría, el Staghelm más joven, Valstann, recibió la orden de defender el puesto avanzado de los elfos de la noche de la Aldea de Southwind. Lamentablemente, Valstann perdería la vida ese día, ya que la Aldea del Viento Meridional caería ante los ejércitos de Ahn'Qiraj." },
		[2797] = { file = "2797", len = 31.112, text = "Impertérrito y con el corazón encogido, un vengativo Fandral Staghelm seguiría adelante. La derrota en Silithus supondría una gran pérdida para la nación de los elfos de la noche y muy posiblemente para el mundo. La batalla se prolongó durante meses. Todo Silithus fue invadido por los Qiraji. Staghelm y su ejército fueron empujados de vuelta a Tanaris. Con un ejército diezmado e incontables inocentes asesinados, la arrogancia que había impulsado a Fandral Staghelm se apagó por completo." },
		[2798] = { file = "2798", len = 18.495, text = "Su orgullo totalmente aplastado. Por segunda vez en su existencia, Staghelm sentiría en la boca del estómago el estremecimiento que sólo puede provocar el miedo. Fue en Tanaris, entonces, donde Staghelm se acercaría a Anachronos, progenie de Nozdormu, y suplicaría la ayuda del Vuelo de Bronce." },
		[2799] = { file = "2799", len = 14.263, text = "Al principio, Anacronos se negó a involucrar al Vuelo de Bronce en los asuntos de las razas inferiores. No fue hasta que los Qiraji atacaron descaradamente las Cavernas del Tiempo cuando Anacronos accedió a unir fuerzas con los elfos de la noche." },
		[2800] = { file = "2800", len = 27.376, text = "Anacronos pronto se daría cuenta de que ni siquiera el poderoso Vuelo de Bronce podría detener la marea de las fuerzas invasoras Qiraji. Por cada cincuenta de los insectos aniquilados por su aliento, cien estarían esperando para ocupar su lugar. Con las líneas de los elfos de la noche tambaleándose y la amenaza de ser empujados más al norte, a las tierras salvajes de Feralas, Anacronos decidió que los hijos de los Aspectos debían ser informados." },
		[2801] = { file = "2801", len = 12.643, text = "Primero llamaría a la Luz de Dragón de Ysera. Merithra del Sueño respondería a su llamada y, a partir de ahí, el Vuelo del Dragón de Alexstrasza y el Vuelo del Dragón de Malygos se pondrían al corriente." },
		[2802] = { file = "2802", len = 29.78, text = "Los dragones se encontrarían en la estratosfera, muy por encima de Silithus: Miles de metros por encima de la fortaleza de Ahn'Qiraj. Allí estaba Anachronos, hijo del Nozdormu, Aspecto del Tiempo. Del Sueño Esmeralda vendría Merithra, hija de Ysera, Aspecto de la Naturaleza. Caelestrasz, hijo de Alexstrasza, Aspecto de la Vida, representaría el Vuelo del Dragón Rojo. Arygos, hijo de Malygos, Aspecto de la Magia, representaría la Huida del Dragón Azul." },
		[2803] = { file = "2803", len = 21.943, text = "Los dragones observaron cómo un flujo interminable de silithid y Qiraji salía de Ahn'Qiraj. Tenían claro que ninguna fuerza podría acabar con esta guerra. Desde el interior del templo principal, decenas de miles de las fuerzas Qiraji esperaban. Con cada segundo que pasaba, se incubaban y preparaban más, listas para ser liberadas en el mundo." },
		[2804] = { file = "2804", len = 30.302, text = "Arygos fue el primero en notar las extrañas emanaciones. El templo monolítico del cuadrante sur de Ahn'Qiraj irradiaba una magia tenue distinta a todo lo que habían percibido procedente de los Qiraji. Por mucho que lo intentaron, ninguno fue capaz de penetrar más en el templo para encontrar la fuente de esta energía. Sólo algo de inmenso poder podía protegerse tan completamente. Tal vez... algo que controla a los insectos. Algo que controla incluso a los Qiraji." },
		[2805] = { file = "2805", len = 14.733, text = "Los dragones sabían que tenían que reaccionar con rapidez, no fuera que el mundo sufriera otra catástrofe épica. Tras una cuidadosa deliberación, se decidió que lo mejor sería detener a los ejércitos anfitriones en su origen o cerca de él." },
		[2806] = { file = "2806", len = 17.998, text = "Se crearía una gran barrera, extraída de la esencia tanto de los elfos de la noche como de los libélulas. Una barrera mágica que podría contener a los silithid y a sus señores dentro de los muros de Ahn'Qiraj y evitar futuras incursiones. Ahn'Qiraj se convertiría en una prisión." },
		[2807] = { file = "2807", len = 27.742, text = "Primer día Nuestro peregrinaje ha terminado. Por fin hemos llegado a Silithus, donde vamos a establecer contacto. Hemos venido de muchos lugares para colaborar en lo que va a ser una empresa monumental. Hay una tremenda sensación de excitación en el aire. Mañana dedicaremos toda nuestra energía a construir aquello que permitirá la comunicación con ELLOS. Mañana construiremos una piedra de viento." },
		[2808] = { file = "2808", len = 32.34, text = "Día 2 La ubicación de la piedra de viento ha sido objeto de gran debate. Ni siquiera los más sabios entre nosotros pueden determinar con gran certeza a qué lugar se refiere realmente el lugar mencionado en la antigua profecía. Yo me he quedado con el grupo original del norte y, sin duda, el tiempo nos dará la razón. El argumento de que las líneas de energía se cruzan en ángulos perjudiciales en este lugar es tonto e ingenuo. Ya estamos reuniendo los materiales de construcción necesarios a gran velocidad." },
		[2809] = { file = "2809", len = 28.865, text = "Día 15 Nuestra dedicación ha dado sus frutos. Somos el primer campamento en terminar la construcción de una piedra de viento. Si los otros tontos se hubieran quedado con nosotros, ¡habríamos completado la tarea en menos de una semana! Mañana comenzaremos los rituales para invocar al mismísimo Barón Kazum. Exigió ser el primero en probar el sistema y no podíamos contradecirle, ya que es rápido para la ira. Espero que esté encantado con nosotros." },
		[2810] = { file = "2810", len = 32.052, text = "Para difusión inmediata a todos los miembros del Martillo del Crepúsculo. La búsqueda del traidor, Ortell, progresa a un ritmo muy satisfactorio. Nuestros exploradores han acotado su localización a una red de cavernas en Westfall. La traición de Ortell no será perdonada y su huida representa un gran riesgo para la seguridad de nuestra organización. Cualquier individuo que oculte información sobre el paradero de Ortell será debidamente castigado. -Twilight Lord Everun" },
		[2811] = { file = "2811", len = 26.41, text = "Para su difusión inmediata a todos los miembros del Martillo Crepuscular. Dado el estado actual de las cosas en Silithus, toda distribución de textos de los Verdaderos Creyentes se hará bajo la escolta de no menos de cuatro miembros armados del Martillo Crepuscular. Cualquier miembro que viole esta nueva política será castigado sumariamente. -Lord Crepuscular D'Sak" },
		[2812] = { file = "2812", len = 22.648, text = "Para difusión inmediata a todos los miembros del Martillo del Crepúsculo. La siguiente información describe el uso de las piedras de viento para la comunicación con nuestros maestros en el Consejo Abisal. Todo uso frívolo de las piedras de viento será castigado de la manera más dolorosa. -Conservador del Crepúsculo Havunth" },
		[2813] = { file = "2813", len = 27.376, text = "Templarios Abisales Acomo iniciado se te permite establecer contacto con Templarios Abisales para rituales rutinarios. Recuerda llevar siempre el atuendo adecuado cuando utilices piedras de viento para evitar activar nuestros encantamientos defensivos. Si surge una emergencia imprevista sin supervisores presentes, se te concede permiso para invocar a un Templario Abisal. Para más detalles sobre los rituales de invocación, consulta el True Believer del mes pasado." },
		[2814] = { file = "2814", len = 19.435, text = "Duques Abisales OSólo los acólitos en posesión de un medallón de estación pueden establecer contacto con los Duques Abisales. Los miembros del Martillo del Crepúsculo implicados en comunicaciones no autorizadas con los Duques Abisales o en el uso no autorizado de medallones de estación serán sancionados personalmente." },
		[2815] = { file = "2815", len = 27.69, text = "El Alto Consejo de los Señores Abisales OSólo se permite a los Señores del Crepúsculo ponerse en contacto con el Príncipe Skaldrenox, el Alto Mariscal Whirlaxis, el Barón Kazum o Lord Skwol. En ningún caso se permite a ningún miembro de bajo rango del Martillo del Crepúsculo iniciar la comunicación con el Alto Consejo. Cualquier forastero que sea sorprendido utilizando una piedra de viento de esta manera será reducido a cenizas en el acto." },
		[2816] = { file = "2816", len = 35.109, text = "El Estado del Culto, Volumen 92 I Con un corazón alegre os saludo, hermanos míos, porque el estado de nuestro culto no podría ser más grandioso. Somos legión, y nuestros objetivos están cada vez más cerca de cumplirse. Cantan alabanzas a nuestros señores en Darkshore, se inclinan en jubiloso ensueño en el Desfiladero Ardiente, abrazan al siervo de nuestros amos, Aku'mai, en las Profundidades de Blackfathom. En efecto, hermanos y hermanas, ¡pronto un enjambre de fieles cubrirá todo Azeroth!" },
		[2817] = { file = "2817", len = 20.297, text = "¡Estado del Culto, Volumen 127 IEs un día verdaderamente feliz! Los informes de la destrucción de nuestro campamento más septentrional pueden desafiar los corazones de los infieles, pero esta matanza no debe verse como una tragedia. ¡No!" },
		[2818] = { file = "2818", len = 20.297, text = "¡El derramamiento de nuestra sangre por uno del Alto Consejo Abisal es una bendición! ¡Debemos envidiar a nuestros camaradas caídos, pues sus espíritus residen ahora en el vientre de una bestia muy justa! ¡Alabados sean los Antiguos Dioses! ¡Alabados sean sus siervos! ¡Alabado sea el Martillo del Crepúsculo!" },
		[2819] = { file = "2819", len = 37.616, text = "Estado del culto, volumen 233 La oportunidad llama de nuevo a la puerta, hermanos y hermanas. El Círculo Cenarion, un vil culto de amantes de la naturaleza, envía ahora agentes contra nosotros. Deben querer impedir que invoquemos las piedras rojas atrayentes. ¡No podemos permitirlo! Las piedras rojas son críticas para nuestros nuevos aliados. No debemos permitir que los perros falderos del Círculo Cenarion tengan éxito. Manténganse firmes, mis fieles amigos. ¡Manténganse firmes!" },
		[2820] = { file = "2820", len = 21.342, text = "Algunos se preguntarán cómo pueden amarnos los dioses antiguos y sus secuaces. ¿No nos matan? ¿No causan dolor y sufrimiento a todos? ¿Cómo pueden seres tan malévolos conocer el amor en sus corazones? Hay una respuesta sencilla a esta pregunta. ¿Tan simple que no es necesario formularla?" },
		[2821] = { file = "2821", len = 16.222, text = "La fe. La fe es el manantial del que nos brota la alegría de la servidumbre. La fe nos mantendrá calientes en las noches más frías de Silithus. La fe nos mantendrá en gracia de nuestros Señores cuando lleguen los Días Finales. La fe nos salvará." },
		[2822] = { file = "2822", len = 28.421, text = "Cómo hacer una boya de arcanita: Mezcla un poco de Arcanita con un poco de Boya. ¡Buena suerte! No pensaste que sería tan fácil, ¿verdad? Todavía te debo por la escala astillada, viejo amigo. -Azuregos P.D. Espero que se te ocurra cómo hacer una boya de arcanita de verdad, porque esa tontería me la acabo de inventar sobre la marcha. No tengo ni idea de cómo van a encontrar a Maws." },
		[2829] = { file = "2829", len = 26.776, text = "Querido diario, Hoy, mi archienemigo, Narain Soothfancy, intentó engañarme enviando compinches para ocupar su lugar en la ejecución. SU ejecución. ¿Puedes creerlo? I se había tomado la molestia de idear este diabólico plan para atraerlo fuera de esa maldita choza y ¿él hace esto? Como sea... Demasiado enojado para seguir escribiendo. Volveré más tarde." },
		[2830] = { file = "2830", len = 15.726, text = "Querido diario, Dejé mi escondite furioso después de mi última entrada. Vaya si estaba enfadado. Decidí rediseñar los uniformes de mis secuaces para reflejar mejor mi angustia. Me siento un poco mejor, pero me falta algo. Ahora vuelvo..." },
		[2831] = { file = "2831", len = 17.815, text = "Querido diario, Ok, estoy bien ahora. Golpeé a uno de mis secuaces hasta que lloró como una niñita. Hrm... Me siento un poco mal ahora. ¡Un momento! ¡Maldición, soy un genio MALVADO! Malvado, ¿sabes? Estoy tan decepcionado de mí mismo. Vuelvo enseguida." },
		[2832] = { file = "2832", len = 30.929, text = "Querido diario, Le di un abrazo y le dije que siguiera con el buen trabajo. Ahora me siento mejor. Que quede entre tú y yo, diario. ¿Dónde estaba? ¡Oh sí, NARAIN! ¡¡¡ARGH!!! Odio a ese tipo. Fue Narain, después de todo, el que destruyó la curva en cada examen cuando éramos estudiantes en el Instituto Gnomeregan de Tinkering. ¿Me van a expulsar de la escuela? En lo que a mí respecta, Gnomeregan recibió su merecido. Eso es todo por hoy. ¡Duerme bien, diario!" },
		[2833] = { file = "2833", len = 26.749, text = "Querido diario, Debo estar envejeciendo. Olvidé por completo que te estaba hablando de Narain y su engaño. De todos modos, me enfadé tanto cuando vi un señuelo disfrazado de Narain en lugar de Narain, que ordené a Número Dos que destruyera al tonto. I se subió a mi máquina voladora y empezó a destrozar su precioso, estúpido y tonto libro sobre dracónico. ¿Qué fanfarrón? ¿Quién lee Dracónico? ¡Lo odio tanto!" },
		[2834] = { file = "2834", len = 34.351, text = "Querido diario, Lo siento, me quedé dormido. Estaba volando enfadado y tirando capítulos de ese estúpido libro. Vi a un demonio debajo de mí en Darkwhisper y decidí hacer que el primer capítulo formara un tornado mágico de papel y destrozara su cuerpo en un millón de pedazos. Fue liberador. Magia + papel = diversión. Eso me hizo bastante feliz, así que decidí volar a los Reinos del Este. Mi primera parada fue el Núcleo Fundido. Narain siempre hablaba de ese lugar. \"Núcleo Fundido esto y Ragnaros aquello...\"" },
		[2835] = { file = "2835", len = 21.342, text = "¿Sabéis qué? Si le gusta tanto, ¡quizá le guste intentar reconstruir su libro yendo al Núcleo Fundido y resucitando el capítulo de un montón de cenizas! Ya que estaba en el vecindario, me imaginé que algunos de esos técnicos voraces en el laboratorio del viejo Victor Nefarius podrían tener un uso para esta cosa Dracónica. ¡Bombas fuera!" },
		[2836] = { file = "2836", len = 28.917, text = "Esto empezaba a convertirse en una especie de deporte. Me estaba aficionando a dividir ese maldito libro. Las siguientes entregas fueron fáciles. Undercity, hogar de los fétidos muertos putrefactos y posiblemente del mejor chili que he probado nunca, recibió un capítulo. Stormwind, capital del Queso, el otro. Diario, ¿alguna vez has puesto queso de Stormwind en el chili de Undercity? ¿HOLA? Eso debería hacer sonar algunas alarmas." },
		[2837] = { file = "2837", len = 17.476, text = "Me estaba cansando, así que di la vuelta a la máquina voladora y me dirigí a casa, pero no sin antes hacer dos paradas más. Le di un repaso a Lord Kazzak y sus demonios en la Cicatriz Manchada (odia que haga eso) y metí otro por la chimenea de Onyxia. Cansado. Me voy a dormir." },
		[2838] = { file = "2838", len = 21.081, text = "A quien corresponda, Cómo me gustan estos juegos que jugamos. Sólo puedo suponer que si estás leyendo esta carta, de alguna manera, por milagro o intervención divina, has logrado vencerme. Es absurdo, lo sé, pero cosas más extrañas han sucedido en la historia de este mundo." },
		[2839] = { file = "2839", len = 23.693, text = "Como todas las cosas en la vida, hay un glorioso resquicio de tragedia, caos y maldad en esta triste historia. Aunque me has matado, lo has hecho de una forma tan lenta y desordenada que he tenido tiempo suficiente para escribir esta carta DESPUÉS de haber destruido tu única esperanza de salvar este mundo. El polvo de cristal rojo triturado es todo lo que queda del fragmento de tu cetro." },
		[2840] = { file = "2840", len = 14.837, text = "Disfruta del armamento Nemesis y Stormrage que puedes encontrar en mi tesoro. Créeme cuando te digo esto: Me complace saber que hice lo que mi padre no pudo... Atentamente, Lord Victor Nefarius \"Nefarian\"" },
		[2841] = { file = "2841", len = 32.026, text = "En nombre de Smokywood Pastures, gracias de nuevo por investigar esto. No estamos seguros de qué grupo tiene a Metzen, pero investigar a cualquiera de los dos sería un buen lugar para empezar. El tiempo es amigo del dinero, y tenemos muy poco en este caso. Sea rápido en sus esfuerzos para rescatar, ya que estos grupos no son para ser tomado a la ligera en lo que son capaces de hacer. Anyway, las dos páginas siguientes son las notas de rescate que hemos recibido. Buena suerte..." },
		[2842] = { file = "2842", len = 26.201, text = "Si quieres recuperar el reno vivo, entonces serás rápido con el rescate. A los piratas de Southsea no les gustan los retrasos en el pago, y sabemos lo valiosa que es la bestia para SU forma de piratería. Blleva la suma de 1000 oros a la boca de la Cala del Aparejador Perdido en Tanaris. Cualquier intento de rescatar al reno hará que Metzen tenga que dar un largo paseo por un tablón muy corto. Yeargh... Los Piratas del Mar del Sur" },
		[2843] = { file = "2843", len = 31.399, text = "Tu preciada mascota no lo está haciendo muy bien aquí fuera en el implacable calor del Desfiladero Ardiente... harás bien en satisfacer nuestras demandas sin demora. Nos traerás cinco rubíes estrella y la suma de 700 de oro - pon ambos en un único paquete sencillo que esté libre de marcas. Deja el paquete en las puertas del Paso de la Piedra en el plazo de una semana. Si no cumples con nuestras demandas, Metzen será el plato principal de un banquete tradicional del Velo de Invierno de los Enanos del Hierro Oscuro. Mmmm... renos..." },
		[2844] = { file = "2844", len = 20.95, text = "Más rápido que las águilas llegaron sus jinetes, AY silbó, y gritó, y los llamó por sus nombres; \"¡Ahora, Mercer! ¡Ahora, Chilton! ¡Ahora, Jordan y Kaplan! On, Nagle! ¡A Pardo! ¡Andando, Goodman y Metzen! ¡A lo alto del porche! ¡A lo alto del muro! Now dash away! dash away! dash away all!\"" },
		[2859] = { file = "2859", len = 41.665, text = "BRAZIER DE INVOCACIÓN: MANUAL DEL USUARIO Dónde encontrar Loci Embrujados INTRODUCCIÓN Contenidos en estas páginas están los lugares de los espíritus y almas caídos y corrompidos implicados en el Incidente del Amuleto de Lord Valthalak. Aunque ya has salvado a estos antiguos compañeros míos, supongo que los repugnantes ecos del mal que una vez retorció sus espíritus aún perduran en esos lugares encantados. Tal era el poder malévolo del espíritu de Lord Valthalak. Adicicionalmente, el brasero se puede utilizar para invocar a Lord Valathalak, aunque como antes, se debe tener extrema precaución al hacerlo." },
		[2860] = { file = "2860", len = 33.724, text = "INTRODUCCIÓN, continuación... El propio brasero funciona igual que el Brasero de la Invocación. Simplemente colócalo dentro del alcance de cualquiera de los cinco loci encantados e invocará a los espíritus de los muertos. A Como nota al margen, porque sé que te interesará saberlo, el Estandarte de la Provocación puede usarse de forma similar en la arena de las Profundidades de Blackrock. Asegúrate de darles una lección a Theldren y a sus matones de mi parte cada vez que tengas ocasión cuando estés allí. Rigue leyendo si deseas más información." },
		[2863] = { file = "2863", len = 31.19, text = "MOR GRAYHOOF Tauren Druida y Primer Caído Mor Grayhoof fue siempre un compañero incondicional y de confianza en La Hoja Velada. Cuando huíamos de Valthalak, nos perseguía un verdadero ejército de sus espectrales asesinos y acechadores. La huida de Blackrock Spire fue caótica, por no decir otra cosa. Por desgracia, en el camino, Mor perdió pie de algún modo, aunque sospecho que lo empujaron. En cualquier caso, cayó en los recovecos de la parte inferior de la aguja." },
		[2864] = { file = "2864", len = 29.257, text = "MOR GRAYHOOF, continuación... LMás tarde, descubrimos que Mor había sobrevivido a la caída. Pero no iba a haber un final feliz para mi buen amigo; fue hecho prisionero por los trolls de Tazz'Alaor. No mucho después, mientras estaba siendo torturado por el Maestro de Guerra Voone, un grupo de asesinos de Valthalak saltó y terminó el trabajo. Si buscas levantar el eco del espíritu de Mor Grayhoof, la cámara del Maestro de Guerra Voone es un lugar encantado." },
		[2866] = { file = "2866", len = 43.781, text = "JARIEN Y SOTHOS, continuación... S Así fue como se encontraron enfrentándose a las pruebas que se exigen a aquellos que buscan unirse a la Cruzada. De particular interés para ellos era una posición de caballero dentro de las filas; algo que requería pruebas más difíciles aparentemente. Más tarde se descubrió que Sothos había suspendido la última prueba. Sin embargo, Jarien no lo permitió y, desafiándola abiertamente, insistió en que pudiera unirse a ella entre los caballeros. Por lo que hemos averiguado, el Gran Cruzado Dathrohan los mató a ambos en el acto, en medio de sus aposentos. Así pues, otro de estos lugares encantados es el Trono Carmesí, en el interior del Bastión Escarlata de Stratholme." },
		[2867] = { file = "2867", len = 37.93, text = "KORMOK Two-Headed Ogre Necromancer ¿Qué se puede decir de Kormok? Era un ogro bicéfalo de la variedad caster que no solía ser tan malo. Cuando lo acogimos por primera vez fue como prisionero en un trabajo que habíamos aceptado en Estepas Ardientes. Sin embargo, demostró ser inestimable para ayudarnos a salir de una situación complicada en la que caímos allí, por lo que se convirtió en uno de los magos más importantes de la compañía. Una era siempre alegre, si no un poco tonta, mientras que la otra era astuta, calculadora y tenía una mirada casi muerta. Realmente espeluznante." },
		[2870] = { file = "2870", len = 41.326, text = "LORD VALTHALAK, continuación... No teníamos ni idea de la profundidad de los conocimientos mágicos de Valthalak en lo que a manipulación de almas se refiere, o probablemente nunca habríamos aceptado el trabajo en primer lugar. Pero lo hicimos, y resultó ser el último trabajo que aceptaríamos. Habiendo matado a Lord Valthalak, y tomado su libro de hechizos, Kormok debió sentir algo sobre su amuleto. Insistió en llevárselo como parte del botín, lo que rápidamente derivó en una acalorada discusión, y casi una pelea, por el objeto. En aquel momento no sabíamos que el amuleto contenía una buena parte del espíritu de Valthalak; lo descubrimos más tarde, para nuestro disgusto." },
		[2871] = { file = "2871", len = 45.557, text = "LORD VALTHALAK, continuación... al romper el amuleto en pedazos, huimos del fantasma recién levantado de Valthalak, así como de su ejército de asesinos espectrales. Y el ruido que hicimos luchando por el amuleto había despertado a varios de los defensores que quedaban en la Aguja. Casi todos conseguimos salir de Blackrock y pensamos que estábamos a salvo. Pero, incluso desde el más allá, Valthalak nos enviaba a sus esbirros sin importar dónde nos escondiéramos. La Cuchilla Velada pronto se desintegró después de esa misión, y entonces fuimos presa fácil. Acomo debes saber, esto hace que la morada de Lord Valthalak, lo que ahora es la cámara de La Bestia en Blackrock Spire, sea el último de los lugares embrujados." },
		[2872] = { file = "2872", len = 30.746, text = "A todos los hombres y mujeres sanos: El Azote ha regresado y debemos dejar de lado nuestras disputas para enfrentarnos a esta amenaza. El Amanecer Argentino no rechazará a nadie que desee tomar las armas contra la amenaza del Azote. Aquellos que quieran defender nuestras tierras se están reuniendo en la Capilla de la Esperanza de la Luz en las Planicies Orientales. Juntos, prevaleceremos. Guardián de los Rollos El Amanecer Argentino" },
		[2878] = { file = "2878", len = 55.458, text = "Mi Emily, Hace pocos días, levantamos el campamento en este lugar olvidado de la Luz, cumpliendo las órdenes del Rey de regresar a casa. Mi corazón era ligero a pesar de lo sombrío de mi entorno, porque sabía que tras la gélida caminata hasta la costa y el largo y agotador viaje, encontraría consuelo en tus brazos. Hoy hemos llegado a la costa para encontrar nuestros barcos, nuestros medios de regreso, nada más que cáscaras carbonizadas; no podemos irnos, y no tenemos otra opción que seguir adelante en el corazón de este páramo abismal. He ido hasta el fin del mundo para mantenerte a salvo, Emily... y ahora... Desearía con todo mi ser haberme quedado en Lordaeron contigo. Pensamientos sobre ti llenan cada momento que estoy despierto. Eres mi calor en esta tierra helada, amada, y nadie puede quitármelo. Maxwell" },
		[2880] = { file = "2880", len = 67.265, text = "Reuben, Escribo esta carta sabiendo que tal vez nunca la veas; simplemente no puedo quedarme de brazos cruzados, escuchando el constante golpeteo contra las murallas de Hearthglen. Los muertos vivientes están fuera de nuestra aldea, en un asalto incesante, y se nos ha encomendado defender a la gente del pueblo hasta que lleguen los refuerzos. Mi pierna se rompió en la última carga, y por eso estoy sentado, inútil, con mi espada a mi lado por si hubiera una brecha en nuestras defensas. No hay bromas... sólo sonidos de lucha y muerte. El príncipe Arthas está aquí, luchando en primera línea con sus hombres. Si él no estuviera presente, habríamos caído hace mucho tiempo. Su amor por esta tierra y sus gentes es contagioso; sirvo a sus órdenes con mucho gusto y lo haré hasta el fin de mis días. La lucha es cada vez más intensa; con la pierna rota o sin ella, no puedo quedarme aquí sentado. Todas las espadas son necesarias. Espero que estas palabras te encuentren en tiempos más felices. Tu amigo, Leagrem" },
		[2881] = { file = "2881", len = 37.433, text = "Heliana, Yo, Vargus, aún vivo, a pesar de tus deseos de lo contrario. Desprecio andar por el campo con esta ridícula armadura. Nuestras últimas órdenes nos hacen dirigirnos a Andorhal en busca de grano o alguna tontería por el estilo. ¿Por qué debería preocuparme por los almacenes de alimentos en Andorhal, de todos los lugares? Toda esta idea de estar en el ejército es ridícula. Ten por seguro, tía Heliana, que volveré a por tu herencia; incluso si me hieren gravemente y me quedo sin comida, el puro rencor me impulsará a seguir adelante. Vargus" },
		[2882] = { file = "2882", len = 60.082, text = "Querida Amelia, Esta noche he visto cosas que me atormentarán hasta el fin de los tiempos. Stratholme está en llamas... y nosotros somos los responsables. Nuestro Príncipe nos llevó a las calles de la ciudad esta noche; nos ordenó entrar en las casas de los habitantes y... matarlos mientras dormían. Estaban plagados, afirmó Lord Arthas, y había que matarlos antes de que nos mataran a nosotros. Fue una masacre. Cientos murieron en silencio ante las espadas de aquellos que habían jurado protegerlos. No pude soportarlo más; huí. Desertor puedo ser, pero no podía cometer tales atrocidades. En cada hogar no podía evitar ver tu rostro, o el de nuestros hijos, sobre las víctimas mientras morían. Si oponerse a eso significa ser un traidor, que así sea. Espero encontrar el camino de vuelta a ti a tiempo, pero las carreteras son inseguras. Dale a nuestros hijos mi amor en mi ausencia. James" },
		[2883] = { file = "2883", len = 50.991, text = "Samla, Mientras seguimos a nuestro Señor Arthas hacia el norte, siempre hacia el norte, mi corazón se entristece. Mientras que una vez brilló con la Luz, ahora percibo un oscurecimiento en el espíritu del joven paladín. Su celo se ve ensombrecido por una pesadilla en su alma que no puedo adivinar... Pronto tocaremos tierra en los yermos helados. Aunque muchos de sus hombres enferman a causa del frío y de las batallas contra bestias pútridas, Arthas nos dice que lo que busca en el hielo cambiará las tornas de la batalla. Pero sus palabras no me sirvieron de consuelo, pues después de pronunciarlas... la sombría sonrisa que se dibujó en sus labios curvados me heló más que cualquier ventisca. Ruega por nosotros, Samla, y reza por nuestro mundo, Torgal" },
		[2884] = { file = "2884", len = 39.053, text = "Querida Pamela, Mañana nos plantamos en Andorhal, y me temo que esta será mi última carta para ti, mi amor. Los muertos vivientes son infatigables y nosotros, me temo, sólo somos humanos. No podemos resistir contra ellos. Pero no te preocupes, porque aunque estamos seguros de perecer, nuestra esperanza se mantiene fuerte. Y, querida mía, me consuela saber que, cuando esos terrores oscuros asalten nuestros muros y se estrellen contra nosotros, mis últimos pensamientos no serán de muerte. Pensaré en ti en mis brazos, y al fin conoceré la paz. Christoph" },
		[2885] = { file = "2885", len = 44.931, text = "Hola, $n. Resulta que he desenterrado un poco de información de esa nota. Sobre James, poco he podido encontrar, me temo. Aunque ni ella ni sus hijos sobrevivieron a la guerra, sí lo hizo su hermano, un hombre llamado Alexander Calder; puedes encontrarlo en la Caverna Perdida de Ironforge, estudiando la peligrosa magia de la Legión Ardiente. También tenía una prima a la que estaba muy unida, una mujer ahora conocida como Deze Snowbane, que promueve la batalla por la Cuenca de Arathi dentro de Orgrimmar. Deberías visitar a alguno de ellos la próxima vez que estés por la zona. Estoy seguro de que les interesará oír hablar de su Amelia perdida, aunque sólo sea eso." },
		[2886] = { file = "2886", len = 43.363, text = "Saludos, $n. Pensé que te interesarían los resultados de mi investigación. Resulta que tanto a Reuben como a Leagrem les sobrevive -por así decirlo- su familia. Incluso si ya están al tanto del destino del soldado perdido, visitar a uno de ellos puede resultar una empresa digna. Puedes encontrar a la ex mujer de Reuben, Joanna Whitehall, en el Barrio de la Guerra de la Ciudad Subterránea, donde pasa la mayor parte del tiempo. No sé si será muy receptiva a la noticia. En cuanto a Leagrem, su tía se convirtió en la matrona del orfanato de Stormwind, una posición admirable. Sea cual sea tu camino en la vida, te deseo la mejor de las suertes." },
		[2887] = { file = "2887", len = 36.101, text = "$n, espero que esta carta te encuentre bien. El padre de Samla guía a los Desamparados y Trolls que peregrinan a Thunder Bluff en los caminos de su fe. Se llama Miles Welsh, y puedes encontrarlo con sus compañeros no muertos en los Pozos de la Visión. A Torgal, mientras tanto, le sobrevive su prima, Elissa Dumas. Es una mujer solitaria por lo que he llegado a entender; pasa sus días en el Templo de la Luna en Darnassus. Te insto a que visites a quien puedas, $n. Puede que nunca se hayan enterado del destino de Torgal o Samla." },
		[2888] = { file = "2888", len = 27.69, text = "El Custodio te pasó la carta que descubriste, $n, y pensé que te gustaría recibir una actualización. El último miembro superviviente de la familia del \"Vargus\" mencionado ha sido rastreado hasta el desierto de Silithus, morando en Cenarion Hold. Se hace llamar Garon Hutchins. Deberías hablar con él durante tu próxima excursión a los páramos. Puede que le interese escuchar lo que hemos aprendido." },
		[2889] = { file = "2889", len = 27.742, text = "Saludos. Por fin he encontrado tiempo para investigar la misiva que encontraste en el Azote. La hermana de Maxwell, Zarena Cromwind, regenta una pequeña armería en la Bahía del Botín. No estoy seguro de lo cercana que era a su hermano, pero si te encuentras de paso, deberías concertar una reunión. El cierre de estos asuntos es precioso y raro en estos tiempos." },
		[2890] = { file = "2890", len = 35.683, text = "Por fin he desenterrado información sobre el antiguo soldado con el que luchaste. El rastro fue difícil de seguir, ya que este árbol genealógico en particular no estaba bien documentado, pero por fin he encontrado un pariente de sangre. ¿Crees que el cuidador Alen de la Capilla Esperanza de la Luz es, de hecho, hijo de Christoph? Podría aliviar su mente saber de su padre. Si alguna vez vuelves a estar al servicio del Amanecer Argentino en las Tierras Plagadas, por favor, habla con él. Sería una amabilidad." },
		["n0222fad5-b7c1-4569-a4ce-73a39738b0de"] = { file = "n0222fad5-b7c1-4569-a4ce-73a39738b0de", len = 21.577, text = "\"Tras la batalla, las fuerzas de Tortheldrin quedaron dispersas y desorganizadas. La mayoría se dedicó a intentar recuperar el control de la ciudad, y esta distracción permitió a los rebeldes que quedaban escapar y reagruparse. Sin ningún otro lugar adonde ir, el Shal'nan condujo lo poco que quedaba de sus fuerzas hacia el oeste, en dirección a la costa\"." },
		["n06f1bc7e-f852-4fd6-b51e-26e3b99772ec"] = { file = "n06f1bc7e-f852-4fd6-b51e-26e3b99772ec", len = 32.366, text = "Informe sobre la situación de los wendigos en las cuevas cercanas a Kharanos Escrito por la montaraz Gretchen a partir de los hallazgos del montaraz Cornelius Los wendigos rara vez salen de sus cuevas, pero ha habido informes de ataques a civiles en los alrededores de asentamientos cercanos, como Kharanos y Las Birras. Parecen estar cada vez más agitados en su búsqueda de alimento. Ya hemos perdido a uno de los nuestros intentando contenerlos. Aunque la eliminación total de las bestias es inviable," },
		["n0c41f493-c24c-40e9-afc1-b09cf3637400"] = { file = "n0c41f493-c24c-40e9-afc1-b09cf3637400", len = 45.636, text = "La Plaga ha traspasado las fronteras de El Baluarte y la estación oriental. Sus filas aumentan cada día. No doy crédito a cómo han podido fallar de esa forma nuestras defensas. Como señalé en mis anteriores informes, el insignificante destacamento de guardas destinados a Rémol es insuficiente para lo que nos espera. La cuestión no es si seremos superados, sino cuándo. Y, una vez que caiga Rémol, pasará a convertirse en el centro de mando perfecto para sitiar Entrañas. Más que solicitar, exijo que se desplieguen refuerzos desde sus lujosos puestos en Entrañas para controlar la situación mientras todavía estamos en disposición de hacerlo. Guardia de la muerte Dillinger" },
		["n0e666a6a-0997-496c-a762-b62b13cef545"] = { file = "n0e666a6a-0997-496c-a762-b62b13cef545", len = 32.81, text = "Cuando los viejos árboles del bosque encantado fueron arrancados y derribados, la tierra tembló. Los bosquecillos y los claros al cuidado de los hijos y las hijas de Cenarius, y las torres de piedra de los hijos de las estrellas cayeron por tierra. Estaba nuestra reina, radiante incluso en la desesperación, en el caos de las batallas. El cielo encantado mudó sus colores con la descarga de la magia, con explosiones que amenazaban con destruir el mundo. El hermano luchó contra el hermano." },
		["n0f6afa34-e890-4e06-966d-2ef2c6247550"] = { file = "n0f6afa34-e890-4e06-966d-2ef2c6247550", len = 7.497, text = "mandala dorados'no do fal mush t'as'e a ni banthalo aman dur fandu fal Shar'adore dur ethala dur neph'o..." },
		["n1f034ba4-227a-431e-9332-d0391dffe448"] = { file = "n1f034ba4-227a-431e-9332-d0391dffe448", len = 16.065, text = "Al tocar el pequeño cristal blanco, oyes unos sonidos débiles en el viento. Se trata de algún tipo de grabación\010. \"La rebelión de Eldre'Thalas, segunda parte\"" },
		["n1f1023f1-3606-4f7f-aecb-9e015cb72cb1"] = { file = "n1f1023f1-3606-4f7f-aecb-9e015cb72cb1", len = 45.584, text = "Ira Valor, acechadora forestal Ira se encargó de reunir comida y provisiones en los bosques cercanos cuando su padre cayó enfermo. Aunque los recursos no escaseaban, tenía tantas probabilidades de encontrar comida como de convertirse en ella. Con el paso de los años, hizo de los bosques su hogar, hasta el punto de preferir pasar el tiempo en ellos antes que en el Cerro del Cuervo. Los viajeros que se perdían en el bosque contaban historias de una sombra que parecía abrirles la senda de vuelta al camino. Nunca hubo confirmación sobre su identidad, pero los rumores se extendieron como la pólvora. Se dice que Ira sigue en el bosque, ofreciendo una mano amiga a quienes caen presa de las bestias que allí habitan." },
		["n262e77bf-b3d1-4ea4-8939-54061c7d8dda"] = { file = "n262e77bf-b3d1-4ea4-8939-54061c7d8dda", len = 34.377, text = "\"Sea cual sea la verdad, está claro que nuestros benefactores no desean hablar de Al'Akir ni de sus siervos, y se apresuran a desestimar todos los rumores sobre la presencia del Señor del Viento como meras fantasías que no merecen ser tomadas en serio. Nos aseguran que no debemos preocuparnos por tales asuntos aquí, y que nuestro pueblo está a salvo en las Islas de los cielonatos. Aunque esto supone un consuelo solemne para muchos, también plantea una pregunta inquietante: ¿qué es, exactamente, lo que nos están ocultando los espíritus de viento?\"." },
		["n29b4aa1f-4d2c-40c8-a1ba-3eb38b900fd7"] = { file = "n29b4aa1f-4d2c-40c8-a1ba-3eb38b900fd7", len = 15.569, text = "Al tocar el pequeño cristal blanco, oyes unos sonidos débiles en el viento. Se trata de algún tipo de grabación\010. \"La rebelión de Eldre'Thalas, cuarta parte\"" },
		["n2bc07cae-0777-423d-bff1-c92d7b182798"] = { file = "n2bc07cae-0777-423d-bff1-c92d7b182798", len = 20.506, text = "\"Hubo quienes se opusieron abiertamente al plan del príncipe de canalizar una fuente de energía demoníaca para alimentar su red de focos cristalinos. Muchos de los detractores eran miembros de familias nobles que intentaron utilizar su influencia para volver la opinión pública en contra de la casa Tortheldrin y de los planes del príncipe\"." },
		["n32235ecf-83b8-4b89-972e-6e321ae610e6"] = { file = "n32235ecf-83b8-4b89-972e-6e321ae610e6", len = 36.702, text = "Aunque hayas llegado a Forjaz por desesperación, la Luz nunca abandona a aquellos que lo necesitan. Con el tiempo, tu devoción crecerá y aprenderás a sentir la calidez de la Luz. Nuestros primos entre los gnomos son bienvenidos en nuestros rangos, al igual que cualquier enano robusto. Percibo que tienes el don de canalizar la Luz, y esta es una cualidad especial que deberías alimentar. Cuando tengas tiempo, ven a buscarme. Estaré en la parte trasera de Yunquemar, justo encima de la colina. Silo Khalder, instructor de sacerdotes" },
		["n336026dd-204b-4be6-8080-14366bd9ed1f"] = { file = "n336026dd-204b-4be6-8080-14366bd9ed1f", len = 24.973, text = "El culto nos pilló por sorpresa. Cogieron a Raani totalmente desprevenida, y a Arvensus le clavaron una espada en el estómago. En cuanto a mí, recibí un rayo en el pecho y perdí el conocimiento. Ni siquiera se molestaron en rematarme... Supongo que dieron por hecho que mis heridas acabarían conmigo. A fin de cuentas, también yo creo que puede ser así." },
		["n39db806d-47eb-44f1-9570-eab65b6f8880"] = { file = "n39db806d-47eb-44f1-9570-eab65b6f8880", len = 10.423, text = "LISTA DE TAREAS Preparar el equipo para salir de caza Fabricar ganchos para el cinturón de Grund Reparar las gafas de soldar Enviar una carta a mamá Página 45" },
		["n3dcdc025-cb17-4d5c-8602-2ddcac00c69b"] = { file = "n3dcdc025-cb17-4d5c-8602-2ddcac00c69b", len = 35.135, text = "\"El príncipe se opuso con vehemencia a la idea de una senda alternativa para combatir la dependencia de su pueblo respecto a la magia. Afirmó que los llamamientos a adoptar esta magia naturalista no eran más que propaganda difundida por usurpadores ilegítimos del vacío trono de la reina Azshara. Junto a sus partidarios, tachó la magia druídica de vil y bárbara, totalmente indigna de las orgullosas y antiguas tradiciones de los Altonato. Sin embargo, la práctica del druidismo comenzó a arraigarse en los márgenes de la sociedad de Eldre'Thalas y, con ella, la rebelión siguió creciendo\"." },
		["n42311f20-2f31-4b1f-a0ac-642597bcd7ee"] = { file = "n42311f20-2f31-4b1f-a0ac-642597bcd7ee", len = 40.934, text = "Al tocar el cristal resplandeciente, sientes una ráfaga de viento a tu alrededor que te hace llegar las siguientes palabras\010: Los Formavientos te han estado observando con atención, y ha llegado el momento de que des el siguiente paso como $c. Los espíritus de viento han desaparecido de la Isla de Zephras, y recae en nosotros el deber de enfrentarnos a los peligros del plano elemental para traerlos de vuelta. No hay deber más sagrado que este, y nuestra supervivencia depende de ello. Búscame en Thendal, cerca del centro urbano. Me encargaré de que recibas entrenamiento. -Formavientos Boro, instructor de chamanes" },
		["n4324d43b-1480-41f6-9ee8-199d1464e8a6"] = { file = "n4324d43b-1480-41f6-9ee8-199d1464e8a6", len = 30.197, text = "\"El príncipe Tortheldrin empezó a frustrarse, temiendo que las demoras y los eternos debates provocaran un mayor deterioro de su reino. Por ello, su respuesta ante esta resistencia fue rápida y brutal. En el transcurso de una sola y sangrienta noche, se llevó a cabo una purga que supuso la destrucción total de docenas de casas nobles. Todos aquellos que se opusieron públicamente al príncipe fueron silenciados de forma abrupta, y linajes enteros desaparecieron de la noche a la mañana\"." },
		["n46054ee4-0a08-4521-be77-74ddce042b48"] = { file = "n46054ee4-0a08-4521-be77-74ddce042b48", len = 18.913, text = "Illidan, que también había sobrevivido al Diluvio, había subido a la cima del Monte Hyjal mucho antes que Malfurión y sus elfos de la noche. En su locura por conservar un reducto para la magia en el mundo, Illidan volcó en el lago de la montaña el contenido de sus viales: las preciosas aguas del Pozo de la Eternidad." },
		["n4d105205-649c-46fe-8167-38a13f094e16"] = { file = "n4d105205-649c-46fe-8167-38a13f094e16", len = 30.276, text = "Desaparecido: Cabo Keeshan Fue visto por última vez durante la sangrienta batalla del Fuerte de Petravista. Según los informes, fue arrastrado por los orcos Roca Negra. Se cree que permanece retenido como prisionero de guerra en el campamento Roca Negra, al norte de Villa del Lago, justo al oeste del paso que conduce a las Estepas Ardientes. Por mandato del magistrado Salomón, todo aquel que colabore en el rescate del cabo Keeshan será recompensado por el Alguacil Marris." },
		["n4e0c55d7-0cb5-47bc-a216-265516b9b8c6"] = { file = "n4e0c55d7-0cb5-47bc-a216-265516b9b8c6", len = 35.161, text = "Anoduna terro belore, fal talah do fal neph'anis dor dorini talah fal neph'o do fal fandu'talah talah fal Thus Dorini. Thus bandu lo ethala dur Balah, dor fal fandu'tala dorini, Al'shar a thera do ri aman, fandu'tala do tal talah dorini shar'adore do tal dorini. Talah fal dorini fal Thus, fal talah do fal neph'anis, fandu'talah dur Balah, t'ase'mushal tal alah'ni, su fulo tal al'shar lo dath'ana ni bandu do ri balah neph'anis dur ri aman. Ni thoribas, ethal belore il'amare a u'phol'belore" },
		["n5008e97b-e943-4576-adb8-33622ea465b5"] = { file = "n5008e97b-e943-4576-adb8-33622ea465b5", len = 16.614, text = "Saludos: La Alianza se alegra de tu llegada y te otorga permiso para viajar con total libertad por sus tierras. Este documento te servirá como guía para llegar al resto de ciudades pertenecientes a nuestra alianza." },
		["n52aa7754-c4d3-4800-a102-7d9eaafbbb36"] = { file = "n52aa7754-c4d3-4800-a102-7d9eaafbbb36", len = 22.335, text = "En esta misma sala encontrarás a Vol'jin de la tribu Lanza Negra. Los trols Lanza Negra son amigos leales de los orcos. Nuestro vínculo se selló con sangre en el fragor de la batalla durante nuestra huida de las tierras humanas hasta el continente del este. Trátalo con respeto y él hará lo mismo. Si le faltas al respeto... Bueno, yo de ti no lo haría." },
		["n53d3c131-a7ce-4e73-af64-54f0b7920d32"] = { file = "n53d3c131-a7ce-4e73-af64-54f0b7920d32", len = 19.461, text = "\"Agradezco todo lo que habéis sacrificado, todo lo que habéis construido y todo lo que me habéis enseñado para ser una mejor persona. Todos vosotros representáis la inquebrantable determinación del pueblo shen'dorei. Prosperaremos en este nuevo y hermoso mundo y, juntos, alcanzaremos nuevas cotas\"." },
		["n5439151c-7329-4f1e-a408-43b001e6f07f"] = { file = "n5439151c-7329-4f1e-a408-43b001e6f07f", len = 28.709, text = "Conociendo de sobra hacia dónde conducirían los implacables planes de Illidan, Malfurión decidió neutralizar de una vez por todas a su hermano enloquecido por el poder. Con la ayuda de Cenarius, Malfurión encerró a Illidan en un gran túmulo subterráneo, en el que permanecería encadenado e impotente hasta el final de sus días. Para garantizar el confinamiento de su hermano, Malfurión encargó al joven guardián Maiev Cantosombrío la tarea de vigilar personalmente a Illidan." },
		["n557f616f-7abc-407d-a2e0-4894df59a410"] = { file = "n557f616f-7abc-407d-a2e0-4894df59a410", len = 40.15, text = "\"Al final se logró evitar la destrucción total gracias a la intervención de los rebeldes, pero a costa de un precio muy alto. La batalla se cobró incontables vidas en ambos bandos, pero fueron los rebeldes quienes sufrieron las mayores pérdidas. El propio Shal'nan fue el único que sobrevivió al enfrentamiento final en el santuario de Tortheldrin. Las personas más cercanas a él han documentado que las heridas que sufrió durante aquella última batalla lo dejaron marcado de por vida. En los siglos transcurridos desde aquellos días oscuros, el Shal'nan nunca ha vuelto a hablar de lo ocurrido, y se muestra retraído y melancólico cuando se le pregunta al respecto\"." },
		["n55f127eb-c73c-4a25-adfb-80f049eee90b"] = { file = "n55f127eb-c73c-4a25-adfb-80f049eee90b", len = 33.097, text = "Darnassus está al otro lado del mar, en la costa del norte de Kalimdor. La propia ciudad descansa sobre la copa del gran árbol Teldrassil. La ruta más segura para ti es por el puerto al oeste de Ventormenta. Sube al barco del muelle más al sur hasta el puerto de Auberdine. Al llegar, dirígete a la parte norte de los muelles de Auberdine y toma otro barco hasta la aldea de Ru'theran, donde encontrarás un transportador mágico que te llevará a la ciudad. Explora Darnassus y habla con Tyrande Susurravientos, la suma sacerdotisa de Elune." },
		["n581b0908-37ac-4be7-8bc8-05ab9e6365c6"] = { file = "n581b0908-37ac-4be7-8bc8-05ab9e6365c6", len = 32.209, text = "Cuando los ejércitos trol se desmoronaron e intentaron huir, las tropas de Thoradin les dieron caza y aniquilaron hasta el último de los soldados trol. Los trols jamás se recuperarían por completo de su derrota y la historia jamás volvería a presenciar su ascenso como nación. Seguros de que Quel'Thalas estaba a salvo de la destrucción, los elfos prometieron lealtad y amistad hacia la nación de Arathor y el linaje de su rey, Thoradin. Los humanos y los elfos establecerían una relación pacífica durante los próximos siglos." },
		["n5c0e799e-2955-4261-aa2d-ca51a07b0033"] = { file = "n5c0e799e-2955-4261-aa2d-ca51a07b0033", len = 32.836, text = "\"Por lo tanto, renuncio a mi cargo como gobernante para ceder el gobierno de las Islas de los Cielonatos a un consejo de sabios cuidadosamente seleccionado. Una vez finalizado el periodo de transición, tendréis la oportunidad de elegir a vuestros propios líderes, y vuestras voces determinarán el rumbo a seguir a partir de entonces. Habéis demostrado ser capaces de gobernaros a vosotros mismos mejor de lo que jamás podría hacerlo ningún rey, reina, príncipe o soberano individual... y eso me llena de un profundo orgullo\"." },
		["n5d3eb146-8d0f-455c-857a-7d5376b48bbc"] = { file = "n5d3eb146-8d0f-455c-857a-7d5376b48bbc", len = 21.76, text = "Esta garra petrificada se encontró en las costas del sur de Tuercespina. Los ecologistas creen que la garra pertenece a un antiguo roca de sol. Si bien las criaturas juegan un papel preponderante en la primitiva mitología tauren, la existencia de esta garra sugiere que realmente existieron en algún momento de la historia." },
		["n6145630e-ecd3-44df-a910-babdbcf85201"] = { file = "n6145630e-ecd3-44df-a910-babdbcf85201", len = 23.014, text = "Los ejércitos unidos de los elfos y los humanos se enfrentaron a las incontenibles bandas de guerra trol al pie de las montañas de Alterac. La batalla duró varios días, pero los constantes ejércitos de Arathor no se cansaban ni cedían un ápice de terreno al ataque trol. Los señores élficos consideraron que había llegado el momento de liberar los poderes de su magia sobre el enemigo." },
		["n6188d881-ec2a-45b3-bcae-e3958a5941b9"] = { file = "n6188d881-ec2a-45b3-bcae-e3958a5941b9", len = 42.162, text = "Silvia Valor, guardia del Cerro del Cuervo Silvia Valor ya era toda una heroína local cuando le ofrecieron unirse a la guardia. Si había algo que no podía soportar más que nada en el mundo, eran los oportunistas que se aprovechaban de la gente en apuros. Bandidos, estafadores, agitadores... Daba igual. Silvia acababa con ellos por tratar de sembrar el caos en su querido hogar. Era lógico que se le asignara un puesto de verdadera autoridad para que pudiera llevar a la práctica su visión de la justicia. Se dice que, hasta su último aliento, nunca abandonó las granjas y los hogares del Bosque del Ocaso. Y que quizá su vigilia tampoco acabara tras su muerte..." },
		["n62e71863-56f6-4a32-bf0e-4b928ed1af85"] = { file = "n62e71863-56f6-4a32-bf0e-4b928ed1af85", len = 26.723, text = "Sigues hojeando el libro y das con un diagrama que ocupa dos páginas enteras\010. Modificaciones del sistema de armas Torreta de hielo: operativa Lanzallamas: operativo Pulso eléctrico: operativo Aerosol radiactivo: operativo Rifle automático: operativo Haz láser cercenador: EXPERIMENTAL Cañón sónico: EXPERIMENTAL Rayo fásico: SOLO CONCEPTO Página 34 Página 35" },
		["n630846b3-f73b-4c74-8875-7595b3514234"] = { file = "n630846b3-f73b-4c74-8875-7595b3514234", len = 11.86, text = "Cuando hayas conocido al resto de líderes de la Alianza, lord Fordragón quiere que te presentes ante él aquí, en el castillo. Te deseo buena suerte en tus viajes, visitante de los cielonatos." },
		["n63322625-66c6-4433-99d6-44709e8ec5fd"] = { file = "n63322625-66c6-4433-99d6-44709e8ec5fd", len = 40.882, text = "\"El mensaje de resistencia difundido por el Shal'nan comenzó a ganar peso por toda Eldre'Thalas, debido en gran parte a la humillación pública que el príncipe sufría casi a diario a manos de las operaciones rebeldes. La idea de una forma de vida alternativa y más naturalista también comenzó a extenderse rápidamente por el reino durante aquellos días. Esto se vio muy influido por el ejemplo de los druidas Cenarion, los cuales habían tomado el control del gran imperio kaldorei al norte del continente. Incluso había rumores de que los rebeldes contaban con el apoyo de agentes encubiertos enviados por el nuevo líder de facto de los elfos de la noche: el archidruida Malfurion Tempestira\"." },
		["n65574f68-6abb-4da9-b74e-76f74a0fe8fe"] = { file = "n65574f68-6abb-4da9-b74e-76f74a0fe8fe", len = 22.648, text = "\"Últimamente, los magistri de la Orden Eminente se muestran cada vez más recelosos ante las intenciones de los espíritus de viento e insisten en que es necesario comprender mejor todos los poderes y peligros propios de este reino. Aunque esos peligros se encuentren ahora lejos de nosotros, sostienen que ese conocimiento nos preparará mejor para afrontar el futuro\"." },
		["n66288054-3c98-4808-95ff-23fd599fa313"] = { file = "n66288054-3c98-4808-95ff-23fd599fa313", len = 15.595, text = "Al tocar el pequeño cristal blanco, oyes unos sonidos débiles en el viento. Se trata de algún tipo de grabación\010. \"Un fragmento del discurso de Shal'nan durante la ceremonia de inauguración del Santuario de los Cuatro Vientos en la Isla de Zephras\"." },
		["n67ccfd46-09e2-4ffd-a1ad-8c5856b97d5f"] = { file = "n67ccfd46-09e2-4ffd-a1ad-8c5856b97d5f", len = 31.216, text = "Ya has escuchado la llamada de algo más grandioso que tú: la de los elementos. Los enanos tenemos una fuerte conexión con la tierra, pero, con el debido entrenamiento, podemos aprender a hablar con todos los elementos. Los elementales pueden ser exigentes y difíciles, pero estoy aquí para enseñarte a comunicarte con ellos. Reúnete conmigo en Yunquemar y te enseñaré a escuchar y hacerte oír por los elementos. -Teo Mazatormenta, instructor de chamanes" },
		["n6a530ab3-efd1-4487-aa83-f9fd179966a3"] = { file = "n6a530ab3-efd1-4487-aa83-f9fd179966a3", len = 41.9, text = "Si alguien encuentra esto alguna vez, le ruego que haga todo lo posible por detenerlos. A fecha de esta nota mal escrita, apenas quedaban unos pocos en la torre cuando me tuve que alejar a hurtadillas. Además, pido que intente recuperar la pluma de la suerte de Raani de su cuerpo. Le gustaba contar historias fantásticas sobre cómo se la había arrancado a una especie de pájaro de fuego y creo que querría asegurarse de que volviera a casa. Si, además, esa persona tuviera la ocasión de buscar el sello familiar de Arvensus Cantosombrío en su cadáver, le agradecería mucho que lo hiciese. Su tío es el sumo anciano Cantosombrío, y seguro que él querría que se devolviera a la familia." },
		["n6becd0e6-bf22-4f51-a16c-0e29a1f7dd5c"] = { file = "n6becd0e6-bf22-4f51-a16c-0e29a1f7dd5c", len = 30.537, text = "\"Con la fundación de nuestro nuevo hogar aquí, entre las nubes, nos adentramos en una nueva era de paz y prosperidad para nuestro pueblo. Todos hemos soportado infinitas penurias hasta llegar aquí. He visto cómo nuestro pueblo se ha convertido en una sociedad resiliente y autosuficiente, lo que me llena de un orgullo que no puedo ni siquiera comenzar a describir. Sin embargo, lo que más me enorgullece es que ahora tengo claro que ya no es necesario que actúe como nuestro único gobernante\"." },
		["n70d20f30-9c13-4445-a1d4-17a8a9ee7fd3"] = { file = "n70d20f30-9c13-4445-a1d4-17a8a9ee7fd3", len = 34.743, text = "\"El Shal'nan y sus fuerzas rebeldes atacaron durante la víspera del ritual de invocación. Al considerar que era su última oportunidad de frustrar los temerarios planes de Tortheldrin, llevaron a cabo una audaz incursión en el santuario del príncipe, decididos a detener el ritual. Tal y como temían, el hechizo acabó por descontrolarse, amenazando con destruir todo el centro de la ciudad. Mientras la batalla se recrudecía, una magia salvaje devastaba las calles, abriendo portales al Vacío Abisal e invocando monstruos Arcanos que se cebaban sin piedad con los indefensos ciudadanos de Eldre'Thalas\"." },
		["n7bf411b0-1037-4ed3-883b-94af21c37493"] = { file = "n7bf411b0-1037-4ed3-883b-94af21c37493", len = 34.743, text = "\"El joven príncipe Tortheldrin planeó construir una red de focos cristalinos y utilizarlos para extraer y moldear una nueva fuente de poder de la que pudiera abastecerse nuestro pueblo. El motivo de controversia para muchos era que pretendía utilizar precisamente el poder que había estado a punto de destruir a nuestro pueblo. Su intención era extraer ese poder de un mundo demoníaco situado en el propio Vacío Abisal. Muchos temían, y con razón, que esto pudiera abrir una nueva brecha a través de la cual pudieran volver a nuestro mundo las entidades demoníacas\"." },
		["n7cc3ac6a-f8d7-4189-bfe6-411b5df64d70"] = { file = "n7cc3ac6a-f8d7-4189-bfe6-411b5df64d70", len = 37.329, text = "bendecido. No todo los nobles lucharon. Algunos permanecieron quietos, transfigurados, cuando la locura se apoderó de ellos. Poderosas ciudades y aldeas humildes cayeron a su alrededor. En Ameth'Aran, todo estaba en ruinas y la gente se aferraba al suelo, aunque esto no podía evitar su destrucción. Fue entonces cuando Athrikus Narassin, favorito de Azshara, apareció para guiarlos y conducirlos a un lugar seguro. Mediante un encantamiento, podría protegerlos. Mientras a su alrededor, el hermano y la hermana, el padre y la madre perecían," },
		["n7eae769e-c850-4233-b63d-beace4164086"] = { file = "n7eae769e-c850-4233-b63d-beace4164086", len = 35.553, text = "Hermano Haalien: ¡Ha llegado el momento de demostrar tu valía a los Al'Aketh! Adéntrate en Ventosombra y localiza el pilón. Has expresado tus inquietudes acerca de los druidas, y la plana mayor de nuestra orden te ha escuchado. Llévate a estos fieles soldados en tu justa misión, y dad muerte a los druidas con presteza, no sea que interfieran en nuestros planes. Tenemos ojos y oídos en Valanaar que nos confirmarán si habéis tenido éxito. ¡Se acerca la hora de la verdad! ¡No habrá quien nos detenga! -N" },
		["n7ef2fb02-8158-451d-a277-b18196894360"] = { file = "n7ef2fb02-8158-451d-a277-b18196894360", len = 36.075, text = "$N: El Viejo Ojofuego es una criatura mágica de la noche y, como tal, necesitamos un arma mágica que también lo sea. Podemos imbuir dicha arma de la luz de la luna llena y utilizarla para volver la magia oscura que impulsa a esta criatura en su contra. Para ello, necesitamos unos materiales específicos con los que forjar una espada de plata lunar brillante capaz de destruir este mal por completo. No será tarea fácil, pero has demostrado tener un enorme potencial, así que confío en que serás capaz de conseguir lo que necesitamos." },
		["n826ab865-6339-4c6b-9476-2c83c5f079f9"] = { file = "n826ab865-6339-4c6b-9476-2c83c5f079f9", len = 38.374, text = "A la memoria de mi querido mentor, Horatio M. Montgomery, M.D. curandero, maestro y amigo. 50 BTFT - 25 ATFT \"El mundo está lleno de gente enferma y cansada. Nuestra labor, como curanderos, o mejor dicho, como hombres y mujeres del mundo de la medicina, es librarlos a todos de sus males imaginarios.'\" - H.M.M., Médico, JD, gran maestro agricultor, bailarín extraordinario, amigo de los animales" },
		["n86ade330-a0fb-4715-bd34-5826a6e3ac14"] = { file = "n86ade330-a0fb-4715-bd34-5826a6e3ac14", len = 26.462, text = "Recuperado de las ruinas submarinas de Suramar, este astrolabio funcional fue fabricado por los elfos de la noche altonatos hace doce mil años. Los altonatos, obsesionados con la magia, lo oculto y la astronomía, desarrollaron una serie de ingeniosos aparatos. Este dispositivo proporciona valiosa información sobre el saber científico de los antiguos elfos de la noche." },
		["n885bab42-60e7-459a-b4cd-4182468502a6"] = { file = "n885bab42-60e7-459a-b4cd-4182468502a6", len = 21.185, text = "Cuando los altos elfos hacían frente al feroz ataque de los trols, los dispersos humanos nómadas de Lordaeron lucharon por consolidar sus propias tierras tribales. Las antiguas tribus humanas atacaban asentamientos hermanos sin contemplar valores tales como la unificación racial o el honor." },
		["n8905f1b4-caa3-449c-9b57-c219af16e762"] = { file = "n8905f1b4-caa3-449c-9b57-c219af16e762", len = 43.703, text = "\"Gran parte de la flora y la fauna de las Islas de los Cielonatos ha sido moldeada por las fuerzas elementales que reinan en el reino del Muro Celeste. Muchas criaturas que antes estaban ligadas a la tierra presentan ahora rasgos aviares, como picos, garfas y plumas. Otras han adquirido la capacidad de volar, aunque estas transformaciones siguen siendo menos comunes que otros cambios externos. Entre los shen'dorei, la influencia del plano elemental sobre el cuerpo ha sido gradual y sutil. Sin embargo, durante las últimas generaciones, los efectos se han vuelto cada vez más drásticos. Consideremos, por ejemplo, el fenómeno que ahora se conoce comúnmente como la 'bendición tocada por el cielo'\"." },
		["n90d671b6-9023-4932-acdf-4ff4acef41c1"] = { file = "n90d671b6-9023-4932-acdf-4ff4acef41c1", len = 41.822, text = "Registro de mecánico\010El pequeño diario con tapa de cuero está cubierto de aceite y manchas de grasa. Contiene bocetos de diseños y configuraciones mecánicas, con anotaciones y descripciones. Abres una página al azar\010. Este encargo me pagará las facturas durante años. Solo hace falta que se me ocurra algo para evitar que el neutralizador de oscilaciones se sobrecaliente o se haga añicos. Lo que tengo que hacer es transferir por un vórtice el exceso de calor al núcleo de combustión, pero lo he estado posponiendo porque tengo que desmantelar todo el caminante y desmontar el motor entero. Página 17" },
		["n90edecce-8838-49c3-9f42-e8065ef4ca4a"] = { file = "n90edecce-8838-49c3-9f42-e8065ef4ca4a", len = 19.383, text = "fue Asterion, que vivió entre el pueblo de Balshal’Aran, y fue muchas veces a Ameth’Aran para conocer las necesidades y los deseos de su gente. Y así fue, junto al Pozo de la Eternidad, que las ciudades gemelas crecieron y prosperaron, mientras que el mundo bajo las estrellas caía lentamente en la locura." },
		["n944a49a6-b57e-4a4c-ae39-581dfe133bae"] = { file = "n944a49a6-b57e-4a4c-ae39-581dfe133bae", len = 29.91, text = "Saludos, $N. Has demostrado ser una cazadora prometedora, y me gustaría asegurarme de que recibes el entrenamiento adecuado. Los forestales hacen un buen trabajo manteniendo a la naturaleza a raya en la Arboleda Thendal, pero no podemos decir lo mismo más allá de nuestras fronteras. Búscame por el centro de la ciudad tan pronto como te sea posible. La naturaleza te llama. -Tai'ree Vista Lejana, instructora de cazadores" },
		["n9672f725-f7ca-43f5-b472-317c3e0b25b3"] = { file = "n9672f725-f7ca-43f5-b472-317c3e0b25b3", len = 22.988, text = "Tarrel, amado mío: No pasa un día en que no me quede ensimismada pensando en esas trenzas broncíneas, esa risa atronadora o esos antebrazos musculosos. Debes acudir a mi encuentro en Auberdine con el próximo barco. Estamos hechos el uno para el otro. ¡En tu corazón, sabes que es cierto! Tuya si así lo deseas, Hollee" },
		["n989c840a-8669-4047-98fc-b6971cdc70ff"] = { file = "n989c840a-8669-4047-98fc-b6971cdc70ff", len = 21.159, text = "Mientras viajaban en silencio, examinaron los restos de la catástrofe y comprendieron que sus pasiones habían sido la causa de la destrucción del planeta. Aunque Sargeras y su Legión habían sido aniquilados por la destrucción del Pozo, Malfurión y sus compañeros sobrevivieron para reflexionar sobre el terrible precio de la victoria." },
		["n9d32306a-cf3e-4439-9c06-fc8ce83987c3"] = { file = "n9d32306a-cf3e-4439-9c06-fc8ce83987c3", len = 43.311, text = "Nuestros aliados renegados tienen su hogar en la región conocida como Claros de Tirisfal, en el continente del este. Encontrarás la ciudad de Entrañas bajo las ruinas de lo que antaño fue Lordaeron. Para llegar a Tirisfal, sal de la ciudad por la puerta del sur y dirígete al este, hacia la torre del zepelín. Embarca en el zepelín de la zona sur de la torre y, tras cruzar el gran mar, llegarás a Rémol. Desde allí, solo debes dirigirte al norte hasta las ruinas de Lordaeron. Encuentra el ascensor, desciende hasta las profundidades de Entrañas y busca a la Dama Oscura en el Barrio Real. Un aviso: La capital de los renegados puede llegar a ser... inquietante." },
		["na2ea01e6-e0b4-4302-afe2-74aa97a4bbd1"] = { file = "na2ea01e6-e0b4-4302-afe2-74aa97a4bbd1", len = 45.636, text = "\"Hoy en día, tres de cada diez niños nacidos en las Islas de los Cielonatos presentan la llamativa tez de los tocados por el cielo. En los últimos siglos, el ritmo de nuestras transformaciones físicas se ha acelerado, y muchos eruditos creen que los últimos vestigios de nuestra herencia kaldorei podrían desaparecer por completo en el plazo de dos o tres generaciones. Quizá nunca lleguemos a comprender del todo la causa de esta transformación. Sin embargo, es evidente que, al forjar nuestras vidas en el plano elemental, este, a su vez, nos está transformando. El Muro Celeste es un lugar increíble, pero esto sirve para recordarnos que aún sabemos peligrosamente poco sobre el efecto de un lugar así sobre quienes no han nacido en él\"." },
		["na417c22a-8087-48a9-8e86-ae6a5a17072b"] = { file = "na417c22a-8087-48a9-8e86-ae6a5a17072b", len = 32.679, text = "Ejecutor Zygand: En mi humilde opinión, las fuerzas de la Plaga presentes en nuestras tierras no son resultado de una defensa negligente. Llevo un tiempo observando a nuestras fuerzas en El Baluarte y la estación oriental, y sería necesario un verdadero ejército para atravesarlas. En lugar de ello, sospecho que la Plaga está siendo creada dentro de nuestras fronteras por algún enemigo oculto. Seguiré investigando este asunto con la esperanza de erradicar este problema. Kristof" },
		["na627b071-0849-4ae2-b9b4-6fdaf2005331"] = { file = "na627b071-0849-4ae2-b9b4-6fdaf2005331", len = 13.558, text = "Al tocar el pequeño cristal blanco, oyes unos sonidos débiles en el viento. Se trata de algún tipo de grabación\010. \"El misterio tocado por el cielo\"" },
		["na9d6f0a4-9117-4e0b-90e6-2d6a520c6f2f"] = { file = "na9d6f0a4-9117-4e0b-90e6-2d6a520c6f2f", len = 11.546, text = "Por increíble que parezca, hay una talla casi legible en la piel de la manzana\010. Manzana ñam ñam. Ahora coger flores yo." },
		["nabaa2e9b-b185-4bb4-9f0a-e366123de9ab"] = { file = "nabaa2e9b-b185-4bb4-9f0a-e366123de9ab", len = 37.146, text = "\"Se ha documentado que, desde nuestro ascenso a Muro Celeste, nuestro pueblo ha adoptado formas más ágiles y esbeltas, aunque esto es fruto de una evolución a lo largo de miles de años. Sin embargo, el primer caso registrado de la bendición tocada por el cielo, que hace que los niños shen'dorei nazcan con la piel de un color azul cerúleo intenso, se observó hace menos de cinco generaciones. En tan solo una generación desde su primera aparición, uno de cada veinte niños nacidos de nuestro pueblo presentaba esta curiosa alteración. Dos generaciones más tarde, esa proporción se había duplicado\"." },
		["nad2e6310-a9b9-4063-862b-ba769059cd6a"] = { file = "nad2e6310-a9b9-4063-862b-ba769059cd6a", len = 46.289, text = "Lord Grant Valor, patriarca de la familia Valor Lord Grant (que en paz descanse) fue el máximo exponente de la excelencia de la Alianza. Un líder nato, cuya mano firme guio a los habitantes del Cerro del Cuervo hacia la prosperidad. Cuando la oscuridad comenzó a tomar los bosques, fue el primero en movilizar a nuestro pueblo. Para lord Grant no existía enemigo más repugnante que los no-muertos. Patrullaba personalmente los cementerios del Bosque del Ocaso para mantener a raya a los siervos de la oscuridad. El día que recibió un golpe mortal, todos en la ciudad compartieron su dolor. Gracias al cuidado de su familia, logró volver a sus obligaciones, pero, desde entonces, una persistente dolencia le acompañaría durante el resto de sus días." },
		["naf618832-a389-4493-b388-127bfac792ec"] = { file = "naf618832-a389-4493-b388-127bfac792ec", len = 27.873, text = "\"Seguiré sirviendo a nuestro pueblo aquí, en Zephras, y dedicaré gran parte de mi tiempo a fortalecer nuestra relación con los espíritus del viento, a quienes tanto les debemos. Los espíritus elementales son sabios y maravillosos, y aún nos queda mucho por aprender los unos de los otros. Me comprometo a velar por que los shen'dorei perseveren en este reino hermoso y extraño... y a garantizar que lo hagamos con justicia y libres del yugo de cualquier tiranía\"." },
		["naf7e950d-f4fc-4196-9ac9-1c0ef5fa73bb"] = { file = "naf7e950d-f4fc-4196-9ac9-1c0ef5fa73bb", len = 26.828, text = "¡Saludos, joven druida! Estoy muy orgulloso del esfuerzo que has demostrado durante tu instrucción hasta el momento. Debes sentirte honrado por haberte unido a la Zarpa. Recibirás más lecciones similares. La siguiente estará disponible una vez que hayas alcanzado el nivel 14. En ese momento, cuando estés listo, búscame en el Alto de los Ancestros de Cima del Trueno. Turak Runatótem" },
		["nb013055b-47a3-4689-a273-c933a3344031"] = { file = "nb013055b-47a3-4689-a273-c933a3344031", len = 29.753, text = "Las potentes energías del Pozo ardieron rápidamente y se fusionaron para crear un nuevo Pozo de la Eternidad. El exultante Illidan, que creía que el nuevo Pozo era un regalo para las futuras generaciones, se sorprendió al advertir la ira de Malfurión. Este explicó a su hermano que la magia era inherentemente caótica y que su uso conduciría inevitablemente a la propagación de la corrupción y la guerra. No obstante, Illidan se negó a renunciar a sus poderes mágicos." },
		["nb43b9ad3-7d8d-4632-929a-a7813c488c9a"] = { file = "nb43b9ad3-7d8d-4632-929a-a7813c488c9a", len = 39.21, text = "Tus habilidades emergentes son demasiado rudimentarias para percibirlo, pero esta tablilla está cargada con poderosas maldiciones de sufrimiento que impiden que pueda leerla alguien indeseado. Gracias a mi poder, he sentido tus primeros pasos hacia una débil conexión con el Vacío Abisal, y por eso te ofrezco el beneficio del tutelaje. Con mi ayuda, aprenderás a mandar a los demonios e invocar llamas desde el más allá. Búscame en las profundidades de El Cubil, una vez que hayas encontrado el camino. Tengo que contarte cosas muy importantes. Nartok, instructor de brujos" },
		["nb8f421b1-6f7d-4ef0-b73e-3c984ab5ce43"] = { file = "nb8f421b1-6f7d-4ef0-b73e-3c984ab5ce43", len = 37.851, text = "Merrick Valor, observador de Villa Oscura Merrick era el hijo menor de la familia Valor. Al ser testigo de la corrupción que se cernía sobre su hogar, decidió unirse a los vigías en un intento desesperado por proteger a sus seres queridos. Aunque carecía de toda experiencia, rápidamente se labró un nombre entre sus camaradas y no tardó en ascender en las filas de los Observadores. Tenía un don para el tiro con arco, y no tardó en convertirse en uno de los defensores acérrimos de Villa Oscura. Su misión personal era mantener la seguridad en los caminos, siempre en guardia ante las criaturas cada vez más hostiles que rondaban los bosques." },
		["nb9bde131-21a6-4977-a0f7-94eefdce05b2"] = { file = "nb9bde131-21a6-4977-a0f7-94eefdce05b2", len = 33.802, text = "Cuando los elfos de la noche arribaron a las costas de la nueva tierra, advirtieron que Hyjal, la montaña sagrada, había sobrevivido a la catástrofe. Con la intención de establecer un nuevo hogar para todos, Malfurión y los elfos de la noche subieron por las laderas del Monte Hyjal y llegaron a la cima azotada por el viento. Al descender en la boscosa hondonada, entre los enormes picos de las montañas encontraron un pequeño lago de aguas mansas. Aterrorizados, descubrieron que las aguas del lago estaban contaminadas por la magia." },
		["nba963cdf-76c6-4bca-a4cd-36b6434378a9"] = { file = "nba963cdf-76c6-4bca-a4cd-36b6434378a9", len = 16.431, text = "Trotamundos de los elfos: La Horda ha tenido a bien invitarte, y el Jefe de Guerra te ha otorgado permiso para viajar con libertad por nuestro territorio. Usa esta guía para ubicarte en nuestras tierras." },
		["nbcd91173-6bc3-475a-a9b8-d05cedf22cc1"] = { file = "nbcd91173-6bc3-475a-a9b8-d05cedf22cc1", len = 52.767, text = "Querida Tabitha: Qué extraño me resulta predecir mi propia muerte. Te escribo esta nota porque desconozco la hora en la que me llevará el destino y, aunque soy consciente de que deja mucho que desear como despedida, la pluma no logra transmitir el dolor que siento al abandonarte. Cada día me despierto invadido por la pena de la que no he logrado protegerte. Lamento haber sido incapaz de proteger a nuestro querido hijo y que la tristeza me haya hecho caer en una trampa de la que no puedo escapar. Eres mi amor y mi confidente, y mi vida ha valido mucho más de lo que habría valido de no haber estado contigo. Cada día, cuando me adentro en las ruinas de nuestro antaño orgulloso hogar, temo que sea el último y, en cada ocasión, doy las gracias por poder regresar contigo. Rezo para que nos volvamos a encontrar, aunque sea durante un mero instante." },
		["nbed73d25-5594-44e5-a942-0504799c6685"] = { file = "nbed73d25-5594-44e5-a942-0504799c6685", len = 35.579, text = "\"El líder de los rebeldes era una figura misteriosa conocida únicamente como el 'Shal'nan', o 'el Velado'. Llevaba una máscara dorada sin rasgos, destinada a ocultar su identidad y proteger a sus allegados. Este elfo se convirtió rápidamente en un símbolo de rebeldía contra la opresión, y su nombre pasó a ser un grito de guerra sinónimo de rebelión. Mediante el sabotaje, la coacción y —según algunos rumores— el asesinato, los rebeldes se convirtieron rápidamente en una espina clavada en los esfuerzos del príncipe Tortheldrin por construir su red de focos cristalinos\"." },
		["nc279f75a-fc13-4f69-bcdf-befede121d1a"] = { file = "nc279f75a-fc13-4f69-bcdf-befede121d1a", len = 36.075, text = "Archidruida: $N ha prestado un gran servicio a la tierra. Los pozos de Pezuña Invernal, Tronacuerno y Bravacrín han sido purificados de los venenos de los goblins gracias a su valentía. Con el tiempo, sus aguas rejuvenecidas nutrirán a todos los que pisen las grandes llanuras de Mulgore, y la tierra se curará. Alabada sea la Madre Tierra. Te pido que le otorgues una recompensa acorde con sus esfuerzos en nombre de todos los habitantes del Poblado Pezuña de Sangre. Con suma reverencia, Mull Tronacuerno" },
		["nc746f365-b15f-42ce-a416-a01d4733a21d"] = { file = "nc746f365-b15f-42ce-a416-a01d4733a21d", len = 15.935, text = "Al tocar el pequeño cristal blanco, oyes unos sonidos débiles en el viento. Se trata de algún tipo de grabación\010. \"La rebelión de Eldre'Thalas, primera parte\"" },
		["nc92a9af8-f5d8-4d52-87ff-6f96064618b1"] = { file = "nc92a9af8-f5d8-4d52-87ff-6f96064618b1", len = 24.529, text = "Eh, tú, $c. Mueve el culo y ven a verme detrás de la abadía. No sé cómo pretende sobrevivir sin algo de orientación, y mucho menos prosperar, un $c novato como tú en esta tierra. ¡El viejo Tordrin se encargará de dártela! Si es que tienes agallas... Tordrin Hojatallo, (increíblemente apuesto) instructor de cazadores" },
		["ncb0bbeff-340c-47cb-87dc-1a7d98456abc"] = { file = "ncb0bbeff-340c-47cb-87dc-1a7d98456abc", len = 32.914, text = "Memorias de los Valor Una crónica de la familia Valor y su servicio al Cerro del Cuervo No había familia más grandiosa en todos los Reinos del Este que los Valor. Sus hazañas en defensa del pueblo al que juraron proteger fueron auténticos milagros, y su pérdida es una tragedia para el Cerro del Cuervo. Escribo este relato para que quede constancia de lo brillantes que fueron Grant, Ira, Silvia y Merrick. Que estas líneas sirvan de pequeño consuelo ante lo mucho que lamento su ausencia." },
		["nd16c1d14-a407-4527-87f7-7b2fd2603176"] = { file = "nd16c1d14-a407-4527-87f7-7b2fd2603176", len = 30.485, text = "sobre la orilla del lago, Ameth'Aran y Bashal'Aran eran los primeros, con la inspiración de Azshara, la amada reina de los kaldorei, en su creación. Ella llevó hasta sus ciudades gemelas a sus siervos privilegiados, los nobles y, para gobernarlos, designó a Athrikus Narassin, aunque él prefería pasar sus días en la Torre de Althalaxx, alejado del bullicio. Su mano derecha, una maga conocida por su destreza en las artes arcanas, así como por sus habilidades físicas," },
		["nd2ff1245-1ff9-438f-abb1-1241bf74a3c2"] = { file = "nd2ff1245-1ff9-438f-abb1-1241bf74a3c2", len = 44.722, text = "Sé cómo te llegará esta carta, y por ello te pido mis más sinceras disculpas. Sin duda alguna, enviaré a tu hermosa ciudad a todos los aventureros que pueda. Espero que su contribución compense la falta de otro tipo de apoyo en estos momentos. Nuestras tierras se ven acosadas por infinidad de enemigos. Estoy seguro de que tú mismo conoces bien esa realidad, pero ha agotado dolorosamente los recursos de los que disponemos. Estaría encantado de ayudar si la situación cambiara, pero incluso entonces estaría enfrascado en muchos otros proyectos que exigen nuestra atención prioritaria. Manteneos firmes. Estamos todos juntos en esto. - Baros Alexston Arquitecto urbano de Ventormenta" },
		["nd378519f-b57f-482c-9e8d-4170746ed41e"] = { file = "nd378519f-b57f-482c-9e8d-4170746ed41e", len = 31.295, text = "Hola de nuevo, $N. Entiendo muy bien cómo te sientes al verte en tu situación actual. El hecho de que hayas llegado tan lejos te distingue de otros paladines recién resucitados. Descubrirás que lo más difícil de tu nueva vida será redescubrir lo que perdiste en la anterior... y soportar el dolor que ello te causa. Habla conmigo en Camposanto y te ayudaré a reunir fuerzas para dar tus primeros pasos. -Aramis Manomartillo, instructor de paladines" },
		["nd42c96df-42ba-49c9-b816-52c1cafaec4e"] = { file = "nd42c96df-42ba-49c9-b816-52c1cafaec4e", len = 26.906, text = "los montaraces solicitan recursos adicionales para limitar su propagación. No podemos seguir confiando en enviar aventureros a solucionar el problema. Tarde o temprano se agotarán los alimentos, y los wendigos se verán forzados a atacar directamente nuestras aldeas. Quizás incluso la propia Forjaz. Transmite mis condolencias a la familia del montaraz Cornelius, que luchó valientemente para mantener a salvo a la gente de Dun Morogh." },
		["nd8513252-6098-4544-beb8-bf9fbf08ec5e"] = { file = "nd8513252-6098-4544-beb8-bf9fbf08ec5e", len = 42.266, text = "Al tocar el cristal resplandeciente, sientes una ráfaga de viento a tu alrededor que te hace llegar las siguientes palabras\010: La Orden Eminente te ha estado observando, $N, y creemos que tus habilidades son muy prometedoras. Los espíritus de viento han abandonado la Isla de Zephras, y, ahora más que nunca, se necesitan magos tan prometedores como tú. Si conseguimos sobrevivir a esta crisis, debemos usar nuestro conocimiento de lo Arcano para desvelar los secretos de este reino. Búscame en Thendal, en la planta baja del gran árbol. Comenzaremos tu entrenamiento. -Dorii Susurro Brillante, instructora de magos" },
		["nd882f597-38a1-4486-a253-d81dec18ae52"] = { file = "nd882f597-38a1-4486-a253-d81dec18ae52", len = 17.11, text = "Por su parte, muchos altonatos salieron ilesos del cataclismo. Se dirigieron a las costas de la nueva tierra, junto con los otros elfos de la noche. Aunque Malfurión desconfiaba de los altonatos, estaba tranquilo porque no podían causar verdadero daño sin las energías del Pozo." },
		["ndbaa1af1-b7cd-4909-8ef3-46c0dab23d23"] = { file = "ndbaa1af1-b7cd-4909-8ef3-46c0dab23d23", len = 25.94, text = "Preocupado ante la certeza de que la destrucción del nuevo Pozo conllevaría una catástrofe aún mayor, los elfos de la noche decidieron dejarlo en su lugar. No obstante, Malfurión declaró que nadie volvería jamás a practicar las artes de la magia. Bajo la mirada atenta de Cenarius, empezaron a estudiar las antiguas artes de los druidas con el propósito de sanar el planeta herido y replantar sus bosques amados en la base del Monte Hyjal." },
		["ndcbb76f1-ec0d-4343-ab2e-530c8c06bedc"] = { file = "ndcbb76f1-ec0d-4343-ab2e-530c8c06bedc", len = 26.227, text = "Saludos, $N. Desde que se marcharon los espíritus de viento, Zephras se ha visto al borde de un precipicio. Los pájaros, las bestias y hasta las raíces bajo nuestros pies nos piden ayuda. Búscame en la planta baja del gran árbol aquí, en Thendal. Te aconsejaré y entrenaré en las artes druídicas. -Xyton Ventargento, instructor de druidas" },
		["ndd4ce00c-0b63-44e2-bae0-ca036f768fc7"] = { file = "ndd4ce00c-0b63-44e2-bae0-ca036f768fc7", len = 52.95, text = "Señor Alexston de Ventormenta: Debo felicitarle por el largo camino recorrido para restaurar la ciudad de Ventormenta. Muchos de los que pasan por Auberdine hablan maravillas de su grandeza y de sus sólidos cimientos. Es precisamente este éxito el que me ha llevado a enviar esta misiva. Auberdine ha encontrado su lugar en este mundo junto al mar. Donde antes vivíamos aislados, ahora encontramos la esperanza traída por los mismos vientos que azotan nuestras costas. Quien porta este mensaje representa a uno de esos viajeros que los vientos nos han traído. Espero que pueda ayudar a su pueblo como ha ayudado al mío. A cambio, le pido que envíe provisiones y mano de obra a Auberdine para que podamos fortalecer la ciudad frente a la ira de este mundo que tanto nos ha arrebatado. - Thundris Tejevientos, Anciano de Auberdine" },
		["ne23c82f1-0936-4fbd-9994-695c3d53c864"] = { file = "ne23c82f1-0936-4fbd-9994-695c3d53c864", len = 38.504, text = "\"Cuando el cansado ejército rebelde llegó al puerto de Eldre'narr, los magistri al mando de la ciudad ya habían oído hablar de la poderosa ira de Tortheldrin, así como de su orden de matar a cualquier rebelde. En un acto de misericordia milagrosa, no hicieron nada para obstaculizar el avance de los rebeldes, a los que permitieron tomar varios barcos sin resistencia alguna. El Shal'nan comprendió que este acto de misericordia probablemente expondría a muchos habitantes de Eldre'narr a la ira de Tortheldrin, pero, aun así, aceptó este regalo inesperado con elegancia y, con el corazón apesadumbrado, condujo a su pueblo hacia el oeste\"." },
		["ne5658ef4-2671-496d-a082-d6e03e97e768"] = { file = "ne5658ef4-2671-496d-a082-d6e03e97e768", len = 28.578, text = "\"En los días inmediatamente posteriores a los disturbios ocurridos en el Pozo de la Eternidad, una gran agitación reinaba en Eldre'Thalas. Las fuerzas demoníacas que brotaron del pozo estuvieron a punto de asolar los asediados reinos élficos, arrasando la tierra y matando de manera indiscriminada. De no ser por la intervención del semidios Goldrinn y el sacrificio de innumerables héroes kaldorei, el reino de Eldre'Thalas habría sido pasto de las llamas\"." },
		["ne5aa3917-eeb1-4e4a-8d2a-2b93d253812b"] = { file = "ne5aa3917-eeb1-4e4a-8d2a-2b93d253812b", len = 42.841, text = "\"Los sabios de los Formavientos, por el contrario, depositan una confianza implícita en los espíritus y consideran que cualquier cuestionamiento de sus designios es una afrenta a nuestros benefactores. Sostienen que nuestros protectores en el Muro Celeste ya han sacrificado mucho para traernos hasta aquí y ofrecernos sustento. Afirman que, si algún conocimiento adicional fuera vital para nuestra supervivencia, lo revelarían a su debido tiempo. Esta diferencia de creencias ha dado lugar a una tensión nada desdeñable entre las dos órdenes. Sea cual sea la verdad, está claro que no estamos solos en este reino y que aún quedan muchos misterios que escapan a nuestro entendimiento\"." },
		["ne82a4782-b718-448c-83f5-b4e39a7abb48"] = { file = "ne82a4782-b718-448c-83f5-b4e39a7abb48", len = 25.496, text = "Día 1 La actividad de Ventura y Cía. sigue siendo motivo de preocupación. Sus operaciones mineras no dejan de crecer y he oído un nuevo ruido estridente que sugiere el despliegue de un nuevo y horrible constructo. Aún no los considero una amenaza para Cima del Trueno, pero si los provocan, podrían atacar el Poblado Pezuña de Sangre desde el sur." },
		["ned970455-e904-42df-a989-3af977a77a2f"] = { file = "ned970455-e904-42df-a989-3af977a77a2f", len = 13.27, text = "Al tocar el pequeño cristal blanco, oyes unos sonidos débiles en el viento. Se trata de algún tipo de grabación\010. \"Sobre el Señor del Viento\"" },
		["nededb6fa-cc22-4517-b3d1-7bcf66a04847"] = { file = "nededb6fa-cc22-4517-b3d1-7bcf66a04847", len = 15.882, text = "Al tocar el pequeño cristal blanco, oyes unos sonidos débiles en el viento. Se trata de algún tipo de grabación\010. \"La rebelión de Eldre'Thalas, tercera parte\"" },
		["nee21dab1-cfce-40f2-9732-d9a5f5cb05ec"] = { file = "nee21dab1-cfce-40f2-9732-d9a5f5cb05ec", len = 34.403, text = "Tu primera parada debería ser Forjaz, a la que puedes llegar gracias a esa maravilla tecnológica que es el Tranvía Subterráneo. La entrada del tranvía se encuentra en el Distrito de los Enanos, aquí, en Ventormenta, justo al sudoeste del castillo. El tranvía te llevará de forma segura al corazón de Forjaz. Cuando llegues, explora la ciudad y habla con el manitas mayor Mekkatorque y con el rey Magni Barbabronce en Ciudad Manitas y en la Gran Forja respectivamente. Preséntate como agente de los cielonatos y te mostrarán su hospitalidad." },
		["nee9d2980-4678-4b2f-8305-51ae8fd2e809"] = { file = "nee9d2980-4678-4b2f-8305-51ae8fd2e809", len = 44.669, text = "\"¿Quién es Al'Akir, el Señor del Viento? Los sacerdotes de la secta radical de Al'Aketh quieren hacernos creer que es el verdadero gobernante del Muro Celeste, el reino que ahora consideramos nuestro hogar. Según ellos, aquí no somos más que intrusos, y un día Al'Akir se presentará ante nosotros para ajustar cuentas por nuestra intromisión en su dominio dentro del plano elemental. Aunque tales afirmaciones puedan parecer a simple vista desvaríos de personas enloquecidas, puede que haya algo de verdad en ellas. Cuando se les pregunta por la naturaleza de Al'Akir, los espíritus de viento se muestran evasivos y agitados. El mero hecho de pronunciar el nombre del Señor del Viento parece causarles una profunda inquietud. Puede que incluso miedo\"." },
		["neea9df6d-2fc1-448a-8241-1306a79620b5"] = { file = "neea9df6d-2fc1-448a-8241-1306a79620b5", len = 25.678, text = "\"Tras el apogeo de la guerra y del Gran Cataclismo, pronto se hizo evidente la nueva realidad de un mundo privado de la magia sustentadora de la que dependía nuestro pueblo. Los Tortheldrin, la casa gobernante de Eldre'Thalas, pusieron en marcha planes para garantizar la estabilidad y la continuidad de nuestro modo de vida. Sin embargo, los métodos que pretendían emplear suscitaron una profunda preocupación entre gran parte de la población\"." },
		["nefb57278-ea65-4202-98c8-5c32e8c882fc"] = { file = "nefb57278-ea65-4202-98c8-5c32e8c882fc", len = 20.611, text = "En cuanto cesaron los combates, empezaron a subir unas cajas enormes de piedras de viento a lo alto de la torre. El líder, una especie de sacerdote, mencionó algo acerca de un ritual. Escribo esta nota para avisar a Aonda en caso de que no consiga volver a Shen'dar, pero aquí están tramando algo. Algo malo." },
		["nf345aa30-c4de-4183-80b8-81668213a7e1"] = { file = "nf345aa30-c4de-4183-80b8-81668213a7e1", len = 33.541, text = "A continuación, te recomiendo que vuelvas a Mulgore y te reúnas con Cairne Pezuña de Sangre en Cima del Trueno. Cairne es el jefe de la tribu Pezuña de Sangre de los tauren y, gracias a él, tu gente y el Anillo de la Tierra habéis recibido permiso para estableceros en Mulgore. Ya tendrías que conocer el camino a Cima del Trueno. Habla con el maestro de vuelo en el centro de Orgrimmar y sube a lomos de un dracoleón hasta Cima del Trueno. Cairne estará en la meseta central, justo al este del gran tótem que sirve de alcándara de dracoleones en la ciudad." },
		["nf3b7db85-7dc7-49fd-b453-f188d151de1b"] = { file = "nf3b7db85-7dc7-49fd-b453-f188d151de1b", len = 35.683, text = "Atacaremos la ciudad de Rémol justo antes del alba. La fuerza auxiliar prenderá fuego a la torre del zepelín a modo de distracción. Cuando se propaguen las llamas y se alejen los defensores de la ciudad, el grueso del ejército, liderado por el lugarteniente, atacará desde el norte. Los objetivos principales son el magistrado y los civiles. Destruid cuanto veáis e incinerad los cuerpos. Dicen que los Renegados no sienten miedo alguno, pero nosotros haremos que vuelvan a temer a la Luz, hermanos y hermanas. ¡Por Lordaeron!" },
		["nf6e19259-62bd-4cbd-aed0-fdb3ed2a22d1"] = { file = "nf6e19259-62bd-4cbd-aed0-fdb3ed2a22d1", len = 43.52, text = "\"El terror que provocó tan brutal represión hizo que un silencio consternado se apoderara de Eldre'Thalas. Todas las conversaciones sobre el plan del príncipe Tortheldrin cesaron de golpe... Al menos, durante un tiempo. Por desgracia para él, cuanto más oprimían los tiranos a su pueblo, más fuerte ardía la llama de la resistencia. Hubo quienes se opusieron para garantizar que nuestro pueblo no repitiera los mismos errores que la reina Azshara. Un grupo de eruditos, antiguos miembros de la orden de los Shen'dralar, se reunió en secreto para forjar un pacto. Tras jurar que detendrían al príncipe por cualquier medio necesario, comenzaron a sembrar las semillas de la rebelión\"." },
		["nfc037ec9-8093-4201-aa17-48660f59d137"] = { file = "nfc037ec9-8093-4201-aa17-48660f59d137", len = 27.193, text = "Los escasos elfos de la noche que sobrevivieron a la explosión se subieron a rústicas balsas y lentamente se dirigieron a la única masa de tierra visible. De algún modo, por la gracia de Elune, Malfurión, Tyrande y Cenario sobrevivieron al Gran Diluvio. Los maltrechos héroes guiaron a sus compañeros supervivientes y se establecieron en un nuevo lugar." },
		["nfedbb732-a293-4bcd-ab63-a954606ef38f"] = { file = "nfedbb732-a293-4bcd-ab63-a954606ef38f", len = 15.386, text = "Lady Mara Fordragon Alta sacerdotisa de Ventormenta Patrona de los refugiados que huyeron de Lordaeron tras la Primera Guerra. Fue la brillante madre de nuestro futuro. Que descanse en la Luz." },
		["nff369097-c25d-445d-9ffa-561ccd669fcc"] = { file = "nff369097-c25d-445d-9ffa-561ccd669fcc", len = 27.037, text = "Lady Cassandra Valor, madre amantísima y amada esposa Poco se sabe sobre Cassandra, salvo su amor por su familia. Crio a unos hijos valientes y cuidó de un marido poderoso, lo que ha llevado a algunos a pensar que la grandeza de la familia se debía exclusivamente a ella. Un halago que la misma Cassandra siempre rechazaba con elegancia. Si no se la recuerda por nada más, que quede claro que todo lo que hizo fue por su familia." },
	},

